    "Índia": ["Mumbai","Delhi","Bangalore","Hyderabad","Chennai","Kolkata","Pune","Ahmedabad","Surat","Jaipur","Lucknow","Kanpur","Nagpur","Indore","Bhopal","Patna","Vadodara","Ludhiana"],
    "Austrália": ["Sydney","Melbourne","Brisbane","Perth","Adelaide","Gold Coast","Newcastle","Canberra","Wollongong","Hobart","Geelong","Townsville","Cairns","Darwin","Toowoomba","Ballarat","Bendigo","Mackay"],
    "África do Sul": ["Johannesburg","Cape Town","Durban","Pretoria","Port Elizabeth","Bloemfontein","East London","Polokwane","Nelspruit","Kimberley","Pietermaritzburg","Rustenburg","George","Welkom","Newcastle","Mbombela","Soweto","Sandton"],
    "Nigéria": ["Lagos","Abuja","Kano","Ibadan","Port Harcourt","Benin","Kaduna","Enugu","Aba","Onitsha","Ilorin","Jos","Maiduguri","Zaria","Warri","Akure","Calabar","Sokoto"],
    "Egito": ["Cairo","Alexandria","Giza","Shubra","Port Said","Suez","Mansoura","Tanta","Asyut","Faiyum","Zagazig","Ismailia","Aswan","Damanhur","Damietta","Beni Suef","Hurghada","Luxor"],
    "Suécia": ["Stockholm","Göteborg","Malmö","Uppsala","Västerås","Örebro","Linköping","Helsingborg","Jönköping","Norrköping","Lund","Umeå","Gävle","Borås","Eskilstuna","Halmstad","Karlstad","Sundsvall"],
    "Noruega": ["Oslo","Bergen","Trondheim","Stavanger","Drammen","Fredrikstad","Kristiansand","Sandnes","Tromsø","Sarpsborg","Skien","Ålesund","Sandefjord","Haugesund","Tønsberg","Moss","Porsgrunn","Bodø"],
    "Dinamarca": ["Copenhagen","Aarhus","Odense","Aalborg","Esbjerg","Randers","Kolding","Horsens","Vejle","Roskilde","Herning","Helsingør","Silkeborg","Næstved","Fredericia","Viborg","Køge","Holstebro"],
    "Suíça": ["Zürich","Genève","Basel","Bern","Lausanne","Winterthur","St. Gallen","Lugano","Luzern","Biel","Thun","Köniz","La Chaux-de-Fonds","Schaffhausen","Fribourg","Chur","Neuchâtel","Vernier"],
    "Áustria": ["Wien","Graz","Linz","Salzburg","Innsbruck","Klagenfurt","Villach","Wels","Sankt Pölten","Dornbirn","Steyr","Wiener Neustadt","Feldkirch","Bregenz","Leonding","Klosterneuburg","Baden","Wolfsberg"],
    "Chile": ["Santiago","Valparaíso","Concepción","Antofagasta","Temuco","Rancagua","Iquique","Talca","Arica","Chillán","La Serena","Calama","Coquimbo","Osorno","Valdivia","Punta Arenas","Quilpué","Copiapó"],
    "Colômbia": ["Bogotá","Medellín","Cali","Barranquilla","Cartagena","Cúcuta","Bucaramanga","Pereira","Santa Marta","Ibagué","Manizales","Pasto","Neiva","Villavicencio","Armenia","Popayán","Sincelejo","Valledupar"]
  }'::jsonb;
  city_arr text[];
  city text;
  prefix text;
  suffix text[] := ARRAY['FC','SC','AC','CF','United','City','Athletic','Sporting','Olympic'];
BEGIN
  city_arr := ARRAY(SELECT jsonb_array_elements_text(coalesce(cities->_country, '["United","City","Athletic","Royal","Olympic","Wanderers","Pioneers","Phoenix","Eagles","Lions","Tigers","Sharks","Wolves","Hawks","Stars","Galaxy","Storm","Thunder"]'::jsonb)));
  city := city_arr[((_idx - 1) % array_length(city_arr, 1)) + 1];
  prefix := prefixes[((_idx * 7) % array_length(prefixes, 1)) + 1];
  -- Alterna: alguns clubes "Prefix Cidade", outros "Cidade Suffix"
  IF _idx % 2 = 0 THEN
    RETURN prefix || ' ' || city;
  ELSE
    RETURN city || ' ' || suffix[((_idx * 3) % array_length(suffix, 1)) + 1];
  END IF;
END;
$$;
CREATE OR REPLACE FUNCTION public.bot_strength_for_division(_division int)
RETURNS int
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $$
  SELECT CASE _division
    WHEN 1 THEN 70 + floor(random() * 21)::int  -- 70-90
    WHEN 2 THEN 60 + floor(random() * 21)::int  -- 60-80
    WHEN 3 THEN 50 + floor(random() * 21)::int  -- 50-70
    ELSE          40 + floor(random() * 21)::int  -- 40-60
  END;
$$;
CREATE OR REPLACE FUNCTION public.random_bot_logo()
RETURNS text
LANGUAGE sql
VOLATILE
SET search_path TO 'public'
AS $$
  SELECT (ARRAY['⚽','🏆','⭐','🦁','🐅','🐺','🦅','🐂','🐎','🦈','🐊','🦌','🐘','🦏','🐃','🐉','🔥','⚡','🌟','💎','👑','🛡️','⚔️','🎯','🚀','🏰'])[floor(random() * 26 + 1)::int];
$$;
DO $$
DECLARE
  _hist RECORD;
  _country text;
  _target_league_id uuid;
  _shield jsonb;
  _logo text;
  _club_name text;
BEGIN
  FOR _hist IN
    -- Pega último estado de cada humano que estava em alguma liga antiga (que acabou de ser apagada).
    -- Usamos game_saves como fonte da verdade do clube.
    SELECT DISTINCT ON (gs.user_id)
      gs.user_id,
      gs.club_data
    FROM public.game_saves gs
    ORDER BY gs.user_id, gs.updated_at DESC
  LOOP
    _country := public.normalize_country(coalesce(_hist.club_data->'club'->>'country', _hist.club_data->>'country', ''));
    IF _country IS NULL THEN
      _country := 'Brasil'; -- fallback
    END IF;
    _club_name := coalesce(_hist.club_data->'club'->>'name', _hist.club_data->>'name', 'Manager FC');
    _logo := coalesce(_hist.club_data->'club'->>'logo', _hist.club_data->>'logo', '⚽');
    _shield := coalesce(_hist.club_data->'club'->'shield', _hist.club_data->'shield');
    -- Busca a divisão MAIS BAIXA do país (D4 > D3 > D2)
    SELECT id INTO _target_league_id
    FROM public.world_leagues
    WHERE country = _country AND season = 1
    ORDER BY division DESC
    LIMIT 1;
    IF _target_league_id IS NULL THEN
      -- Se não achou, joga em Brasil D4
      SELECT id INTO _target_league_id
      FROM public.world_leagues
      WHERE country = 'Brasil' AND division = 4 AND season = 1
      LIMIT 1;
    END IF;
    -- Insere humano no slot. Se já estiver lá (rerun), ignora.
    INSERT INTO public.world_league_teams (league_id, user_id, is_bot, club_name, club_logo, shield)
    VALUES (_target_league_id, _hist.user_id, false, _club_name, _logo, _shield)
    ON CONFLICT (league_id, club_name) DO NOTHING;
  END LOOP;
END $$;
DO $$
DECLARE
  _league RECORD;
  _current_count int;
  _bots_needed int;
  _i int;
  _bot_name text;
  _attempt int;
BEGIN
  FOR _league IN
    SELECT id, country, division, total_slots
    FROM public.world_leagues
    WHERE season = 1
    ORDER BY country, division
  LOOP
    SELECT COUNT(*) INTO _current_count
    FROM public.world_league_teams
    WHERE league_id = _league.id;
    _bots_needed := _league.total_slots - _current_count;
    IF _bots_needed <= 0 THEN CONTINUE; END IF;
    _i := 1;
    WHILE _bots_needed > 0 AND _i < 200 LOOP
      _bot_name := public.generate_bot_club_name(_league.country, _i);
      -- Tenta inserir; se conflitar (nome duplicado), aumenta i
      BEGIN
        INSERT INTO public.world_league_teams (
          league_id, user_id, is_bot, bot_strength,
          club_name, club_logo
        ) VALUES (
          _league.id, NULL, true,
          public.bot_strength_for_division(_league.division),
          _bot_name,
          public.random_bot_logo()
        );
        _bots_needed := _bots_needed - 1;
      EXCEPTION WHEN unique_violation THEN
        -- nome colidiu, tenta o próximo
      END;
      _i := _i + 1;
    END LOOP;
  END LOOP;
END $$;
UPDATE public.world_leagues
SET status = 'in_progress',
    current_matchday = 0,
    season_started_at = now(),
    season_ends_at = now() + interval '30 days'
WHERE season = 1 AND status = 'pending';
DO $$
DECLARE
  _team RECORD;
  _d1_id uuid;
  _victim_bot_id uuid;
  _old_league_id uuid;
  _old_division int;
  _new_bot_name text;
  _attempt int;
BEGIN
  FOR _team IN
    SELECT wlt.id, wlt.user_id, wl.country, wl.division, wlt.league_id
    FROM public.world_league_teams wlt
    JOIN public.world_leagues wl ON wl.id = wlt.league_id
    WHERE wlt.user_id IS NOT NULL
      AND wl.season = 1
      AND wl.division <> 1
  LOOP
    SELECT id INTO _d1_id
    FROM public.world_leagues
    WHERE country = _team.country AND division = 1 AND season = 1
    LIMIT 1;
    IF _d1_id IS NULL THEN CONTINUE; END IF;
    _old_league_id := _team.league_id;
    _old_division := _team.division;
    SELECT id INTO _victim_bot_id
    FROM public.world_league_teams
    WHERE league_id = _d1_id AND is_bot = true
    ORDER BY bot_strength ASC, created_at DESC
    LIMIT 1;
    IF _victim_bot_id IS NOT NULL THEN
      -- Gera nome único para o bot na liga antiga
      _attempt := 1;
      LOOP
        _new_bot_name := public.generate_bot_club_name(_team.country, 9000 + _attempt);
        EXIT WHEN NOT EXISTS (
          SELECT 1 FROM public.world_league_teams
          WHERE league_id = _old_league_id AND club_name = _new_bot_name
        );
        _attempt := _attempt + 1;
        EXIT WHEN _attempt > 500;
      END LOOP;
      UPDATE public.world_league_teams
      SET league_id = _old_league_id,
          club_name = _new_bot_name,
          bot_strength = public.bot_strength_for_division(_old_division),
          points = 0, wins = 0, draws = 0, losses = 0,
          goals_for = 0, goals_against = 0, played = 0
      WHERE id = _victim_bot_id;
    END IF;
    UPDATE public.world_league_teams
    SET league_id = _d1_id,
        points = 0, wins = 0, draws = 0, losses = 0,
        goals_for = 0, goals_against = 0, played = 0
    WHERE id = _team.id;
  END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.assign_user_to_d1_on_save()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _country text;
  _club_name text;
  _logo text;
  _shield jsonb;
  _d1_id uuid;
  _existing uuid;
  _victim_bot_id uuid;
BEGIN
  SELECT id INTO _existing
  FROM public.world_league_teams
  WHERE user_id = NEW.user_id
  LIMIT 1;
  IF _existing IS NOT NULL THEN RETURN NEW; END IF;
  _country := public.normalize_country(
    coalesce(NEW.club_data->'club'->>'country', NEW.club_data->>'country', 'Brasil')
  );
  _club_name := coalesce(NEW.club_data->'club'->>'name', NEW.club_data->>'name', 'Manager FC');
  _logo := coalesce(NEW.club_data->'club'->>'logo', NEW.club_data->>'logo', '⚽');
  _shield := coalesce(NEW.club_data->'club'->'shield', NEW.club_data->'shield');
  SELECT id INTO _d1_id
  FROM public.world_leagues
  WHERE country = _country AND division = 1 AND season = 1
  LIMIT 1;
  IF _d1_id IS NULL THEN
    SELECT id INTO _d1_id FROM public.world_leagues
    WHERE country = 'Brasil' AND division = 1 AND season = 1 LIMIT 1;
  END IF;
  IF _d1_id IS NULL THEN RETURN NEW; END IF;
  SELECT id INTO _victim_bot_id
  FROM public.world_league_teams
  WHERE league_id = _d1_id AND is_bot = true
  ORDER BY bot_strength ASC, created_at DESC
  LIMIT 1;
  IF _victim_bot_id IS NOT NULL THEN
    -- Evita colisão de nome: se já existir o nome, dá um sufixo único
    IF EXISTS (SELECT 1 FROM public.world_league_teams
               WHERE league_id = _d1_id AND club_name = _club_name AND id <> _victim_bot_id) THEN
      _club_name := _club_name || ' (' || substring(NEW.user_id::text, 1, 4) || ')';
    END IF;
    UPDATE public.world_league_teams
    SET user_id = NEW.user_id,
        is_bot = false,
        bot_strength = NULL,
        club_name = _club_name,
        club_logo = _logo,
        shield = _shield,
        points = 0, wins = 0, draws = 0, losses = 0,
        goals_for = 0, goals_against = 0, played = 0
    WHERE id = _victim_bot_id;
  ELSE
    INSERT INTO public.world_league_teams (league_id, user_id, is_bot, club_name, club_logo, shield)
    VALUES (_d1_id, NEW.user_id, false, _club_name, _logo, _shield)
    ON CONFLICT (league_id, club_name) DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_assign_user_to_d1 ON public.game_saves;
CREATE TRIGGER trg_assign_user_to_d1
AFTER INSERT ON public.game_saves
FOR EACH ROW
EXECUTE FUNCTION public.assign_user_to_d1_on_save();
CREATE OR REPLACE FUNCTION public.set_friendly_auto_sim_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'accepted' AND NEW.auto_sim_at IS NULL THEN
    -- usa match_date como fonte da verdade; fallback now()+5min
    NEW.auto_sim_at := COALESCE(NEW.match_date, now() + interval '5 minutes');
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_friendly_auto_sim_at ON public.friendly_invites;
CREATE TRIGGER trg_friendly_auto_sim_at
BEFORE INSERT OR UPDATE OF status ON public.friendly_invites
FOR EACH ROW
EXECUTE FUNCTION public.set_friendly_auto_sim_at();
UPDATE public.friendly_invites
SET auto_sim_at = COALESCE(match_date, now())
WHERE status = 'accepted' AND auto_sim_at IS NULL AND match_result IS NULL;
CREATE OR REPLACE FUNCTION public.calc_club_strength_from_save(_club_data jsonb)
RETURNS int
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $$
DECLARE
  _players jsonb;
  _strength int;
BEGIN
  _players := COALESCE(_club_data->'players', _club_data->'club'->'players');
  IF _players IS NULL OR jsonb_typeof(_players) <> 'array' OR jsonb_array_length(_players) = 0 THEN
    RETURN 65; -- default neutro
  END IF;
  SELECT COALESCE(round(avg(ovr))::int, 65)
  INTO _strength
  FROM (
    SELECT COALESCE(
      NULLIF((p->>'overall'),'')::int,
      NULLIF((p->>'ovr'),'')::int,
      65
    ) AS ovr
    FROM jsonb_array_elements(_players) p
    WHERE COALESCE((p->>'injured')::boolean, false) = false
    ORDER BY ovr DESC
    LIMIT 11
  ) t;
  RETURN COALESCE(_strength, 65);
END $$;
CREATE OR REPLACE FUNCTION public.target_division_for_strength(_strength int)
RETURNS int
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN _strength >= 78 THEN 1
    WHEN _strength >= 70 THEN 2
    WHEN _strength >= 62 THEN 3
    ELSE 4
  END;
$$;
CREATE OR REPLACE FUNCTION public.assign_user_to_d1_on_save()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _country text;
  _club_name text;
  _logo text;
  _shield jsonb;
  _strength int;
  _target_div int;
  _try_div int;
  _league_id uuid;
  _existing uuid;
  _victim_bot_id uuid;
  _victim_strength int;
BEGIN
  -- Já tem time no mundial? não realocar
  SELECT id INTO _existing
  FROM public.world_league_teams
  WHERE user_id = NEW.user_id
  LIMIT 1;
  IF _existing IS NOT NULL THEN RETURN NEW; END IF;
  _country := public.normalize_country(
    COALESCE(NEW.club_data->'club'->>'country', NEW.club_data->>'country', 'Brasil')
  );
  IF _country IS NULL THEN _country := 'Brasil'; END IF;
  _club_name := COALESCE(NEW.club_data->'club'->>'name', NEW.club_data->>'name', 'Manager FC');
  _logo := COALESCE(NEW.club_data->'club'->>'logo', NEW.club_data->>'logo', '⚽');
  _shield := COALESCE(NEW.club_data->'club'->'shield', NEW.club_data->'shield');
  _strength := public.calc_club_strength_from_save(NEW.club_data);
  _target_div := public.target_division_for_strength(_strength);
  -- Tenta alocar começando pela divisão alvo, descendo se não houver bot mais fraco
  -- (preferência por colocar humano em divisão compatível com sua força)
  FOR _try_div IN _target_div..4 LOOP
    SELECT id INTO _league_id
    FROM public.world_leagues
    WHERE country = _country AND division = _try_div AND season = 1
    LIMIT 1;
    IF _league_id IS NULL THEN
      -- Fallback Brasil
      SELECT id INTO _league_id
      FROM public.world_leagues
      WHERE country = 'Brasil' AND division = _try_div AND season = 1
      LIMIT 1;
    END IF;
    IF _league_id IS NULL THEN CONTINUE; END IF;
    -- Procura bot mais fraco que o humano (balanceamento)
    SELECT id, COALESCE(bot_strength, 60)
    INTO _victim_bot_id, _victim_strength
    FROM public.world_league_teams
    WHERE league_id = _league_id
      AND is_bot = true
      AND COALESCE(bot_strength, 60) <= _strength
    ORDER BY COALESCE(bot_strength, 60) ASC, created_at DESC
    LIMIT 1;
    -- Se não há bot fraco aqui mas é a última divisão (4), pega o mais fraco mesmo assim
    IF _victim_bot_id IS NULL AND _try_div = 4 THEN
      SELECT id, COALESCE(bot_strength, 60)
      INTO _victim_bot_id, _victim_strength
      FROM public.world_league_teams
      WHERE league_id = _league_id AND is_bot = true
      ORDER BY COALESCE(bot_strength, 60) ASC, created_at DESC
      LIMIT 1;
    END IF;
    IF _victim_bot_id IS NOT NULL THEN
      -- Evita colisão de nome
      IF EXISTS (
        SELECT 1 FROM public.world_league_teams
        WHERE league_id = _league_id AND club_name = _club_name AND id <> _victim_bot_id
      ) THEN
        _club_name := _club_name || ' (' || substring(NEW.user_id::text, 1, 4) || ')';
      END IF;
      UPDATE public.world_league_teams
      SET user_id = NEW.user_id,
          is_bot = false,
          bot_strength = NULL,
          club_name = _club_name,
          club_logo = _logo,
          shield = _shield,
          points = 0, wins = 0, draws = 0, losses = 0,
          goals_for = 0, goals_against = 0, played = 0
      WHERE id = _victim_bot_id;
      RETURN NEW;
    END IF;
    -- Sem bot adequado, tenta próxima divisão (mais baixa)
  END LOOP;
  -- Último fallback: insere direto (caso algo dê errado)
  SELECT id INTO _league_id
  FROM public.world_leagues
  WHERE country = _country AND division = 4 AND season = 1
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    INSERT INTO public.world_league_teams (league_id, user_id, is_bot, club_name, club_logo, shield)
    VALUES (_league_id, NEW.user_id, false, _club_name, _logo, _shield)
    ON CONFLICT (league_id, club_name) DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
DROP FUNCTION IF EXISTS public.calc_club_strength_from_save(jsonb);
DROP FUNCTION IF EXISTS public.target_division_for_strength(int);
CREATE OR REPLACE FUNCTION public.assign_user_to_d1_on_save()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _country text;
  _club_name text;
  _logo text;
  _shield jsonb;
  _existing uuid;
  _try_div int;
  _league_id uuid;
  _team_count int;
  _victim_bot_id uuid;
BEGIN
  -- Já tem time no mundial? não realocar
  SELECT id INTO _existing
  FROM public.world_league_teams
  WHERE user_id = NEW.user_id
  LIMIT 1;
  IF _existing IS NOT NULL THEN RETURN NEW; END IF;
  _country := public.normalize_country(
    COALESCE(NEW.club_data->'club'->>'country', NEW.club_data->>'country', 'Brasil')
  );
  IF _country IS NULL THEN _country := 'Brasil'; END IF;
  _club_name := COALESCE(NEW.club_data->'club'->>'name', NEW.club_data->>'name', 'Manager FC');
  _logo := COALESCE(NEW.club_data->'club'->>'logo', NEW.club_data->>'logo', '⚽');
  _shield := COALESCE(NEW.club_data->'club'->'shield', NEW.club_data->'shield');
  -- Percorre da divisão mais alta para a mais baixa
  FOR _try_div IN 1..4 LOOP
    SELECT id INTO _league_id
    FROM public.world_leagues
    WHERE country = _country AND division = _try_div AND season = 1
    LIMIT 1;
    -- Fallback Brasil se país não tem essa divisão
    IF _league_id IS NULL THEN
      SELECT id INTO _league_id
      FROM public.world_leagues
      WHERE country = 'Brasil' AND division = _try_div AND season = 1
      LIMIT 1;
    END IF;
    IF _league_id IS NULL THEN CONTINUE; END IF;
    SELECT count(*) INTO _team_count
    FROM public.world_league_teams
    WHERE league_id = _league_id;
    -- Caso 1: liga tem espaço livre (< 20) → INSERT direto
    IF _team_count < 20 THEN
      IF EXISTS (
        SELECT 1 FROM public.world_league_teams
        WHERE league_id = _league_id AND club_name = _club_name
      ) THEN
        _club_name := _club_name || ' (' || substring(NEW.user_id::text, 1, 4) || ')';
      END IF;
      INSERT INTO public.world_league_teams (league_id, user_id, is_bot, club_name, club_logo, shield)
      VALUES (_league_id, NEW.user_id, false, _club_name, _logo, _shield)
      ON CONFLICT (league_id, club_name) DO NOTHING;
      RETURN NEW;
    END IF;
    -- Caso 2: liga cheia (20) → tenta substituir um bot
    SELECT id INTO _victim_bot_id
    FROM public.world_league_teams
    WHERE league_id = _league_id AND is_bot = true
    ORDER BY COALESCE(bot_strength, 60) ASC, created_at DESC
    LIMIT 1;
    IF _victim_bot_id IS NOT NULL THEN
      IF EXISTS (
        SELECT 1 FROM public.world_league_teams
        WHERE league_id = _league_id AND club_name = _club_name AND id <> _victim_bot_id
      ) THEN
        _club_name := _club_name || ' (' || substring(NEW.user_id::text, 1, 4) || ')';
      END IF;
      UPDATE public.world_league_teams
      SET user_id = NEW.user_id,
          is_bot = false,
          bot_strength = NULL,
          club_name = _club_name,
          club_logo = _logo,
          shield = _shield,
          points = 0, wins = 0, draws = 0, losses = 0,
          goals_for = 0, goals_against = 0, played = 0
      WHERE id = _victim_bot_id;
      RETURN NEW;
    END IF;
    -- Liga cheia sem bots → desce para próxima divisão
  END LOOP;
  RETURN NEW;
END $$;
UPDATE public.world_leagues SET league_name = 'Brasileirão Série A' WHERE country = 'Brasil' AND division = 1;
