ALTER TABLE public.live_match_substitutions
  ADD COLUMN IF NOT EXISTS shared_match_id text;
CREATE INDEX IF NOT EXISTS idx_live_match_substitutions_shared
  ON public.live_match_substitutions(shared_match_id);
CREATE OR REPLACE FUNCTION public.fill_sub_shared_match_id()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.shared_match_id IS NULL AND NEW.live_match_id IS NOT NULL THEN
    SELECT COALESCE(shared_match_id, match_id)
      INTO NEW.shared_match_id
    FROM public.live_matches
    WHERE id = NEW.live_match_id;
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_fill_sub_shared_match_id ON public.live_match_substitutions;
CREATE TRIGGER trg_fill_sub_shared_match_id
  BEFORE INSERT ON public.live_match_substitutions
  FOR EACH ROW
  EXECUTE FUNCTION public.fill_sub_shared_match_id();
UPDATE public.live_match_substitutions s
SET shared_match_id = COALESCE(lm.shared_match_id, lm.match_id)
FROM public.live_matches lm
WHERE s.live_match_id = lm.id
  AND s.shared_match_id IS NULL;
DROP POLICY IF EXISTS "Match participants can view substitutions" ON public.live_match_substitutions;
CREATE POLICY "Match participants can view substitutions"
  ON public.live_match_substitutions
  FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.live_matches lm
      WHERE lm.id = live_match_substitutions.live_match_id
        AND (
          lm.user_id = auth.uid()
          OR (lm.shared_match_id IS NOT NULL
              AND public.is_match_participant(auth.uid(), lm.shared_match_id))
        )
    )
    OR (
      shared_match_id IS NOT NULL
      AND public.is_match_participant(auth.uid(), shared_match_id)
    )
  );
CREATE OR REPLACE FUNCTION public.close_expired_auctions()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _auction RECORD;
  _closed int := 0;
  _to_free int := 0;
  _sold int := 0;
BEGIN
  FOR _auction IN
    SELECT * FROM public.player_auctions
    WHERE status = 'active' AND expires_at <= now()
    FOR UPDATE
  LOOP
    IF _auction.current_bidder_id IS NOT NULL AND _auction.current_bid >= _auction.min_price THEN
      -- Sold: notify winner & seller; mark closed (the actual transfer of squad happens via in-app notification flow)
      UPDATE public.player_auctions
      SET status = 'sold'
      WHERE id = _auction.id;
      INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
      VALUES (
        _auction.current_bidder_id, 'auction_won',
        '🏆 Leilão vencido!',
        'Você arrematou ' || _auction.player_name || ' por R$ ' || _auction.current_bid::text,
        '🏆',
        jsonb_build_object('auction_id', _auction.id, 'player_data', _auction.player_data, 'amount', _auction.current_bid)
      );
      IF _auction.seller_id IS NOT NULL AND NOT _auction.is_system THEN
        INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
        VALUES (
          _auction.seller_id, 'auction_sold',
          '💰 Jogador vendido no leilão',
          _auction.player_name || ' vendido por R$ ' || _auction.current_bid::text,
          '💰',
          jsonb_build_object('auction_id', _auction.id, 'amount', _auction.current_bid, 'buyer', _auction.current_bidder_name)
        );
      END IF;
      _sold := _sold + 1;
    ELSE
      -- No bids: move to free agents market for 7 days
      UPDATE public.player_auctions
      SET status = 'expired'
      WHERE id = _auction.id;
      INSERT INTO public.free_agents_market (
        player_data, player_name, player_position, player_age, player_overall,
        visible_stats, origin, origin_club_name, available_from, available_until
      ) VALUES (
        _auction.player_data,
        _auction.player_name,
        COALESCE(_auction.player_data->>'position', 'CM'),
        _auction.player_age,
        _auction.player_overall,
        '{}'::jsonb,
        'auction_unsold',
        _auction.seller_club_name,
        now(),
        now() + interval '7 days'
      );
      IF _auction.seller_id IS NOT NULL AND NOT _auction.is_system THEN
        INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
        VALUES (
          _auction.seller_id, 'auction_unsold',
          'Leilão sem lances',
          _auction.player_name || ' foi para os Jogadores Livres.',
          '🆓',
          jsonb_build_object('auction_id', _auction.id)
        );
      END IF;
      _to_free := _to_free + 1;
    END IF;
    _closed := _closed + 1;
  END LOOP;
  RETURN jsonb_build_object(
    'closed', _closed,
    'sold', _sold,
    'moved_to_free_agents', _to_free
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.close_expired_auctions() TO authenticated, service_role;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'close-expired-auctions-weekly') THEN
    PERFORM cron.unschedule('close-expired-auctions-weekly');
  END IF;
END $$;
SELECT cron.schedule(
  'close-expired-auctions-weekly',
  '0 20 * * 0', -- Sundays at 20:00 UTC = 17:00 BRT
  $$ SELECT public.close_expired_auctions(); $$
);
CREATE OR REPLACE FUNCTION public.validate_auction()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  required_min bigint;
BEGIN
  IF NEW.player_overall < 60 THEN
    RAISE EXCEPTION 'Player must be 60+ overall for auction';
  END IF;
  IF NEW.player_age > 35 THEN
    RAISE EXCEPTION 'Player must be 35 years old or younger';
  END IF;
  -- Lance mínimo padronizado por faixa de OVR
  required_min := CASE
    WHEN NEW.player_overall >= 80 THEN 500000
    WHEN NEW.player_overall >= 70 THEN 300000
    WHEN NEW.player_overall >= 60 THEN 200000
    ELSE 100000
  END;
  IF NEW.min_price < required_min THEN
    NEW.min_price := required_min;
  END IF;
  IF NEW.current_bid < NEW.min_price THEN
    NEW.current_bid := NEW.min_price;
  END IF;
  RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.place_auction_bid(_auction_id uuid, _amount bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _auction RECORD;
  _user uuid := auth.uid();
  _bidder_name text;
  _min_increment bigint;
  _required_min bigint;
  _new_expires timestamptz;
  _now timestamptz := now();
  _is_admin boolean;
  _bidder_budget bigint;
  _max_allowed bigint;
BEGIN
  IF _user IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;
  SELECT * INTO _auction FROM public.player_auctions WHERE id = _auction_id FOR UPDATE;
  IF _auction IS NULL THEN
    RAISE EXCEPTION 'AUCTION_NOT_FOUND';
  END IF;
  IF _auction.status <> 'active' THEN
    RAISE EXCEPTION 'AUCTION_CLOSED';
  END IF;
  IF _auction.expires_at <= _now THEN
    RAISE EXCEPTION 'AUCTION_EXPIRED';
  END IF;
  _is_admin := public.has_role(_user, 'admin');
  IF _auction.seller_id = _user AND NOT _auction.is_system AND NOT _is_admin THEN
    RAISE EXCEPTION 'CANNOT_BID_OWN_AUCTION';
  END IF;
  IF _auction.current_bidder_id IS NULL THEN
    _required_min := _auction.min_price;
  ELSE
    _min_increment := CASE
      WHEN _auction.current_bid < 200000     THEN 10000
      WHEN _auction.current_bid < 500000     THEN 25000
      WHEN _auction.current_bid < 1000000    THEN 50000
      WHEN _auction.current_bid < 5000000    THEN 100000
      WHEN _auction.current_bid < 20000000   THEN 250000
      ELSE 500000
    END;
    _required_min := _auction.current_bid + _min_increment;
  END IF;
  IF _amount < _required_min THEN
    RAISE EXCEPTION 'BID_TOO_LOW' USING DETAIL = _required_min::text;
  END IF;
  -- 80% budget cap (skip for admins)
  IF NOT _is_admin THEN
    SELECT COALESCE((club_data->>'budget')::bigint, 0)
      INTO _bidder_budget
    FROM public.game_saves
    WHERE user_id = _user
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
    IF _bidder_budget IS NULL THEN _bidder_budget := 0; END IF;
    _max_allowed := (_bidder_budget * 80) / 100;
    IF _amount > _max_allowed THEN
      RAISE EXCEPTION 'BID_OVER_BUDGET_LIMIT' USING DETAIL = _max_allowed::text;
    END IF;
  END IF;
  SELECT COALESCE(display_name, 'Manager')
    INTO _bidder_name
  FROM public.profiles
  WHERE user_id = _user
  LIMIT 1;
  IF _bidder_name IS NULL THEN _bidder_name := 'Manager'; END IF;
  IF (_auction.expires_at - _now) <= interval '5 minutes' THEN
    _new_expires := _auction.expires_at + interval '10 minutes';
  ELSE
    _new_expires := _auction.expires_at;
  END IF;
  IF _auction.current_bidder_id IS NOT NULL AND _auction.current_bidder_id <> _user THEN
    INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
    VALUES (
      _auction.current_bidder_id,
      'auction_outbid',
      'Lance superado!',
      'Seu lance em ' || _auction.player_name || ' foi superado. Novo lance: R$ ' || (_amount/1000)::text || 'k por ' || _bidder_name || '.',
      '🔨',
      jsonb_build_object(
        'auction_id', _auction.id,
        'player_name', _auction.player_name,
        'previous_bid', _auction.current_bid,
        'new_bid', _amount,
        'new_bidder', _bidder_name
      )
    );
  END IF;
  UPDATE public.player_auctions
  SET current_bid = _amount,
      current_bidder_id = _user,
      current_bidder_name = _bidder_name,
      expires_at = _new_expires
  WHERE id = _auction_id;
  INSERT INTO public.auction_bids (auction_id, bidder_id, bidder_name, amount)
  VALUES (_auction_id, _user, _bidder_name, _amount);
  RETURN jsonb_build_object('ok', true, 'new_bid', _amount, 'expires_at', _new_expires);
END;
$$;
INSERT INTO public.global_ranking (user_id, club_name, ranking_points, games_played, wins, draws, losses, last_change)
SELECT 
  gs.user_id,
  COALESCE(gs.club_data->>'name', 'Clube') AS club_name,
  0, 0, 0, 0, 0, 0
FROM public.game_saves gs
WHERE NOT EXISTS (
  SELECT 1 FROM public.global_ranking gr WHERE gr.user_id = gs.user_id
);
UPDATE public.multiplayer_leagues
SET 
  tier = 'nacional',
  division = 1,
  league_type = 'main',
  total_rounds = 30,
  max_members = 20,
  match_time = '19:00',
  name = country || ' Série A',
  round_interval_hours = 24
WHERE tier = 'varzea' OR league_type = 'beginner';
UPDATE public.multiplayer_leagues
SET match_time = CASE division
  WHEN 1 THEN '19:00'
  WHEN 2 THEN '18:00'
  WHEN 3 THEN '17:00'
  WHEN 4 THEN '16:00'
  ELSE match_time
END,
total_rounds = 30,
max_members = 20,
round_interval_hours = 24
WHERE auto_created = true AND division BETWEEN 1 AND 4;
CREATE OR REPLACE FUNCTION public.fill_league_with_bots(_league_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _league RECORD;
  _current_count int;
  _needed int;
  _bot_name text;
  _bot_logo text;
  _bot_strength int;
  _i int;
  _bot_idx int;
  _added int := 0;
BEGIN
  SELECT * INTO _league FROM public.multiplayer_leagues WHERE id = _league_id;
  IF _league IS NULL THEN RETURN 0; END IF;
  SELECT count(*) INTO _current_count FROM public.league_members WHERE league_id = _league_id;
  _needed := COALESCE(_league.max_members, 20) - _current_count;
  IF _needed <= 0 THEN RETURN 0; END IF;
  SELECT count(*) INTO _bot_idx FROM public.league_members WHERE league_id = _league_id;
  FOR _i IN 1.._needed LOOP
    _bot_idx := _bot_idx + 1;
    _bot_name := public.generate_bot_club_name(COALESCE(_league.country, 'Brasil'), _bot_idx);
    _bot_logo := public.random_bot_logo();
    _bot_strength := public.bot_strength_for_division(COALESCE(_league.division, 1));
    INSERT INTO public.league_members (
      league_id, user_id, club_name, club_logo,
      points, wins, draws, losses, goals_for, goals_against, played,
      reputation, budget
    ) VALUES (
      _league_id, NULL,
      _bot_name || ' BOT', _bot_logo,
      0, 0, 0, 0, 0, 0, 0,
      _bot_strength, 1000000
    );
    _added := _added + 1;
  END LOOP;
  RETURN _added;
END;
$$;
CREATE OR REPLACE FUNCTION public.auto_assign_league(_user_id uuid, _club_name text, _country text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _league_id uuid;
  _code text;
  _country_status record;
  _div int;
  _division_names text[] := ARRAY['Série A', 'Série B', 'Série C', 'Série D'];
  _match_times text[] := ARRAY['19:00', '18:00', '17:00', '16:00'];
BEGIN
  -- Já está em alguma liga deste país?
  SELECT lm.league_id INTO _league_id
  FROM league_members lm
  JOIN multiplayer_leagues ml ON ml.id = lm.league_id
  WHERE lm.user_id = _user_id AND ml.country = _country
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    RETURN _league_id;
  END IF;
  -- País bloqueado?
  SELECT * INTO _country_status FROM country_status WHERE country = _country;
  IF _country_status IS NOT NULL AND _country_status.is_locked THEN
    RAISE EXCEPTION 'Este país está lotado. Escolha outro ou aguarde o próximo mês.';
  END IF;
  -- Procura D1 com vaga (primeiro), depois D2, D3, D4
  FOR _div IN 1..4 LOOP
    SELECT ml.id INTO _league_id
    FROM multiplayer_leagues ml
    WHERE ml.country = _country
      AND ml.tier = 'nacional'
      AND ml.division = _div
      AND ml.auto_created = true
      AND ml.season_status IN ('registration', 'waiting')
      AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id AND lm2.user_id IS NOT NULL) < ml.max_members
    ORDER BY ml.created_at ASC
    LIMIT 1;
    IF _league_id IS NOT NULL THEN
      EXIT;
    END IF;
  END LOOP;
  -- Não achou? Cria a próxima divisão necessária (começa pela D1)
  IF _league_id IS NULL THEN
    SELECT COALESCE(max(division), 0) + 1 INTO _div
    FROM multiplayer_leagues
    WHERE country = _country AND tier = 'nacional' AND auto_created = true;
    _div := LEAST(GREATEST(_div, 1), 4);
    _code := upper(substr(md5(random()::text), 1, 6));
    INSERT INTO multiplayer_leagues (
      name, code, owner_id, country, auto_created, max_members, status,
      league_type, total_rounds, season_status, division, tier, tier_level,
      match_time, round_interval_hours
    ) VALUES (
      _country || ' ' || _division_names[_div],
      _code, _user_id, _country, true, 20, 'waiting',
      'main', 30, 'registration', _div, 'nacional', _div,
      _match_times[_div], 24
    )
    RETURNING id INTO _league_id;
  END IF;
  -- Insere o jogador como membro
  INSERT INTO league_members (
    league_id, user_id, club_name, club_logo,
    points, wins, draws, losses, goals_for, goals_against, played,
    reputation, budget
  ) VALUES (
    _league_id, _user_id, _club_name, '⚽',
    0, 0, 0, 0, 0, 0, 0,
    65, 1000000
  );
  RETURN _league_id;
END;
$$;
CREATE OR REPLACE FUNCTION public.process_season_transition(_country text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _league RECORD;
  _player RECORD;
  _position integer;
  _reward bigint;
  _base_rewards bigint[] := ARRAY[
    20000000, 17000000, 14500000, 12500000, 11000000,
    10000000,  9200000,  8400000,  7800000,  7200000,
     6600000,  6000000,  5400000,  4800000,  4200000,
     3600000,  3000000,  2400000,  1800000,  1200000
  ];
  _divisor numeric;
  _pos_index integer;
  _target_league_id uuid;
  _next_division int;
  _prev_division int;
BEGIN
  -- Distribui prêmios em todas as ligas finalizadas
  FOR _league IN
    SELECT id, division, season, league_type, country
    FROM multiplayer_leagues
    WHERE country = _country
      AND season_status = 'finished'
      AND league_type = 'main'
      AND tier = 'nacional'
    ORDER BY division ASC
  LOOP
    _position := 0;
    FOR _player IN
      SELECT lm.id as member_db_id, lm.user_id, lm.points, lm.goals_for, lm.goals_against
      FROM league_members lm
      WHERE lm.league_id = _league.id
      ORDER BY lm.points DESC, (lm.goals_for - lm.goals_against) DESC, lm.goals_for DESC
    LOOP
      _position := _position + 1;
      _divisor := CASE COALESCE(_league.division, 1)
        WHEN 1 THEN 1.0
        WHEN 2 THEN 2.0
        WHEN 3 THEN 4.0
        ELSE 10.0
      END;
      _pos_index := LEAST(_position, 20);
      _reward := (_base_rewards[_pos_index] / _divisor)::bigint;
      UPDATE league_members SET budget = budget + _reward WHERE id = _player.member_db_id;
    END LOOP;
  END LOOP;
  -- Promoção (top 4) para divisão anterior (div-1) e Rebaixamento (bottom 4) para div+1
  FOR _league IN
    SELECT id, division, country
    FROM multiplayer_leagues
    WHERE country = _country
      AND season_status = 'finished'
      AND league_type = 'main'
      AND tier = 'nacional'
      AND division BETWEEN 1 AND 4
    ORDER BY division ASC
  LOOP
    _next_division := _league.division + 1;
    _prev_division := _league.division - 1;
    -- Promoção: top 4 → div-1 (se existir)
    IF _prev_division >= 1 THEN
      SELECT id INTO _target_league_id
      FROM multiplayer_leagues
      WHERE country = _country AND tier = 'nacional' AND division = _prev_division AND auto_created = true
      LIMIT 1;
      IF _target_league_id IS NOT NULL THEN
        UPDATE league_members
        SET league_id = _target_league_id
        WHERE id IN (
          SELECT lm.id FROM league_members lm
          WHERE lm.league_id = _league.id AND lm.user_id IS NOT NULL
          ORDER BY lm.points DESC, (lm.goals_for - lm.goals_against) DESC, lm.goals_for DESC
          LIMIT 4
        );
      END IF;
    END IF;
    -- Rebaixamento: bottom 4 → div+1 (se existir)
    IF _next_division <= 4 THEN
      SELECT id INTO _target_league_id
      FROM multiplayer_leagues
      WHERE country = _country AND tier = 'nacional' AND division = _next_division AND auto_created = true
      LIMIT 1;
      IF _target_league_id IS NOT NULL THEN
        UPDATE league_members
        SET league_id = _target_league_id
        WHERE id IN (
          SELECT lm.id FROM league_members lm
          WHERE lm.league_id = _league.id AND lm.user_id IS NOT NULL
          ORDER BY lm.points ASC, (lm.goals_for - lm.goals_against) ASC, lm.goals_for ASC
          LIMIT 4
        );
      END IF;
    END IF;
  END LOOP;
  -- Reset stats e avança temporada
  UPDATE league_members lm
  SET points = 0, wins = 0, draws = 0, losses = 0, goals_for = 0, goals_against = 0, played = 0
  FROM multiplayer_leagues ml
  WHERE lm.league_id = ml.id
    AND ml.country = _country
    AND ml.season_status = 'finished'
    AND ml.league_type = 'main'
    AND ml.tier = 'nacional';
  DELETE FROM league_matches lm
  USING multiplayer_leagues ml
  WHERE lm.league_id = ml.id
    AND ml.country = _country
    AND ml.season_status = 'finished'
    AND ml.league_type = 'main'
    AND ml.tier = 'nacional';
  UPDATE multiplayer_leagues
  SET season = season + 1,
      season_status = 'registration',
      current_round = 0,
      season_start = NULL,
      season_end = NULL
  WHERE country = _country
    AND season_status = 'finished'
    AND league_type = 'main'
    AND tier = 'nacional';
END;
$$;
CREATE OR REPLACE FUNCTION public.redistribute_beginners(_country text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _beginner_member RECORD;
  _target_league_id uuid;
  _div int;
BEGIN
  FOR _beginner_member IN
    SELECT lm.id as member_id, lm.user_id, lm.club_name, lm.club_logo, lm.reputation
    FROM league_members lm
    JOIN multiplayer_leagues ml ON ml.id = lm.league_id
    WHERE ml.country = _country
      AND ml.league_type = 'beginner'
      AND ml.season_status = 'finished'
    ORDER BY lm.reputation DESC
  LOOP
    -- Procura D4 → D3 → D2 → D1 com vaga
    FOR _div IN REVERSE 4..1 LOOP
      SELECT ml.id INTO _target_league_id
      FROM multiplayer_leagues ml
      WHERE ml.country = _country
        AND ml.tier = 'nacional'
        AND ml.division = _div
        AND ml.auto_created = true
        AND ml.season_status IN ('registration', 'waiting')
        AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id AND lm2.user_id IS NOT NULL) < ml.max_members
      LIMIT 1;
      IF _target_league_id IS NOT NULL THEN EXIT; END IF;
    END LOOP;
    IF _target_league_id IS NOT NULL THEN
      UPDATE league_members
      SET league_id = _target_league_id, points = 0, wins = 0, draws = 0,
          losses = 0, goals_for = 0, goals_against = 0, played = 0
      WHERE id = _beginner_member.member_id;
    END IF;
  END LOOP;
END;
$$;
CREATE TABLE IF NOT EXISTS public.continental_competitions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  continent text NOT NULL,
  tier text NOT NULL CHECK (tier IN ('principal', 'secundaria')),
  season integer NOT NULL DEFAULT 1,
  season_year integer,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'registration', 'in_progress', 'finished', 'cancelled')),
  current_stage text DEFAULT 'group',
  current_round integer DEFAULT 0,
  total_teams integer DEFAULT 16,
  num_groups integer DEFAULT 4,
  start_date date,
  end_date date,
  champion_team_id uuid,
  runner_up_team_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(continent, tier, season)
);
ALTER TABLE public.continental_competitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view continental competitions"
  ON public.continental_competitions FOR SELECT
  USING (true);
CREATE POLICY "Admins manage continental competitions"
  ON public.continental_competitions FOR ALL
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE INDEX idx_cont_comp_continent ON public.continental_competitions(continent, tier);
CREATE INDEX idx_cont_comp_status ON public.continental_competitions(status);
CREATE TABLE IF NOT EXISTS public.continental_teams (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  competition_id uuid NOT NULL REFERENCES public.continental_competitions(id) ON DELETE CASCADE,
  user_id uuid,
  is_bot boolean NOT NULL DEFAULT false,
  club_name text NOT NULL,
  club_logo text,
  country text NOT NULL,
  source text NOT NULL,
  group_label text,
  seed integer,
  group_points integer NOT NULL DEFAULT 0,
  group_wins integer NOT NULL DEFAULT 0,
  group_draws integer NOT NULL DEFAULT 0,
  group_losses integer NOT NULL DEFAULT 0,
  group_goals_for integer NOT NULL DEFAULT 0,
  group_goals_against integer NOT NULL DEFAULT 0,
  eliminated boolean NOT NULL DEFAULT false,
  eliminated_in_stage text,
  bot_strength integer DEFAULT 70,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.continental_teams ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view continental teams"
  ON public.continental_teams FOR SELECT
  USING (true);
CREATE POLICY "Admins manage continental teams"
  ON public.continental_teams FOR ALL
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE INDEX idx_cont_teams_comp ON public.continental_teams(competition_id);
CREATE INDEX idx_cont_teams_user ON public.continental_teams(user_id);
CREATE INDEX idx_cont_teams_group ON public.continental_teams(competition_id, group_label);
CREATE TABLE IF NOT EXISTS public.continental_matches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  competition_id uuid NOT NULL REFERENCES public.continental_competitions(id) ON DELETE CASCADE,
  stage text NOT NULL,
  round integer NOT NULL DEFAULT 1,
  leg integer NOT NULL DEFAULT 1,
  group_label text,
  home_team_id uuid REFERENCES public.continental_teams(id) ON DELETE CASCADE,
  away_team_id uuid REFERENCES public.continental_teams(id) ON DELETE CASCADE,
  home_goals integer,
  away_goals integer,
  home_goals_pen integer,
  away_goals_pen integer,
  aggregate_home integer,
  aggregate_away integer,
  scheduled_at timestamptz NOT NULL,
  played_at timestamptz,
  status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'live', 'played', 'cancelled')),
  match_data jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.continental_matches ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view continental matches"
  ON public.continental_matches FOR SELECT
  USING (true);
CREATE POLICY "Admins manage continental matches"
  ON public.continental_matches FOR ALL
  USING (public.has_role(auth.uid(), 'admin'))
  WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE INDEX idx_cont_matches_comp ON public.continental_matches(competition_id);
CREATE INDEX idx_cont_matches_stage ON public.continental_matches(competition_id, stage, round);
CREATE INDEX idx_cont_matches_scheduled ON public.continental_matches(scheduled_at);
CREATE TRIGGER update_continental_competitions_updated_at
  BEFORE UPDATE ON public.continental_competitions
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE OR REPLACE FUNCTION public.get_continent_for_country(_country text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path TO 'public'
AS $$
  SELECT CASE _country
    WHEN 'Brasil' THEN 'América do Sul'
    WHEN 'Argentina' THEN 'América do Sul'
    WHEN 'Chile' THEN 'América do Sul'
    WHEN 'Colômbia' THEN 'América do Sul'
    WHEN 'Uruguai' THEN 'América do Sul'
    WHEN 'Peru' THEN 'América do Sul'
    WHEN 'Equador' THEN 'América do Sul'
    WHEN 'Paraguai' THEN 'América do Sul'
    WHEN 'Bolívia' THEN 'América do Sul'
    WHEN 'Venezuela' THEN 'América do Sul'
    WHEN 'Espanha' THEN 'Europa'
    WHEN 'Inglaterra' THEN 'Europa'
    WHEN 'Itália' THEN 'Europa'
    WHEN 'Alemanha' THEN 'Europa'
    WHEN 'França' THEN 'Europa'
    WHEN 'Portugal' THEN 'Europa'
    WHEN 'Holanda' THEN 'Europa'
    WHEN 'Bélgica' THEN 'Europa'
    WHEN 'Áustria' THEN 'Europa'
    WHEN 'Suíça' THEN 'Europa'
    WHEN 'Dinamarca' THEN 'Europa'
    WHEN 'Suécia' THEN 'Europa'
    WHEN 'Noruega' THEN 'Europa'
    WHEN 'Rússia' THEN 'Europa'
    WHEN 'Turquia' THEN 'Europa'
    WHEN 'México' THEN 'América do Norte'
    WHEN 'Estados Unidos' THEN 'América do Norte'
    WHEN 'Canadá' THEN 'América do Norte'
    WHEN 'Egito' THEN 'África'
    WHEN 'Marrocos' THEN 'África'
    WHEN 'Nigéria' THEN 'África'
    WHEN 'África do Sul' THEN 'África'
    WHEN 'Japão' THEN 'Ásia'
    WHEN 'Coreia do Sul' THEN 'Ásia'
    WHEN 'China' THEN 'Ásia'
    WHEN 'Arábia Saudita' THEN 'Ásia'
    WHEN 'Índia' THEN 'Ásia'
    WHEN 'Austrália' THEN 'Oceania'
    WHEN 'Nova Zelândia' THEN 'Oceania'
    ELSE NULL
  END;
$$;
CREATE OR REPLACE FUNCTION public.qualify_continental_humans(_continent text, _tier text, _season integer)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _result jsonb := '[]'::jsonb;
  _country text;
  _league_id uuid;
  _member RECORD;
  _position int;
  _added int;
  _seen_users uuid[] := ARRAY[]::uuid[];
  _seen_clubs text[] := ARRAY[]::text[];
  _start_pos int;
  _end_pos int;
  _cup_winner RECORD;
  _previously_qualified_clubs text[] := ARRAY[]::text[];
BEGIN
  -- Para Secundária, não duplicar clubes já na Principal da mesma temporada
  IF _tier = 'secundaria' THEN
    SELECT array_agg(DISTINCT ct.club_name) INTO _previously_qualified_clubs
    FROM continental_teams ct
    JOIN continental_competitions cc ON cc.id = ct.competition_id
    WHERE cc.continent = _continent
      AND cc.tier = 'principal'
      AND cc.season = _season;
    _previously_qualified_clubs := COALESCE(_previously_qualified_clubs, ARRAY[]::text[]);
  END IF;
  -- Define faixa de posições por tier
  IF _tier = 'principal' THEN
    _start_pos := 1; _end_pos := 4;
  ELSE
    _start_pos := 5; _end_pos := 8;
  END IF;
  -- Itera países do continente
  FOR _country IN
    SELECT DISTINCT country FROM multiplayer_leagues
    WHERE tier = 'nacional' AND division = 1
      AND public.get_continent_for_country(country) = _continent
  LOOP
    SELECT id INTO _league_id
    FROM multiplayer_leagues
    WHERE country = _country AND tier = 'nacional' AND division = 1
      AND auto_created = true
    ORDER BY created_at ASC LIMIT 1;
    
    IF _league_id IS NULL THEN CONTINUE; END IF;
    
    _position := 0;
    _added := 0;
    FOR _member IN
      SELECT user_id, club_name, club_logo
      FROM league_members
      WHERE league_id = _league_id AND user_id IS NOT NULL
      ORDER BY points DESC, (goals_for - goals_against) DESC, goals_for DESC
      LIMIT _end_pos
    LOOP
      _position := _position + 1;
      IF _position < _start_pos THEN CONTINUE; END IF;
      -- Skip duplicados
      IF _member.club_name = ANY(_seen_clubs) 
         OR _member.club_name = ANY(_previously_qualified_clubs) THEN
        CONTINUE;
      END IF;
      _result := _result || jsonb_build_object(
        'user_id', _member.user_id,
        'club_name', _member.club_name,
        'club_logo', COALESCE(_member.club_logo, '⚽'),
        'country', _country,
        'source', 'league_pos_' || _position,
        'is_bot', false
      );
      _seen_clubs := _seen_clubs || _member.club_name;
      _seen_users := _seen_users || _member.user_id;
      _added := _added + 1;
    END LOOP;
    -- Para Principal: adiciona campeão da copa nacional do país
    IF _tier = 'principal' THEN
      SELECT ct.user_id, ct.club_name, ct.club_logo, ct.is_bot
      INTO _cup_winner
      FROM cup_competitions cc
      JOIN cup_teams ct ON ct.cup_id = cc.id
      WHERE cc.country = _country
        AND cc.cup_type = 'national'
        AND cc.status = 'finished'
        AND ct.eliminated = false
      ORDER BY cc.season_year DESC NULLS LAST, cc.created_at DESC
      LIMIT 1;
      
      IF FOUND AND NOT (_cup_winner.club_name = ANY(_seen_clubs)) THEN
        _result := _result || jsonb_build_object(
          'user_id', _cup_winner.user_id,
          'club_name', _cup_winner.club_name,
          'club_logo', COALESCE(_cup_winner.club_logo, '🏆'),
          'country', _country,
          'source', 'national_cup_winner',
          'is_bot', COALESCE(_cup_winner.is_bot, false)
        );
        _seen_clubs := _seen_clubs || _cup_winner.club_name;
      END IF;
    END IF;
  END LOOP;
  RETURN _result;
END;
$$;
CREATE OR REPLACE FUNCTION public.start_continental_tournament(
  _continent text,
  _tier text,
  _season integer DEFAULT 1,
  _start_date date DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  _comp_id uuid;
  _qualified jsonb;
  _target_size int;
  _num_groups int;
  _teams_per_group int;
  _team_record RECORD;
  _team_id uuid;
  _team_ids uuid[] := ARRAY[]::uuid[];
  _group_team_ids uuid[];
  _i int;
  _group_idx int;
  _group_label text;
  _bot_idx int := 0;
  _bot_name text;
  _start date := COALESCE(_start_date, CURRENT_DATE);
  _day_offset int;
  _round_in_group int;
  _idx_a int;
  _idx_b int;
  _scheduled_ts timestamptz;
  _matches_to_insert jsonb := '[]'::jsonb;
  _bot_country text;
BEGIN
  -- Cria/recupera competição
  INSERT INTO continental_competitions (continent, tier, season, status, total_teams, num_groups, start_date, season_year)
  VALUES (
    _continent, _tier, _season, 'in_progress',
    CASE WHEN _tier = 'principal' THEN 16 ELSE 8 END,
    CASE WHEN _tier = 'principal' THEN 4 ELSE 2 END,
    _start, EXTRACT(YEAR FROM _start)::int
  )
  ON CONFLICT (continent, tier, season) DO UPDATE
    SET status = 'in_progress', start_date = EXCLUDED.start_date
  RETURNING id INTO _comp_id;
  -- Limpa registros anteriores (re-execução segura)
  DELETE FROM continental_matches WHERE competition_id = _comp_id;
  DELETE FROM continental_teams WHERE competition_id = _comp_id;
  _target_size := CASE WHEN _tier = 'principal' THEN 16 ELSE 8 END;
  _num_groups := CASE WHEN _tier = 'principal' THEN 4 ELSE 2 END;
  _teams_per_group := _target_size / _num_groups;
  -- Qualifica humanos
  _qualified := public.qualify_continental_humans(_continent, _tier, _season);
  -- Insere humanos
  FOR _team_record IN SELECT * FROM jsonb_array_elements(_qualified)
  LOOP
    INSERT INTO continental_teams (
      competition_id, user_id, is_bot, club_name, club_logo, country, source, bot_strength
    ) VALUES (
      _comp_id,
      NULLIF(_team_record.value->>'user_id','')::uuid,
      COALESCE((_team_record.value->>'is_bot')::boolean, false),
      _team_record.value->>'club_name',
      _team_record.value->>'club_logo',
      _team_record.value->>'country',
      _team_record.value->>'source',
      75
    ) RETURNING id INTO _team_id;
    _team_ids := _team_ids || _team_id;
  END LOOP;
  -- Completa com bots se necessário
  WHILE array_length(_team_ids, 1) IS NULL OR array_length(_team_ids, 1) < _target_size LOOP
    _bot_idx := _bot_idx + 1;
    -- Escolhe um país aleatório do continente para o bot
    SELECT country INTO _bot_country FROM multiplayer_leagues
    WHERE public.get_continent_for_country(country) = _continent
    ORDER BY random() LIMIT 1;
    _bot_country := COALESCE(_bot_country, 'Brasil');
    _bot_name := public.generate_bot_club_name(_bot_country, _bot_idx + 100);
    INSERT INTO continental_teams (
      competition_id, user_id, is_bot, club_name, club_logo, country, source, bot_strength
    ) VALUES (
      _comp_id, NULL, true,
      _bot_name || ' BOT', public.random_bot_logo(),
      _bot_country, 'bot_filler',
      CASE WHEN _tier = 'principal' THEN 75 + floor(random()*10)::int ELSE 65 + floor(random()*10)::int END
    ) RETURNING id INTO _team_id;
    _team_ids := _team_ids || _team_id;
  END LOOP;
  -- Embaralha (Fisher-Yates simples)
  FOR _i IN REVERSE array_length(_team_ids,1)..2 LOOP
    _idx_a := _i;
    _idx_b := 1 + floor(random() * _i)::int;
    IF _idx_a <> _idx_b THEN
      _team_id := _team_ids[_idx_a];
      _team_ids[_idx_a] := _team_ids[_idx_b];
      _team_ids[_idx_b] := _team_id;
    END IF;
  END LOOP;
  -- Distribui em grupos e atribui group_label
  FOR _i IN 1.._target_size LOOP
    _group_idx := ((_i - 1) / _teams_per_group);
    _group_label := chr(65 + _group_idx);
    UPDATE continental_teams 
      SET group_label = _group_label, seed = _i
      WHERE id = _team_ids[_i];
  END LOOP;
  -- Agenda fase de grupos:
  --   Principal (4 grupos × 4 times = 6 partidas/grupo): 
  --     dia 15-20 (6 dias) — distribuir as rodadas (3 rodadas naturais)
  --   Secundária (2 grupos × 4 times): mesmo, mas menos jogos
  -- Para 4 times, round-robin gera 3 rodadas (3 jogos por rodada). Vamos espalhar as 3 rodadas
  -- nos dias 0,2,4 (relativos ao _start = dia 15) → cabe em dia 15, 17, 19 com folga.
  -- Para garantir "todo dia", também duplicamos para ida/volta? NÃO — manteremos jogo único na fase de grupos.
  FOR _group_idx IN 0.._num_groups - 1 LOOP
    _group_label := chr(65 + _group_idx);
    SELECT array_agg(id ORDER BY seed) INTO _group_team_ids
    FROM continental_teams 
    WHERE competition_id = _comp_id AND group_label = _group_label;
    -- 4 times → 3 rodadas: (1v4,2v3) (1v3,2v4) (1v2,3v4)
    FOR _round_in_group IN 1..3 LOOP
      _day_offset := (_round_in_group - 1) * 2; -- dias 0,2,4 → 15,17,19 BRT
      _scheduled_ts := ((_start + _day_offset)::text || ' 20:00:00 America/Sao_Paulo')::timestamptz;
      
      IF _round_in_group = 1 THEN
        -- 1v4, 2v3
        INSERT INTO continental_matches (competition_id, stage, round, group_label, home_team_id, away_team_id, scheduled_at)
        VALUES 
          (_comp_id, 'group', 1, _group_label, _group_team_ids[1], _group_team_ids[4], _scheduled_ts),
          (_comp_id, 'group', 1, _group_label, _group_team_ids[2], _group_team_ids[3], _scheduled_ts);
      ELSIF _round_in_group = 2 THEN
        INSERT INTO continental_matches (competition_id, stage, round, group_label, home_team_id, away_team_id, scheduled_at)
        VALUES 
          (_comp_id, 'group', 2, _group_label, _group_team_ids[1], _group_team_ids[3], _scheduled_ts),
          (_comp_id, 'group', 2, _group_label, _group_team_ids[4], _group_team_ids[2], _scheduled_ts);
      ELSE
        INSERT INTO continental_matches (competition_id, stage, round, group_label, home_team_id, away_team_id, scheduled_at)
        VALUES 
          (_comp_id, 'group', 3, _group_label, _group_team_ids[1], _group_team_ids[2], _scheduled_ts),
          (_comp_id, 'group', 3, _group_label, _group_team_ids[3], _group_team_ids[4], _scheduled_ts);
      END IF;
    END LOOP;
  END LOOP;
  -- Mata-mata (placeholders agendados; chaves serão preenchidas pelo advancer ao fim dos grupos)
  -- Principal: oitavas (8 jogos) dia 21 → mas 16 times geram 8 oitavas? Não — 16 times = 8 oitavas.
  -- Espec do usuário: D21 oitavas, D22 quartas, D23 semi, D24 final.
  -- Para Secundária (8 times) começamos direto em quartas no dia 22.
  -- Aqui apenas registramos a janela; o advancer cria os pares quando souber os classificados.
  -- Atualiza end_date estimada
  UPDATE continental_competitions 
    SET end_date = _start + 9
    WHERE id = _comp_id;
  RETURN _comp_id;
END;
$$;
CREATE TABLE IF NOT EXISTS public.continental_qualifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid,
  club_name text NOT NULL,
  club_logo text,
  country text NOT NULL,
  continent text NOT NULL,
  source text NOT NULL, -- 'national_cup_winner' | 'league_pos_X'
  tier text NOT NULL,   -- 'principal' | 'secundaria'
  season_year int NOT NULL,
  qualified_at timestamptz NOT NULL DEFAULT now(),
  consumed boolean NOT NULL DEFAULT false
);
ALTER TABLE public.continental_qualifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view continental qualifications"
  ON public.continental_qualifications FOR SELECT USING (true);
CREATE INDEX IF NOT EXISTS idx_cont_qual_country_year 
  ON public.continental_qualifications(country, season_year, consumed);
CREATE OR REPLACE FUNCTION public.qualify_national_cup_teams(_country text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _teams jsonb := '[]'::jsonb;
  _league_id uuid;
  _member RECORD;
  _count int := 0;
  _seen_clubs text[] := ARRAY[]::text[];
BEGIN
  -- Pega TODOS os 20 da Série A
  SELECT id INTO _league_id
  FROM multiplayer_leagues
  WHERE country = _country AND tier = 'nacional' AND division = 1 AND auto_created = true
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    FOR _member IN
      SELECT user_id, club_name, club_logo
      FROM league_members
      WHERE league_id = _league_id
      ORDER BY points DESC NULLS LAST, (goals_for - goals_against) DESC NULLS LAST
      LIMIT 20
    LOOP
      _teams := _teams || jsonb_build_object(
        'user_id', _member.user_id,
        'club_name', _member.club_name,
        'club_logo', COALESCE(_member.club_logo, '⚽'),
        'is_bot', _member.user_id IS NULL
      );
      _seen_clubs := _seen_clubs || _member.club_name;
      _count := _count + 1;
    END LOOP;
  END IF;
  -- Top 12 da Série B
  SELECT id INTO _league_id
  FROM multiplayer_leagues
  WHERE country = _country AND tier = 'nacional' AND division = 2 AND auto_created = true
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    FOR _member IN
      SELECT user_id, club_name, club_logo
      FROM league_members
      WHERE league_id = _league_id
        AND NOT (club_name = ANY(_seen_clubs))
      ORDER BY points DESC NULLS LAST, (goals_for - goals_against) DESC NULLS LAST
      LIMIT 12
    LOOP
      _teams := _teams || jsonb_build_object(
        'user_id', _member.user_id,
        'club_name', _member.club_name,
        'club_logo', COALESCE(_member.club_logo, '⚽'),
        'is_bot', _member.user_id IS NULL
      );
      _count := _count + 1;
    END LOOP;
  END IF;
  -- Completa com bots se faltar para 32
  WHILE _count < 32 LOOP
    _teams := _teams || jsonb_build_object(
      'user_id', NULL,
      'club_name', generate_bot_club_name(_country, _count + 100),
      'club_logo', random_bot_logo(),
      'is_bot', true
    );
    _count := _count + 1;
  END LOOP;
  RETURN _teams;
END;
$$;
CREATE OR REPLACE FUNCTION public.start_national_cup(_country text, _season_year int)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _cup_id uuid;
  _teams jsonb;
  _team_record record;
  _team_ids uuid[] := ARRAY[]::uuid[];
  _new_team_id uuid;
  _i int;
  _today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  _round_dates timestamptz[];
BEGIN
  -- Evita duplicar
  IF EXISTS (
    SELECT 1 FROM cup_competitions 
    WHERE country = _country AND cup_type = 'national' 
      AND season_year = _season_year AND status IN ('scheduled','in_progress')
  ) THEN
    RAISE NOTICE 'Cup already exists for % season %', _country, _season_year;
    RETURN NULL;
  END IF;
  _teams := qualify_national_cup_teams(_country);
  
  IF jsonb_array_length(_teams) <> 32 THEN
    RAISE EXCEPTION 'Expected 32 teams, got %', jsonb_array_length(_teams);
  END IF;
  -- Cria copa
  INSERT INTO cup_competitions (
    name, cup_type, country, season_year, format, status, current_round, total_rounds, tier
  ) VALUES (
    'Copa do ' || _country, 'national', _country, _season_year, 'knockout', 'scheduled', 1, 5, 'nacional'
  ) RETURNING id INTO _cup_id;
  -- Insere times com seed aleatório (Fisher-Yates)
  FOR _team_record IN
    SELECT * FROM jsonb_array_elements(_teams) WITH ORDINALITY AS t(team, ord)
    ORDER BY random()
  LOOP
    INSERT INTO cup_teams (
      cup_id, user_id, is_bot, bot_name, bot_strength,
      club_name, club_logo, seed, eliminated
    ) VALUES (
      _cup_id,
      NULLIF(_team_record.team->>'user_id','')::uuid,
      (_team_record.team->>'is_bot')::boolean,
      CASE WHEN (_team_record.team->>'is_bot')::boolean THEN _team_record.team->>'club_name' ELSE NULL END,
      CASE WHEN (_team_record.team->>'is_bot')::boolean THEN 50 + floor(random()*30)::int ELSE NULL END,
      _team_record.team->>'club_name',
      _team_record.team->>'club_logo',
      array_length(_team_ids, 1),
      false
    ) RETURNING id INTO _new_team_id;
    _team_ids := array_append(_team_ids, _new_team_id);
  END LOOP;
  -- Datas: dia 10=R32, dia 12=R16, dia 14=QF, dia 16=SF, dia 17=F (12h BRT)
  _round_dates := ARRAY[
    ((_today + 10) || ' 12:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo',
    ((_today + 12) || ' 12:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo',
    ((_today + 14) || ' 12:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo',
    ((_today + 16) || ' 12:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo',
    ((_today + 17) || ' 12:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo'
  ];
  -- Cria os 16 jogos da R32
  FOR _i IN 1..16 LOOP
    INSERT INTO cup_matches (
      cup_id, round, leg, home_team_id, away_team_id, scheduled_at, status
    ) VALUES (
      _cup_id, 1, 1, _team_ids[_i*2-1], _team_ids[_i*2], _round_dates[1], 'scheduled'
    );
  END LOOP;
  UPDATE cup_competitions SET status = 'in_progress' WHERE id = _cup_id;
  
  RETURN _cup_id;
END;
$$;
CREATE OR REPLACE FUNCTION public.finish_national_cup_award_continental(_cup_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _cup RECORD;
  _winner RECORD;
  _continent text;
  _country_continent_map jsonb := '{
    "Brasil":"América do Sul","Argentina":"América do Sul","Uruguai":"América do Sul","Chile":"América do Sul","Colômbia":"América do Sul","Peru":"América do Sul","Equador":"América do Sul","Paraguai":"América do Sul","Bolívia":"América do Sul","Venezuela":"América do Sul",
    "Espanha":"Europa","Inglaterra":"Europa","Itália":"Europa","Alemanha":"Europa","França":"Europa","Portugal":"Europa","Holanda":"Europa","Bélgica":"Europa","Turquia":"Europa","Rússia":"Europa","Suécia":"Europa","Noruega":"Europa","Dinamarca":"Europa","Suíça":"Europa","Áustria":"Europa",
    "México":"América do Norte","Estados Unidos":"América do Norte","Canadá":"América do Norte",
    "Egito":"África","Marrocos":"África","Nigéria":"África","África do Sul":"África",
    "Japão":"Ásia","Coreia do Sul":"Ásia","Arábia Saudita":"Ásia","China":"Ásia","Índia":"Ásia",
    "Austrália":"Oceania","Nova Zelândia":"Oceania"
  }'::jsonb;
BEGIN
  SELECT * INTO _cup FROM cup_competitions WHERE id = _cup_id;
  IF _cup IS NULL OR _cup.status <> 'finished' THEN RETURN; END IF;
  -- Vencedor = único time não eliminado
  SELECT user_id, club_name, club_logo INTO _winner
  FROM cup_teams
  WHERE cup_id = _cup_id AND eliminated = false
  LIMIT 1;
  IF _winner IS NULL THEN RETURN; END IF;
  _continent := _country_continent_map->>_cup.country;
  IF _continent IS NULL THEN RETURN; END IF;
  -- Registra vaga continental (só se humano)
  IF _winner.user_id IS NOT NULL THEN
    INSERT INTO continental_qualifications (
      user_id, club_name, club_logo, country, continent, source, tier, season_year
    ) VALUES (
      _winner.user_id, _winner.club_name, _winner.club_logo, _cup.country, _continent,
      'national_cup_winner', 'principal', COALESCE(_cup.season_year, EXTRACT(year FROM now())::int)
    );
    -- Notifica
    INSERT INTO user_notifications (user_id, type, title, message, icon, data)
    VALUES (
      _winner.user_id, 'cup_won', '🏆 Campeão da Copa!',
      'Você venceu a ' || _cup.name || ' e garantiu vaga na Continental Principal!',
      '🏆',
      jsonb_build_object('cup_id', _cup_id, 'country', _cup.country)
    );
    -- Prêmio em dinheiro (R$ 15M)
    UPDATE league_members 
    SET budget = budget + 15000000
    WHERE user_id = _winner.user_id;
  END IF;
END;
$$;
CREATE TABLE IF NOT EXISTS public.club_world_cups (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  season_year int NOT NULL,
  status text NOT NULL DEFAULT 'scheduled', -- scheduled | groups | knockout | finished
  current_stage text NOT NULL DEFAULT 'groups', -- groups | r16 | qf | sf | final | done
  current_round int NOT NULL DEFAULT 1,
  champion_team_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(season_year)
);
CREATE TABLE IF NOT EXISTS public.club_world_cup_teams (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cup_id uuid NOT NULL REFERENCES public.club_world_cups(id) ON DELETE CASCADE,
  user_id uuid,
  is_bot boolean NOT NULL DEFAULT false,
  bot_strength int,
  club_name text NOT NULL,
  club_logo text,
  country text,
  continent text,
  group_letter text, -- A..H
  group_pos int,
  played int NOT NULL DEFAULT 0,
  wins int NOT NULL DEFAULT 0,
  draws int NOT NULL DEFAULT 0,
  losses int NOT NULL DEFAULT 0,
  goals_for int NOT NULL DEFAULT 0,
  goals_against int NOT NULL DEFAULT 0,
  points int NOT NULL DEFAULT 0,
  eliminated boolean NOT NULL DEFAULT false,
  source text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.club_world_cup_matches (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cup_id uuid NOT NULL REFERENCES public.club_world_cups(id) ON DELETE CASCADE,
  stage text NOT NULL, -- groups | r16 | qf | sf | final
  round int NOT NULL DEFAULT 1,
  group_letter text,
  home_team_id uuid REFERENCES public.club_world_cup_teams(id),
  away_team_id uuid REFERENCES public.club_world_cup_teams(id),
  home_goals int,
  away_goals int,
  scheduled_at timestamptz NOT NULL,
  played_at timestamptz,
  status text NOT NULL DEFAULT 'scheduled',
  match_data jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_cwc_matches_cup_status ON public.club_world_cup_matches(cup_id, status, scheduled_at);
CREATE INDEX IF NOT EXISTS idx_cwc_teams_cup_group ON public.club_world_cup_teams(cup_id, group_letter, points DESC);
ALTER TABLE public.club_world_cups ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.club_world_cup_teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.club_world_cup_matches ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view club world cups" ON public.club_world_cups FOR SELECT USING (true);
CREATE POLICY "Anyone can view club world cup teams" ON public.club_world_cup_teams FOR SELECT USING (true);
CREATE POLICY "Anyone can view club world cup matches" ON public.club_world_cup_matches FOR SELECT USING (true);
CREATE OR REPLACE FUNCTION public.qualify_club_world_cup(_season_year int)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _teams jsonb := '[]'::jsonb;
  _seen_clubs text[] := ARRAY[]::text[];
  _continents text[] := ARRAY['América do Sul','Europa','América do Norte','África','Ásia','Oceania'];
  _cont text;
  _comp RECORD;
  _team RECORD;
  _count int := 0;
  _added_per_cont int;
BEGIN
  -- 1) Top 2 de cada Continental Principal finalizada (12 clubes)
  FOREACH _cont IN ARRAY _continents LOOP
    _added_per_cont := 0;
    FOR _comp IN
      SELECT id FROM continental_competitions
      WHERE continent = _cont AND tier = 'principal' AND status = 'finished'
      ORDER BY created_at DESC LIMIT 1
    LOOP
      FOR _team IN
        SELECT user_id, club_name, club_logo, country, points, goals_for, goals_against
        FROM continental_teams
        WHERE competition_id = _comp.id
        ORDER BY 
          CASE WHEN eliminated = false THEN 0 ELSE 1 END,
          points DESC NULLS LAST,
          (goals_for - goals_against) DESC NULLS LAST
        LIMIT 4
      LOOP
        IF _team.club_name = ANY(_seen_clubs) THEN CONTINUE; END IF;
        IF _added_per_cont >= 2 THEN EXIT; END IF;
        _teams := _teams || jsonb_build_object(
          'user_id', _team.user_id,
          'club_name', _team.club_name,
          'club_logo', COALESCE(_team.club_logo, '⚽'),
          'country', _team.country,
          'continent', _cont,
          'is_bot', _team.user_id IS NULL,
          'source', 'continental_principal_top2'
        );
        _seen_clubs := _seen_clubs || _team.club_name;
        _count := _count + 1;
        _added_per_cont := _added_per_cont + 1;
      END LOOP;
    END LOOP;
  END LOOP;
  -- 2) Completar com melhores da Série A (D1) de cada país, balanceado por continente
  FOR _team IN
    SELECT lm.user_id, lm.club_name, lm.club_logo, ml.country, lm.points
    FROM league_members lm
    JOIN multiplayer_leagues ml ON ml.id = lm.league_id
    WHERE ml.tier = 'nacional' AND ml.division = 1 AND ml.auto_created = true
      AND NOT (lm.club_name = ANY(_seen_clubs))
    ORDER BY lm.points DESC NULLS LAST, (lm.goals_for - lm.goals_against) DESC NULLS LAST
  LOOP
    IF _count >= 32 THEN EXIT; END IF;
    _teams := _teams || jsonb_build_object(
      'user_id', _team.user_id,
      'club_name', _team.club_name,
      'club_logo', COALESCE(_team.club_logo, '⚽'),
      'country', _team.country,
      'continent', NULL,
      'is_bot', _team.user_id IS NULL,
      'source', 'league_top'
    );
    _seen_clubs := _seen_clubs || _team.club_name;
    _count := _count + 1;
  END LOOP;
  -- 3) Completar com bots se ainda faltar
  WHILE _count < 32 LOOP
    _teams := _teams || jsonb_build_object(
      'user_id', NULL,
      'club_name', generate_bot_club_name('Brasil', _count + 500),
      'club_logo', random_bot_logo(),
      'country', 'Brasil',
      'continent', 'América do Sul',
      'is_bot', true,
      'source', 'bot_fill'
    );
    _count := _count + 1;
  END LOOP;
  RETURN _teams;
END;
$$;
CREATE OR REPLACE FUNCTION public.start_club_world_cup(_season_year int)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _cup_id uuid;
  _teams jsonb;
  _team_record record;
  _team_ids uuid[] := ARRAY[]::uuid[];
  _new_team_id uuid;
  _today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  _groups text[] := ARRAY['A','B','C','D','E','F','G','H'];
  _g int;
  _i int;
  _matchday1 timestamptz;
  _matchday2 timestamptz;
  _matchday3 timestamptz;
  _t1 uuid; _t2 uuid; _t3 uuid; _t4 uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM club_world_cups WHERE season_year = _season_year) THEN
    RAISE NOTICE 'Club World Cup already exists for %', _season_year;
    RETURN NULL;
  END IF;
  _teams := qualify_club_world_cup(_season_year);
  IF jsonb_array_length(_teams) <> 32 THEN
    RAISE EXCEPTION 'Expected 32 teams, got %', jsonb_array_length(_teams);
  END IF;
  INSERT INTO club_world_cups (name, season_year, status, current_stage)
  VALUES ('Mundial de Clubes ' || _season_year, _season_year, 'groups', 'groups')
  RETURNING id INTO _cup_id;
  -- Inserir times com ordem aleatória
  FOR _team_record IN
    SELECT * FROM jsonb_array_elements(_teams) WITH ORDINALITY AS t(team, ord)
    ORDER BY random()
  LOOP
    INSERT INTO club_world_cup_teams (
      cup_id, user_id, is_bot, bot_strength, club_name, club_logo, country, continent, source
    ) VALUES (
      _cup_id,
      NULLIF(_team_record.team->>'user_id','')::uuid,
      (_team_record.team->>'is_bot')::boolean,
      CASE WHEN (_team_record.team->>'is_bot')::boolean THEN 70 + floor(random()*20)::int ELSE NULL END,
      _team_record.team->>'club_name',
      _team_record.team->>'club_logo',
      _team_record.team->>'country',
      _team_record.team->>'continent',
      _team_record.team->>'source'
    ) RETURNING id INTO _new_team_id;
    _team_ids := array_append(_team_ids, _new_team_id);
  END LOOP;
  -- Distribuir nos 8 grupos (4 times cada)
  FOR _g IN 1..8 LOOP
    FOR _i IN 1..4 LOOP
      UPDATE club_world_cup_teams
      SET group_letter = _groups[_g], group_pos = _i
      WHERE id = _team_ids[(_g-1)*4 + _i];
    END LOOP;
  END LOOP;
  -- Datas dos jogos de grupo (21h BRT = 00h UTC dia seguinte)
  _matchday1 := ((_today + 20) || ' 21:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo';
  _matchday2 := ((_today + 21) || ' 21:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo';
  _matchday3 := ((_today + 22) || ' 21:00:00')::timestamp AT TIME ZONE 'America/Sao_Paulo';
  -- Para cada grupo, gerar 6 jogos (round-robin de 4 = 3 rodadas com 2 jogos cada)
  -- Pares: R1: 1v2, 3v4 | R2: 1v3, 2v4 | R3: 1v4, 2v3
  FOR _g IN 1..8 LOOP
    SELECT id INTO _t1 FROM club_world_cup_teams WHERE cup_id = _cup_id AND group_letter = _groups[_g] AND group_pos = 1;
    SELECT id INTO _t2 FROM club_world_cup_teams WHERE cup_id = _cup_id AND group_letter = _groups[_g] AND group_pos = 2;
    SELECT id INTO _t3 FROM club_world_cup_teams WHERE cup_id = _cup_id AND group_letter = _groups[_g] AND group_pos = 3;
    SELECT id INTO _t4 FROM club_world_cup_teams WHERE cup_id = _cup_id AND group_letter = _groups[_g] AND group_pos = 4;
    -- R1
    INSERT INTO club_world_cup_matches (cup_id, stage, round, group_letter, home_team_id, away_team_id, scheduled_at)
    VALUES (_cup_id, 'groups', 1, _groups[_g], _t1, _t2, _matchday1),
           (_cup_id, 'groups', 1, _groups[_g], _t3, _t4, _matchday1);
    -- R2
    INSERT INTO club_world_cup_matches (cup_id, stage, round, group_letter, home_team_id, away_team_id, scheduled_at)
    VALUES (_cup_id, 'groups', 2, _groups[_g], _t1, _t3, _matchday2),
           (_cup_id, 'groups', 2, _groups[_g], _t2, _t4, _matchday2);
    -- R3
    INSERT INTO club_world_cup_matches (cup_id, stage, round, group_letter, home_team_id, away_team_id, scheduled_at)
    VALUES (_cup_id, 'groups', 3, _groups[_g], _t1, _t4, _matchday3),
           (_cup_id, 'groups', 3, _groups[_g], _t2, _t3, _matchday3);
  END LOOP;
  RETURN _cup_id;
END;
$$;
CREATE OR REPLACE FUNCTION public.award_club_world_cup_prizes(_cup_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _final_match RECORD;
  _winner_id uuid; _runner_id uuid;
  _winner RECORD; _runner RECORD;
  _semi_losers uuid[];
  _semi_team RECORD;
BEGIN
  -- Encontrar a final
  SELECT * INTO _final_match
  FROM club_world_cup_matches
  WHERE cup_id = _cup_id AND stage = 'final' AND status = 'finished'
  LIMIT 1;
  IF _final_match IS NULL THEN RETURN; END IF;
  IF (_final_match.match_data->>'winner_team_id') IS NOT NULL THEN
    _winner_id := (_final_match.match_data->>'winner_team_id')::uuid;
    _runner_id := CASE WHEN _winner_id = _final_match.home_team_id 
                       THEN _final_match.away_team_id ELSE _final_match.home_team_id END;
  END IF;
  IF _winner_id IS NULL THEN RETURN; END IF;
  -- Marcar campeão
  UPDATE club_world_cups SET champion_team_id = _winner_id, status = 'finished', current_stage = 'done' WHERE id = _cup_id;
  -- Premiar campeão (R$ 100M)
  SELECT * INTO _winner FROM club_world_cup_teams WHERE id = _winner_id;
  IF _winner.user_id IS NOT NULL THEN
    UPDATE league_members SET budget = budget + 100000000 WHERE user_id = _winner.user_id;
    INSERT INTO user_notifications (user_id, type, title, message, icon, data)
    VALUES (_winner.user_id, 'world_cup_won', '🌍 CAMPEÃO MUNDIAL!',
            'Você venceu o ' || (SELECT name FROM club_world_cups WHERE id = _cup_id) || '! Prêmio: R$ 100M.',
            '🏆', jsonb_build_object('cup_id', _cup_id));
  END IF;
  -- Premiar vice (R$ 50M)
  SELECT * INTO _runner FROM club_world_cup_teams WHERE id = _runner_id;
  IF _runner.user_id IS NOT NULL THEN
    UPDATE league_members SET budget = budget + 50000000 WHERE user_id = _runner.user_id;
    INSERT INTO user_notifications (user_id, type, title, message, icon, data)
    VALUES (_runner.user_id, 'world_cup_runner', '🥈 Vice-Campeão Mundial',
            'Você foi vice-campeão do Mundial de Clubes! Prêmio: R$ 50M.',
            '🥈', jsonb_build_object('cup_id', _cup_id));
  END IF;
  -- Premiar perdedores das semis (R$ 25M cada)
  SELECT array_agg(loser) INTO _semi_losers FROM (
    SELECT CASE WHEN (m.match_data->>'winner_team_id')::uuid = m.home_team_id THEN m.away_team_id ELSE m.home_team_id END AS loser
    FROM club_world_cup_matches m
    WHERE m.cup_id = _cup_id AND m.stage = 'sf' AND m.status = 'finished'
  ) sl;
  IF _semi_losers IS NOT NULL THEN
    FOR _semi_team IN SELECT * FROM club_world_cup_teams WHERE id = ANY(_semi_losers) AND user_id IS NOT NULL LOOP
      UPDATE league_members SET budget = budget + 25000000 WHERE user_id = _semi_team.user_id;
      INSERT INTO user_notifications (user_id, type, title, message, icon, data)
      VALUES (_semi_team.user_id, 'world_cup_semi', '🥉 Semifinalista Mundial',
              'Você chegou às semifinais do Mundial de Clubes! Prêmio: R$ 25M.',
              '🥉', jsonb_build_object('cup_id', _cup_id));
    END LOOP;
  END IF;
END;
$$;
CREATE OR REPLACE FUNCTION public.cwc_update_standings(
  _home_id uuid, _away_id uuid,
  _hg int, _ag int, _hp int, _ap int
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE club_world_cup_teams
  SET played = played + 1,
      wins = wins + CASE WHEN _hp = 3 THEN 1 ELSE 0 END,
      draws = draws + CASE WHEN _hp = 1 THEN 1 ELSE 0 END,
      losses = losses + CASE WHEN _hp = 0 THEN 1 ELSE 0 END,
      goals_for = goals_for + _hg,
      goals_against = goals_against + _ag,
      points = points + _hp
  WHERE id = _home_id;
  UPDATE club_world_cup_teams
  SET played = played + 1,
      wins = wins + CASE WHEN _ap = 3 THEN 1 ELSE 0 END,
      draws = draws + CASE WHEN _ap = 1 THEN 1 ELSE 0 END,
      losses = losses + CASE WHEN _ap = 0 THEN 1 ELSE 0 END,
      goals_for = goals_for + _ag,
      goals_against = goals_against + _hg,
      points = points + _ap
  WHERE id = _away_id;
END;
$$;
CREATE OR REPLACE FUNCTION public.get_user_upcoming_matches(_user_id uuid, _limit int DEFAULT 10)
RETURNS TABLE (
  competition_type text,
  competition_name text,
  priority int,
  match_id uuid,
  stage text,
  home_club text,
  away_club text,
  is_home boolean,
  scheduled_at timestamptz
)
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  WITH all_matches AS (
    -- 1. Mundial de Clubes
    SELECT 
      'world_cup'::text AS competition_type,
      cwc.name AS competition_name,
      1 AS priority,
      cwcm.id AS match_id,
      cwcm.stage AS stage,
      home.club_name AS home_club,
      away.club_name AS away_club,
      (home.user_id = _user_id) AS is_home,
      cwcm.scheduled_at
    FROM club_world_cup_matches cwcm
    JOIN club_world_cups cwc ON cwc.id = cwcm.cup_id
    JOIN club_world_cup_teams home ON home.id = cwcm.home_team_id
    JOIN club_world_cup_teams away ON away.id = cwcm.away_team_id
    WHERE cwcm.status = 'scheduled'
      AND (home.user_id = _user_id OR away.user_id = _user_id)
    UNION ALL
    -- 2. Continental
    SELECT
      'continental'::text,
      ('Continental ' || INITCAP(cc.tier) || ' · ' || cc.continent),
      CASE WHEN cc.tier = 'principal' THEN 2 ELSE 3 END,
      cm.id,
      cm.stage,
      ht.club_name,
      at.club_name,
      (ht.user_id = _user_id),
      cm.scheduled_at
    FROM continental_matches cm
    JOIN continental_competitions cc ON cc.id = cm.competition_id
    JOIN continental_teams ht ON ht.id = cm.home_team_id
    JOIN continental_teams at ON at.id = cm.away_team_id
    WHERE cm.status = 'scheduled'
      AND (ht.user_id = _user_id OR at.user_id = _user_id)
    UNION ALL
    -- 3. Copa Nacional
    SELECT
      'national_cup'::text,
      cc.name,
      4,
      cm.id,
      CASE cc.current_round
        WHEN 1 THEN 'R32' WHEN 2 THEN 'R16' WHEN 3 THEN 'Quartas'
        WHEN 4 THEN 'Semi' WHEN 5 THEN 'Final'
        ELSE 'R' || cc.current_round::text
      END,
      ht.club_name,
      at.club_name,
      (ht.user_id = _user_id),
      cm.scheduled_at
    FROM cup_matches cm
    JOIN cup_competitions cc ON cc.id = cm.cup_id
    JOIN cup_teams ht ON ht.id = cm.home_team_id
    JOIN cup_teams at ON at.id = cm.away_team_id
    WHERE cm.status = 'scheduled'
      AND cc.cup_type = 'national'
      AND (ht.user_id = _user_id OR at.user_id = _user_id)
    UNION ALL
    -- 4. Liga
    SELECT
      'league'::text,
      ml.name,
      5,
      lm.id,
      'Rodada ' || lm.round::text,
      hm.club_name,
      am.club_name,
      (lm.home_user_id = _user_id),
      lm.auto_sim_at
    FROM league_matches lm
    JOIN multiplayer_leagues ml ON ml.id = lm.league_id
    JOIN league_members hm ON hm.league_id = lm.league_id AND hm.user_id = lm.home_user_id
    JOIN league_members am ON am.league_id = lm.league_id AND am.user_id = lm.away_user_id
    WHERE lm.status = 'scheduled'
      AND lm.auto_sim_at IS NOT NULL
      AND (lm.home_user_id = _user_id OR lm.away_user_id = _user_id)
  )
  SELECT * FROM all_matches
  ORDER BY scheduled_at ASC, priority ASC
  LIMIT _limit;
$$;
