CREATE OR REPLACE FUNCTION public.check_club_name_available(_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  normalized text;
  exists_count int;
  suggestions text[] := ARRAY[]::text[];
  candidate text;
  i int;
BEGIN
  normalized := trim(_name);
  IF normalized IS NULL OR length(normalized) = 0 THEN
    RETURN jsonb_build_object('available', false, 'reason', 'empty', 'suggestions', '[]'::jsonb);
  END IF;
  -- Verifica em game_saves (clubes humanos)
  SELECT count(*) INTO exists_count
  FROM public.game_saves
  WHERE lower(trim(coalesce(club_data->>'name',''))) = lower(normalized);
  IF exists_count = 0 THEN
    -- Também verifica em league_members (BOT/humanos em ligas)
    SELECT count(*) INTO exists_count
    FROM public.league_members
    WHERE lower(trim(coalesce(club_name,''))) = lower(normalized);
  END IF;
  IF exists_count = 0 THEN
    RETURN jsonb_build_object('available', true, 'suggestions', '[]'::jsonb);
  END IF;
  -- Gera 3 sugestões: "Nome FC", "Nome 2", "Nome United"
  FOR candidate IN
    SELECT v FROM (VALUES
      (normalized || ' FC'),
      (normalized || ' 2'),
      (normalized || ' United'),
      ('Real ' || normalized),
      (normalized || ' City')
    ) AS t(v)
  LOOP
    SELECT count(*) INTO exists_count
    FROM public.game_saves
    WHERE lower(trim(coalesce(club_data->>'name',''))) = lower(candidate);
    IF exists_count = 0 THEN
      SELECT count(*) INTO exists_count
      FROM public.league_members
      WHERE lower(trim(coalesce(club_name,''))) = lower(candidate);
    END IF;
    IF exists_count = 0 THEN
      suggestions := array_append(suggestions, candidate);
      EXIT WHEN array_length(suggestions, 1) >= 3;
    END IF;
  END LOOP;
  RETURN jsonb_build_object(
    'available', false,
    'reason', 'duplicate',
    'suggestions', to_jsonb(suggestions)
  );
END;
$$;
GRANT EXECUTE ON FUNCTION public.check_club_name_available(text) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.sync_global_ranking_from_match()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_goals  INTEGER;
  v_opp_goals   INTEGER;
  v_outcome     TEXT;
  v_weight      NUMERIC;
  v_base        INTEGER;
  v_delta       INTEGER;
  v_club_name   TEXT;
  v_existing    RECORD;
  v_comp_lower  TEXT;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- Determina gols do usuário
  IF NEW.is_home THEN
    v_user_goals := NEW.home_goals;
    v_opp_goals  := NEW.away_goals;
    v_club_name  := NEW.home_team;
  ELSE
    v_user_goals := NEW.away_goals;
    v_opp_goals  := NEW.home_goals;
    v_club_name  := NEW.away_team;
  END IF;
  -- Resultado
  IF v_user_goals > v_opp_goals THEN
    v_outcome := 'win';  v_base := 12;
  ELSIF v_user_goals < v_opp_goals THEN
    v_outcome := 'loss'; v_base := -6;
  ELSE
    v_outcome := 'draw'; v_base := 4;
  END IF;
  -- Peso por tipo de competição
  v_comp_lower := lower(coalesce(NEW.competition, '') || ' ' || coalesce(NEW.match_type, ''));
  v_weight := CASE
    WHEN v_comp_lower LIKE '%mundial%' OR v_comp_lower LIKE '%world%' THEN 2.0
    WHEN v_comp_lower LIKE '%continental%' OR v_comp_lower LIKE '%libertador%' OR v_comp_lower LIKE '%champions%' OR v_comp_lower LIKE '%europa%' THEN 1.6
    WHEN v_comp_lower LIKE '%copa%' OR v_comp_lower LIKE '%cup%' THEN 1.2
    WHEN v_comp_lower LIKE '%amist%' OR v_comp_lower LIKE '%friendly%' THEN 0.5
    ELSE 1.0  -- liga padrão
  END;
  v_delta := round(v_base * v_weight);
  SELECT id, ranking_points, games_played, wins, draws, losses
    INTO v_existing
    FROM public.global_ranking
    WHERE user_id = NEW.user_id
    LIMIT 1;
  IF v_existing.id IS NULL THEN
    INSERT INTO public.global_ranking (
      user_id, club_name, ranking_points, games_played,
      wins, draws, losses, last_change, current_competition
    ) VALUES (
      NEW.user_id, v_club_name, GREATEST(0, v_delta), 1,
      CASE WHEN v_outcome = 'win'  THEN 1 ELSE 0 END,
      CASE WHEN v_outcome = 'draw' THEN 1 ELSE 0 END,
      CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
      v_delta, coalesce(NEW.competition, 'Amistoso')
    );
  ELSE
    UPDATE public.global_ranking SET
      club_name           = v_club_name,
      ranking_points      = GREATEST(0, coalesce(ranking_points, 0) + v_delta),
      games_played        = coalesce(games_played, 0) + 1,
      wins                = coalesce(wins,   0) + CASE WHEN v_outcome = 'win'  THEN 1 ELSE 0 END,
      draws               = coalesce(draws,  0) + CASE WHEN v_outcome = 'draw' THEN 1 ELSE 0 END,
      losses              = coalesce(losses, 0) + CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
      last_change         = v_delta,
      current_competition = coalesce(NEW.competition, 'Amistoso'),
      updated_at          = now()
      WHERE id = v_existing.id;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Nunca derrubar o INSERT da partida por causa do ranking
  RAISE WARNING 'sync_global_ranking_from_match falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_sync_global_ranking ON public.match_history;
CREATE TRIGGER trg_sync_global_ranking
  AFTER INSERT ON public.match_history
  FOR EACH ROW
  EXECUTE FUNCTION public.sync_global_ranking_from_match();
CREATE OR REPLACE FUNCTION public.ensure_ranking_for_save()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_club_name TEXT;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  -- Extrai o nome do clube do JSON club_data
  v_club_name := coalesce(NEW.club_data->>'name', NEW.save_name, 'Clube');
  INSERT INTO public.global_ranking (
    user_id, club_name, ranking_points, games_played,
    wins, draws, losses, last_change, current_competition
  ) VALUES (
    NEW.user_id, v_club_name, 0, 0, 0, 0, 0, 0, 'Nenhuma'
  )
  ON CONFLICT (user_id) DO UPDATE
    SET club_name = EXCLUDED.club_name,
        updated_at = now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ensure_ranking_for_save falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public'
      AND tablename = 'global_ranking'
      AND indexdef LIKE '%UNIQUE%user_id%'
  ) THEN
    -- Limpa duplicatas mantendo a mais recente
    DELETE FROM public.global_ranking a
      USING public.global_ranking b
      WHERE a.user_id = b.user_id
        AND a.created_at < b.created_at;
    CREATE UNIQUE INDEX IF NOT EXISTS uq_global_ranking_user
      ON public.global_ranking(user_id);
  END IF;
END $$;
DROP TRIGGER IF EXISTS trg_ensure_ranking_for_save ON public.game_saves;
CREATE TRIGGER trg_ensure_ranking_for_save
  AFTER INSERT ON public.game_saves
  FOR EACH ROW
  EXECUTE FUNCTION public.ensure_ranking_for_save();
INSERT INTO public.global_ranking (
  user_id, club_name, ranking_points, games_played,
  wins, draws, losses, last_change, current_competition
)
SELECT DISTINCT ON (gs.user_id)
  gs.user_id,
  coalesce(gs.club_data->>'name', gs.save_name, 'Clube'),
  0, 0, 0, 0, 0, 0, 'Nenhuma'
FROM public.game_saves gs
LEFT JOIN public.global_ranking gr ON gr.user_id = gs.user_id
WHERE gr.id IS NULL
ORDER BY gs.user_id, gs.updated_at DESC
ON CONFLICT (user_id) DO NOTHING;
ALTER TABLE public.newspaper_entries
  ADD COLUMN IF NOT EXISTS image_key TEXT;
CREATE INDEX IF NOT EXISTS idx_newspaper_entries_event_image
  ON public.newspaper_entries (created_at DESC)
  WHERE is_event = true;
CREATE OR REPLACE FUNCTION public.publish_newspaper_event(
  _user_id uuid,
  _category text,
  _text text,
  _image_key text
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Bots não têm user_id, então pulamos para não violar NOT NULL.
  IF _user_id IS NULL THEN
    RETURN;
  END IF;
  INSERT INTO public.newspaper_entries (user_id, category, text, is_event, image_key)
  VALUES (_user_id, _category, _text, true, _image_key);
END;
$$;
CREATE OR REPLACE FUNCTION public.broadcast_league_champion()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _champ RECORD;
  _is_early boolean;
  _played_total int;
  _expected_total int;
  _img_key text;
  _headline text;
  _body text;
BEGIN
  IF NEW.season_status = 'finished' AND COALESCE(OLD.season_status, '') <> 'finished' THEN
    -- Pega líder da liga (campeão)
    SELECT user_id, club_name, points, played
      INTO _champ
    FROM public.league_members
    WHERE league_id = NEW.id
    ORDER BY points DESC NULLS LAST, (goals_for - goals_against) DESC NULLS LAST
    LIMIT 1;
    IF _champ.club_name IS NULL THEN
      RETURN NEW;
    END IF;
    -- Detecta título antecipado: somatório de jogos disputados < total esperado
    SELECT COALESCE(sum(played), 0) INTO _played_total
      FROM public.league_members WHERE league_id = NEW.id;
    _expected_total := COALESCE(NEW.total_rounds, 0) * COALESCE(NEW.max_members, 20);
    _is_early := _expected_total > 0 AND _played_total < _expected_total - COALESCE(NEW.max_members, 20);
    IF _is_early THEN
      _img_key := 'league_champion_early';
      _headline := '🏆 CAMPEÃO ANTECIPADO!';
      _body := _champ.club_name || ' conquista o título de ' || NEW.name || ' com rodadas de antecedência!';
    ELSE
      _img_key := 'league_champion';
      _headline := '🏆 CAMPEÃO!';
      _body := _champ.club_name || ' é o campeão de ' || NEW.name || ' na temporada ' || COALESCE(NEW.season, 1) || '!';
    END IF;
    -- Publica para o campeão (se humano)
    PERFORM public.publish_newspaper_event(_champ.user_id, 'CAMPEÃO', _headline || E'\n\n' || _body, _img_key);
    -- Publica também para todos os outros humanos da mesma liga (para feed global ficar visível)
    INSERT INTO public.newspaper_entries (user_id, category, text, is_event, image_key)
    SELECT lm.user_id, 'CAMPEÃO', _headline || E'\n\n' || _body, true, _img_key
    FROM public.league_members lm
    WHERE lm.league_id = NEW.id
      AND lm.user_id IS NOT NULL
      AND lm.user_id <> COALESCE(_champ.user_id, '00000000-0000-0000-0000-000000000000'::uuid);
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_broadcast_league_champion ON public.multiplayer_leagues;
CREATE TRIGGER trg_broadcast_league_champion
  AFTER UPDATE OF season_status ON public.multiplayer_leagues
  FOR EACH ROW EXECUTE FUNCTION public.broadcast_league_champion();
CREATE OR REPLACE FUNCTION public.broadcast_cup_champion()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _winner_team RECORD;
  _img_key text;
  _category text;
  _headline text;
  _body text;
  _final_match RECORD;
  _winner_team_id uuid;
BEGIN
  IF NEW.status = 'finished' AND COALESCE(OLD.status, '') <> 'finished' THEN
    -- Tenta achar o campeão pela final (último round)
    SELECT * INTO _final_match
    FROM public.cup_matches
    WHERE cup_id = NEW.id AND status = 'finished'
    ORDER BY round DESC, played_at DESC NULLS LAST
    LIMIT 1;
    IF _final_match.id IS NULL THEN
      RETURN NEW;
    END IF;
    -- Decide vencedor
    IF (_final_match.match_data->>'winner_team_id') IS NOT NULL THEN
      _winner_team_id := (_final_match.match_data->>'winner_team_id')::uuid;
    ELSIF COALESCE(_final_match.home_goals, 0) >= COALESCE(_final_match.away_goals, 0) THEN
      _winner_team_id := _final_match.home_team_id;
    ELSE
      _winner_team_id := _final_match.away_team_id;
    END IF;
    SELECT user_id, club_name INTO _winner_team
    FROM public.cup_teams
    WHERE id = _winner_team_id;
    IF _winner_team.club_name IS NULL THEN
      RETURN NEW;
    END IF;
    -- Tipo de copa define visual e categoria
    IF NEW.cup_type IN ('continental', 'world', 'club_world_cup', 'international') THEN
      _img_key := 'international_champion';
      _category := 'COPA';
      _headline := '🌍 CAMPEÃO INTERNACIONAL!';
    ELSE
      _img_key := 'cup_champion';
      _category := 'COPA';
      _headline := '🏆 CAMPEÃO DE COPA!';
    END IF;
    _body := _winner_team.club_name || ' vence a final e levanta o troféu de ' || COALESCE(NEW.name, 'Copa') || '!';
    PERFORM public.publish_newspaper_event(_winner_team.user_id, _category, _headline || E'\n\n' || _body, _img_key);
    -- Publica também para todos os outros humanos que participaram dessa copa
    INSERT INTO public.newspaper_entries (user_id, category, text, is_event, image_key)
    SELECT DISTINCT ct.user_id, _category, _headline || E'\n\n' || _body, true, _img_key
    FROM public.cup_teams ct
    WHERE ct.cup_id = NEW.id
      AND ct.user_id IS NOT NULL
      AND ct.user_id <> COALESCE(_winner_team.user_id, '00000000-0000-0000-0000-000000000000'::uuid);
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_broadcast_cup_champion ON public.cup_competitions;
CREATE TRIGGER trg_broadcast_cup_champion
  AFTER UPDATE OF status ON public.cup_competitions
  FOR EACH ROW EXECUTE FUNCTION public.broadcast_cup_champion();
ALTER TABLE public.loan_listings
  ADD COLUMN IF NOT EXISTS salary_payer text NOT NULL DEFAULT 'buyer',
  ADD COLUMN IF NOT EXISTS salary_split_pct integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS loan_fee bigint NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS open_to_offers boolean NOT NULL DEFAULT true;
ALTER TABLE public.loan_listings
  DROP CONSTRAINT IF EXISTS loan_listings_salary_payer_check;
ALTER TABLE public.loan_listings
  ADD CONSTRAINT loan_listings_salary_payer_check
  CHECK (salary_payer IN ('seller','buyer','split'));
ALTER TABLE public.loan_listings
  DROP CONSTRAINT IF EXISTS loan_listings_split_check;
ALTER TABLE public.loan_listings
  ADD CONSTRAINT loan_listings_split_check
  CHECK (salary_split_pct BETWEEN 0 AND 100);
ALTER TABLE public.loan_listings
  DROP CONSTRAINT IF EXISTS loan_listings_loan_fee_check;
ALTER TABLE public.loan_listings
  ADD CONSTRAINT loan_listings_loan_fee_check
  CHECK (loan_fee >= 0);
CREATE TABLE IF NOT EXISTS public.loan_offers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  listing_id uuid NOT NULL REFERENCES public.loan_listings(id) ON DELETE CASCADE,
  seller_id uuid NOT NULL,
  buyer_id uuid NOT NULL,
  buyer_club_name text NOT NULL DEFAULT '',
  -- proposed terms
  offered_salary_payer text NOT NULL DEFAULT 'buyer',
  offered_salary_split_pct integer NOT NULL DEFAULT 0,
  offered_loan_fee bigint NOT NULL DEFAULT 0,
  message text DEFAULT '',
  -- counter from seller (optional)
  counter_salary_payer text,
  counter_salary_split_pct integer,
  counter_loan_fee bigint,
  counter_message text,
  status text NOT NULL DEFAULT 'pending',
  expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'),
  resolved_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT loan_offers_status_check
    CHECK (status IN ('pending','accepted','rejected','countered','expired','cancelled')),
  CONSTRAINT loan_offers_payer_check
    CHECK (offered_salary_payer IN ('seller','buyer','split')),
  CONSTRAINT loan_offers_counter_payer_check
    CHECK (counter_salary_payer IS NULL OR counter_salary_payer IN ('seller','buyer','split')),
  CONSTRAINT loan_offers_split_check
    CHECK (offered_salary_split_pct BETWEEN 0 AND 100),
  CONSTRAINT loan_offers_counter_split_check
    CHECK (counter_salary_split_pct IS NULL OR counter_salary_split_pct BETWEEN 0 AND 100),
  CONSTRAINT loan_offers_fee_check
    CHECK (offered_loan_fee >= 0),
  CONSTRAINT loan_offers_counter_fee_check
    CHECK (counter_loan_fee IS NULL OR counter_loan_fee >= 0),
  CONSTRAINT loan_offers_no_self
    CHECK (seller_id <> buyer_id)
);
