CREATE OR REPLACE FUNCTION public.replace_bot_with_player(
  _league_id uuid,
  _user_id uuid,
  _club_name text,
  _club_logo text DEFAULT '⚽'
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _bot_member_id uuid;
  _existing uuid;
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'NOT_AUTHENTICATED';
  END IF;
  -- Já está na liga?
  SELECT id INTO _existing
  FROM public.league_members
  WHERE league_id = _league_id AND user_id = _user_id
  LIMIT 1;
  IF _existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'ALREADY_IN_LEAGUE', 'member_id', _existing);
  END IF;
  -- Pega o bot mais fraco (faz sentido: jogador novo herda time fraco)
  SELECT id INTO _bot_member_id
  FROM public.league_members
  WHERE league_id = _league_id
    AND is_bot = true
  ORDER BY COALESCE(bot_strength, 50) ASC, random()
  LIMIT 1
  FOR UPDATE SKIP LOCKED;
  IF _bot_member_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'reason', 'NO_BOT_SLOT_AVAILABLE');
  END IF;
  -- Substitui: jogador herda a vaga + estatísticas atuais (rodadas já jogadas).
  UPDATE public.league_members
  SET user_id = _user_id,
      is_bot = false,
      bot_strength = NULL,
      club_name = _club_name,
      club_logo = _club_logo,
      updated_at = now()
  WHERE id = _bot_member_id;
  RETURN jsonb_build_object(
    'success', true,
    'member_id', _bot_member_id,
    'inherited_slot', true
  );
END;
$$;
REVOKE ALL ON FUNCTION public.replace_bot_with_player(uuid, uuid, text, text) FROM public;
GRANT EXECUTE ON FUNCTION public.replace_bot_with_player(uuid, uuid, text, text) TO authenticated;
CREATE OR REPLACE FUNCTION public.propagate_live_match_result()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_match_id text;
  v_invite_id uuid;
  v_events jsonb;
BEGIN
  -- only run when transitioning to finished
  IF NEW.status <> 'finished' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'finished' THEN RETURN NEW; END IF;
  v_match_id := COALESCE(NEW.shared_match_id, NEW.match_id);
  IF v_match_id IS NULL THEN RETURN NEW; END IF;
  v_events := COALESCE(NEW.events, '[]'::jsonb);
  -- friendly: match_id like 'friendly-<uuid>'
  IF v_match_id LIKE 'friendly-%' THEN
    BEGIN
      v_invite_id := substring(v_match_id from 10)::uuid;
      UPDATE friendly_invites
      SET status = 'finished',
          match_result = jsonb_build_object(
            'home_goals', NEW.home_goals,
            'away_goals', NEW.away_goals,
            'events', v_events,
            'home_name', NEW.home_team,
            'away_name', NEW.away_team,
            'simulated', true,
            'auto_simulated', false,
            'live_match_id', NEW.id
          )
      WHERE id = v_invite_id
        AND (status = 'accepted' OR match_result IS NULL);
    EXCEPTION WHEN OTHERS THEN
      -- bad uuid, ignore
      NULL;
    END;
    RETURN NEW;
  END IF;
  -- try as uuid for league_matches / custom_tournament_matches
  BEGIN
    UPDATE league_matches
    SET home_goals = NEW.home_goals,
        away_goals = NEW.away_goals,
        status = 'finished',
        played_at = COALESCE(played_at, now()),
        match_data = COALESCE(match_data, '{}'::jsonb) || jsonb_build_object(
          'events', v_events,
          'simulated', true,
          'auto_simulated', false,
          'live_match_id', NEW.id,
          'home_name', NEW.home_team,
          'away_name', NEW.away_team
        )
    WHERE id::text = v_match_id
      AND status = 'scheduled';
    UPDATE custom_tournament_matches
    SET home_goals = NEW.home_goals,
        away_goals = NEW.away_goals,
        status = 'finished',
        played_at = COALESCE(played_at, now()),
        match_data = COALESCE(match_data, '{}'::jsonb) || jsonb_build_object(
          'events', v_events,
          'simulated', true,
          'auto_simulated', false,
          'live_match_id', NEW.id,
          'home_name', NEW.home_team,
          'away_name', NEW.away_team
        )
    WHERE id::text = v_match_id
      AND status = 'scheduled';
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_propagate_live_match_result ON public.live_matches;
CREATE TRIGGER trg_propagate_live_match_result
AFTER INSERT OR UPDATE OF status ON public.live_matches
FOR EACH ROW
EXECUTE FUNCTION public.propagate_live_match_result();
CREATE OR REPLACE FUNCTION public.admin_add_money_to_club(
  p_target_user_id uuid,
  p_amount bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_admin uuid := auth.uid();
  v_is_admin boolean;
  v_save_id uuid;
  v_state jsonb;
  v_current bigint;
  v_new bigint;
  v_club_name text;
BEGIN
  IF v_admin IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;
  SELECT public.has_role(v_admin, 'admin'::app_role) INTO v_is_admin;
  IF NOT COALESCE(v_is_admin, false) THEN
    RAISE EXCEPTION 'Acesso negado: requer admin' USING ERRCODE = '42501';
  END IF;
  IF p_amount IS NULL OR p_amount = 0 THEN
    RAISE EXCEPTION 'Valor inválido' USING ERRCODE = '22023';
  END IF;
  IF abs(p_amount) > 1000000000 THEN
    RAISE EXCEPTION 'Valor excede o limite (±R$ 1B por operação)' USING ERRCODE = '22023';
  END IF;
  -- Lock atômico na linha do save
  SELECT id, game_state INTO v_save_id, v_state
  FROM public.game_saves
  WHERE user_id = p_target_user_id
  FOR UPDATE;
  IF v_save_id IS NULL THEN
    RAISE EXCEPTION 'Save do clube não encontrado' USING ERRCODE = 'P0002';
  END IF;
  v_current := COALESCE((v_state->'club'->>'budget')::bigint, 0);
  v_new := GREATEST(0, v_current + p_amount);
  v_club_name := COALESCE(v_state->'club'->>'name', 'Clube');
  v_state := jsonb_set(
    v_state,
    '{club,budget}',
    to_jsonb(v_new),
    true
  );
  UPDATE public.game_saves
  SET game_state = v_state
  WHERE id = v_save_id;
  -- Log auditável
  INSERT INTO public.admin_logs (admin_id, action, target_user_id, details)
  VALUES (
    v_admin,
    'add_money',
    p_target_user_id,
    jsonb_build_object(
      'amount', p_amount,
      'previous_budget', v_current,
      'new_budget', v_new,
      'club_name', v_club_name
    )
  );
  -- Notifica o jogador
  INSERT INTO public.user_notifications (user_id, icon, type, title, message)
  VALUES (
    p_target_user_id,
    CASE WHEN p_amount > 0 THEN '💰' ELSE '⚠️' END,
    CASE WHEN p_amount > 0 THEN 'success' ELSE 'warning' END,
    CASE WHEN p_amount > 0 THEN 'Crédito da Administração' ELSE 'Ajuste da Administração' END,
    'Saldo ajustado em R$ ' || p_amount::text || '. Novo saldo: R$ ' || v_new::text || '.'
  );
  RETURN jsonb_build_object(
    'success', true,
    'club_name', v_club_name,
    'previous_budget', v_current,
    'new_budget', v_new,
    'delta', p_amount
  );
END;
$$;
REVOKE ALL ON FUNCTION public.admin_add_money_to_club(uuid, bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_add_money_to_club(uuid, bigint) TO authenticated;
CREATE OR REPLACE FUNCTION public.world_leagues_redistribute_kickoff()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_league record;
  v_idx int := 0;
  v_new_hour int;
  v_updated_leagues int := 0;
  v_updated_matches int := 0;
  v_match_count int;
BEGIN
  -- D1 entre 16..22 (rotaciona); divisões 2..4 mantêm seus horários
  FOR v_league IN
    SELECT id, division, kickoff_hour
    FROM world_leagues
    WHERE division = 1
    ORDER BY country
  LOOP
    v_new_hour := 16 + (v_idx % 7); -- 16,17,18,19,20,21,22
    v_idx := v_idx + 1;
    IF v_new_hour <> v_league.kickoff_hour THEN
      UPDATE world_leagues
        SET kickoff_hour = v_new_hour, updated_at = now()
        WHERE id = v_league.id;
      v_updated_leagues := v_updated_leagues + 1;
    END IF;
    -- Reagenda partidas futuras (status='scheduled') para o novo horário
    UPDATE world_matches
      SET kickoff_at = date_trunc('day', kickoff_at AT TIME ZONE 'America/Sao_Paulo')
                       AT TIME ZONE 'America/Sao_Paulo'
                       + make_interval(hours => v_new_hour)
      WHERE league_id = v_league.id
        AND status = 'scheduled';
    GET DIAGNOSTICS v_match_count = ROW_COUNT;
    v_updated_matches := v_updated_matches + v_match_count;
  END LOOP;
  RETURN jsonb_build_object(
    'ok', true,
    'updated_leagues', v_updated_leagues,
    'updated_matches', v_updated_matches
  );
END;
$$;
REVOKE ALL ON FUNCTION public.world_leagues_redistribute_kickoff() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.world_leagues_redistribute_kickoff() TO authenticated, service_role;
ALTER TABLE public.world_leagues
  ADD COLUMN IF NOT EXISTS kickoff_minute INTEGER NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.world_leagues_kickoff_for(
  _country TEXT,
  _division INTEGER
) RETURNS TABLE(h INTEGER, m INTEGER)
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  base_hour INTEGER;
  hash_val INTEGER;
BEGIN
  -- Hash estável do país → janela 16..22 (7 slots)
  hash_val := abs(hashtext(_country));
  base_hour := 16 + (hash_val % 7);
  IF _division = 1 THEN
    h := base_hour; m := 0;
  ELSIF _division = 2 THEN
    h := base_hour; m := 30;
  ELSIF _division = 3 THEN
    h := GREATEST(12, base_hour - 1); m := 0;
  ELSIF _division = 4 THEN
    h := LEAST(22, base_hour + 1); m := 0;
  ELSE
    -- Várzea / outros
    h := GREATEST(12, base_hour - 2); m := 0;
  END IF;
  RETURN NEXT;
END;
$$;
CREATE OR REPLACE FUNCTION public.world_leagues_apply_fixed_kickoff()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  lg RECORD;
  k RECORD;
  leagues_updated INTEGER := 0;
  matches_updated INTEGER := 0;
  m_count INTEGER;
BEGIN
  FOR lg IN
    SELECT id, country, division, season
    FROM public.world_leagues
    WHERE status IN ('pending', 'in_progress')
  LOOP
    SELECT * INTO k FROM public.world_leagues_kickoff_for(lg.country, lg.division);
    UPDATE public.world_leagues
      SET kickoff_hour = k.h, kickoff_minute = k.m
      WHERE id = lg.id;
    leagues_updated := leagues_updated + 1;
    -- Recalcula kickoff_at de world_matches mantendo a data BRT
    -- BRT = UTC-3 → UTC = BRT + 3h
    WITH upd AS (
      UPDATE public.world_matches wm
      SET kickoff_at = (
        date_trunc('day', wm.kickoff_at AT TIME ZONE 'America/Sao_Paulo')
          + make_interval(hours => k.h, mins => k.m)
      ) AT TIME ZONE 'America/Sao_Paulo'
      WHERE wm.league_id = lg.id
        AND wm.season = lg.season
        AND wm.status = 'scheduled'
      RETURNING 1
    )
    SELECT COUNT(*) INTO m_count FROM upd;
    matches_updated := matches_updated + COALESCE(m_count, 0);
  END LOOP;
  RETURN jsonb_build_object(
    'leagues_updated', leagues_updated,
    'matches_updated', matches_updated,
    'applied_at', now()
  );
END;
$$;
SELECT public.world_leagues_apply_fixed_kickoff();
CREATE OR REPLACE FUNCTION public.auto_enroll_player_in_world_league()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_country text;
  v_club_name text;
  v_logo text;
  v_league_id uuid;
  v_league_name text;
  v_kickoff_h int;
  v_kickoff_m int;
  v_horario text;
  v_team_id uuid;
BEGIN
  -- já inscrito? sai
  IF EXISTS (SELECT 1 FROM world_league_teams WHERE user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;
  v_country   := COALESCE(NEW.club_data->'club'->>'country', 'BR');
  v_club_name := COALESCE(NEW.club_data->'club'->>'name', 'Meu Clube');
  v_logo      := COALESCE(NEW.club_data->'club'->>'logo', '🛡️');
  -- precisa de clube criado para inscrever
  IF NEW.club_data->'club'->>'name' IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id, league_name, kickoff_hour, COALESCE(kickoff_minute,0)
    INTO v_league_id, v_league_name, v_kickoff_h, v_kickoff_m
  FROM world_leagues
  WHERE country = v_country AND division = 1 AND status = 'in_progress'
  ORDER BY season DESC
  LIMIT 1;
  IF v_league_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT id INTO v_team_id
  FROM world_league_teams
  WHERE league_id = v_league_id AND is_bot = true
  ORDER BY COALESCE(bot_strength, 50) ASC, created_at ASC
  LIMIT 1
  FOR UPDATE SKIP LOCKED;
  IF v_team_id IS NULL THEN
    RETURN NEW;
  END IF;
  UPDATE world_league_teams
     SET user_id = NEW.user_id,
         is_bot = false,
         bot_strength = NULL,
         club_name = v_club_name,
         club_logo = v_logo,
         updated_at = now()
   WHERE id = v_team_id;
  v_horario := lpad(v_kickoff_h::text,2,'0') || ':' || lpad(v_kickoff_m::text,2,'0');
  INSERT INTO user_notifications (user_id, type, title, message, icon, data)
  SELECT NEW.user_id, 'league_enrolled',
         'Inscrição confirmada na liga',
         'Você foi inscrito na liga ' || v_league_name || '. Horário dos jogos: ' || v_horario || ' (BRT). Boa sorte na competição!',
         '🏆',
         jsonb_build_object('league_id', v_league_id, 'league_name', v_league_name, 'kickoff', v_horario)
  WHERE NOT EXISTS (
    SELECT 1 FROM user_notifications
    WHERE user_id = NEW.user_id
      AND type = 'league_enrolled'
      AND data->>'league_id' = v_league_id::text
  );
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_auto_enroll_world_league ON public.game_saves;
CREATE TRIGGER trg_auto_enroll_world_league
AFTER INSERT OR UPDATE OF club_data ON public.game_saves
FOR EACH ROW
EXECUTE FUNCTION public.auto_enroll_player_in_world_league();
