DELETE FROM world_leagues 
WHERE id IN (
    SELECT id FROM (
        SELECT id, ROW_NUMBER() OVER(PARTITION BY country, division ORDER BY created_at ASC) as rn
        FROM world_leagues
    ) t WHERE rn > 1
