CREATE OR REPLACE FUNCTION public.fix_world_leagues_kickoffs()
RETURNS void AS $$
BEGIN
    -- Série A (D1) -> 19:00
    UPDATE world_leagues SET kickoff_hour = 19, kickoff_minute = 0 WHERE division = 1;
    -- Série B (D2) -> 19:30
    UPDATE world_leagues SET kickoff_hour = 19, kickoff_minute = 30 WHERE division = 2;
    -- Série C (D3) -> 18:00
    UPDATE world_leagues SET kickoff_hour = 18, kickoff_minute = 0 WHERE division = 3;
    -- Série D (D4) -> 20:00
    UPDATE world_leagues SET kickoff_hour = 20, kickoff_minute = 0 WHERE division = 4;
    -- Várzea (D5+) -> 17:00
    UPDATE world_leagues SET kickoff_hour = 17, kickoff_minute = 0 WHERE division >= 5;
    -- Sincronizar kickoff_at em world_matches baseado nos novos horários das ligas
    UPDATE world_matches m
    SET kickoff_at = (m.kickoff_at::date + (l.kickoff_hour || ' hours')::interval + (l.kickoff_minute || ' minutes')::interval)
    FROM world_leagues l
    WHERE m.league_id = l.id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
SELECT fix_world_leagues_kickoffs();
CREATE OR REPLACE VIEW public.world_league_standings AS
WITH team_stats AS (
    -- Ganhos como Mandante
    SELECT 
        home_team_id as team_id,
        league_id,
        COUNT(*) as played,
        SUM(CASE WHEN home_goals > away_goals THEN 1 ELSE 0 END) as wins,
        SUM(CASE WHEN home_goals = away_goals THEN 1 ELSE 0 END) as draws,
        SUM(CASE WHEN home_goals < away_goals THEN 1 ELSE 0 END) as losses,
        SUM(home_goals) as goals_for,
        SUM(away_goals) as goals_against
    FROM world_matches
    WHERE status = 'finished'
    GROUP BY home_team_id, league_id
    
    UNION ALL
    
    -- Ganhos como Visitante
    SELECT 
        away_team_id as team_id,
        league_id,
        COUNT(*) as played,
        SUM(CASE WHEN away_goals > home_goals THEN 1 ELSE 0 END) as wins,
        SUM(CASE WHEN away_goals = home_goals THEN 1 ELSE 0 END) as draws,
        SUM(CASE WHEN away_goals < home_goals THEN 1 ELSE 0 END) as losses,
        SUM(away_goals) as goals_for,
        SUM(home_goals) as goals_against
    FROM world_matches
    WHERE status = 'finished'
    GROUP BY away_team_id, league_id
)
SELECT 
    team_id,
    league_id,
    SUM(played) as mp,
    SUM(wins) as w,
    SUM(draws) as d,
    SUM(losses) as l,
    SUM(goals_for) as gf,
    SUM(goals_against) as ga,
    SUM(goals_for - goals_against) as gd,
    SUM(wins * 3 + draws) as pts
FROM team_stats
GROUP BY team_id, league_id;
CREATE OR REPLACE FUNCTION public.sync_league_state(_user_id uuid)
RETURNS jsonb AS $$
DECLARE
    v_league_id uuid;
    v_current_day int;
    v_new_matchday int;
BEGIN
    -- Pegar a liga do usuário
    SELECT league_id INTO v_league_id FROM world_league_teams WHERE user_id = _user_id LIMIT 1;
    
    IF v_league_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not in a league');
    END IF;
    -- Dia atual do mês (assumindo que dia 1 = rodada 1)
    v_current_day := EXTRACT(DAY FROM now());
    
    -- Simular jogos atrasados (se houver algum status NULL da rodada 1 ou anterior ao dia atual)
    UPDATE world_matches 
    SET status = 'finished',
        home_goals = floor(random() * 4),
        away_goals = floor(random() * 3),
        match_data = jsonb_set(COALESCE(match_data, '{}'::jsonb), '{auto_simulated}', 'true')
    WHERE league_id = v_league_id 
      AND kickoff_at < now() - interval '1 hour'
      AND (status IS NULL OR status != 'finished');
    -- Atualizar a rodada da liga baseada no dia atual (se já passou do horário do jogo de hoje)
    -- Se hoje for dia 2, e o jogo de hoje (19h) ainda não aconteceu, a current_matchday deve ser 2.
    -- O sistema de simulação cuidará de rodar o jogo no horário.
    UPDATE world_leagues 
    SET current_matchday = v_current_day
    WHERE id = v_league_id;
    RETURN jsonb_build_object('success', true, 'matchday', v_current_day);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
UPDATE world_matches 
SET status = 'finished',
    home_goals = floor(random() * 4),
    away_goals = floor(random() * 3),
    match_data = jsonb_set(COALESCE(match_data, '{}'::jsonb), '{auto_simulated}', 'true')
WHERE kickoff_at < now() - interval '2 hours' -- Jogos de ontem/hoje cedo
  AND (status IS NULL OR status != 'finished');
UPDATE world_leagues 
SET current_matchday = EXTRACT(DAY FROM now());
ALTER TABLE world_matches DROP CONSTRAINT IF EXISTS world_matches_matchday_check;
ALTER TABLE world_matches ADD CONSTRAINT world_matches_matchday_check CHECK (matchday >= 1 AND matchday <= 38);
UPDATE world_leagues SET kickoff_hour = 19, kickoff_minute = 0 WHERE division = 1;
UPDATE world_leagues SET kickoff_hour = 19, kickoff_minute = 30 WHERE division = 2;
UPDATE world_leagues SET kickoff_hour = 18, kickoff_minute = 0 WHERE division = 3;
UPDATE world_leagues SET kickoff_hour = 20, kickoff_minute = 0 WHERE division = 4;
CREATE OR REPLACE FUNCTION public.initialize_world_league(p_league_id UUID)
RETURNS void AS $$
DECLARE
    v_teams UUID[];
    v_n INT;
    v_kickoff_hour INT;
    v_kickoff_minute INT;
    v_season INT;
    v_start_date DATE;
    v_home UUID;
    v_away UUID;
    v_home_idx INT;
    v_away_idx INT;
    v_matchday INT;
    v_kickoff TIMESTAMP WITH TIME ZONE;
    v_today_utc TIMESTAMP WITH TIME ZONE := now();
BEGIN
    -- Get league info
    SELECT kickoff_hour, kickoff_minute, season 
    INTO v_kickoff_hour, v_kickoff_minute, v_season
    FROM world_leagues WHERE id = p_league_id;
    -- Get teams (ordered for deterministic output)
    SELECT array_agg(id) INTO v_teams 
    FROM (SELECT id FROM world_league_teams WHERE league_id = p_league_id ORDER BY id) t;
    
    v_n := array_length(v_teams, 1);
    IF v_n IS NULL OR v_n < 2 THEN
        RETURN;
    END IF;
    -- Reset existing matches
    DELETE FROM world_matches WHERE league_id = p_league_id AND season = v_season;
    -- Start date: Yesterday so matchday 1 can be treated as finished/ongoing
    v_start_date := (v_today_utc AT TIME ZONE 'UTC' - INTERVAL '1 day' - INTERVAL '3 hours')::date;
    -- Berger Algorithm for Round Robin
    -- N-1 rounds per half. For 20 teams, 19 rounds.
    FOR r IN 0..(v_n - 2) LOOP
        FOR i IN 0..(v_n/2 - 1) LOOP
            -- Determine indices using Berger rotation
            IF i = 0 THEN
                v_home_idx := 0;
                v_away_idx := (v_n - 1 - r) % (v_n - 1) + 1;
            ELSE
                v_home_idx := (i + r) % (v_n - 1) + 1;
                v_away_idx := (v_n - 1 - i + r) % (v_n - 1) + 1;
            END IF;
            v_home := v_teams[v_home_idx + 1];
            v_away := v_teams[v_away_idx + 1];
            -- Swap home/away for variety in the first half
            IF r % 2 = 1 THEN
                DECLARE temp UUID := v_home; BEGIN v_home := v_away; v_away := temp; END;
            END IF;
            -- Turno (Matchdays 1 to N-1, e.g., 1-19)
            v_matchday := r + 1;
            v_kickoff := (v_start_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            INSERT INTO world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_home, v_away, v_kickoff, 'scheduled');
            -- Returno (Matchdays N to 2N-2, e.g., 20-38)
            v_matchday := r + v_n; -- This will be 20 to 38 for N=20
            v_kickoff := (v_start_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            -- Swap for the return leg
            INSERT INTO world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_away, v_home, v_kickoff, 'scheduled');
        END LOOP;
    END LOOP;
    -- Update league metadata
    UPDATE world_leagues 
    SET status = 'in_progress', 
        current_matchday = 1, 
        total_matchdays = (v_n - 1) * 2,
        season_started_at = v_today_utc
    WHERE id = p_league_id;
    -- Simular Rodada 1 retroativamente
    UPDATE world_matches 
    SET status = 'finished',
        home_goals = floor(random() * 4),
        away_goals = floor(random() * 3),
        match_data = jsonb_set(COALESCE(match_data, '{}'::jsonb), '{auto_simulated}', 'true')
    WHERE league_id = p_league_id AND matchday = 1;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.trg_auto_init_world_league_func()
RETURNS TRIGGER AS $$
DECLARE
    v_count INT;
    v_slots INT;
BEGIN
    SELECT count(*) INTO v_count FROM world_league_teams WHERE league_id = NEW.league_id;
    SELECT total_slots INTO v_slots FROM world_leagues WHERE id = NEW.league_id;
    IF v_count >= v_slots AND v_slots >= 20 THEN
        -- Only initialize if no matches exist or we are forcing a reset
        IF NOT EXISTS (SELECT 1 FROM world_matches WHERE league_id = NEW.league_id LIMIT 1) THEN
            PERFORM public.initialize_world_league(NEW.league_id);
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS trg_auto_init_world_league ON world_league_teams;
CREATE TRIGGER trg_auto_init_world_league
AFTER INSERT OR UPDATE ON world_league_teams
FOR EACH ROW EXECUTE FUNCTION public.trg_auto_init_world_league_func();
CREATE OR REPLACE FUNCTION public.validate_world_league(p_league_id UUID)
RETURNS jsonb AS $$
DECLARE
    v_match_count INT;
    v_team_count INT;
BEGIN
    SELECT count(*) INTO v_team_count FROM world_league_teams WHERE league_id = p_league_id;
    SELECT count(*) INTO v_match_count FROM world_matches WHERE league_id = p_league_id;
    
    -- If 20 teams and not 380 matches, fix it
    IF v_team_count = 20 AND v_match_count < 380 THEN
        PERFORM public.initialize_world_league(p_league_id);
        RETURN jsonb_build_object('status', 'fixed', 'new_match_count', 380);
    END IF;
    
    RETURN jsonb_build_object('status', 'valid', 'match_count', v_match_count);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT id FROM world_leagues 
        WHERE total_slots = 20 
        AND (SELECT count(*) FROM world_league_teams WHERE league_id = world_leagues.id) = 20
        AND (SELECT count(*) FROM world_matches WHERE league_id = world_leagues.id) < 380
    ) LOOP
        PERFORM public.initialize_world_league(r.id);
    END LOOP;
END;
$$;
CREATE OR REPLACE FUNCTION public.initialize_world_league(p_league_id UUID)
RETURNS void AS $$
DECLARE
    v_teams UUID[];
    v_n INT;
    v_kickoff_hour INT;
    v_kickoff_minute INT;
    v_season INT;
    v_start_date DATE;
    v_home UUID;
    v_away UUID;
    v_home_idx INT;
    v_away_idx INT;
    v_matchday INT;
    v_kickoff TIMESTAMP WITH TIME ZONE;
    v_today_utc TIMESTAMP WITH TIME ZONE := now();
BEGIN
    -- Get league info
    SELECT kickoff_hour, kickoff_minute, season 
    INTO v_kickoff_hour, v_kickoff_minute, v_season
    FROM world_leagues WHERE id = p_league_id;
    -- Get teams
    SELECT array_agg(id) INTO v_teams 
    FROM (SELECT id FROM world_league_teams WHERE league_id = p_league_id ORDER BY id) t;
    
    v_n := array_length(v_teams, 1);
    IF v_n IS NULL OR v_n < 2 THEN
        RETURN;
    END IF;
    -- Force delete all matches for this league (Global Reset)
    DELETE FROM world_matches WHERE league_id = p_league_id;
    -- Start date: Yesterday
    v_start_date := (v_today_utc AT TIME ZONE 'UTC' - INTERVAL '1 day' - INTERVAL '3 hours')::date;
    -- Berger Algorithm (38 rounds for 20 teams)
    FOR r in 0..(v_n - 2) LOOP
        FOR i in 0..(v_n/2 - 1) LOOP
            IF i = 0 THEN
                v_home_idx := 0;
                v_away_idx := (v_n - 1 - r) % (v_n - 1) + 1;
            ELSE
                v_home_idx := (i + r) % (v_n - 1) + 1;
                v_away_idx := (v_n - 1 - i + r) % (v_n - 1) + 1;
            END IF;
            v_home := v_teams[v_home_idx + 1];
            v_away := v_teams[v_away_idx + 1];
            IF r % 2 = 1 THEN
                DECLARE temp UUID := v_home; BEGIN v_home := v_away; v_away := temp; END;
            END IF;
            -- Turno
            v_matchday := r + 1;
            v_kickoff := (v_start_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            INSERT INTO world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_home, v_away, v_kickoff, 'scheduled');
            -- Returno
            v_matchday := r + v_n;
            v_kickoff := (v_start_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            INSERT INTO world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_away, v_home, v_kickoff, 'scheduled');
        END LOOP;
    END LOOP;
    -- Metadata
    UPDATE world_leagues 
    SET status = 'in_progress', 
        current_matchday = 1, 
        total_matchdays = (v_n - 1) * 2,
        season_started_at = v_today_utc
    WHERE id = p_league_id;
    -- Auto-Simulate Matchday 1
    UPDATE world_matches 
    SET status = 'finished',
        home_goals = floor(random() * 4),
        away_goals = floor(random() * 3),
        match_data = jsonb_set(COALESCE(match_data, '{}'::jsonb), '{auto_simulated}', 'true')
    WHERE league_id = p_league_id AND matchday = 1;
    RAISE NOTICE 'League % initialized with 380 matches and matchday 1 simulated.', p_league_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.fix_league_forcefully(p_league_id UUID)
RETURNS jsonb AS $$
DECLARE
    v_team_count INT;
BEGIN
    SELECT count(*) INTO v_team_count FROM world_league_teams WHERE league_id = p_league_id;
    
    IF v_team_count = 20 THEN
        PERFORM public.initialize_world_league(p_league_id);
        RETURN jsonb_build_object('success', true, 'message', 'League fixed: 380 matches generated.');
    ELSE
        RETURN jsonb_build_object('success', false, 'message', 'League not full (only ' || v_team_count || ' teams).');
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.sync_league_state(_user_id uuid)
RETURNS jsonb AS $$
DECLARE
    v_league_id uuid;
    v_match_count int;
    v_team_count int;
    v_current_day int;
BEGIN
    -- Get user league
    SELECT league_id INTO v_league_id FROM world_league_teams WHERE user_id = _user_id LIMIT 1;
    
    IF v_league_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'User not in a league');
    END IF;
    -- DETECT AND FIX
    SELECT count(*) INTO v_team_count FROM world_league_teams WHERE league_id = v_league_id;
    SELECT count(*) INTO v_match_count FROM world_matches WHERE league_id = v_league_id;
    
    IF v_team_count = 20 AND v_match_count < 380 THEN
        RAISE NOTICE 'Sync: League % is broken (matches: %), fixing...', v_league_id, v_match_count;
        PERFORM public.initialize_world_league(v_league_id);
    END IF;
    -- Update current matchday based on date
    v_current_day := EXTRACT(DAY FROM (now() AT TIME ZONE 'UTC' - INTERVAL '3 hours'));
    IF v_current_day > 38 THEN v_current_day := 38; END IF;
    UPDATE world_leagues SET current_matchday = v_current_day WHERE id = v_league_id;
    -- Auto-finish old scheduled matches
    UPDATE world_matches 
    SET status = 'finished',
        home_goals = floor(random() * 4),
        away_goals = floor(random() * 3),
        match_data = jsonb_set(COALESCE(match_data, '{}'::jsonb), '{auto_simulated}', 'true')
    WHERE league_id = v_league_id 
      AND kickoff_at < now() - interval '1 hour'
      AND status = 'scheduled';
    RETURN jsonb_build_object('success', true, 'league_id', v_league_id, 'matches', (SELECT count(*) FROM world_matches WHERE league_id = v_league_id));
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DROP VIEW IF EXISTS public.world_league_table;
CREATE VIEW public.world_league_table AS
WITH match_results AS (
    -- Results as Home Team
    SELECT 
        home_team_id AS team_id,
        league_id,
        COUNT(*) FILTER (WHERE status = 'finished') as played,
        COUNT(*) FILTER (WHERE status = 'finished' AND home_goals > away_goals) as wins,
        COUNT(*) FILTER (WHERE status = 'finished' AND home_goals = away_goals) as draws,
        COUNT(*) FILTER (WHERE status = 'finished' AND home_goals < away_goals) as losses,
        SUM(COALESCE(home_goals, 0)) FILTER (WHERE status = 'finished') as goals_for,
        SUM(COALESCE(away_goals, 0)) FILTER (WHERE status = 'finished') as goals_against
    FROM public.world_matches
    GROUP BY home_team_id, league_id
    
    UNION ALL
    
    -- Results as Away Team
    SELECT 
        away_team_id AS team_id,
        league_id,
        COUNT(*) FILTER (WHERE status = 'finished') as played,
        COUNT(*) FILTER (WHERE status = 'finished' AND away_goals > home_goals) as wins,
        COUNT(*) FILTER (WHERE status = 'finished' AND away_goals = home_goals) as draws,
        COUNT(*) FILTER (WHERE status = 'finished' AND away_goals < home_goals) as losses,
        SUM(COALESCE(away_goals, 0)) FILTER (WHERE status = 'finished') as goals_for,
        SUM(COALESCE(home_goals, 0)) FILTER (WHERE status = 'finished') as goals_against
    FROM public.world_matches
    GROUP BY away_team_id, league_id
)
SELECT 
    t.team_id,
    t.league_id,
    lt.club_name,
    lt.club_logo,
    SUM(t.played) as mp,
    SUM(t.wins) as w,
    SUM(t.draws) as d,
    SUM(t.losses) as l,
    SUM(t.goals_for) as gf,
    SUM(t.goals_against) as ga,
    SUM(t.goals_for - t.goals_against) as gd,
    SUM(t.wins * 3 + t.draws) as pts
FROM match_results t
JOIN public.world_league_teams lt ON lt.id = t.team_id
GROUP BY t.team_id, t.league_id, lt.club_name, lt.club_logo
ORDER BY pts DESC, gd DESC, gf DESC;
CREATE OR REPLACE FUNCTION public.generate_league_matches(p_league_id UUID)
RETURNS void AS $$
DECLARE
    v_teams UUID[];
    v_n INT;
    v_kickoff_hour INT;
    v_kickoff_minute INT;
    v_season INT;
    v_start_date DATE;
    v_home UUID;
    v_away UUID;
    v_home_idx INT;
    v_away_idx INT;
    v_matchday INT;
    v_kickoff TIMESTAMP WITH TIME ZONE;
BEGIN
    SELECT kickoff_hour, kickoff_minute, season INTO v_kickoff_hour, v_kickoff_minute, v_season
    FROM public.world_leagues WHERE id = p_league_id;
    SELECT array_agg(id) INTO v_teams FROM (SELECT id FROM public.world_league_teams WHERE league_id = p_league_id ORDER BY id) t;
    v_n := array_length(v_teams, 1);
    
    IF v_n != 20 THEN RETURN; END IF;
    DELETE FROM public.world_matches WHERE league_id = p_league_id;
    v_start_date := (now() AT TIME ZONE 'UTC' - INTERVAL '3 hours')::date;
    FOR r in 0..(v_n - 2) LOOP
        FOR i in 0..(v_n/2 - 1) LOOP
            IF i = 0 THEN
                v_home_idx := 0;
                v_away_idx := (v_n - 1 - r) % (v_n - 1) + 1;
            ELSE
                v_home_idx := (i + r) % (v_n - 1) + 1;
                v_away_idx := (v_n - 1 - i + r) % (v_n - 1) + 1;
            END IF;
            v_home := v_teams[v_home_idx + 1];
            v_away := v_teams[v_away_idx + 1];
            IF r % 2 = 1 THEN
                DECLARE temp UUID := v_home; BEGIN v_home := v_away; v_away := temp; END;
            END IF;
            -- Turno (Matchdays 1-19)
            v_matchday := r + 1;
            v_kickoff := (v_start_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_home, v_away, v_kickoff, 'scheduled');
            -- Returno (Matchdays 20-38)
            v_matchday := r + v_n;
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_away, v_home, v_kickoff, 'scheduled');
        END LOOP;
    END LOOP;
    UPDATE public.world_leagues SET status = 'in_progress', current_matchday = 1 WHERE id = p_league_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.simulate_league_matchday(p_league_id UUID, p_matchday INT)
RETURNS void AS $$
BEGIN
    UPDATE public.world_matches
    SET status = 'finished',
        home_goals = floor(random() * 4),
        away_goals = floor(random() * 3),
        match_data = jsonb_build_object('simulated', true, 'simulated_at', now())
    WHERE league_id = p_league_id 
      AND matchday = p_matchday 
      AND status = 'scheduled'
      AND (SELECT is_bot FROM public.world_league_teams WHERE id = home_team_id) = true
      AND (SELECT is_bot FROM public.world_league_teams WHERE id = away_team_id) = true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.check_and_advance_round(p_league_id UUID)
RETURNS void AS $$
DECLARE
    v_current_md INT;
    v_pending INT;
BEGIN
    SELECT current_matchday INTO v_current_md FROM public.world_leagues WHERE id = p_league_id;
    
    SELECT count(*) INTO v_pending 
    FROM public.world_matches 
    WHERE league_id = p_league_id AND matchday = v_current_md AND status = 'scheduled';
    IF v_pending = 0 AND v_current_md < 38 THEN
        UPDATE public.world_leagues SET current_matchday = v_current_md + 1 WHERE id = p_league_id;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.trg_auto_init_league()
RETURNS TRIGGER AS $$
BEGIN
    IF (SELECT count(*) FROM public.world_league_teams WHERE league_id = NEW.league_id) = 20 THEN
        IF NOT EXISTS (SELECT 1 FROM public.world_matches WHERE league_id = NEW.league_id) THEN
            PERFORM public.generate_league_matches(NEW.league_id);
            -- Simulate Matchday 1 immediately if it's bot vs bot
            PERFORM public.simulate_league_matchday(NEW.league_id, 1);
            PERFORM public.check_and_advance_round(NEW.league_id);
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
DROP TRIGGER IF EXISTS trg_auto_init_league ON public.world_league_teams;
CREATE TRIGGER trg_auto_init_league
AFTER INSERT ON public.world_league_teams
FOR EACH ROW EXECUTE FUNCTION public.trg_auto_init_league();
CREATE OR REPLACE FUNCTION public.sync_league_integrity(_user_id UUID)
RETURNS jsonb AS $$
DECLARE
    v_league_id UUID;
    v_team_count INT;
    v_match_count INT;
BEGIN
    SELECT league_id INTO v_league_id FROM public.world_league_teams WHERE user_id = _user_id LIMIT 1;
    IF v_league_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'No league'); END IF;
    SELECT count(*) INTO v_team_count FROM public.world_league_teams WHERE league_id = v_league_id;
    SELECT count(*) INTO v_match_count FROM public.world_matches WHERE league_id = v_league_id;
    IF v_team_count = 20 AND v_match_count < 380 THEN
        PERFORM public.generate_league_matches(v_league_id);
        PERFORM public.simulate_league_matchday(v_league_id, 1);
        PERFORM public.check_and_advance_round(v_league_id);
        RETURN jsonb_build_object('ok', true, 'action', 'regenerated');
    END IF;
    RETURN jsonb_build_object('ok', true, 'action', 'none');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.generate_league_matches_v2(p_league_id UUID)
RETURNS void AS $$
DECLARE
    v_teams UUID[];
    v_n INT;
    v_home UUID;
    v_away UUID;
    v_home_idx INT;
    v_away_idx INT;
    v_matchday INT;
    v_season INT;
    v_kickoff_hour INT;
    v_kickoff_minute INT;
    v_base_date DATE;
    v_kickoff TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Get league metadata
    SELECT season, kickoff_hour, kickoff_minute 
    INTO v_season, v_kickoff_hour, v_kickoff_minute 
    FROM public.world_leagues WHERE id = p_league_id;
    
    -- Get team IDs
    SELECT array_agg(id) INTO v_teams 
    FROM (SELECT id FROM public.world_league_teams WHERE league_id = p_league_id ORDER BY id) t;
    
    v_n := array_length(v_teams, 1);
    
    IF v_n != 20 THEN RETURN; END IF;
    -- Clear existing matches
    DELETE FROM public.world_matches WHERE league_id = p_league_id AND season = v_season;
    -- Base date: Start of the current month
    v_base_date := date_trunc('month', now())::date;
    -- Berger Algorithm for 38 rounds
    FOR r in 0..(v_n - 2) LOOP
        FOR i in 0..(v_n/2 - 1) LOOP
            IF i = 0 THEN
                v_home_idx := 0;
                v_away_idx := (v_n - 1 - r) % (v_n - 1) + 1;
            ELSE
                v_home_idx := (i + r) % (v_n - 1) + 1;
                v_away_idx := (v_n - 1 - i + r) % (v_n - 1) + 1;
            END IF;
            v_home := v_teams[v_home_idx + 1];
            v_away := v_teams[v_away_idx + 1];
            IF r % 2 = 1 THEN
                DECLARE temp UUID := v_home; BEGIN v_home := v_away; v_away := temp; END;
            END IF;
            -- Turno (Matchdays 1-19)
            v_matchday := r + 1;
            v_kickoff := (v_base_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_home, v_away, v_kickoff, 'scheduled');
            -- Returno (Matchdays 20-38)
            v_matchday := r + v_n;
            v_kickoff := (v_base_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (v_kickoff_hour || ' hours')::interval + (v_kickoff_minute || ' minutes')::interval + INTERVAL '3 hours';
            
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_away, v_home, v_kickoff, 'scheduled');
        END LOOP;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT l.id FROM public.world_leagues l
        JOIN (SELECT league_id, count(*) as cnt FROM public.world_league_teams GROUP BY league_id) t ON t.league_id = l.id
        WHERE t.cnt = 20
    ) LOOP
        PERFORM public.generate_league_matches_v2(r.id);
    END LOOP;
END;
$$;
UPDATE public.world_leagues 
SET total_slots = 16, 
    total_matchdays = 30;
CREATE OR REPLACE FUNCTION public.generate_league_matches_v2(p_league_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_teams UUID[];
    v_n INT;
    v_home UUID;
    v_away UUID;
    v_home_idx INT;
    v_away_idx INT;
    v_matchday INT;
    v_season INT;
    v_kickoff_hour INT;
    v_kickoff_minute INT;
    v_base_date DATE;
    v_kickoff TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Get league metadata
    SELECT season, kickoff_hour, kickoff_minute 
    INTO v_season, v_kickoff_hour, v_kickoff_minute 
    FROM public.world_leagues WHERE id = p_league_id;
    
    -- Get team IDs (up to 16)
    SELECT array_agg(id) INTO v_teams 
    FROM (SELECT id FROM public.world_league_teams WHERE league_id = p_league_id ORDER BY id LIMIT 16) t;
    
    v_n := array_length(v_teams, 1);
    
    -- Ensure we have exactly 16 teams as per new requirements
    IF v_n != 16 THEN 
        RAISE NOTICE 'League % has % teams, expected 16', p_league_id, v_n;
        RETURN; 
    END IF;
    -- Clear existing scheduled matches for current season
    DELETE FROM public.world_matches WHERE league_id = p_league_id AND season = v_season AND status = 'scheduled';
    -- Base date: Today, or start of month if preferred. JSON says "duracao_dias: 30".
    -- We'll start from tomorrow to avoid immediate conflicts.
    v_base_date := current_date + interval '1 day';
    -- Berger Algorithm for 16 teams (15 rounds ida + 15 rounds volta = 30 rounds)
    FOR r in 0..(v_n - 2) LOOP
        FOR i in 0..(v_n/2 - 1) LOOP
            IF i = 0 THEN
                v_home_idx := 0;
                v_away_idx := (v_n - 1 - r) % (v_n - 1) + 1;
            ELSE
                v_home_idx := (i + r) % (v_n - 1) + 1;
                v_away_idx := (v_n - 1 - i + r) % (v_n - 1) + 1;
            END IF;
            v_home := v_teams[v_home_idx + 1];
            v_away := v_teams[v_away_idx + 1];
            -- Balance home/away
            IF r % 2 = 1 THEN
                DECLARE temp UUID := v_home; BEGIN v_home := v_away; v_away := temp; END;
            END IF;
            -- Turno (Matchdays 1-15)
            v_matchday := r + 1;
            v_kickoff := (v_base_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (COALESCE(v_kickoff_hour, 19) || ' hours')::interval + (COALESCE(v_kickoff_minute, 0) || ' minutes')::interval;
            
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_home, v_away, v_kickoff, 'scheduled');
            -- Returno (Matchdays 16-30)
            v_matchday := r + v_n; -- (e.g. 0 + 16 = 16, 14 + 16 = 30)
            v_kickoff := (v_base_date + (v_matchday - 1) * INTERVAL '1 day')::timestamp + (COALESCE(v_kickoff_hour, 19) || ' hours')::interval + (COALESCE(v_kickoff_minute, 0) || ' minutes')::interval;
            
            INSERT INTO public.world_matches (league_id, season, matchday, home_team_id, away_team_id, kickoff_at, status)
            VALUES (p_league_id, v_season, v_matchday, v_away, v_home, v_kickoff, 'scheduled');
        END LOOP;
    END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.rebuild_all_leagues_v3()
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT id FROM public.world_leagues LOOP
        PERFORM public.generate_league_matches_v2(r.id);
    END LOOP;
END;
$$;
