        COUNT(*) filter (where status = 'played') as played,
        COUNT(*) filter (where status = 'played' and away_goals > home_goals) as wins,
        COUNT(*) filter (where status = 'played' and away_goals = home_goals) as draws,
        COUNT(*) filter (where status = 'played' and away_goals < home_goals) as losses,
        SUM(COALESCE(away_goals, 0)) as goals_for,
        SUM(COALESCE(home_goals, 0)) as goals_against
    FROM public.league_matches
    GROUP BY league_id, away_user_id
),
aggregated_stats AS (
    SELECT 
        league_id,
        team_id,
        SUM(played) as played,
        SUM(wins) as wins,
        SUM(draws) as draws,
        SUM(losses) as losses,
        SUM(goals_for) as goals_for,
        SUM(goals_against) as goals_against,
        (SUM(wins) * 3 + SUM(draws)) as points,
        (SUM(goals_for) - SUM(goals_against)) as goals_diff
    FROM team_stats
    GROUP BY league_id, team_id
)
SELECT 
    m.id,
    m.league_id,
    m.user_id,
    m.club_name,
    m.club_logo,
    m.reputation,
    m.budget,
    m.joined_at,
    s.played,
    s.wins,
    s.draws,
    s.losses,
    s.goals_for,
    s.goals_against,
    s.points,
    s.goals_diff,
    ROW_NUMBER() OVER(PARTITION BY s.league_id ORDER BY s.points DESC, s.goals_diff DESC, s.goals_for DESC) as position
FROM aggregated_stats s
JOIN public.league_members m ON s.team_id = m.id;
DROP FUNCTION IF EXISTS public.generate_league_calendar(uuid);
DROP FUNCTION IF EXISTS public.ensure_league_full(uuid);
DROP FUNCTION IF EXISTS public.get_division_start_time(integer);
ALTER TABLE public.multiplayer_leagues 
ADD COLUMN IF NOT EXISTS division_level INTEGER DEFAULT 1,
ALTER COLUMN max_members SET DEFAULT 16;
CREATE OR REPLACE FUNCTION public.ensure_league_full(target_league_id UUID)
RETURNS VOID AS $$
DECLARE
    current_count INTEGER;
    needed INTEGER;
BEGIN
    SELECT COUNT(*) INTO current_count FROM public.league_members WHERE league_id = target_league_id;
    
    IF current_count < 16 THEN
        needed := 16 - current_count;
        -- Add bots
        FOR i IN 1..needed LOOP
            INSERT INTO public.league_members (league_id, team_name, is_bot, points, played, wins, draws, losses, goals_for, goals_against)
            VALUES (target_league_id, 'Bot Team ' || substr(gen_random_uuid()::text, 1, 8), true, 0, 0, 0, 0, 0, 0, 0);
        END LOOP;
    ELSIF current_count > 16 THEN
        -- Remove extra members (prioritize bots, then worst performing)
        DELETE FROM public.league_members 
        WHERE id IN (
            SELECT id FROM public.league_members 
            WHERE league_id = target_league_id 
            ORDER BY is_bot DESC, points ASC, (goals_for - goals_against) ASC
            LIMIT (current_count - 16)
        );
    END IF;
END;
$$ LANGUAGE plpgsql;
CREATE TABLE IF NOT EXISTS public.league_player_stats (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    league_id UUID REFERENCES public.multiplayer_leagues(id) ON DELETE CASCADE,
    member_id UUID REFERENCES public.league_members(id) ON DELETE CASCADE,
    player_name TEXT NOT NULL,
    team_name TEXT NOT NULL,
    goals INTEGER DEFAULT 0,
    assists INTEGER DEFAULT 0,
    total_rating DECIMAL(10, 2) DEFAULT 0,
    matches_played INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_player_stats_league ON public.league_player_stats(league_id);
CREATE OR REPLACE FUNCTION public.get_division_start_time(div_level INTEGER)
RETURNS TIME AS $$
BEGIN
    RETURN CASE 
        WHEN div_level = 1 THEN '19:00:00'::TIME
        WHEN div_level = 2 THEN '20:00:00'::TIME
        WHEN div_level = 3 THEN '21:00:00'::TIME
        ELSE '22:00:00'::TIME
    END;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.generate_league_calendar(target_league_id UUID)
RETURNS VOID AS $$
DECLARE
    team_ids UUID[];
    match_time_fixed TIME;
    div_level INTEGER;
    start_date DATE := CURRENT_DATE;
    current_match_time TIMESTAMP;
    i INTEGER;
    j INTEGER;
    home_idx INTEGER;
    away_idx INTEGER;
    temp_id UUID;
BEGIN
    PERFORM public.ensure_league_full(target_league_id);
    DELETE FROM public.league_matches WHERE league_id = target_league_id;
    
    SELECT ARRAY_AGG(id) INTO team_ids FROM (
        SELECT id FROM public.league_members WHERE league_id = target_league_id ORDER BY id
    ) t;
    
    SELECT COALESCE(division_level, 1) INTO div_level FROM public.multiplayer_leagues WHERE id = target_league_id;
    match_time_fixed := public.get_division_start_time(div_level);
    
    FOR i IN 1..15 LOOP 
        FOR j IN 1..8 LOOP 
            home_idx := j;
            away_idx := 16 - j + 1;
            
            -- Round i
            current_match_time := (start_date + (i - 1) * INTERVAL '1 day')::TIMESTAMP + match_time_fixed;
            INSERT INTO public.league_matches (league_id, round, home_team_id, away_team_id, match_time, status)
            VALUES (target_league_id, i, team_ids[home_idx], team_ids[away_idx], current_match_time, 'scheduled');
            
            -- Round i+15
            current_match_time := (start_date + (i + 14) * INTERVAL '1 day')::TIMESTAMP + match_time_fixed;
            INSERT INTO public.league_matches (league_id, round, home_team_id, away_team_id, match_time, status)
            VALUES (target_league_id, i + 15, team_ids[away_idx], team_ids[home_idx], current_match_time, 'scheduled');
        END LOOP;
        
        temp_id := team_ids[16];
        FOR j IN REVERSE 16..3 LOOP
            team_ids[j] := team_ids[j-1];
        END LOOP;
        team_ids[2] := temp_id;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
DROP FUNCTION IF EXISTS public.generate_league_calendar(UUID);
DROP FUNCTION IF EXISTS public.get_league_match_time(INTEGER);
CREATE OR REPLACE FUNCTION public.enforce_league_team_count()
RETURNS TRIGGER AS $$
DECLARE
    team_count INTEGER;
    bot_count INTEGER;
    i INTEGER;
BEGIN
    SELECT count(*) INTO team_count FROM public.league_members WHERE league_id = NEW.id;
    
    IF team_count < 16 THEN
        bot_count := 16 - team_count;
        FOR i IN 1..bot_count LOOP
            INSERT INTO public.league_members (league_id, team_id, is_bot, points, games_played, wins, draws, losses, goals_for, goals_against)
            VALUES (NEW.id, gen_random_uuid(), true, 0, 0, 0, 0, 0, 0, 0);
        END LOOP;
    ELSIF team_count > 16 THEN
        DELETE FROM public.league_members
        WHERE id IN (
            SELECT id FROM public.league_members
            WHERE league_id = NEW.id
            ORDER BY is_bot DESC, points ASC, id ASC
            LIMIT (team_count - 16)
        );
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.get_league_match_time(division_level INTEGER)
RETURNS TIME AS $$
BEGIN
    RETURN CASE 
        WHEN division_level = 1 THEN '19:00:00'::TIME
        WHEN division_level = 2 THEN '20:00:00'::TIME
        ELSE '21:00:00'::TIME
    END;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.generate_league_calendar(p_league_id UUID)
RETURNS VOID AS $$
DECLARE
    v_division_level INTEGER;
    v_match_time TIME;
    v_start_date DATE;
    v_teams UUID[];
    v_num_teams INTEGER := 16;
    v_rounds INTEGER := 30;
    v_matches_per_round INTEGER := 8;
    v_r INTEGER;
    v_m INTEGER;
    v_home_idx INTEGER;
    v_away_idx INTEGER;
    v_temp UUID;
    v_match_date TIMESTAMP WITH TIME ZONE;
BEGIN
    SELECT level, start_date INTO v_division_level, v_start_date FROM public.multiplayer_leagues WHERE id = p_league_id;
    v_match_time := public.get_league_match_time(v_division_level);
    
    SELECT ARRAY_AGG(id) INTO v_teams FROM (
        SELECT id FROM public.league_members WHERE league_id = p_league_id ORDER BY id
    ) t;
    DELETE FROM public.league_matches WHERE league_id = p_league_id;
    FOR v_r IN 1..v_rounds LOOP
        v_match_date := (v_start_date + (v_r - 1 || ' days')::INTERVAL)::DATE + v_match_time;
        
        FOR v_m IN 0..(v_matches_per_round - 1) LOOP
            v_home_idx := v_m;
            v_away_idx := v_num_teams - 1 - v_m;
            
            -- Swap in second leg
            IF v_r > 15 THEN
                v_temp := v_teams[v_home_idx + 1];
                v_home_idx := v_away_idx;
                v_away_idx := ARRAY_POSITION(v_teams, v_temp) - 1;
            END IF;
            INSERT INTO public.league_matches (
                league_id, round, scheduled_at, home_team_id, away_team_id, status
            ) VALUES (
                p_league_id, v_r, v_match_date, v_teams[v_home_idx + 1], v_teams[v_away_idx + 1], 'scheduled'
            );
        END LOOP;
        -- Round robin rotation
        v_temp := v_teams[v_num_teams];
        FOR i IN REVERSE v_num_teams .. 3 LOOP
            v_teams[i] := v_teams[i-1];
        END LOOP;
        v_teams[2] := v_temp;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.simulate_overdue_matches()
RETURNS VOID AS $$
BEGIN
    UPDATE public.league_matches
    SET home_score = FLOOR(RANDOM() * 5), away_score = FLOOR(RANDOM() * 5), status = 'finished', updated_at = NOW()
    WHERE status = 'scheduled' AND scheduled_at < NOW() - INTERVAL '5 minutes';
END;
$$ LANGUAGE plpgsql;
