DROP FUNCTION IF EXISTS public.sync_league_integrity(UUID);
DROP FUNCTION IF EXISTS public.reset_league_structure(UUID);
UPDATE public.multiplayer_leagues
SET max_members = 16,
    total_rounds = 30;
CREATE OR REPLACE FUNCTION public.reset_league_structure(_league_id UUID)
RETURNS VOID AS $$
DECLARE
    _member_count INT;
    _division INT;
    _match_time TIME;
    _start_date TIMESTAMP WITH TIME ZONE;
    _member_ids UUID[];
    _num_teams INT := 16;
    _num_rounds INT := 30;
    _round INT;
BEGIN
    -- 1. Reset all matches
    DELETE FROM public.league_matches WHERE league_id = _league_id;
    -- 2. Ensure we have exactly 16 members (fill with bots if needed)
    SELECT count(*) INTO _member_count FROM public.league_members WHERE league_id = _league_id;
    
    -- Remove excess members
    IF _member_count > _num_teams THEN
        DELETE FROM public.league_members
        WHERE id IN (
            SELECT id FROM public.league_members
            WHERE league_id = _league_id AND user_id IS NULL
            ORDER BY reputation ASC, id DESC
            LIMIT (_member_count - _num_teams)
        );
    END IF;
    -- Fill with bots
    SELECT count(*) INTO _member_count FROM public.league_members WHERE league_id = _league_id;
    WHILE _member_count < _num_teams LOOP
        INSERT INTO public.league_members (league_id, club_name, club_logo, reputation, budget)
        VALUES (_league_id, 'BOT ' || substr(gen_random_uuid()::text, 1, 4), '🤖', 50, 1000000);
        _member_count := _member_count + 1;
    END LOOP;
    -- Reset member stats
    UPDATE public.league_members 
    SET points = 0, wins = 0, draws = 0, losses = 0, goals_for = 0, goals_against = 0, played = 0
    WHERE league_id = _league_id;
    -- 3. Get division for match times
    SELECT COALESCE(division, 1) INTO _division FROM public.multiplayer_leagues WHERE id = _league_id;
    _match_time := CASE 
        WHEN _division = 1 THEN '19:00:00'::TIME
        WHEN _division = 2 THEN '20:00:00'::TIME
        ELSE '21:00:00'::TIME
    END;
    -- 4. Rebuild the schedule
    _start_date := COALESCE((SELECT season_start FROM public.multiplayer_leagues WHERE id = _league_id), CURRENT_TIMESTAMP);
    
    SELECT array_agg(id) INTO _member_ids FROM (
        SELECT id FROM public.league_members WHERE league_id = _league_id ORDER BY id
    ) AS m;
    FOR _round IN 1.._num_rounds LOOP
        DECLARE
            _scheduled_at TIMESTAMP WITH TIME ZONE;
        BEGIN
            _scheduled_at := (_start_date::DATE + (_round - 1))::TIMESTAMP + _match_time;
            
            FOR i IN 1..(_num_teams / 2) LOOP
                DECLARE
                    _idx_home INT;
                    _idx_away INT;
                    _home_id UUID;
                    _away_id UUID;
                    _is_return BOOLEAN := _round > 15;
                    _base_round INT := CASE WHEN _is_return THEN _round - 15 ELSE _round END;
                BEGIN
                    _idx_home := (i + _base_round - 2) % (_num_teams - 1) + 1;
                    _idx_away := (_num_teams - 1 - i + _base_round - 1) % (_num_teams - 1) + 1;
                    IF i = 1 THEN _idx_home := 0; END IF;
                    
                    _home_id := _member_ids[_idx_home + 1];
                    _away_id := _member_ids[_idx_away + 1];
                    IF _is_return THEN
                        DECLARE _tmp UUID := _home_id; BEGIN _home_id := _away_id; _away_id := _tmp; END;
                    END IF;
                    INSERT INTO public.league_matches (league_id, round, home_user_id, away_user_id, status, scheduled_at, auto_sim_at)
                    VALUES (_league_id, _round, 
                        (SELECT user_id FROM public.league_members WHERE id = _home_id), 
                        (SELECT user_id FROM public.league_members WHERE id = _away_id), 
                        'scheduled', _scheduled_at, _scheduled_at + INTERVAL '5 minutes');
                END;
            END LOOP;
        END;
    END LOOP;
    -- 5. Auto-update current round
    UPDATE public.multiplayer_leagues
    SET current_round = GREATEST(1, LEAST(30, (CURRENT_DATE - season_start::DATE) + 1))
    WHERE id = _league_id AND season_status = 'in_progress';
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.sync_league_integrity(_user_id UUID)
RETURNS VOID AS $$
DECLARE
    _lg_id UUID;
BEGIN
    FOR _lg_id IN 
        SELECT DISTINCT league_id FROM public.league_members WHERE user_id = _user_id
    LOOP
        PERFORM public.reset_league_structure(_lg_id);
    END LOOP;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.get_match_commentary(
    home_name TEXT, 
    away_name TEXT, 
    home_goals INT, 
    away_goals INT,
    match_data JSONB
) RETURNS TEXT AS $$
DECLARE
    diff INT := home_goals - away_goals;
    abs_diff INT := ABS(home_goals - away_goals);
    winner_name TEXT;
    loser_name TEXT;
BEGIN
    IF home_goals = away_goals THEN
        RETURN 'As equipes de ' || home_name || ' e ' || away_name || ' ficaram no empate após um confronto equilibrado de ' || home_goals || 'x' || away_goals || '.';
    END IF;
    IF diff > 0 THEN
        winner_name := home_name;
        loser_name := away_name;
    ELSE
        winner_name := away_name;
        loser_name := home_name;
    END IF;
    IF abs_diff >= 3 THEN
        RETURN 'Uma goleada impressionante! ' || winner_name || ' dominou completamente e venceu o ' || loser_name || ' por ' || GREATEST(home_goals, away_goals) || 'x' || LEAST(home_goals, away_goals) || '.';
    ELSIF abs_diff = 1 AND (home_goals + away_goals) >= 3 THEN
        RETURN 'Partida muito disputada entre ' || home_name || ' e ' || away_name || ', decidida nos detalhes. Placar final: ' || home_goals || 'x' || away_goals || '.';
    ELSE
        RETURN winner_name || ' venceu com autoridade sobre o ' || loser_name || ' nesta rodada. Resultado: ' || home_goals || 'x' || away_goals || '.';
    END IF;
END;
$$ LANGUAGE plpgsql SET search_path = public;
CREATE OR REPLACE FUNCTION public.on_league_match_finished()
RETURNS TRIGGER AS $$
DECLARE
    v_home_name TEXT;
    v_away_name TEXT;
    v_commentary TEXT;
    v_league_name TEXT;
    v_league_id UUID;
BEGIN
    -- Only trigger when status changes to 'finished'
    IF (OLD.status = 'scheduled' OR OLD.status = 'live') AND NEW.status = 'finished' THEN
        
        -- Get names
        SELECT club_name INTO v_home_name FROM public.league_members WHERE user_id = NEW.home_user_id OR (user_id IS NULL AND id::text = NEW.home_user_id::text) LIMIT 1;
        SELECT club_name INTO v_away_name FROM public.league_members WHERE user_id = NEW.away_user_id OR (user_id IS NULL AND id::text = NEW.away_user_id::text) LIMIT 1;
        
        -- Get league info
        SELECT name, id INTO v_league_name, v_league_id FROM public.multiplayer_leagues WHERE id = NEW.league_id;
        -- Generate commentary
        v_commentary := public.get_match_commentary(COALESCE(v_home_name, 'Mandante'), COALESCE(v_away_name, 'Visitante'), NEW.home_goals, NEW.away_goals, NEW.match_data);
        -- Create Newspaper Entry
        INSERT INTO public.newspaper_entries (
            text, 
            category, 
            is_event, 
            image_key
        ) VALUES (
            'RODADA ' || NEW.round || ' - ' || COALESCE(v_league_name, 'Liga') || E'\n' ||
            COALESCE(v_home_name, 'Mandante') || ' ' || NEW.home_goals || ' x ' || NEW.away_goals || ' ' || COALESCE(v_away_name, 'Visitante') || E'\n\n' ||
            v_commentary,
            'RESULTADO',
            true,
            'match_result'
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public;
DROP TRIGGER IF EXISTS tr_league_match_newspaper ON public.league_matches;
CREATE TRIGGER tr_league_match_newspaper
AFTER UPDATE ON public.league_matches
FOR EACH ROW
EXECUTE FUNCTION public.on_league_match_finished();
CREATE OR REPLACE FUNCTION public.calculate_league_reward(p_pos INT)
RETURNS BIGINT AS $$
BEGIN
    RETURN CASE
        WHEN p_pos = 1 THEN 18000000
        WHEN p_pos = 2 THEN 12000000
        WHEN p_pos = 3 THEN 10000000
        WHEN p_pos = 4 THEN 8000000
        WHEN p_pos >= 5 AND p_pos <= 8 THEN (6000000 - (p_pos - 5) * 500000)
        WHEN p_pos >= 9 AND p_pos <= 12 THEN (3000000 - (p_pos - 9) * 250000)
        ELSE 0
    END;
END;
$$ LANGUAGE plpgsql SET search_path = public;
