CREATE OR REPLACE FUNCTION public.sync_league_team_count()
RETURNS void AS $$
DECLARE
    l_id UUID;
    t_count INT;
    needed INT;
    bot_names TEXT[] := ARRAY['Real Madrid', 'Manchester City', 'Bayern Munich', 'Liverpool', 'PSG', 'Barcelona', 'Arsenal', 'Inter Milan', 'Borussia Dortmund', 'Atletico Madrid', 'Napoli', 'Juventus', 'Chelsea', 'Tottenham', 'Bayer Leverkusen', 'Benfica'];
    b_name TEXT;
BEGIN
    FOR l_id IN SELECT id FROM public.world_leagues LOOP
        SELECT count(*) INTO t_count FROM public.world_league_teams WHERE league_id = l_id;
        IF t_count < 16 THEN
            needed := 16 - t_count;
            FOR i IN 1..needed LOOP
                SELECT name INTO b_name 
                FROM unnest(bot_names) AS name 
                WHERE name NOT IN (SELECT club_name FROM public.world_league_teams WHERE league_id = l_id)
                LIMIT 1;
                
                IF b_name IS NULL THEN b_name := 'Bot Team ' || (t_count + i); END IF;
                INSERT INTO public.world_league_teams (league_id, club_name, club_logo, reputation)
                VALUES (l_id, b_name, '🤖', 60);
            END LOOP;
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
SELECT public.sync_league_team_count();
DELETE FROM public.world_matches;
DO $$
DECLARE
    v_league_id UUID;
    v_count INTEGER;
    v_to_add INTEGER;
BEGIN
    SELECT id INTO v_league_id FROM public.world_leagues LIMIT 1;
    IF v_league_id IS NULL THEN
        v_league_id := gen_random_uuid();
        INSERT INTO public.world_leagues (id, league_name, flag_emoji, division, total_matchdays, kickoff_hour, kickoff_minute, status)
        VALUES (v_league_id, 'Divisão Nacional 1', '🇧🇷', 1, 30, 19, 30, 'in_progress');
    END IF;
    -- Clean duplicate names
    DELETE FROM public.world_league_teams 
    WHERE id IN (
        SELECT id FROM (
            SELECT id, row_number() OVER (PARTITION BY club_name ORDER BY user_id NULLS LAST, created_at ASC) as rn
            FROM public.world_league_teams
        ) t WHERE rn > 1
    );
    -- Standardize league
    UPDATE public.world_league_teams SET league_id = v_league_id;
    SELECT count(*) INTO v_count FROM public.world_league_teams;
    IF v_count > 16 THEN
        DELETE FROM public.world_league_teams 
        WHERE id IN (
            SELECT id FROM public.world_league_teams 
            ORDER BY user_id NULLS LAST, id ASC 
            OFFSET 16
        );
    ELSIF v_count < 16 THEN
        v_to_add := 16 - v_count;
        FOR i IN 1..v_to_add LOOP
            INSERT INTO public.world_league_teams (id, league_id, club_name, club_logo, is_bot, points, wins, draws, losses, goals_for, goals_against, played)
            VALUES (gen_random_uuid(), v_league_id, 'Bot FC ' || (v_count + i), '⚽', true, 0, 0, 0, 0, 0, 0, 0);
        END LOOP;
    END IF;
END $$;
CREATE OR REPLACE FUNCTION public.rebuild_league_v6()
RETURNS void AS $$
DECLARE
    team_ids UUID[];
    num_teams INTEGER := 16;
    round_num INTEGER;
    i INTEGER;
    h_idx INTEGER;
    a_idx INTEGER;
    temp_id UUID;
    v_league_id UUID;
    v_start DATE := CURRENT_DATE - INTERVAL '4 days';
    v_time TIME := '19:30:00';
BEGIN
    SELECT id INTO v_league_id FROM public.world_leagues LIMIT 1;
    SELECT ARRAY_AGG(id ORDER BY id) INTO team_ids FROM public.world_league_teams;
    -- IDA (Matchdays 1-15)
    FOR round_num IN 1..15 LOOP
        FOR i IN 0..7 LOOP
            h_idx := i;
            a_idx := num_teams - 1 - i;
            
            INSERT INTO public.world_matches (id, league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
            VALUES (
                gen_random_uuid(), v_league_id, team_ids[h_idx + 1], team_ids[a_idx + 1], round_num, 
                (v_start + (round_num - 1) * INTERVAL '1 day' + v_time)::timestamp with time zone,
                CASE WHEN round_num < 5 THEN 'finished'::public.world_match_status ELSE 'scheduled'::public.world_match_status END,
                1
            );
        END LOOP;
        
        temp_id := team_ids[num_teams];
        FOR i IN REVERSE num_teams..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_id;
    END LOOP;
    -- VOLTA (Matchdays 16-30)
    SELECT ARRAY_AGG(id ORDER BY id) INTO team_ids FROM public.world_league_teams;
    FOR round_num IN 1..15 LOOP
        FOR i IN 0..7 LOOP
            h_idx := i;
            a_idx := num_teams - 1 - i;
            
            INSERT INTO public.world_matches (id, league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
            VALUES (
                gen_random_uuid(), v_league_id, team_ids[a_idx + 1], team_ids[h_idx + 1], round_num + 15, 
                (v_start + (round_num + 15 - 1) * INTERVAL '1 day' + v_time)::timestamp with time zone,
                'scheduled'::public.world_match_status,
                1
            );
        END LOOP;
        
        temp_id := team_ids[num_teams];
        FOR i IN REVERSE num_teams..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_id;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
SELECT public.rebuild_league_v6();
UPDATE public.world_matches
SET home_goals = floor(random() * 4)::int, away_goals = floor(random() * 4)::int
WHERE matchday < 5 AND status = 'finished';
UPDATE public.world_league_teams SET points = 0, wins = 0, draws = 0, losses = 0, goals_for = 0, goals_against = 0, played = 0;
UPDATE public.world_league_teams t
SET 
    played = sub.p, wins = sub.w, draws = sub.d, losses = sub.l, 
    goals_for = sub.gf, goals_against = sub.ga, points = (sub.w * 3) + sub.d
FROM (
    SELECT team_id, COUNT(*) as p, SUM(w) as w, SUM(d) as d, SUM(l) as l, SUM(gf) as gf, SUM(ga) as ga
    FROM (
        SELECT home_team_id as team_id, 1 as p, CASE WHEN home_goals > away_goals THEN 1 ELSE 0 END as w, CASE WHEN home_goals = away_goals THEN 1 ELSE 0 END as d, CASE WHEN home_goals < away_goals THEN 1 ELSE 0 END as l, home_goals as gf, away_goals as ga FROM public.world_matches WHERE status = 'finished'
        UNION ALL
        SELECT away_team_id as team_id, 1 as p, CASE WHEN away_goals > home_goals THEN 1 ELSE 0 END as w, CASE WHEN away_goals = home_goals THEN 1 ELSE 0 END as d, CASE WHEN away_goals < home_goals THEN 1 ELSE 0 END as l, away_goals as gf, home_goals as ga FROM public.world_matches WHERE status = 'finished'
    ) m GROUP BY team_id
) sub WHERE t.id = sub.team_id;
ALTER TABLE public.world_matches DROP CONSTRAINT IF EXISTS world_matches_unique_round;
ALTER TABLE public.world_matches ADD CONSTRAINT world_matches_unique_round UNIQUE (home_team_id, away_team_id, matchday);
DELETE FROM public.world_matches;
DO $$
DECLARE
    target_league_id UUID;
    team_count INTEGER;
    teams_needed INTEGER;
    i INTEGER;
BEGIN
    SELECT id INTO target_league_id FROM public.world_leagues WHERE division = 1 LIMIT 1;
    
    IF target_league_id IS NULL THEN
        INSERT INTO public.world_leagues (league_name, division, status, total_matchdays, flag_emoji)
        VALUES ('Divisão Nacional 1', 1, 'in_progress', 30, '🇧🇷')
        RETURNING id INTO target_league_id;
    END IF;
    -- 3. Ensure exactly 16 teams
    SELECT count(*) INTO team_count FROM public.world_league_teams WHERE league_id = target_league_id;
    
    IF team_count < 16 THEN
        teams_needed := 16 - team_count;
        FOR i IN 1..teams_needed LOOP
            INSERT INTO public.world_league_teams (league_id, club_name, club_logo, bot_strength, is_bot)
            VALUES (
                target_league_id, 
                'Bot Club ' || (team_count + i), 
                '🤖', 
                floor(random() * (75 - 60 + 1) + 60)::int, 
                true
            );
        END LOOP;
    ELSIF team_count > 16 THEN
        DELETE FROM public.world_league_teams 
        WHERE id IN (
            SELECT id FROM public.world_league_teams 
            WHERE league_id = target_league_id 
            ORDER BY created_at DESC 
            OFFSET 16
        );
    END IF;
    -- 4. Reset team stats
    UPDATE public.world_league_teams 
    SET wins = 0, draws = 0, losses = 0, played = 0, points = 0, goals_for = 0, goals_against = 0 
    WHERE league_id = target_league_id;
END $$;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'unique_match_per_matchday'
    ) THEN
        ALTER TABLE public.world_matches 
        ADD CONSTRAINT unique_match_per_matchday UNIQUE (home_team_id, away_team_id, matchday);
    END IF;
END $$;
DO $$
DECLARE
    target_league_id UUID;
    team_ids UUID[];
    num_teams INTEGER := 16;
    r INTEGER;
    i INTEGER;
    home_idx INTEGER;
    away_idx INTEGER;
    temp_id UUID;
    kickoff_base TIMESTAMP WITH TIME ZONE := (CURRENT_DATE - INTERVAL '4 days' + TIME '19:30:00');
BEGIN
    SELECT id INTO target_league_id FROM public.world_leagues WHERE division = 1 LIMIT 1;
    SELECT ARRAY(SELECT id FROM public.world_league_teams WHERE league_id = target_league_id ORDER BY id LIMIT 16) INTO team_ids;
    -- Generate first half (Rounds 1-15)
    FOR r IN 1..15 LOOP
        FOR i IN 0..(num_teams / 2 - 1) LOOP
            home_idx := i;
            away_idx := num_teams - 1 - i;
            
            IF r % 2 = 0 THEN
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
                VALUES (target_league_id, team_ids[away_idx + 1], team_ids[home_idx + 1], r, kickoff_base + (INTERVAL '1 day' * (r - 1)), 'scheduled', 1)
                ON CONFLICT DO NOTHING;
            ELSE
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
                VALUES (target_league_id, team_ids[home_idx + 1], team_ids[away_idx + 1], r, kickoff_base + (INTERVAL '1 day' * (r - 1)), 'scheduled', 1)
                ON CONFLICT DO NOTHING;
            END IF;
        END LOOP;
        
        temp_id := team_ids[num_teams];
        FOR i IN REVERSE (num_teams)..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_id;
    END LOOP;
    -- Reset for second half
    SELECT ARRAY(SELECT id FROM public.world_league_teams WHERE league_id = target_league_id ORDER BY id LIMIT 16) INTO team_ids;
    -- Generate second half (Rounds 16-30)
    FOR r IN 16..30 LOOP
        FOR i IN 0..(num_teams / 2 - 1) LOOP
            home_idx := i;
            away_idx := num_teams - 1 - i;
            
            IF (r - 15) % 2 = 0 THEN
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
                VALUES (target_league_id, team_ids[home_idx + 1], team_ids[away_idx + 1], r, kickoff_base + (INTERVAL '1 day' * (r - 1)), 'scheduled', 1)
                ON CONFLICT DO NOTHING;
            ELSE
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, matchday, kickoff_at, status, season)
                VALUES (target_league_id, team_ids[away_idx + 1], team_ids[home_idx + 1], r, kickoff_base + (INTERVAL '1 day' * (r - 1)), 'scheduled', 1)
                ON CONFLICT DO NOTHING;
            END IF;
        END LOOP;
        
        temp_id := team_ids[num_teams];
        FOR i IN REVERSE (num_teams)..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_id;
    END LOOP;
END $$;
DO $$
DECLARE
    m RECORD;
    h_score INTEGER;
    a_score INTEGER;
BEGIN
    FOR m IN SELECT id, home_team_id, away_team_id FROM public.world_matches WHERE matchday <= 4 LOOP
        h_score := floor(random() * 4)::int;
        a_score := floor(random() * 3)::int;
        
        UPDATE public.world_matches
        SET home_goals = h_score, away_goals = a_score, status = 'finished'
        WHERE id = m.id;
        UPDATE public.world_league_teams
        SET played = played + 1,
            goals_for = goals_for + h_score,
            goals_against = goals_against + a_score,
            wins = wins + (CASE WHEN h_score > a_score THEN 1 ELSE 0 END),
            draws = draws + (CASE WHEN h_score = a_score THEN 1 ELSE 0 END),
            losses = losses + (CASE WHEN h_score < a_score THEN 1 ELSE 0 END),
            points = points + (CASE WHEN h_score > a_score THEN 3 WHEN h_score = a_score THEN 1 ELSE 0 END)
        WHERE id = m.home_team_id;
        UPDATE public.world_league_teams
        SET played = played + 1,
            goals_for = goals_for + a_score,
            goals_against = goals_against + h_score,
            wins = wins + (CASE WHEN a_score > h_score THEN 1 ELSE 0 END),
            draws = draws + (CASE WHEN a_score = h_score THEN 1 ELSE 0 END),
            losses = losses + (CASE WHEN a_score < h_score THEN 1 ELSE 0 END),
            points = points + (CASE WHEN a_score > h_score THEN 3 WHEN a_score = h_score THEN 1 ELSE 0 END)
        WHERE id = m.away_team_id;
    END LOOP;
END $$;
