CREATE OR REPLACE FUNCTION public.generate_beginner_cup_fixtures(_cup_id UUID)
RETURNS void AS $$
DECLARE
    team_ids UUID[];
    num_teams INTEGER;
    i INTEGER;
    j INTEGER;
    match_date TIMESTAMP WITH TIME ZONE;
    curr_month INTEGER;
    curr_year INTEGER;
    p_name TEXT;
    num_matches INTEGER;
    next_pow2 INTEGER := 1;
BEGIN
    -- Get current season info from cup
    SELECT season_month, season_year INTO curr_month, curr_year FROM public.beginner_cup WHERE id = _cup_id;
    -- Get all active participants
    SELECT array_agg(team_id) INTO team_ids 
    FROM public.beginner_cup_participants 
    WHERE cup_id = _cup_id AND status = 'playing';
    num_teams := array_length(team_ids, 1);
    IF num_teams IS NULL OR num_teams < 2 THEN RETURN; END IF;
    -- Scheduling: Day 10, 11, 12, 13
    -- Fase 1: Day 10
    -- Quartas: Day 11
    -- Semis: Day 12
    -- Final: Day 13
    
    -- Shuffle teams
    SELECT array_agg(id ORDER BY random()) INTO team_ids FROM (SELECT unnest(team_ids) as id) s;
    -- Determine how many matches for Round 1 to reach a power of 2
    WHILE next_pow2 < num_teams LOOP
        next_pow2 := next_pow2 * 2;
    END LOOP;
    
    -- If num_teams is not power of 2, we need BYEs.
    -- The number of teams playing in Round 1 = (num_teams - (next_pow2 / 2)) * 2
    -- The rest get a BYE.
    
    num_matches := num_teams - (next_pow2 / 2);
    
    IF num_matches = 0 THEN
        -- Perfect power of 2, start with the appropriate phase
        p_name := CASE 
            WHEN next_pow2 = 16 THEN 'Fase 1'
            WHEN next_pow2 = 8 THEN 'Quartas de Final'
            WHEN next_pow2 = 4 THEN 'Semifinal'
            WHEN next_pow2 = 2 THEN 'Final'
            ELSE 'Fase 1'
        END;
        
        match_date := make_timestamptz(curr_year, curr_month, 10, 20, 0, 0);
        
        FOR i IN 1..(num_teams / 2) LOOP
            INSERT INTO public.beginner_cup_matches (cup_id, home_team_id, away_team_id, phase, scheduled_at)
            VALUES (_cup_id, team_ids[i*2-1], team_ids[i*2], p_name, match_date);
        END LOOP;
    ELSE
        -- Needs BYEs
        match_date := make_timestamptz(curr_year, curr_month, 10, 20, 0, 0);
        
        -- First (num_matches * 2) teams play, rest get BYE
        FOR i IN 1..num_matches LOOP
            INSERT INTO public.beginner_cup_matches (cup_id, home_team_id, away_team_id, phase, scheduled_at)
            VALUES (_cup_id, team_ids[i*2-1], team_ids[i*2], 'Fase 1', match_date);
        END LOOP;
        
        -- Update status for BYE teams (they advance automatically)
        -- We'll handle advancing logic in a separate simulation function
    END IF;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.advance_cup_winners(_cup_id UUID, _current_phase TEXT)
RETURNS void AS $$
DECLARE
    winners UUID[];
    next_phase TEXT;
    match_date TIMESTAMP WITH TIME ZONE;
    curr_month INTEGER;
    curr_year INTEGER;
    i INTEGER;
BEGIN
    SELECT season_month, season_year INTO curr_month, curr_year FROM public.beginner_cup WHERE id = _cup_id;
    -- Get winners of current phase
    SELECT array_agg(winner_id) INTO winners 
    FROM public.beginner_cup_matches 
    WHERE cup_id = _cup_id AND phase = _current_phase AND status = 'finished';
    -- Add BYE teams if it was Fase 1
    IF _current_phase = 'Fase 1' THEN
        -- Add teams that didn't play in Fase 1 but are participants
        SELECT array_agg(team_id) INTO winners
        FROM (
            SELECT winner_id FROM public.beginner_cup_matches WHERE cup_id = _cup_id AND phase = 'Fase 1'
            UNION
            SELECT team_id FROM public.beginner_cup_participants 
            WHERE cup_id = _cup_id AND team_id NOT IN (
                SELECT home_team_id FROM public.beginner_cup_matches WHERE cup_id = _cup_id AND phase = 'Fase 1'
                UNION
                SELECT away_team_id FROM public.beginner_cup_matches WHERE cup_id = _cup_id AND phase = 'Fase 1'
            )
        ) s;
    END IF;
    IF array_length(winners, 1) < 2 THEN RETURN; END IF;
    next_phase := CASE 
        WHEN _current_phase = 'Fase 1' THEN 'Quartas de Final'
        WHEN _current_phase = 'Quartas de Final' THEN 'Semifinal'
        WHEN _current_phase = 'Semifinal' THEN 'Final'
        ELSE NULL
    END;
    IF next_phase IS NULL THEN RETURN; END IF;
    match_date := CASE 
        WHEN next_phase = 'Quartas de Final' THEN make_timestamptz(curr_year, curr_month, 11, 20, 0, 0)
        WHEN next_phase = 'Semifinal' THEN make_timestamptz(curr_year, curr_month, 12, 20, 0, 0)
        WHEN next_phase = 'Final' THEN make_timestamptz(curr_year, curr_month, 13, 20, 0, 0)
    END;
    FOR i IN 1..(array_length(winners, 1) / 2) LOOP
        INSERT INTO public.beginner_cup_matches (cup_id, home_team_id, away_team_id, phase, scheduled_at)
        VALUES (_cup_id, winners[i*2-1], winners[i*2], next_phase, match_date);
    END LOOP;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.replace_bot_with_player(_user_id UUID, _team_name TEXT, _logo TEXT)
RETURNS UUID AS $$
DECLARE
    target_team_id UUID;
    curr_month INTEGER := EXTRACT(MONTH FROM now())::INTEGER;
    curr_year INTEGER := EXTRACT(YEAR FROM now())::INTEGER;
    curr_day INTEGER := EXTRACT(DAY FROM now())::INTEGER;
    cup_id UUID;
BEGIN
    -- Already has a team?
    SELECT id INTO target_team_id FROM public.world_teams WHERE user_id = _user_id;
    IF target_team_id IS NOT NULL THEN RETURN target_team_id; END IF;
    -- Season already started (Day 1+) or no bots left?
    -- Actually, if it's Day 1, we might still allow entry if there are bots.
    -- But if games have already been played (e.g., after 19:30 on Day 1), better go to Cup.
    
    IF curr_day > 1 THEN
        -- Go to Cup
        INSERT INTO public.world_teams (user_id, name, logo, is_bot) VALUES (_user_id, _team_name, _logo, false) RETURNING id INTO target_team_id;
        
        INSERT INTO public.beginner_cup (season_month, season_year) 
        VALUES (curr_month, curr_year) 
        ON CONFLICT (season_month, season_year) DO UPDATE SET status = 'active'
        RETURNING id INTO cup_id;
        
        INSERT INTO public.beginner_cup_participants (cup_id, team_id) 
        VALUES (cup_id, target_team_id) ON CONFLICT DO NOTHING;
        
        RETURN target_team_id;
    ELSE
        -- Try to replace a bot in the league
        SELECT id INTO target_team_id FROM public.world_teams WHERE is_bot = true LIMIT 1;
        
        IF target_team_id IS NOT NULL THEN
            UPDATE public.world_teams SET user_id = _user_id, name = _team_name, logo = _logo, is_bot = false, updated_at = now() WHERE id = target_team_id;
            RETURN target_team_id;
        ELSE
            -- League full
            INSERT INTO public.world_teams (user_id, name, logo, is_bot) VALUES (_user_id, _team_name, _logo, false) RETURNING id INTO target_team_id;
            
            INSERT INTO public.beginner_cup (season_month, season_year) 
            VALUES (curr_month, curr_year) 
            ON CONFLICT (season_month, season_year) DO UPDATE SET status = 'active'
            RETURNING id INTO cup_id;
            
            INSERT INTO public.beginner_cup_participants (cup_id, team_id) 
            VALUES (cup_id, target_team_id) ON CONFLICT DO NOTHING;
            
            RETURN target_team_id;
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.process_season_transition()
RETURNS void AS $$
DECLARE
    next_month INTEGER;
    next_year INTEGER;
    cup_winners UUID[];
    i INTEGER;
    league_rec RECORD;
    new_league_id UUID;
    t_id UUID;
BEGIN
    next_month := EXTRACT(MONTH FROM (now() + interval '1 month'))::INTEGER;
    next_year := EXTRACT(YEAR FROM (now() + interval '1 month'))::INTEGER;
    -- 1. Identify Top 8 from Cup (finalists, semifinalists, etc.)
    -- For now, let's just take participants who were active
    SELECT array_agg(team_id) INTO cup_winners
    FROM (
        -- Winners of Final
        SELECT winner_id FROM public.beginner_cup_matches WHERE phase = 'Final' AND status = 'finished'
        UNION
        -- Finalists
        SELECT home_team_id FROM public.beginner_cup_matches WHERE phase = 'Final'
        UNION
        SELECT away_team_id FROM public.beginner_cup_matches WHERE phase = 'Final'
        UNION
        -- Semifinalists
        SELECT home_team_id FROM public.beginner_cup_matches WHERE phase = 'Semifinal'
        UNION
        SELECT away_team_id FROM public.beginner_cup_matches WHERE phase = 'Semifinal'
        LIMIT 16 -- Max 16 to be safe
    ) s;
    -- 2. Clear all League data for new month (as per user's "Reset every Day 1" philosophy from previous prompt)
    -- Actually, we should just generate NEW fixtures.
    
    FOR league_rec IN SELECT id FROM public.world_leagues LOOP
        -- Remove old bots, keep humans but unassign from old leagues if needed? 
        -- No, let's just re-generate.
        PERFORM public.generate_league_fixtures(league_rec.id, next_month, next_year);
    END LOOP;
    -- 3. Insert Cup Winners into a league by replacing bots
    IF cup_winners IS NOT NULL THEN
        FOREACH t_id IN ARRAY cup_winners LOOP
            -- Find a bot in a random league to replace
            UPDATE public.world_teams 
            SET league_id = (SELECT id FROM public.world_leagues ORDER BY random() LIMIT 1)
            WHERE id = t_id;
        END LOOP;
    END IF;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.simulate_cup_match(_match_id UUID)
RETURNS void AS $$
DECLARE
    m RECORD;
    h_goals INTEGER;
    a_goals INTEGER;
    h_pen INTEGER := 0;
    a_pen INTEGER := 0;
    w_id UUID;
BEGIN
    SELECT * INTO m FROM public.beginner_cup_matches WHERE id = _match_id;
    IF m.status = 'finished' THEN RETURN; END IF;
    -- Basic simulation logic
    h_goals := (floor(random() * 4))::int;
    a_goals := (floor(random() * 4))::int;
    -- If draw in knockout, use penalties
    IF h_goals = a_goals THEN
        IF random() > 0.5 THEN
            h_pen := 5; a_pen := 4;
            w_id := m.home_team_id;
        ELSE
            h_pen := 4; a_pen := 5;
            w_id := m.away_team_id;
        END IF;
    ELSE
        w_id := CASE WHEN h_goals > a_goals THEN m.home_team_id ELSE m.away_team_id END;
    END IF;
    UPDATE public.beginner_cup_matches 
    SET 
        home_goals = h_goals, 
        away_goals = a_goals, 
        home_penalties = h_pen, 
        away_penalties = a_pen,
        status = 'finished',
        winner_id = w_id,
        played_at = now()
    WHERE id = _match_id;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.sync_beginner_cup(_user_id UUID)
RETURNS void AS $$
DECLARE
    curr_month INTEGER := EXTRACT(MONTH FROM now())::INTEGER;
    curr_year INTEGER := EXTRACT(YEAR FROM now())::INTEGER;
    curr_day INTEGER := EXTRACT(DAY FROM now())::INTEGER;
    cup_rec RECORD;
    match_rec RECORD;
BEGIN
    -- 1. Ensure Cup exists for current month
    SELECT * INTO cup_rec FROM public.beginner_cup WHERE season_month = curr_month AND season_year = curr_year;
    
    IF cup_rec.id IS NULL THEN
        -- No cup this month yet? Only create if needed (usually handled by replace_bot_with_player)
        RETURN;
    END IF;
    -- 2. If Day >= 10 and no matches generated yet, generate Fase 1
    IF curr_day >= 10 AND NOT EXISTS (SELECT 1 FROM public.beginner_cup_matches WHERE cup_id = cup_rec.id) THEN
        PERFORM public.generate_beginner_cup_fixtures(cup_rec.id);
    END IF;
    -- 3. Simulate matches for past days
    -- Day 10 matches
    IF curr_day > 10 THEN
        FOR match_rec IN SELECT id FROM public.beginner_cup_matches WHERE cup_id = cup_rec.id AND phase = 'Fase 1' AND status = 'scheduled' LOOP
            PERFORM public.simulate_cup_match(match_rec.id);
        END LOOP;
        -- Advance winners to Quartas
        PERFORM public.advance_cup_winners(cup_rec.id, 'Fase 1');
    END IF;
    -- Day 11 matches
    IF curr_day > 11 THEN
        FOR match_rec IN SELECT id FROM public.beginner_cup_matches WHERE cup_id = cup_rec.id AND phase = 'Quartas de Final' AND status = 'scheduled' LOOP
            PERFORM public.simulate_cup_match(match_rec.id);
        END LOOP;
        PERFORM public.advance_cup_winners(cup_rec.id, 'Quartas de Final');
    END IF;
    -- Day 12 matches
    IF curr_day > 12 THEN
        FOR match_rec IN SELECT id FROM public.beginner_cup_matches WHERE cup_id = cup_rec.id AND phase = 'Semifinal' AND status = 'scheduled' LOOP
            PERFORM public.simulate_cup_match(match_rec.id);
        END LOOP;
        PERFORM public.advance_cup_winners(cup_rec.id, 'Semifinal');
    END IF;
    -- Day 13 matches
    IF curr_day > 13 THEN
        FOR match_rec IN SELECT id FROM public.beginner_cup_matches WHERE cup_id = cup_rec.id AND phase = 'Final' AND status = 'scheduled' LOOP
            PERFORM public.simulate_cup_match(match_rec.id);
        END LOOP;
    END IF;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.generate_league_fixtures(_league_id UUID, _month INTEGER, _year INTEGER)
RETURNS void AS $$
DECLARE
    team_ids UUID[];
    num_teams INTEGER := 16;
    num_rounds INTEGER := 30;
    r INTEGER;
    i INTEGER;
    home_idx INTEGER;
    away_idx INTEGER;
    match_date TIMESTAMP WITH TIME ZONE;
    league_name_val TEXT;
    new_team_id UUID;
    curr_day INTEGER := EXTRACT(DAY FROM now())::INTEGER;
    h_goals INTEGER;
    a_goals INTEGER;
    m_status TEXT;
    cup_winners UUID[];
    t_id UUID;
BEGIN
    SELECT name INTO league_name_val FROM public.world_leagues WHERE id = _league_id;
    -- 1. Identify Cup Winners that should be promoted this month
    -- (Those who were in last month's cup and reached the top 8)
    SELECT array_agg(team_id) INTO cup_winners
    FROM (
        SELECT team_id FROM public.beginner_cup_participants p
        JOIN public.beginner_cup c ON p.cup_id = c.id
        WHERE (c.season_month = _month - 1 OR (c.season_month = 12 AND _month = 1))
        AND c.season_year = CASE WHEN _month = 1 THEN _year - 1 ELSE _year END
        -- Simple logic: top 8 based on progress (could be refined)
        LIMIT 8
    ) s;
    -- 2. Fill with Promoted Teams first
    IF cup_winners IS NOT NULL THEN
        -- Only take enough to fill the league (unlikely to exceed 16, but good to check)
        FOR i IN 1..LEAST(num_teams, array_length(cup_winners, 1)) LOOP
            t_id := cup_winners[i];
            UPDATE public.world_teams SET league_id = _league_id, is_bot = false WHERE id = t_id;
            team_ids := array_append(team_ids, t_id);
        END LOOP;
    END IF;
    -- 3. Fill remaining slots with BOTS
    FOR i IN (COALESCE(array_length(team_ids, 1), 0) + 1)..num_teams LOOP
        INSERT INTO public.world_teams (league_id, name, is_bot, strength)
        VALUES (_league_id, 'BOT ' || league_name_val || ' ' || i, true, 65 + (random() * 15)::int)
        RETURNING id INTO new_team_id;
        team_ids := array_append(team_ids, new_team_id);
    END LOOP;
    -- 4. Generate Fixtures (Robin Circle)
    FOR r IN 1..num_rounds LOOP
        match_date := make_timestamptz(_year, _month, LEAST(r, 28), 19, 30, 0);
        
        IF r < curr_day THEN
            m_status := 'finished';
        ELSE
            m_status := 'scheduled';
        END IF;
        FOR i IN 0..(num_teams / 2 - 1) LOOP
            home_idx := i + 1;
            away_idx := num_teams - i;
            
            IF r % 2 = 0 THEN
                h_goals := CASE WHEN m_status = 'finished' THEN (floor(random() * 4))::int ELSE 0 END;
                a_goals := CASE WHEN m_status = 'finished' THEN (floor(random() * 3))::int ELSE 0 END;
                
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, season_month, season_year, status, home_goals, away_goals, played_at)
                VALUES (_league_id, team_ids[away_idx], team_ids[home_idx], r, match_date, _month, _year, m_status, h_goals, a_goals, CASE WHEN m_status = 'finished' THEN match_date ELSE NULL END);
            ELSE
                h_goals := CASE WHEN m_status = 'finished' THEN (floor(random() * 4))::int ELSE 0 END;
                a_goals := CASE WHEN m_status = 'finished' THEN (floor(random() * 3))::int ELSE 0 END;
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, season_month, season_year, status, home_goals, away_goals, played_at)
                VALUES (_league_id, team_ids[home_idx], team_ids[away_idx], r, match_date, _month, _year, m_status, h_goals, a_goals, CASE WHEN m_status = 'finished' THEN match_date ELSE NULL END);
            END IF;
        END LOOP;
        
        team_ids := team_ids[1:1] || team_ids[num_teams:num_teams] || team_ids[2:num_teams-1];
    END LOOP;
    -- 5. Create Standings
    FOR i IN 1..num_teams LOOP
        INSERT INTO public.world_league_table (league_id, team_id, season_month, season_year)
        VALUES (_league_id, team_ids[i], _month, _year)
        ON CONFLICT (team_id, season_month, season_year) DO NOTHING;
    END LOOP;
    -- Update table stats
    UPDATE public.world_league_table t
    SET 
        played = (SELECT count(*) FROM public.world_matches m WHERE (m.home_team_id = t.team_id OR m.away_team_id = t.team_id) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        wins = (SELECT count(*) FROM public.world_matches m WHERE ((m.home_team_id = t.team_id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.team_id AND m.away_goals > m.home_goals)) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        draws = (SELECT count(*) FROM public.world_matches m WHERE (m.home_team_id = t.team_id OR m.away_team_id = t.team_id) AND m.home_goals = m.away_goals AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        losses = (SELECT count(*) FROM public.world_matches m WHERE ((m.home_team_id = t.team_id AND m.home_goals < m.away_goals) OR (m.away_team_id = t.team_id AND m.away_goals < m.home_goals)) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        goals_for = (SELECT coalesce(sum(CASE WHEN m.home_team_id = t.team_id THEN m.home_goals ELSE m.away_goals END), 0) FROM public.world_matches m WHERE (m.home_team_id = t.team_id OR m.away_team_id = t.team_id) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        goals_against = (SELECT coalesce(sum(CASE WHEN m.home_team_id = t.team_id THEN m.away_goals ELSE m.home_goals END), 0) FROM public.world_matches m WHERE (m.home_team_id = t.team_id OR m.away_team_id = t.team_id) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year),
        points = (SELECT 
            (count(*) FILTER (WHERE (m.home_team_id = t.team_id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.team_id AND m.away_goals > m.home_goals)) * 25) +
            (count(*) FILTER (WHERE m.home_goals = m.away_goals) * 10) +
            (count(*) FILTER (WHERE (m.home_team_id = t.team_id AND m.home_goals < m.away_goals) OR (m.away_team_id = t.team_id AND m.away_goals < m.home_goals)) * 3)
            FROM public.world_matches m WHERE (m.home_team_id = t.team_id OR m.away_team_id = t.team_id) AND m.status = 'finished' AND m.season_month = _month AND m.season_year = _year
        )
    WHERE t.league_id = _league_id AND t.season_month = _month AND t.season_year = _year;
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.handle_team_league_entry(_team_id UUID, _country_id UUID)
RETURNS VOID AS $$
DECLARE
  v_league_id UUID;
  v_bot_team_id UUID;
  v_count INT;
  v_season_month INT := EXTRACT(MONTH FROM NOW());
  v_season_year INT := EXTRACT(YEAR FROM NOW());
  v_day INT := EXTRACT(DAY FROM NOW());
BEGIN
  -- 1. Check if there's a league in the country that isn't full (less than 16 teams)
  -- Priority: Leages that are still in "waiting" (if any, though we aim for automatic)
  SELECT id INTO v_league_id
  FROM public.world_leagues
  WHERE country_id = _country_id
  ORDER BY created_at DESC
  LIMIT 1;
  -- If no league exists for country, create one
  IF v_league_id IS NULL THEN
    INSERT INTO public.world_leagues (name, country_id, division_level, match_time, status)
    VALUES ('Série A', _country_id, 1, '19:30:00', 'active')
    RETURNING id INTO v_league_id;
  END IF;
  -- 2. Check if league has space (< 16 teams)
  SELECT count(*) INTO v_count FROM public.world_teams WHERE league_id = v_league_id;
  IF v_count < 16 THEN
    -- Join normally
    UPDATE public.world_teams SET league_id = v_league_id WHERE id = _team_id;
    
    -- Initialize standing if not exists
    INSERT INTO public.world_league_table (league_id, team_id, season_month, season_year, played, wins, draws, losses, goals_for, goals_against, points)
    VALUES (v_league_id, _team_id, v_season_month, v_season_year, 0, 0, 0, 0, 0, 0, 0)
    ON CONFLICT (league_id, team_id, season_month, season_year) DO NOTHING;
  ELSE
    -- 3. League is full. Try to replace a BOT.
    SELECT id INTO v_bot_team_id
    FROM public.world_teams
    WHERE league_id = v_league_id AND is_bot = true
    LIMIT 1;
    IF v_bot_team_id IS NOT NULL THEN
      -- REPLACE BOT LOGIC (CRITICAL)
      -- A. Transfer matches from BOT to human
      UPDATE public.world_matches SET home_team_id = _team_id WHERE home_team_id = v_bot_team_id AND league_id = v_league_id;
      UPDATE public.world_matches SET away_team_id = _team_id WHERE away_team_id = v_bot_team_id AND league_id = v_league_id;
      
      -- B. Transfer standings from BOT to human
      UPDATE public.world_league_table SET team_id = _team_id 
      WHERE team_id = v_bot_team_id AND league_id = v_league_id AND season_month = v_season_month AND season_year = v_season_year;
      
      -- C. Move BOT out of league (or delete if it was just a placeholder)
      UPDATE public.world_teams SET league_id = NULL WHERE id = v_bot_team_id;
      
      -- D. Set human team to league
      UPDATE public.world_teams SET league_id = v_league_id WHERE id = _team_id;
    ELSE
      -- No bots to replace? This shouldn't happen with 16 teams limit, but if it does, 
      -- maybe the player stays in beginner cup or waits for next season.
      -- For now, we'll just log or do nothing.
    END IF;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.on_team_created_enroll()
RETURNS TRIGGER AS $$
DECLARE
  v_country_id UUID;
BEGIN
  -- Get country_id from profiles or some default
  SELECT id INTO v_country_id FROM public.countries WHERE code = 'BR' LIMIT 1;
  
  PERFORM public.handle_team_league_entry(NEW.id, v_country_id);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
