CREATE OR REPLACE FUNCTION public.handle_scout_mission_status()
RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        UPDATE public.scouts SET is_busy = true WHERE id = NEW.scout_id;
    ELSIF (TG_OP = 'UPDATE' AND NEW.status != 'em_andamento') THEN
        UPDATE public.scouts SET is_busy = false WHERE id = NEW.scout_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE TRIGGER on_mission_status_change
AFTER INSERT OR UPDATE ON public.scout_missions
FOR EACH ROW EXECUTE FUNCTION public.handle_scout_mission_status();
ALTER TABLE public.scouts 
ADD COLUMN IF NOT EXISTS seasons_remaining INTEGER DEFAULT 5,
ADD COLUMN IF NOT EXISTS is_free_agent BOOLEAN DEFAULT false;
CREATE POLICY "Scouts livres são visíveis por todos" 
ON public.scouts 
FOR SELECT 
USING (is_free_agent = true OR auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.advance_scout_seasons()
RETURNS void AS $$
BEGIN
    UPDATE public.scouts
    SET seasons_remaining = seasons_remaining - 1
    WHERE user_id IS NOT NULL;
    
    -- Olheiros que expiraram o contrato tornam-se livres e perdem o vínculo com o usuário
    UPDATE public.scouts
    SET is_free_agent = true, user_id = NULL, seasons_remaining = 0
    WHERE seasons_remaining <= 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.generate_random_scout()
RETURNS void AS $$
DECLARE
    new_name TEXT;
    new_country TEXT;
    new_level scout_level;
    new_spec scout_specialization;
    new_eff DOUBLE PRECISION;
    rand_val DOUBLE PRECISION;
BEGIN
    -- Nomes e países aleatórios simplificados
    new_name := (ARRAY['Marco Rossi', 'Jean Pierre', 'Hans Müller', 'Lucas Silva', 'Diego Torres', 'Liam Smith'])[floor(random() * 6 + 1)];
    new_country := (ARRAY['Brasil', 'Argentina', 'Alemanha', 'França', 'Inglaterra', 'Itália'])[floor(random() * 6 + 1)];
    
    rand_val := random();
    IF rand_val > 0.95 THEN new_level := 'elite'; new_eff := 0.85 + (random() * 0.15);
    ELSIF rand_val > 0.8 THEN new_level := 'alto'; new_eff := 0.7 + (random() * 0.15);
    ELSIF rand_val > 0.5 THEN new_level := 'médio'; new_eff := 0.5 + (random() * 0.2);
    ELSE new_level := 'baixo'; new_eff := 0.3 + (random() * 0.2);
    END IF;
    new_spec := (ARRAY['ataque', 'defesa', 'meio', 'jovens', 'geral'])[floor(random() * 5 + 1)]::scout_specialization;
    INSERT INTO public.scouts (name, country, level, specialization, efficiency, is_free_agent, seasons_remaining)
    VALUES (new_name, new_country, new_level, new_spec, new_eff, true, 5);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
ALTER TABLE public.scouts ALTER COLUMN user_id DROP NOT NULL;
ALTER TABLE public.scouts 
ADD COLUMN IF NOT EXISTS market_available_at TIMESTAMP WITH TIME ZONE,
