CREATE OR REPLACE FUNCTION public.generate_weekly_scout()
RETURNS void AS $$
DECLARE
    new_name TEXT;
    new_country TEXT;
    new_level scout_level;
    new_spec scout_specialization;
    new_eff DOUBLE PRECISION;
    rand_val DOUBLE PRECISION;
BEGIN
    new_name := (ARRAY['Marco Rossi', 'Jean Pierre', 'Hans Müller', 'Lucas Silva', 'Diego Torres', 'Liam Smith', 'Mateo Silva', 'Enzo Ferrari'])[floor(random() * 8 + 1)];
    new_country := (ARRAY['Brasil', 'Argentina', 'Alemanha', 'França', 'Inglaterra', 'Itália', 'Espanha', 'Portugal'])[floor(random() * 8 + 1)];
    
    rand_val := random();
    IF rand_val > 0.95 THEN new_level := 'elite'; new_eff := 0.85 + (random() * 0.15);
    ELSIF rand_val > 0.8 THEN new_level := 'alto'; new_eff := 0.7 + (random() * 0.15);
    ELSIF rand_val > 0.5 THEN new_level := 'médio'; new_eff := 0.5 + (random() * 0.2);
    ELSE new_level := 'baixo'; new_eff := 0.3 + (random() * 0.2);
    END IF;
    new_spec := (ARRAY['ataque', 'defesa', 'meio', 'jovens', 'geral'])[floor(random() * 5 + 1)]::scout_specialization;
    -- Apenas 1 por semana será 'is_free_agent' e terá 'market_available_at' definido como agora
    INSERT INTO public.scouts (name, country, level, specialization, efficiency, is_free_agent, seasons_remaining, market_available_at)
    VALUES (new_name, new_country, new_level, new_spec, new_eff, true, 5, now());
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.seed_league_data(p_league_id UUID)
RETURNS void AS $$
DECLARE
    team_rec RECORD;
BEGIN
    FOR team_rec IN SELECT id FROM public.world_teams WHERE league_id = p_league_id LOOP
        -- Insere ou atualiza dados base
        INSERT INTO public.world_league_table (
            league_id, team_id, points, played, wins, draws, losses, goals_for, goals_against, last_5_games
        ) VALUES (
            p_league_id, team_rec.id, 
            floor(random() * 20)::int, -- pontos aleatórios
            floor(random() * 10)::int + 5, -- jogos
            0, 0, 0, 0, 0,
            (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] || 
            (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
            (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
            (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
            (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)]
        )
        ON CONFLICT (league_id, team_id) DO UPDATE SET
            points = EXCLUDED.points,
            played = EXCLUDED.played,
            last_5_games = EXCLUDED.last_5_games;
            
        -- Recalcula wins/draws/losses baseado nos pontos (apenas para simulação visual)
        UPDATE public.world_league_table 
        SET 
            wins = floor(points / 3),
            draws = points % 3,
            losses = played - floor(points / 3) - (points % 3),
            goals_for = played * 2,
            goals_against = played + floor(random() * 5)
        WHERE league_id = p_league_id AND team_id = team_rec.id;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'world_league_table_league_id_team_id_key'
    ) THEN
        ALTER TABLE public.world_league_table ADD CONSTRAINT world_league_table_league_id_team_id_key UNIQUE (league_id, team_id);
    END IF;
END $$;
CREATE OR REPLACE FUNCTION public.seed_league_data(p_league_id UUID)
RETURNS void AS $$
