        v_last5 := (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] || 
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)];
        DELETE FROM public.world_league_table WHERE league_id = p_league_id AND team_id = team_rec.id;
        
        INSERT INTO public.world_league_table (
            league_id, team_id, points, played, wins, draws, losses, goals_for, goals_against, last_5_games
        ) VALUES (
            p_league_id, team_rec.id, 
            floor(random() * 30)::int,
            floor(random() * 10)::int + 10,
            0, 0, 0, 0, 0,
            v_last5
        );
            
        UPDATE public.world_league_table 
        SET 
            wins = floor(points / 3),
            draws = points % 3,
            losses = played - floor(points / 3) - (points % 3),
            goals_for = played * 2,
            goals_against = played + floor(random() * 10)
        WHERE league_id = p_league_id AND team_id = team_rec.id;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.seed_league_data(p_league_id UUID)
RETURNS void AS $$
DECLARE
    team_rec RECORD;
    v_last5 TEXT;
BEGIN
    FOR team_rec IN SELECT id FROM public.world_teams WHERE league_id = p_league_id LOOP
        v_last5 := (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] || 
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)] ||
                   (ARRAY['V','E','D','V','V', 'D', 'E'])[floor(random() * 7 + 1)];
        DELETE FROM public.world_league_table WHERE league_id = p_league_id AND team_id = team_rec.id;
        
        INSERT INTO public.world_league_table (
            league_id, team_id, points, played, wins, draws, losses, goals_for, goals_against, last_5_games,
            season_year, season_month
        ) VALUES (
            p_league_id, team_rec.id, 
            floor(random() * 30)::int,
            floor(random() * 10)::int + 10,
            0, 0, 0, 0, 0,
            v_last5,
            2026, 5 -- Ano e mês atuais conforme sistema
        );
            
        UPDATE public.world_league_table 
        SET 
            wins = floor(points / 3),
            draws = points % 3,
            losses = played - floor(points / 3) - (points % 3),
            goals_for = played * 2,
            goals_against = (played * 2) - floor(points / 3) * 2 -- Ajuste para SG bater
        WHERE league_id = p_league_id AND team_id = team_rec.id;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.recalculate_league_table_from_matches(p_league_id UUID)
RETURNS void AS $$
DECLARE
    team_rec RECORD;
    v_wins INT;
    v_draws INT;
    v_losses INT;
    v_played INT;
    v_goals_for INT;
    v_goals_against INT;
    v_points INT;
    v_last5 TEXT;
BEGIN
    FOR team_rec IN SELECT id FROM public.world_teams WHERE league_id = p_league_id LOOP
        -- Calcula vitórias, empates, derrotas e gols em casa
        SELECT 
            COUNT(*) FILTER (WHERE home_goals > away_goals),
            COUNT(*) FILTER (WHERE home_goals = away_goals),
            COUNT(*) FILTER (WHERE home_goals < away_goals),
            SUM(home_goals),
            SUM(away_goals)
        INTO v_wins, v_draws, v_losses, v_goals_for, v_goals_against
        FROM public.world_matches 
        WHERE league_id = p_league_id AND home_team_id = team_rec.id AND status = 'finished';
        -- Adiciona resultados como visitante
        DECLARE
            v_away_wins INT;
            v_away_draws INT;
            v_away_losses INT;
            v_away_gf INT;
            v_away_ga INT;
        BEGIN
            SELECT 
                COUNT(*) FILTER (WHERE away_goals > home_goals),
                COUNT(*) FILTER (WHERE away_goals = home_goals),
                COUNT(*) FILTER (WHERE away_goals < home_goals),
                SUM(away_goals),
                SUM(home_goals)
            INTO v_away_wins, v_away_draws, v_away_losses, v_away_gf, v_away_ga
            FROM public.world_matches 
            WHERE league_id = p_league_id AND away_team_id = team_rec.id AND status = 'finished';
            v_wins := v_wins + COALESCE(v_away_wins, 0);
            v_draws := v_draws + COALESCE(v_away_draws, 0);
            v_losses := v_losses + COALESCE(v_away_losses, 0);
            v_goals_for := COALESCE(v_goals_for, 0) + COALESCE(v_away_gf, 0);
            v_goals_against := COALESCE(v_goals_against, 0) + COALESCE(v_away_ga, 0);
        END;
        v_played := v_wins + v_draws + v_losses;
        v_points := (v_wins * 3) + v_draws;
        -- Calcula a sequência dos últimos 5 jogos reais
        SELECT string_agg(res, '') FROM (
            SELECT 
                CASE 
                    WHEN (home_team_id = team_rec.id AND home_goals > away_goals) OR (away_team_id = team_rec.id AND away_goals > home_goals) THEN 'V'
                    WHEN home_goals = away_goals THEN 'E'
                    ELSE 'D'
                END as res
            FROM public.world_matches
            WHERE (home_team_id = team_rec.id OR away_team_id = team_rec.id) AND status = 'finished'
            ORDER BY scheduled_at DESC
            LIMIT 5
        ) sub INTO v_last5;
        -- Atualiza a tabela
        INSERT INTO public.world_league_table (
            league_id, team_id, points, played, wins, draws, losses, goals_for, goals_against, last_5_games,
            season_year, season_month
        ) VALUES (
            p_league_id, team_rec.id, 
            v_points, v_played, v_wins, v_draws, v_losses, v_goals_for, v_goals_against, COALESCE(v_last5, '-----'),
            2026, 5
        )
        ON CONFLICT (league_id, team_id) DO UPDATE SET
            points = EXCLUDED.points,
            played = EXCLUDED.played,
            wins = EXCLUDED.wins,
            draws = EXCLUDED.draws,
            losses = EXCLUDED.losses,
            goals_for = EXCLUDED.goals_for,
            goals_against = EXCLUDED.goals_against,
            last_5_games = EXCLUDED.last_5_games;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
ALTER TABLE public.world_leagues 
ADD COLUMN IF NOT EXISTS division INTEGER DEFAULT 1;
CREATE OR REPLACE FUNCTION public.calculate_match_scheduled_time(p_league_id UUID, p_date DATE)
RETURNS TIMESTAMP WITH TIME ZONE AS $$
DECLARE
    v_division INTEGER;
    v_hour INTEGER;
    v_minute INTEGER;
BEGIN
    SELECT division INTO v_division FROM public.world_leagues WHERE id = p_league_id;
    
    IF v_division = 1 THEN
        -- Divisão 1: Sempre 19:30 BRT (22:30 UTC)
        RETURN (p_date + TIME '22:30:00')::TIMESTAMP WITH TIME ZONE;
    ELSE
        -- Outras divisões: Aleatório a partir das 16:00 BRT (19:00 UTC)
        -- Gera hora entre 19:00 e 23:00 UTC
        v_hour := floor(random() * 5 + 19); 
        v_minute := (ARRAY[0, 15, 30, 45])[floor(random() * 4 + 1)];
        RETURN (p_date + (v_hour || ':' || v_minute || ':00')::TIME)::TIMESTAMP WITH TIME ZONE;
    END IF;
END;
$$ LANGUAGE plpgsql STABLE SET search_path = public;
CREATE OR REPLACE FUNCTION public.get_available_league_for_country(p_country_id UUID)
RETURNS UUID AS $$
DECLARE
    v_league_id UUID;
BEGIN
    -- Busca uma liga Div 1 que não esteja lotada (max 16 times por simplicidade)
    SELECT id INTO v_league_id 
    FROM public.world_leagues 
    WHERE country_id = p_country_id AND division = 1
    AND (SELECT count(*) FROM public.world_teams WHERE league_id = public.world_leagues.id) < 16
    LIMIT 1;
    
    -- Se não achou Div 1 livre, busca ou cria Div 2
    IF v_league_id IS NULL THEN
        SELECT id INTO v_league_id 
        FROM public.world_leagues 
        WHERE country_id = p_country_id AND division = 2
        AND (SELECT count(*) FROM public.world_teams WHERE league_id = public.world_leagues.id) < 16
        LIMIT 1;
    END IF;
    
    RETURN v_league_id;
END;
$$ LANGUAGE plpgsql STABLE SET search_path = public;
CREATE OR REPLACE FUNCTION public.after_match_finished_sync_table()
RETURNS TRIGGER AS $$
BEGIN
    IF (NEW.status = 'finished' AND (OLD.status IS NULL OR OLD.status != 'finished')) THEN
        -- Chama o recalculo para a liga deste jogo
        PERFORM public.recalculate_league_table_from_matches(NEW.league_id);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
DROP TRIGGER IF EXISTS tr_after_match_finished_sync ON public.world_matches;
CREATE TRIGGER tr_after_match_finished_sync
AFTER UPDATE ON public.world_matches
FOR EACH ROW
EXECUTE FUNCTION public.after_match_finished_sync_table();
CREATE OR REPLACE FUNCTION public.admin_add_money_to_club(
    p_target_user_id UUID,
    p_amount BIGINT,
    p_reason TEXT DEFAULT 'Ajuste administrativo'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_old_budget BIGINT;
    v_new_budget BIGINT;
    v_club_name TEXT;
    v_admin_id UUID;
    v_result JSONB;
BEGIN
    -- 1. Verifica se quem chama é admin
    v_admin_id := auth.uid();
    IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_admin_id AND role = 'admin') THEN
        RAISE EXCEPTION 'Acesso negado: Somente administradores podem realizar esta operação.';
    END IF;
    -- 2. Busca clube do alvo e lock para update
    SELECT budget, name INTO v_old_budget, v_club_name
    FROM public.clubs
    WHERE user_id = p_target_user_id
    FOR UPDATE;
    IF v_club_name IS NULL THEN
        RAISE EXCEPTION 'Clube não encontrado para o usuário informado.';
    END IF;
    -- 3. Atualiza o saldo
    UPDATE public.clubs
    SET budget = budget + p_amount,
        updated_at = now()
    WHERE user_id = p_target_user_id
    RETURNING budget INTO v_new_budget;
    -- 4. Registra no Log de Auditoria
    INSERT INTO public.admin_logs (user_id, action, target_user_id, details)
    VALUES (
        v_admin_id,
        'add_money',
        p_target_user_id,
        jsonb_build_object(
            'amount', p_amount,
            'reason', p_reason,
            'club_name', v_club_name,
            'old_budget', v_old_budget,
            'new_budget', v_new_budget
        )
    );
    -- 5. Envia Notificação (se existir tabela de notificações)
    -- Tenta inserir na tabela de notificações do sistema
    BEGIN
        INSERT INTO public.notifications (user_id, title, message, type, is_read, created_at)
        VALUES (
            p_target_user_id,
            CASE WHEN p_amount >= 0 THEN '💰 Bônus Recebido!' ELSE '💸 Ajuste Financeiro' END,
            'Seu clube recebeu um ajuste de R$ ' || TO_CHAR(p_amount, 'FM999G999G999G999') || '. Motivo: ' || p_reason,
            'finance',
            false,
            now()
        );
    EXCEPTION WHEN OTHERS THEN
        -- Se a tabela de notificações não existir ou falhar, apenas ignora
    END;
    -- 6. Retorna resultado para o frontend
    v_result := jsonb_build_object(
        'success', true,
        'club_name', v_club_name,
        'old_budget', v_old_budget,
        'new_budget', v_new_budget,
        'delta', p_amount
    );
    RETURN v_result;
END;
$$;
CREATE TABLE IF NOT EXISTS public.admin_finance_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    admin_id UUID REFERENCES auth.users(id),
    target_user_id UUID REFERENCES auth.users(id),
    amount BIGINT NOT NULL,
    reason TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now()
);
ALTER TABLE public.admin_finance_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins can view finance logs" ON public.admin_finance_logs FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin')
);
CREATE OR REPLACE FUNCTION public.execute_admin_money_transfer(
    p_target_id UUID,
    p_value BIGINT,
    p_description TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_admin_id UUID;
    v_old_bal BIGINT;
    v_new_bal BIGINT;
    v_club_name TEXT;
BEGIN
    -- Validação de Admin
    v_admin_id := auth.uid();
    IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_admin_id AND role = 'admin') THEN
        RAISE EXCEPTION 'Ação não autorizada. Apenas administradores podem gerenciar finanças.';
    END IF;
    -- Busca clube e lock
    SELECT budget, name INTO v_old_bal, v_club_name
    FROM public.clubs
    WHERE user_id = p_target_id
    FOR UPDATE;
    IF v_club_name IS NULL THEN
        RAISE EXCEPTION 'O usuário alvo não possui um clube ativo.';
    END IF;
    -- Executa Transação
    UPDATE public.clubs
    SET budget = budget + p_value,
        updated_at = now()
    WHERE user_id = p_target_id
    RETURNING budget INTO v_new_bal;
    -- Log de Auditoria
    INSERT INTO public.admin_finance_logs (admin_id, target_user_id, amount, reason)
    VALUES (v_admin_id, p_target_id, p_value, p_description);
    -- Notificação de Sistema
    INSERT INTO public.notifications (user_id, title, message, type)
    VALUES (
        p_target_id,
        '💼 Movimentação Administrativa',
        'Seu saldo foi alterado em R$ ' || TO_CHAR(p_value, 'FM999G999G999G999') || '. Motivo: ' || p_description,
        'finance'
    );
    RETURN jsonb_build_object(
        'status', 'success',
        'club', v_club_name,
        'previous_balance', v_old_bal,
        'current_balance', v_new_bal,
        'difference', p_value
    );
END;
$$;
CREATE OR REPLACE FUNCTION public.execute_admin_money_transfer(p_target_id uuid, p_value bigint, p_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_admin_id UUID;
    v_old_bal BIGINT;
    v_new_bal BIGINT;
    v_club_name TEXT;
    v_save_id UUID;
    v_club_data JSONB;
    v_source TEXT;
BEGIN
    v_admin_id := auth.uid();
    IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = v_admin_id AND role = 'admin') THEN
        RAISE EXCEPTION 'Ação não autorizada. Apenas administradores podem gerenciar finanças.';
    END IF;
    -- 1) Tenta tabela legado clubs
    SELECT budget, name INTO v_old_bal, v_club_name
    FROM public.clubs
    WHERE user_id = p_target_id
    FOR UPDATE;
    IF v_club_name IS NOT NULL THEN
        UPDATE public.clubs
        SET budget = budget + p_value, updated_at = now()
        WHERE user_id = p_target_id
        RETURNING budget INTO v_new_bal;
        v_source := 'clubs';
    ELSE
        -- 2) Fallback: game_saves (fonte real do save online)
        SELECT id, club_data INTO v_save_id, v_club_data
        FROM public.game_saves
        WHERE user_id = p_target_id
        FOR UPDATE
        LIMIT 1;
        IF v_save_id IS NULL THEN
            RAISE EXCEPTION 'O usuário alvo não possui clube nem save ativo.';
        END IF;
        v_club_name := COALESCE(v_club_data #>> '{club,name}', v_club_data ->> 'name', 'Clube');
        v_old_bal := COALESCE((v_club_data #>> '{club,budget}')::BIGINT, (v_club_data ->> 'budget')::BIGINT, 0);
        v_new_bal := v_old_bal + p_value;
        IF v_club_data ? 'club' THEN
            v_club_data := jsonb_set(v_club_data, '{club,budget}', to_jsonb(v_new_bal));
        ELSE
            v_club_data := jsonb_set(v_club_data, '{budget}', to_jsonb(v_new_bal));
        END IF;
        UPDATE public.game_saves
        SET club_data = v_club_data, updated_at = now()
        WHERE id = v_save_id;
        v_source := 'game_saves';
    END IF;
    INSERT INTO public.admin_finance_logs (admin_id, target_user_id, amount, reason)
    VALUES (v_admin_id, p_target_id, p_value, p_description);
    INSERT INTO public.notifications (user_id, title, message, type)
    VALUES (
        p_target_id,
        '💼 Movimentação Administrativa',
        'Seu saldo foi alterado em R$ ' || TO_CHAR(p_value, 'FM999G999G999G999') || '. Motivo: ' || p_description,
        'finance'
    );
    RETURN jsonb_build_object(
        'status', 'success',
        'club', v_club_name,
        'previous_balance', v_old_bal,
        'current_balance', v_new_bal,
        'difference', p_value,
        'source', v_source
    );
END;
$function$;
