CREATE POLICY "Jogos da copa são visíveis por todos" ON public.national_cup_matches FOR SELECT USING (true);
CREATE POLICY "Prêmios da copa são visíveis por todos" ON public.national_cup_prizes FOR SELECT USING (true);
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ language 'plpgsql';
CREATE TRIGGER update_national_cups_updated_at BEFORE UPDATE ON public.national_cups FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
CREATE TRIGGER update_national_cup_matches_updated_at BEFORE UPDATE ON public.national_cup_matches FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
ALTER TABLE public.national_cups 
ADD COLUMN IF NOT EXISTS kickoff_time TIME WITHOUT TIME ZONE DEFAULT '12:00:00';
CREATE OR REPLACE FUNCTION public.simulate_overdue_cup_matches()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Esta função apenas marca como 'live' jogos que já passaram do horário
  -- A simulação real dos eventos deve ser feita pela Edge Function para manter a lógica do motor de jogo
  UPDATE public.national_cup_matches
  SET status = 'live'
  WHERE status = 'scheduled'
    AND scheduled_at <= now();
END;
$$;
