CREATE OR REPLACE FUNCTION public.auto_assign_league(_user_id uuid, _club_name text, _country text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _league_id uuid;
  _member_count int;
  _has_active_main boolean;
BEGIN
  -- 1. Check if user is already in any league of this country
  SELECT lm.league_id INTO _league_id
  FROM league_members lm
  JOIN multiplayer_leagues ml ON ml.id = lm.league_id
  WHERE lm.user_id = _user_id AND ml.country = _country
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    RETURN _league_id;
  END IF;
  -- 2. Check if there are active main leagues in progress for this country
  SELECT EXISTS (
    SELECT 1 FROM multiplayer_leagues
    WHERE country = _country AND league_type = 'main' AND season_status = 'in_progress'
  ) INTO _has_active_main;
  IF _has_active_main THEN
    -- Season is running: Try to find an open beginner league
    SELECT ml.id INTO _league_id
    FROM multiplayer_leagues ml
    WHERE ml.country = _country
      AND ml.league_type = 'beginner'
      AND ml.auto_created = true
      AND ml.season_status IN ('registration', 'waiting')
      AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id) < ml.max_members
    ORDER BY ml.created_at ASC
    LIMIT 1;
    -- If no beginner league with space, user must wait or we can let them join a beginner league if we want to keep it "infinite"
    -- But the instruction says "Nunca criar ligas infinitas automaticamente"
    -- For beginner leagues, we might allow creation or also put in queue. 
    -- The user specifically asked for "Inscrito para próxima temporada" which implies the MAIN league.
    
    IF _league_id IS NOT NULL THEN
       INSERT INTO league_members (league_id, user_id, club_name, club_logo)
       VALUES (_league_id, _user_id, _club_name, '⚽')
       ON CONFLICT DO NOTHING;
       RETURN _league_id;
    END IF;
  END IF;
  -- 3. Try to join main league in registration/waiting
  SELECT ml.id INTO _league_id
  FROM multiplayer_leagues ml
  WHERE ml.country = _country
    AND ml.league_type = 'main'
    AND ml.auto_created = true
    AND ml.season_status IN ('registration', 'waiting')
    AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id) < ml.max_members
  ORDER BY ml.division ASC, ml.created_at ASC
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    INSERT INTO league_members (league_id, user_id, club_name, club_logo)
    VALUES (_league_id, _user_id, _club_name, '⚽')
    ON CONFLICT DO NOTHING;
    RETURN _league_id;
  END IF;
  -- 4. If no space and no league in registration, add to waiting list
  -- We DON'T create a new league here anymore as per "O jogo NÃO deve criar automaticamente uma nova liga"
  INSERT INTO public.league_waiting_list (user_id, country, league_type, status)
  VALUES (_user_id, _country, 'main', 'waiting')
  ON CONFLICT (user_id, country, league_type) DO UPDATE SET status = 'waiting', enrolled_at = NOW();
  RETURN NULL; -- Return NULL to indicate queued
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_league_waiting_list(_league_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_country TEXT;
  v_league_type TEXT;
  v_max_members INT;
  v_current_members INT;
  v_vagas INT;
  v_next_user RECORD;
BEGIN
  -- Get league details
  SELECT country, league_type, max_members INTO v_country, v_league_type, v_max_members
  FROM multiplayer_leagues
  WHERE id = _league_id;
  -- Count current members
  SELECT count(*) INTO v_current_members
  FROM league_members
  WHERE league_id = _league_id;
  v_vagas := v_max_members - v_current_members;
  WHILE v_vagas > 0 LOOP
    -- Get next user in line for this country and type
    SELECT * INTO v_next_user
    FROM league_waiting_list
    WHERE country = v_country 
      AND league_type = v_league_type 
      AND status = 'waiting'
    ORDER BY enrolled_at ASC
    LIMIT 1;
    EXIT WHEN v_next_user IS NULL;
    -- Get club name (from profile or clubs table)
    -- We'll assume the client passes it or we find it. For now, try to find it in clubs.
    DECLARE
      v_club_name TEXT;
    BEGIN
      SELECT name INTO v_club_name FROM clubs WHERE user_id = v_next_user.user_id LIMIT 1;
      IF v_club_name IS NULL THEN v_club_name := 'Novo Clube'; END IF;
      -- Add to league
      INSERT INTO league_members (league_id, user_id, club_name, club_logo)
      VALUES (_league_id, v_next_user.user_id, v_club_name, '⚽')
      ON CONFLICT DO NOTHING;
      -- Mark as processed
      UPDATE league_waiting_list SET status = 'processed' WHERE id = v_next_user.id;
      
      -- Send notification
      INSERT INTO user_notifications (user_id, title, message, type)
      VALUES (v_next_user.user_id, '⚽ Bem-vindo à Liga!', 'Sua vaga na liga ' || v_country || ' foi liberada. A temporada começou!', 'league_entry');
    END;
    v_vagas := v_vagas - 1;
  END LOOP;
END;
$$;
CREATE OR REPLACE FUNCTION public.trigger_on_member_leave()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Small delay or background task would be ideal, but for now we run it inline
  -- Or just check if the league is in registration/waiting
  PERFORM public.process_league_waiting_list(OLD.league_id);
  RETURN OLD;
END;
$$;
CREATE OR REPLACE TRIGGER trg_on_member_leave
AFTER DELETE ON public.league_members
FOR EACH ROW EXECUTE FUNCTION public.trigger_on_member_leave();
