CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id UUID)
RETURNS JSONB AS $$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
BEGIN
    -- 1. Buscar pedido com LOCK para evitar concorrência (Race Conditions)
    SELECT * INTO v_order FROM public.payment_orders WHERE id = p_order_id FOR UPDATE;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pedido não encontrado', 'status', 'NOT_FOUND');
    END IF;
    -- 2. Validar Status (Só libera se for approved/PAID)
    IF v_order.status != 'approved' AND v_order.status != 'paid' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pagamento não confirmado', 'current_status', v_order.status);
    END IF;
    -- 3. Anti-Duplicação (Verificar se já foi entregue)
    IF v_order.delivered IS TRUE THEN
        RETURN jsonb_build_object('success', true, 'message', 'O produto já foi liberado anteriormente', 'already_delivered', true);
    END IF;
    -- 4. Buscar detalhes do item comprado
    SELECT * INTO v_item FROM public.shop_items WHERE id = v_order.item_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Configuração do item não encontrada');
    END IF;
    -- 5. Buscar o clube vinculado ao usuário
    SELECT id INTO v_club_id FROM public.clubs WHERE user_id = v_order.user_id;
    -- 6. Lógica de Liberação Baseada no Tipo de Produto
    CASE v_item.category
        WHEN 'finance' THEN
            -- Liberação de Créditos/Dinheiro no Jogo
            UPDATE public.clubs 
            SET budget = budget + COALESCE((v_item.bonus_data->>'value')::numeric, 0),
                updated_at = now()
            WHERE id = v_club_id;
            
        WHEN 'marketing' THEN
            -- Liberação de Torcedores (Expansão de marca)
            UPDATE public.clubs 
            SET fans = fans + COALESCE((v_item.bonus_data->>'value')::integer, 0),
                updated_at = now()
            WHERE id = v_club_id;
            
        WHEN 'premium' THEN
            -- Ativação de Assinatura Premium
            INSERT INTO public.premium_users (user_id, expires_at)
            VALUES (v_order.user_id, now() + interval '30 days')
            ON CONFLICT (user_id) 
            DO UPDATE SET expires_at = GREATEST(premium_users.expires_at, now()) + interval '30 days';
            
        WHEN 'uniform' THEN
            -- Liberação de Slots de Lançamento de Uniforme
            UPDATE public.clubs 
            SET uniform_launches_available = uniform_launches_available + 1,
                updated_at = now()
            WHERE id = v_club_id;
            
        ELSE
            -- Item de Inventário Genérico
            INSERT INTO public.shop_inventory (user_id, item_id, quantity)
            VALUES (v_order.user_id, v_item.id, 1)
            ON CONFLICT (user_id, item_id) 
            DO UPDATE SET quantity = shop_inventory.quantity + 1, updated_at = now();
    END CASE;
    -- 7. Atualizar Status de Entrega e Persistir Timestamp
    UPDATE public.payment_orders 
    SET delivered = true, 
        updated_at = now() 
    WHERE id = p_order_id;
    -- 8. Registrar Logs de Auditoria para Segurança
    INSERT INTO public.admin_logs (action, details)
    VALUES ('AUTO_DELIVERY', jsonb_build_object(
        'order_id', p_order_id, 
        'user_id', v_order.user_id, 
        'item_name', v_item.name,
        'category', v_item.category,
        'released_at', now()
    ));
    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Produto liberado com sucesso', 
        'item', v_item.name,
        'released_at', now()
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
ALTER TABLE public.world_matches 
ADD COLUMN IF NOT EXISTS season_month INTEGER,
ADD COLUMN IF NOT EXISTS season_year INTEGER;
UPDATE public.world_matches 
SET 
  season_month = EXTRACT(MONTH FROM scheduled_at),
  season_year = EXTRACT(YEAR FROM scheduled_at)
WHERE season_month IS NULL;
UPDATE public.world_leagues 
SET current_round = 10;
UPDATE public.world_matches
SET status = 'played',
    played_at = now(),
    home_goals = (random() * 4)::int,
    away_goals = (random() * 3)::int
WHERE round <= 10 AND status = 'scheduled';
UPDATE public.multiplayer_leagues
SET current_round = 10
WHERE season_status = 'in_progress';
UPDATE public.league_matches
SET status = 'played',
    played_at = now(),
    home_goals = (random() * 4)::int,
    away_goals = (random() * 3)::int
WHERE round <= 10 AND status = 'scheduled';
UPDATE public.world_leagues 
SET current_round = 16;
UPDATE public.world_matches
SET status = 'played',
    played_at = now(),
    home_goals = (random() * 4)::int,
    away_goals = (random() * 3)::int
WHERE round <= 16 AND status = 'scheduled';
UPDATE public.multiplayer_leagues
SET current_round = 16
WHERE season_status = 'in_progress';
UPDATE public.league_matches
SET status = 'played',
    played_at = now(),
    home_goals = (random() * 4)::int,
    away_goals = (random() * 3)::int
WHERE round <= 16 AND status = 'scheduled';
DO $$
DECLARE
  v_league_id uuid := 'edb83ebc-95c3-4f26-99b3-0b758a5d08c6';
  v_team_ids uuid[];
  v_n int;
  v_round int;
  v_i int;
  v_home uuid;
  v_away uuid;
  v_kick timestamptz;
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_fixed uuid;
  v_rotating uuid[];
  v_left uuid[];
  v_right uuid[];
  v_status text;
  v_hg int;
  v_ag int;
  v_smonth int;
  v_syear int;
  v_round_volta int;
BEGIN
  SELECT season_month, season_year INTO v_smonth, v_syear FROM public.world_leagues WHERE id = v_league_id;
  DELETE FROM public.world_matches WHERE league_id = v_league_id;
  SELECT array_agg(id ORDER BY random()) INTO v_team_ids
  FROM public.world_teams WHERE league_id = v_league_id;
  v_n := array_length(v_team_ids, 1);
  IF v_n IS NULL OR v_n < 4 OR v_n % 2 <> 0 THEN RETURN; END IF;
  v_fixed := v_team_ids[1];
  v_rotating := v_team_ids[2:v_n];
  FOR v_round IN 1..(v_n - 1) LOOP
    v_left := array_prepend(v_fixed, v_rotating[1:(v_n/2 - 1)]);
    v_right := (SELECT array_agg(x ORDER BY i DESC) FROM unnest(v_rotating[(v_n/2):(v_n-1)]) WITH ORDINALITY AS t(x, i));
    FOR v_i IN 1..(v_n/2) LOOP
      IF v_round % 2 = 1 THEN
        v_home := v_left[v_i]; v_away := v_right[v_i];
      ELSE
        v_home := v_right[v_i]; v_away := v_left[v_i];
      END IF;
      -- IDA
      v_kick := ((v_today - 16 + v_round)::text || ' 19:30:00-03')::timestamptz;
      v_status := CASE WHEN v_round <= 16 THEN 'finished' ELSE 'scheduled' END;
      v_hg := CASE WHEN v_status = 'finished' THEN floor(random()*4)::int ELSE 0 END;
      v_ag := CASE WHEN v_status = 'finished' THEN floor(random()*3)::int ELSE 0 END;
      INSERT INTO public.world_matches
        (league_id, home_team_id, away_team_id, round, status, home_goals, away_goals, scheduled_at, played_at, season_month, season_year)
      VALUES
        (v_league_id, v_home, v_away, v_round, v_status, v_hg, v_ag, v_kick,
         CASE WHEN v_status='finished' THEN v_kick END, v_smonth, v_syear);
      -- VOLTA
      v_round_volta := v_round + (v_n - 1);
      v_kick := ((v_today - 16 + v_round_volta)::text || ' 19:30:00-03')::timestamptz;
      v_status := CASE WHEN v_round_volta <= 16 THEN 'finished' ELSE 'scheduled' END;
      v_hg := CASE WHEN v_status = 'finished' THEN floor(random()*4)::int ELSE 0 END;
      v_ag := CASE WHEN v_status = 'finished' THEN floor(random()*3)::int ELSE 0 END;
      INSERT INTO public.world_matches
        (league_id, home_team_id, away_team_id, round, status, home_goals, away_goals, scheduled_at, played_at, season_month, season_year)
      VALUES
        (v_league_id, v_away, v_home, v_round_volta, v_status, v_hg, v_ag, v_kick,
         CASE WHEN v_status='finished' THEN v_kick END, v_smonth, v_syear);
    END LOOP;
    v_rotating := array_prepend(v_rotating[v_n - 1], v_rotating[1:(v_n - 2)]);
  END LOOP;
  UPDATE public.world_leagues SET current_round = 16 WHERE id = v_league_id;
END $$;
