ALTER TABLE public.payment_orders ADD COLUMN IF NOT EXISTS delivered BOOLEAN DEFAULT FALSE;
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_duration_days INTEGER;
    v_immediate_cash INTEGER;
BEGIN
    -- 1. Get order and item details
    SELECT po.* INTO v_order FROM public.payment_orders po WHERE po.id = p_order_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Order not found');
    END IF;
    IF v_order.delivered THEN
        RETURN jsonb_build_object('success', true, 'message', 'Already delivered');
    END IF;
    SELECT si.* INTO v_item FROM public.shop_items si WHERE si.id = v_order.item_id;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;
    -- 2. Get club ID for the user
    SELECT id INTO v_club_id FROM public.clubs WHERE user_id = v_order.user_id;
    
    IF v_club_id IS NULL THEN
        -- Fallback if club table not yet synced
        RETURN jsonb_build_object('success', false, 'error', 'Club not found for user');
    END IF;
    -- 3. Calculate expiration
    v_duration_days := COALESCE(v_item.duration_days, 30);
    v_expires_at := now() + (v_duration_days || ' days')::INTERVAL;
    -- 4. Logic by category
    CASE v_item.category
        WHEN 'sponsorship' THEN
            -- Add to club_sponsorships
            INSERT INTO public.club_sponsorships (
                club_id, 
                sponsor_name, 
                contract_value_cents, 
                payment_type, 
                bonus_data, 
                expires_at
            ) VALUES (
                v_club_id,
                v_item.name,
                COALESCE((v_item.bonus_data->>'dinheiroSemanal')::numeric, 0) * 100,
                'weekly',
                v_item.bonus_data,
                v_expires_at
            );
            -- Check for immediate cash bonus
            v_immediate_cash := COALESCE((v_item.bonus_data->>'immediate_cash')::integer, 0);
            IF v_immediate_cash > 0 THEN
                UPDATE public.clubs SET budget = budget + v_immediate_cash WHERE id = v_club_id;
            END IF;
        WHEN 'marketing' THEN
            -- Add to active effects
            INSERT INTO public.club_active_effects (
                club_id,
                item_id,
                category,
                bonus_data,
                expires_at
            ) VALUES (
                v_club_id,
                v_item.id,
                'marketing',
                v_item.bonus_data,
                v_expires_at
            );
        WHEN 'stickers' THEN
            -- For stickers, we could grant special packs or just mark as active
            -- Stickers usually are one-time items or per-purchase
            -- We'll track it in active effects for now to show "Active" in UI
            INSERT INTO public.club_active_effects (
                club_id,
                item_id,
                category,
                bonus_data,
                expires_at
            ) VALUES (
                v_club_id,
                v_item.id,
                'stickers',
                v_item.bonus_data,
                v_expires_at
            );
        WHEN 'uniform' THEN
            -- Unlock uniform editor
            INSERT INTO public.club_active_effects (
                club_id,
                item_id,
                category,
                bonus_data,
                expires_at
            ) VALUES (
                v_club_id,
                v_item.id,
                'uniform',
                v_item.bonus_data,
                v_expires_at
            );
        WHEN 'members' THEN
            -- Update club membership status
            INSERT INTO public.club_memberships (
                club_id,
                active_plan_id,
                total_members,
                monthly_revenue_cents,
                happiness
            ) VALUES (
                v_club_id,
                v_item.id,
                COALESCE((v_item.bonus_data->>'initialMembers')::integer, 100),
                COALESCE((v_item.bonus_data->>'monthlyRevenue')::numeric, 0) * 100,
                100
            ) ON CONFLICT (club_id) DO UPDATE SET
                active_plan_id = v_item.id,
                happiness = 100;
        ELSE
            -- Generic handler for other items
            INSERT INTO public.club_active_effects (
                club_id,
                item_id,
                category,
                bonus_data,
                expires_at
            ) VALUES (
                v_club_id,
                v_item.id,
                v_item.category,
                v_item.bonus_data,
                v_expires_at
            );
    END CASE;
    -- 5. Mark as delivered
    UPDATE public.payment_orders SET delivered = TRUE, status = 'approved' WHERE id = p_order_id;
    -- 6. Log in club history or news
    INSERT INTO public.newspaper_entries (
        user_id,
        text,
        category,
        importance
    ) VALUES (
        v_order.user_id,
        format('O clube anunciou a aquisição de: %s. Um marco importante para o futuro do time!', v_item.name),
        'finance',
        2
    );
    RETURN jsonb_build_object('success', true, 'delivered_at', now());
END;
$$;
ALTER TABLE public.clubs 
ADD COLUMN IF NOT EXISTS total_members INTEGER DEFAULT 0,
ADD COLUMN IF NOT EXISTS engagement_rate DECIMAL DEFAULT 5.0,
ADD COLUMN IF NOT EXISTS sales_bonus_multiplier DECIMAL DEFAULT 1.0;
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_duration_days INTEGER;
    v_immediate_cash INTEGER;
    v_new_fans INTEGER;
    v_new_members INTEGER;
    v_sales_bonus DECIMAL;
BEGIN
    SELECT po.* INTO v_order FROM public.payment_orders po WHERE po.id = p_order_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Order not found'); END IF;
    IF v_order.delivered THEN RETURN jsonb_build_object('success', true, 'message', 'Already delivered'); END IF;
    SELECT si.* INTO v_item FROM public.shop_items si WHERE si.id = v_order.item_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Item not found'); END IF;
    SELECT id INTO v_club_id FROM public.clubs WHERE user_id = v_order.user_id;
    IF v_club_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Club not found'); END IF;
    v_duration_days := COALESCE(v_item.duration_days, 30);
    v_expires_at := now() + (v_duration_days || ' days')::INTERVAL;
    CASE v_item.category
        WHEN 'members' THEN
            -- Extract impacts from bonus_data
            v_new_members := COALESCE((v_item.bonus_data->>'initialMembers')::integer, 100);
            v_new_fans := COALESCE((v_item.bonus_data->>'initialFans')::integer, 500);
            v_sales_bonus := COALESCE((v_item.bonus_data->>'salesMultiplier')::decimal, 1.1);
            -- Apply impacts to club
            UPDATE public.clubs SET 
                total_members = total_members + v_new_members,
                fans = fans + v_new_fans,
                sales_bonus_multiplier = GREATEST(sales_bonus_multiplier, v_sales_bonus),
                engagement_rate = LEAST(engagement_rate + 2.0, 15.0)
            WHERE id = v_club_id;
            -- Membership specific record
            INSERT INTO public.club_memberships (
                club_id, active_plan_id, total_members, monthly_revenue_cents, happiness
            ) VALUES (
                v_club_id, v_item.id, v_new_members,
                COALESCE((v_item.bonus_data->>'monthlyRevenue')::numeric, 0) * 100,
                100
            ) ON CONFLICT (club_id) DO UPDATE SET
                active_plan_id = v_item.id,
                total_members = public.club_memberships.total_members + EXCLUDED.total_members,
                happiness = 100;
        WHEN 'marketing' THEN
            UPDATE public.clubs SET 
                engagement_rate = LEAST(engagement_rate + 1.5, 20.0),
                fans = fans + COALESCE((v_item.bonus_data->>'immediate_fans')::integer, 200)
            WHERE id = v_club_id;
            INSERT INTO public.club_active_effects (club_id, item_id, category, bonus_data, expires_at)
            VALUES (v_club_id, v_item.id, 'marketing', v_item.bonus_data, v_expires_at);
        WHEN 'sponsorship' THEN
            INSERT INTO public.club_sponsorships (club_id, sponsor_name, contract_value_cents, payment_type, bonus_data, expires_at)
            VALUES (v_club_id, v_item.name, COALESCE((v_item.bonus_data->>'dinheiroSemanal')::numeric, 0) * 100, 'weekly', v_item.bonus_data, v_expires_at);
            
            v_immediate_cash := COALESCE((v_item.bonus_data->>'immediate_cash')::integer, 0);
            IF v_immediate_cash > 0 THEN
                UPDATE public.clubs SET budget = budget + v_immediate_cash WHERE id = v_club_id;
            END IF;
        
        ELSE
            INSERT INTO public.club_active_effects (club_id, item_id, category, bonus_data, expires_at)
            VALUES (v_club_id, v_item.id, v_item.category, v_item.bonus_data, v_expires_at);
    END CASE;
    UPDATE public.payment_orders SET delivered = TRUE, status = 'approved' WHERE id = p_order_id;
    INSERT INTO public.newspaper_entries (user_id, text, category, importance)
    VALUES (v_order.user_id, format('O clube anunciou a aquisição de: %s. A torcida está empolgada!', v_item.name), 'finance', 2);
    RETURN jsonb_build_object('success', true, 'delivered_at', now());
END;
$$;
CREATE OR REPLACE FUNCTION public.calculate_merch_sales(p_club_id UUID, p_base_amount BIGINT)
RETURNS BIGINT
LANGUAGE plpgsql
AS $$
DECLARE
    v_multiplier DECIMAL;
    v_members_bonus DECIMAL;
    v_total_members INTEGER;
BEGIN
    SELECT sales_bonus_multiplier, total_members INTO v_multiplier, v_total_members FROM public.clubs WHERE id = p_club_id;
    
    -- Bonus based on members volume (0.1% per 1000 members)
    v_members_bonus := 1.0 + (v_total_members::decimal / 100000.0);
    
    RETURN (p_base_amount::decimal * v_multiplier * v_members_bonus)::bigint;
END;
$$;
ALTER TABLE public.club_active_effects
  ADD COLUMN IF NOT EXISTS last_delivery_at timestamptz NOT NULL DEFAULT now();
DROP POLICY IF EXISTS "Users insert own free orders" ON public.payment_orders;
CREATE POLICY "Users insert own free orders" ON public.payment_orders
  FOR INSERT
  WITH CHECK (
    auth.uid() = user_id
    AND amount_cents >= 0
    AND status = 'approved'
  );
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club RECORD;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_duration_days INTEGER;
    v_immediate_cash INTEGER;
    v_new_fans INTEGER;
    v_new_members INTEGER;
    v_sales_bonus DECIMAL;
    v_sub_type TEXT;
BEGIN
    SELECT po.* INTO v_order FROM public.payment_orders po WHERE po.id = p_order_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Order not found'); END IF;
    IF v_order.delivered THEN RETURN jsonb_build_object('success', true, 'message', 'Already delivered'); END IF;
    SELECT si.* INTO v_item FROM public.shop_items si WHERE si.id = v_order.item_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Item not found'); END IF;
    SELECT * INTO v_club FROM public.clubs WHERE user_id = v_order.user_id;
    IF v_club.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Club not found'); END IF;
    -- VALIDAÇÃO DE TORCIDA (anti-abuso: bloqueia ativação se torcida caiu entre compra e entrega)
    IF v_item.category = 'sponsorship' AND COALESCE(v_club.fans, 0) < COALESCE(v_item.min_fans, 0) THEN
        UPDATE public.payment_orders SET status = 'refunded', delivered = false,
            metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('refund_reason', 'insufficient_fans', 'required_fans', v_item.min_fans, 'club_fans', v_club.fans)
        WHERE id = p_order_id;
        INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
        VALUES (v_order.user_id, 'warning', 'Financeiro', 'high',
                'Patrocínio não ativado',
                format('O patrocínio "%s" exige %s torcedores. Você tem %s. O pedido foi marcado para estorno.', v_item.name, v_item.min_fans, v_club.fans),
                '⚠️', jsonb_build_object('order_id', p_order_id, 'item_id', v_item.id));
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_fans');
    END IF;
    v_duration_days := COALESCE(v_item.duration_days, 30);
    v_expires_at := now() + (v_duration_days || ' days')::INTERVAL;
    v_sub_type := COALESCE(v_item.bonus_data->>'sub_type', v_item.category);
    CASE v_item.category
        WHEN 'members' THEN
            v_new_members := COALESCE((v_item.bonus_data->>'initialMembers')::integer, 100);
            v_new_fans := COALESCE((v_item.bonus_data->>'initialFans')::integer, 500);
            v_sales_bonus := COALESCE((v_item.bonus_data->>'salesMultiplier')::decimal, 1.1);
            UPDATE public.clubs SET 
                total_members = total_members + v_new_members,
                fans = fans + v_new_fans,
                sales_bonus_multiplier = GREATEST(sales_bonus_multiplier, v_sales_bonus),
                engagement_rate = LEAST(engagement_rate + 2.0, 15.0)
            WHERE id = v_club.id;
            INSERT INTO public.club_memberships (
                club_id, active_plan_id, total_members, monthly_revenue_cents, happiness
            ) VALUES (
                v_club.id, v_item.id, v_new_members,
                COALESCE((v_item.bonus_data->>'monthlyRevenue')::numeric, 0) * 100,
                100
            ) ON CONFLICT (club_id) DO UPDATE SET
                active_plan_id = v_item.id,
                total_members = public.club_memberships.total_members + EXCLUDED.total_members,
                happiness = 100;
        WHEN 'marketing' THEN
            UPDATE public.clubs SET 
                engagement_rate = LEAST(engagement_rate + 1.5, 20.0),
                fans = fans + COALESCE((v_item.bonus_data->>'immediate_fans')::integer, 200)
            WHERE id = v_club.id;
            INSERT INTO public.club_active_effects (club_id, item_id, category, bonus_data, expires_at)
            VALUES (v_club.id, v_item.id, 'marketing', v_item.bonus_data, v_expires_at);
        WHEN 'sponsorship' THEN
            INSERT INTO public.club_sponsorships (club_id, sponsor_name, contract_value_cents, payment_type, bonus_data, expires_at)
            VALUES (v_club.id, v_item.name, COALESCE((v_item.bonus_data->>'dinheiroSemanal')::numeric, 0) * 100, 'weekly', v_item.bonus_data, v_expires_at);
            v_immediate_cash := COALESCE((v_item.bonus_data->>'immediate_cash')::integer, 0);
            IF v_immediate_cash > 0 THEN
                UPDATE public.clubs SET budget = budget + v_immediate_cash WHERE id = v_club.id;
            END IF;
            -- Notificação enriquecida de patrocínio
            INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
            VALUES (v_order.user_id, 'success', 'Patrocínio', 'high',
                    format('Novo patrocínio: %s', v_item.name),
                    format('Contrato (%s) assinado. Bônus imediato: R$ %s. Renda diária ativada.',
                           upper(v_sub_type),
                           to_char(v_immediate_cash, 'FM999G999G999')),
                    '🤝',
                    jsonb_build_object('order_id', p_order_id, 'item_id', v_item.id, 'sub_type', v_sub_type));
        ELSE
            INSERT INTO public.club_active_effects (club_id, item_id, category, bonus_data, expires_at)
            VALUES (v_club.id, v_item.id, v_item.category, v_item.bonus_data, v_expires_at);
    END CASE;
    UPDATE public.payment_orders SET delivered = TRUE, status = 'approved' WHERE id = p_order_id;
    INSERT INTO public.newspaper_entries (user_id, text, category, importance)
    VALUES (v_order.user_id, format('O clube anunciou a aquisição de: %s. A torcida está empolgada!', v_item.name), 'finance', 2);
    RETURN jsonb_build_object('success', true, 'delivered_at', now());
END;
$function$;
CREATE OR REPLACE FUNCTION public.cron_generate_youth_for_all()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_club RECORD;
  v_processed INT := 0;
  v_generated INT := 0;
  v_skipped INT := 0;
  v_academy JSONB;
  v_academy_level INT;
  v_academy_active BOOLEAN;
  v_investment NUMERIC;
  v_cycle_days INT;
  v_cycle_interval INTERVAL;
  v_max_prospects INT;
  v_current_count INT;
  v_name TEXT;
  v_first_names TEXT[] := ARRAY[
    'Gabriel','Lucas','Matheus','Vinícius','Pedro','João','Felipe','Thiago','Bruno','Rodrigo',
    'Arthur','Diego','Rafael','Vitor','Gustavo','Carlos','Eduardo','Henrique','Ícaro','Júnior',
    'Kauã','Leonardo','Murilo','Nathan','Otávio','Paulo','Renan','Samuel','Tiago','Wesley'
  ];
  v_surnames TEXT[] := ARRAY[
    'Silva','Santos','Oliveira','Souza','Rodrigues','Ferreira','Alves','Pereira','Lima','Gomes',
    'Costa','Ribeiro','Martins','Carvalho','Lopes','Almeida','Barros','Cardoso','Dias','Mendes',
    'Nogueira','Pinto','Rocha','Teixeira','Vieira','Moreira','Cavalcanti','Tavares','Andrade','Moura'
  ];
  v_positions TEXT[] := ARRAY['GOL','ZAG','LAT','VOL','MEI','ATA'];
  v_personalities TEXT[] := ARRAY['lider','festeiro','dedicado','ambicioso','leal','calmo','competitivo','introvertido'];
  v_position TEXT;
  v_age INT;
  v_min_ovr INT;
  v_max_ovr INT;
  v_overall INT;
  v_potential INT;
  v_rarity TEXT;
  v_rarity_luck NUMERIC;
  v_dominant TEXT;
  v_height INT;
  v_weight INT;
  v_market_value BIGINT;
  v_attrs JSONB;
  v_prospect_id UUID;
BEGIN
  FOR v_club IN
    SELECT c.id, c.user_id, c.country, c.last_youth_generation_at, gs.club_data
    FROM public.clubs c
    LEFT JOIN public.game_saves gs ON gs.user_id = c.user_id
    WHERE c.user_id IS NOT NULL
  LOOP
    v_processed := v_processed + 1;
    v_academy := COALESCE(v_club.club_data->'infrastructure'->'youthAcademy', '{}'::jsonb);
    v_academy_level := COALESCE((v_academy->>'level')::INT, 0);
    v_academy_active := v_academy_level >= 1 AND COALESCE((v_academy->>'active')::BOOLEAN, true);
    v_investment := COALESCE((v_club.club_data->>'youthInvestment')::NUMERIC, 0);
    IF NOT v_academy_active THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    -- Ciclo: nível 1 = 14d, evolui até 7d (cap inferior para respeitar regra dos 7 dias)
    v_cycle_days := GREATEST(7, 15 - v_academy_level);
    v_cycle_interval := (v_cycle_days || ' days')::INTERVAL;
    IF v_club.last_youth_generation_at IS NOT NULL
       AND (now() - v_club.last_youth_generation_at) < v_cycle_interval THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    v_max_prospects := LEAST(40, 10 + v_academy_level * 2);
    SELECT COUNT(*) INTO v_current_count FROM public.youth_prospects WHERE club_id = v_club.id;
    IF v_current_count >= v_max_prospects THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;
    -- Geração
    v_position := v_positions[1 + floor(random() * array_length(v_positions, 1))::INT];
    v_age := 15 + floor(random() * 3)::INT;
    v_min_ovr := CASE v_age WHEN 15 THEN 45 WHEN 16 THEN 48 ELSE 52 END;
    v_max_ovr := CASE v_age WHEN 15 THEN 58 WHEN 16 THEN 62 ELSE 66 END;
    v_min_ovr := v_min_ovr + (v_academy_level / 3);
    v_max_ovr := v_max_ovr + (v_academy_level / 3);
    v_overall := v_min_ovr + floor(random() * (v_max_ovr - v_min_ovr + 1))::INT;
    IF v_investment >= 2400000 THEN v_overall := v_overall + 5;
    ELSIF v_investment >= 1200000 THEN v_overall := v_overall + 3;
    ELSIF v_investment >= 600000 THEN v_overall := v_overall + 1;
    END IF;
    v_potential := v_overall + 10 + floor(random() * 15)::INT;
    v_rarity_luck := random() + (v_academy_level * 0.005) + CASE WHEN v_investment > 2000000 THEN 0.05 ELSE 0 END;
    IF v_rarity_luck > 0.98 THEN
      v_rarity := 'Craque geracional';
      v_potential := 95 + floor(random() * 5)::INT;
    ELSIF v_rarity_luck > 0.90 THEN
      v_rarity := 'Promessa';
      v_potential := 88 + floor(random() * 7)::INT;
    ELSIF v_rarity_luck > 0.75 THEN
      v_rarity := 'Bom talento';
      v_potential := 80 + floor(random() * 8)::INT;
    ELSE
      v_rarity := 'Comum';
    END IF;
    v_potential := LEAST(99, GREATEST(v_potential, v_overall + 5));
    v_dominant := CASE WHEN random() < 0.7 THEN 'Destro' WHEN random() < 0.9 THEN 'Canhoto' ELSE 'Ambidestro' END;
    v_height := 165 + (v_age - 15) * 3 + CASE WHEN v_position IN ('GOL','ZAG') THEN 8 WHEN v_position = 'ATA' THEN 3 ELSE 0 END + floor(random() * 15)::INT;
    v_weight := v_height - 105 + floor(random() * 15)::INT;
    v_market_value := (v_overall::BIGINT * v_overall * 1200) + (v_potential::BIGINT * v_potential * 2500);
    v_name := v_first_names[1 + floor(random() * array_length(v_first_names, 1))::INT]
           || ' '
           || v_surnames[1 + floor(random() * array_length(v_surnames, 1))::INT];
    v_attrs := jsonb_build_object(
      'speed', v_overall, 'shooting', v_overall, 'passing', v_overall, 'defending', v_overall,
      'physical', v_overall, 'dribbling', v_overall, 'positioning', v_overall, 'heading', v_overall,
      'marking', v_overall, 'vision', v_overall, 'crossing', v_overall, 'longShots', v_overall,
      'workRate', v_overall, 'composure', v_overall, 'aggression', v_overall, 'setPieces', v_overall,
      'goalkeeping', CASE WHEN v_position = 'GOL' THEN v_overall + 5 ELSE GREATEST(1, v_overall - 30) END
    );
    INSERT INTO public.youth_prospects (
      club_id, name, age, position, overall, potential, attributes, market_value,
      personality, dominant_foot, rarity, nationality, morale, months_in_academy,
      height, weight, tactical_iq, interception, stamina_stat, energy, fatigue,
      contract_status, evolution_history
    ) VALUES (
      v_club.id, v_name, v_age, v_position, v_overall, v_potential, v_attrs, v_market_value,
      v_personalities[1 + floor(random() * array_length(v_personalities, 1))::INT],
      v_dominant, v_rarity,
      CASE WHEN random() < 0.9 THEN COALESCE(v_club.country, 'Brasil') ELSE 'Brasil' END,
      100, 0,
      v_height, v_weight,
      30 + floor(random() * 20)::INT + (v_overall / 5),
      CASE WHEN v_position IN ('ZAG','VOL') THEN LEAST(99, v_overall + 10) ELSE GREATEST(10, v_overall - 15) END,
      v_overall + floor(random() * 11)::INT - 5,
      100, 0,
      'base',
      jsonb_build_array(jsonb_build_object('date', now(), 'overall', v_overall, 'attributes', v_attrs))
    ) RETURNING id INTO v_prospect_id;
    UPDATE public.clubs SET last_youth_generation_at = now() WHERE id = v_club.id;
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES (
      v_club.user_id,
      CASE WHEN v_rarity = 'Comum' THEN 'info' ELSE 'success' END,
      'Base',
      CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 'high' ELSE 'medium' END,
      CASE WHEN v_rarity = 'Comum' THEN '🌟 Novo talento na base!' ELSE format('⭐ Nova %s na base!', v_rarity) END,
      format('%s (%s, OVR %s, POT %s) acaba de surgir na categoria de base.', v_name, v_position, v_overall, v_potential),
      '🎓',
      jsonb_build_object('prospect_id', v_prospect_id, 'rarity', v_rarity, 'source', 'cron_auto')
    );
    INSERT INTO public.newspaper_entries (user_id, text, category, importance)
    VALUES (
      v_club.user_id,
      format('A categoria de base revelou %s — %s de %s anos com OVR %s e potencial %s.',
             v_name, v_position, v_age, v_overall, v_potential),
      'base',
      CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 3 ELSE 1 END
    );
    v_generated := v_generated + 1;
  END LOOP;
  RETURN jsonb_build_object(
    'success', true,
    'processed', v_processed,
    'generated', v_generated,
    'skipped', v_skipped,
    'ran_at', now()
  );
END;
$$;
DO $$
BEGIN
  PERFORM cron.unschedule('cron-youth-generation-hourly');
EXCEPTION WHEN OTHERS THEN NULL;
END $$;
SELECT cron.schedule(
  'cron-youth-generation-hourly',
  '0 * * * *',
  $$SELECT public.cron_generate_youth_for_all();$$
);
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club RECORD;
    v_expires_at TIMESTAMP WITH TIME ZONE;
    v_duration_days INTEGER;
    v_immediate_cash NUMERIC;
    v_immediate_fans INTEGER;
    v_immediate_members INTEGER;
    v_sales_bonus NUMERIC;
    v_sub_type TEXT;
    v_save_id UUID;
    v_club_data JSONB;
BEGIN
    SELECT po.* INTO v_order FROM public.payment_orders po WHERE po.id = p_order_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Order not found'); END IF;
    IF v_order.delivered THEN RETURN jsonb_build_object('success', true, 'message', 'Already delivered'); END IF;
    SELECT si.* INTO v_item FROM public.shop_items si WHERE si.id = v_order.item_id;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'Item not found'); END IF;
    SELECT * INTO v_club FROM public.clubs WHERE user_id = v_order.user_id;
    IF v_club.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'Club not found'); END IF;
    -- Anti-abuso: patrocínio exige torcida mínima no momento da entrega
    IF v_item.category = 'sponsorship' AND COALESCE(v_club.fans, 0) < COALESCE(v_item.min_fans, 0) THEN
        UPDATE public.payment_orders SET status = 'refunded', delivered = false,
            metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('refund_reason','insufficient_fans','required_fans',v_item.min_fans,'club_fans',v_club.fans)
        WHERE id = p_order_id;
        INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
        VALUES (v_order.user_id, 'warning', 'Financeiro', 'high',
                'Patrocínio não ativado',
                format('O patrocínio "%s" exige %s torcedores. Você tem %s. O pedido foi marcado para estorno.', v_item.name, v_item.min_fans, v_club.fans),
                '⚠️', jsonb_build_object('order_id', p_order_id, 'item_id', v_item.id));
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_fans');
    END IF;
    v_duration_days   := COALESCE(v_item.duration_days, 30);
    v_expires_at      := now() + (v_duration_days || ' days')::INTERVAL;
    v_sub_type        := COALESCE(v_item.bonus_data->>'sub_type', v_item.category);
    v_immediate_cash  := COALESCE((v_item.bonus_data->>'immediate_cash')::numeric, 0);
    v_immediate_fans  := COALESCE((v_item.bonus_data->>'immediate_fans')::integer, 0);
    v_immediate_members := COALESCE((v_item.bonus_data->>'initialMembers')::integer, COALESCE((v_item.bonus_data->>'immediate_members')::integer, 0));
    v_sales_bonus     := COALESCE((v_item.bonus_data->>'salesMultiplier')::numeric, 0);
    -- Aplica bônus imediatos para QUALQUER categoria
    IF v_immediate_cash > 0 OR v_immediate_fans > 0 OR v_immediate_members > 0 OR v_sales_bonus > 0 THEN
        UPDATE public.clubs SET
            budget                 = budget + v_immediate_cash,
            fans                   = fans + v_immediate_fans,
            total_members          = COALESCE(total_members, 0) + v_immediate_members,
            sales_bonus_multiplier = GREATEST(COALESCE(sales_bonus_multiplier, 1.0), v_sales_bonus)
        WHERE id = v_club.id;
    END IF;
    -- Lógica específica por categoria (mantém comportamento atual + acrescenta)
    IF v_item.category = 'members' THEN
        INSERT INTO public.club_memberships (club_id, active_plan_id, total_members, monthly_revenue_cents, happiness)
        VALUES (v_club.id, v_item.id, GREATEST(v_immediate_members, 0),
                COALESCE((v_item.bonus_data->>'monthlyRevenue')::numeric, 0) * 100, 100)
        ON CONFLICT (club_id) DO UPDATE SET
            active_plan_id = v_item.id,
            total_members  = public.club_memberships.total_members + EXCLUDED.total_members,
            monthly_revenue_cents = GREATEST(public.club_memberships.monthly_revenue_cents, EXCLUDED.monthly_revenue_cents),
            happiness      = 100;
    ELSIF v_item.category = 'sponsorship' THEN
        INSERT INTO public.club_sponsorships (club_id, sponsor_name, contract_value_cents, payment_type, bonus_data, expires_at, is_active)
        VALUES (v_club.id, v_item.name, COALESCE((v_item.bonus_data->>'dinheiroSemanal')::numeric, 0) * 100, 'weekly', v_item.bonus_data, v_expires_at, true);
    ELSIF v_item.category = 'uniform' THEN
        -- Desbloqueia editor de uniformes no save mais recente
        SELECT id, club_data INTO v_save_id, v_club_data
        FROM public.game_saves WHERE user_id = v_order.user_id
        ORDER BY updated_at DESC LIMIT 1;
        IF v_save_id IS NOT NULL THEN
            v_club_data := COALESCE(v_club_data, '{}'::jsonb);
            v_club_data := jsonb_set(v_club_data,'{clubProfile}', COALESCE(v_club_data->'clubProfile','{}'::jsonb),true);
            v_club_data := jsonb_set(v_club_data,'{clubProfile,uniformsUnlocked}', 'true'::jsonb, true);
            UPDATE public.game_saves SET club_data = v_club_data, updated_at = now() WHERE id = v_save_id;
        END IF;
    END IF;
    -- SEMPRE registra como efeito ativo (com prazo) para aparecer em "Produtos Ativos"
    INSERT INTO public.club_active_effects (club_id, item_id, category, bonus_data, expires_at)
    VALUES (v_club.id, v_item.id, v_item.category,
            COALESCE(v_item.bonus_data, '{}'::jsonb) || jsonb_build_object('name', v_item.name, 'sub_type', v_sub_type),
            v_expires_at);
    -- Marca pedido entregue
    UPDATE public.payment_orders SET delivered = TRUE, status = 'approved' WHERE id = p_order_id;
    -- Notificação unificada
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES (v_order.user_id, 'success', 'Loja', 'high',
            'Produto ativado',
            format('"%s" foi ativado. Bônus: R$ %s · +%s torcedores · +%s sócios. Válido por %s dias.',
                v_item.name,
                to_char(v_immediate_cash, 'FM999G999G999'),
                v_immediate_fans, v_immediate_members, v_duration_days),
            '📦',
            jsonb_build_object('order_id', p_order_id, 'item_id', v_item.id, 'category', v_item.category, 'expires_at', v_expires_at));
    -- Notícia do clube
    INSERT INTO public.newspaper_entries (user_id, text, category, importance)
    VALUES (v_order.user_id, format('O clube oficializou: %s. Benefícios em vigor por %s dias.', v_item.name, v_duration_days), 'finance', 2);
    RETURN jsonb_build_object('success', true, 'delivered_at', now(), 'expires_at', v_expires_at);
END;
$function$;
CREATE OR REPLACE FUNCTION public.expire_shop_effects()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_eff RECORD;
    v_spon RECORD;
    v_user_id UUID;
    v_count_eff INTEGER := 0;
    v_count_spon INTEGER := 0;
BEGIN
    -- Patrocínios vencidos
    FOR v_spon IN
        SELECT s.*, c.user_id AS uid
        FROM public.club_sponsorships s
        JOIN public.clubs c ON c.id = s.club_id
        WHERE s.is_active = true AND s.expires_at IS NOT NULL AND s.expires_at < now()
    LOOP
        UPDATE public.club_sponsorships SET is_active = false WHERE id = v_spon.id;
        INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
        VALUES (v_spon.uid, 'info', 'Patrocínio', 'normal',
                'Patrocínio expirado',
                format('O contrato com "%s" chegou ao fim. Receita encerrada.', v_spon.sponsor_name),
                '⏳', jsonb_build_object('sponsorship_id', v_spon.id));
        v_count_spon := v_count_spon + 1;
    END LOOP;
    -- Efeitos ativos vencidos
    FOR v_eff IN
        SELECT e.*, c.user_id AS uid
        FROM public.club_active_effects e
        JOIN public.clubs c ON c.id = e.club_id
        WHERE e.expires_at IS NOT NULL AND e.expires_at < now()
    LOOP
        DELETE FROM public.club_active_effects WHERE id = v_eff.id;
        INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
        VALUES (v_eff.uid, 'info', 'Loja', 'normal',
                'Produto expirou',
                format('"%s" terminou. Benefícios encerrados automaticamente.',
                       COALESCE(v_eff.bonus_data->>'name', v_eff.category)),
                '⏳', jsonb_build_object('effect_id', v_eff.id, 'category', v_eff.category));
        v_count_eff := v_count_eff + 1;
    END LOOP;
    RETURN jsonb_build_object('expired_effects', v_count_eff, 'expired_sponsorships', v_count_spon);
END;
$function$;
DO $$
BEGIN
    PERFORM cron.unschedule('expire-shop-effects-5min');
EXCEPTION WHEN OTHERS THEN NULL;
END $$;
SELECT cron.schedule(
    'expire-shop-effects-5min',
    '*/5 * * * *',
    $$ SELECT public.expire_shop_effects(); $$
);
INSERT INTO public.clubs (user_id, name, country, fans, reputation)
SELECT gs.user_id,
       COALESCE(gs.club_data->>'name', 'Meu Clube'),
       COALESCE(gs.club_data->>'country', 'Brasil'),
       COALESCE((gs.club_data->>'fans')::INT, 1000),
       COALESCE((gs.club_data->>'reputation')::INT, 65)
FROM public.game_saves gs
LEFT JOIN public.clubs c ON c.user_id = gs.user_id
WHERE c.id IS NULL AND gs.user_id IS NOT NULL
ON CONFLICT (user_id) DO NOTHING;
CREATE OR REPLACE FUNCTION public.cron_generate_youth_for_all()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_save RECORD;
  v_club_id UUID;
  v_country TEXT;
  v_last_gen TIMESTAMPTZ;
  v_processed INT := 0;
  v_generated INT := 0;
  v_skipped INT := 0;
  v_academy JSONB;
  v_academy_level INT;
  v_academy_active BOOLEAN;
  v_investment NUMERIC;
  v_cycle_days INT;
  v_cycle_interval INTERVAL;
  v_max_prospects INT;
  v_current_count INT;
  v_name TEXT;
  v_first_names TEXT[] := ARRAY['Gabriel','Lucas','Matheus','Vinícius','Pedro','João','Felipe','Thiago','Bruno','Rodrigo','Arthur','Diego','Rafael','Vitor','Gustavo','Carlos','Eduardo','Henrique','Ícaro','Júnior','Kauã','Leonardo','Murilo','Nathan','Otávio','Paulo','Renan','Samuel','Tiago','Wesley'];
  v_surnames TEXT[] := ARRAY['Silva','Santos','Oliveira','Souza','Rodrigues','Ferreira','Alves','Pereira','Lima','Gomes','Costa','Ribeiro','Martins','Carvalho','Lopes','Almeida','Barros','Cardoso','Dias','Mendes','Nogueira','Pinto','Rocha','Teixeira','Vieira','Moreira','Cavalcanti','Tavares','Andrade','Moura'];
  v_positions TEXT[] := ARRAY['GOL','ZAG','LAT','VOL','MEI','ATA'];
  v_personalities TEXT[] := ARRAY['lider','festeiro','dedicado','ambicioso','leal','calmo','competitivo','introvertido'];
  v_position TEXT;
  v_age INT;
  v_min_ovr INT;
  v_max_ovr INT;
  v_overall INT;
  v_potential INT;
  v_pot_cap INT;
  v_rarity TEXT;
  v_rarity_luck NUMERIC;
  v_dominant TEXT;
  v_height INT;
  v_weight INT;
  v_market_value BIGINT;
  v_attrs JSONB;
  v_prospect_id UUID;
BEGIN
  FOR v_save IN
    SELECT gs.user_id, gs.club_data
    FROM public.game_saves gs
    WHERE gs.user_id IS NOT NULL
      AND COALESCE((gs.club_data->'infrastructure'->'youthAcademy'->>'level')::INT, 0) >= 1
  LOOP
    v_processed := v_processed + 1;
    SELECT id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen
    FROM public.clubs WHERE user_id = v_save.user_id LIMIT 1;
    IF v_club_id IS NULL THEN
      INSERT INTO public.clubs (user_id, name, country, fans, reputation)
      VALUES (
        v_save.user_id,
        COALESCE(v_save.club_data->>'name', 'Meu Clube'),
        COALESCE(v_save.club_data->>'country', 'Brasil'),
        COALESCE((v_save.club_data->>'fans')::INT, 1000),
        COALESCE((v_save.club_data->>'reputation')::INT, 65)
      )
      ON CONFLICT (user_id) DO UPDATE SET name = EXCLUDED.name
      RETURNING id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen;
    END IF;
    v_academy := COALESCE(v_save.club_data->'infrastructure'->'youthAcademy', '{}'::jsonb);
    v_academy_level := COALESCE((v_academy->>'level')::INT, 0);
    v_academy_active := v_academy_level >= 1 AND COALESCE((v_academy->>'active')::BOOLEAN, true);
    v_investment := COALESCE((v_save.club_data->>'youthInvestment')::NUMERIC, 0);
    IF NOT v_academy_active THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_cycle_days := GREATEST(7, 15 - v_academy_level);
    v_cycle_interval := (v_cycle_days || ' days')::INTERVAL;
    IF v_last_gen IS NOT NULL AND (now() - v_last_gen) < v_cycle_interval THEN
      v_skipped := v_skipped + 1; CONTINUE;
    END IF;
    v_max_prospects := LEAST(40, 10 + v_academy_level * 2);
    SELECT COUNT(*) INTO v_current_count FROM public.youth_prospects WHERE club_id = v_club_id;
    IF v_current_count >= v_max_prospects THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_position := v_positions[1 + floor(random() * array_length(v_positions, 1))::INT];
    v_age := 15 + floor(random() * 3)::INT;
    v_min_ovr := CASE v_age WHEN 15 THEN 45 WHEN 16 THEN 48 ELSE 52 END + (v_academy_level / 3);
    v_max_ovr := CASE v_age WHEN 15 THEN 58 WHEN 16 THEN 62 ELSE 66 END + (v_academy_level / 3);
    v_overall := v_min_ovr + floor(random() * (v_max_ovr - v_min_ovr + 1))::INT;
    IF v_investment >= 2400000 THEN v_overall := v_overall + 5;
    ELSIF v_investment >= 1200000 THEN v_overall := v_overall + 3;
    ELSIF v_investment >= 600000 THEN v_overall := v_overall + 1;
    END IF;
    -- Teto de potencial em função do nível da base
    v_pot_cap := LEAST(99, 63 + floor(v_academy_level * 1.2)::INT);
    v_potential := LEAST(v_pot_cap, v_overall + 5 + floor(random() * GREATEST(1, (v_pot_cap - v_overall - 4)))::INT);
    v_rarity_luck := random() + (v_academy_level * 0.005) + CASE WHEN v_investment > 2000000 THEN 0.05 ELSE 0 END;
    IF v_rarity_luck > 0.98 AND v_pot_cap >= 95 THEN
      v_rarity := 'Craque geracional';
      v_potential := LEAST(v_pot_cap, 95 + floor(random() * 5)::INT);
    ELSIF v_rarity_luck > 0.90 AND v_pot_cap >= 88 THEN
      v_rarity := 'Promessa';
      v_potential := LEAST(v_pot_cap, 88 + floor(random() * 7)::INT);
    ELSIF v_rarity_luck > 0.75 AND v_pot_cap >= 80 THEN
      v_rarity := 'Bom talento';
      v_potential := LEAST(v_pot_cap, 80 + floor(random() * 8)::INT);
    ELSE
      v_rarity := 'Comum';
    END IF;
    v_potential := LEAST(99, GREATEST(v_potential, v_overall + 5));
    v_dominant := CASE WHEN random() < 0.7 THEN 'Destro' WHEN random() < 0.9 THEN 'Canhoto' ELSE 'Ambidestro' END;
    v_height := 165 + (v_age - 15) * 3 + CASE WHEN v_position IN ('GOL','ZAG') THEN 8 WHEN v_position = 'ATA' THEN 3 ELSE 0 END + floor(random() * 15)::INT;
    v_weight := v_height - 105 + floor(random() * 15)::INT;
    v_market_value := (v_overall::BIGINT * v_overall * 1200) + (v_potential::BIGINT * v_potential * 2500);
    v_name := v_first_names[1 + floor(random() * array_length(v_first_names, 1))::INT] || ' '
           || v_surnames[1 + floor(random() * array_length(v_surnames, 1))::INT];
    v_attrs := jsonb_build_object(
      'speed', v_overall, 'shooting', v_overall, 'passing', v_overall, 'defending', v_overall,
      'physical', v_overall, 'dribbling', v_overall, 'positioning', v_overall, 'heading', v_overall,
      'marking', v_overall, 'vision', v_overall, 'crossing', v_overall, 'longShots', v_overall,
      'workRate', v_overall, 'composure', v_overall, 'aggression', v_overall, 'setPieces', v_overall,
      'goalkeeping', CASE WHEN v_position = 'GOL' THEN v_overall + 5 ELSE GREATEST(1, v_overall - 30) END
    );
    INSERT INTO public.youth_prospects (
      club_id, name, age, position, overall, potential, attributes, market_value,
      personality, dominant_foot, rarity, nationality, morale, months_in_academy,
      height, weight, tactical_iq, interception, stamina_stat, energy, fatigue,
      contract_status, evolution_history
    ) VALUES (
      v_club_id, v_name, v_age, v_position, v_overall, v_potential, v_attrs, v_market_value,
      v_personalities[1 + floor(random() * array_length(v_personalities, 1))::INT],
      v_dominant, v_rarity,
      CASE WHEN random() < 0.9 THEN COALESCE(v_country, 'Brasil') ELSE 'Brasil' END,
      100, 0, v_height, v_weight,
      30 + floor(random() * 20)::INT + (v_overall / 5),
      CASE WHEN v_position IN ('ZAG','VOL') THEN LEAST(99, v_overall + 10) ELSE GREATEST(10, v_overall - 15) END,
      v_overall + floor(random() * 11)::INT - 5,
      100, 0, 'base',
      jsonb_build_array(jsonb_build_object('date', now(), 'overall', v_overall, 'attributes', v_attrs))
    ) RETURNING id INTO v_prospect_id;
    UPDATE public.clubs SET last_youth_generation_at = now() WHERE id = v_club_id;
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES (
      v_save.user_id,
      CASE WHEN v_rarity = 'Comum' THEN 'info' ELSE 'success' END,
      'Base',
      CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 'high' ELSE 'medium' END,
      CASE WHEN v_rarity = 'Comum' THEN '🌟 Novo talento na base!' ELSE format('⭐ Nova %s na base!', v_rarity) END,
      format('%s (%s, OVR %s, POT %s) acaba de surgir na categoria de base.', v_name, v_position, v_overall, v_potential),
      '🎓',
      jsonb_build_object('prospect_id', v_prospect_id, 'rarity', v_rarity, 'source', 'cron_auto')
    );
    v_generated := v_generated + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'processed', v_processed, 'generated', v_generated, 'skipped', v_skipped, 'ran_at', now());
END;
$function$;
SELECT public.cron_generate_youth_for_all();
CREATE OR REPLACE FUNCTION public.youth_potential_bounds(lvl INT)
RETURNS TABLE(min_pot INT, max_pot INT, rare_chance NUMERIC, rare_bonus_min INT, rare_bonus_max INT)
LANGUAGE sql IMMUTABLE AS $$
  SELECT min_pot, max_pot, rare_chance, rare_bonus_min, rare_bonus_max
  FROM (VALUES
    (1,45,52,0.005,4,8),(2,46,53,0.005,4,8),(3,47,54,0.005,4,8),
    (4,48,55,0.015,4,9),(5,49,56,0.015,4,9),
    (6,50,58,0.025,5,9),(7,51,59,0.025,5,9),
    (8,52,60,0.04,5,10),(9,53,61,0.04,5,10),
    (10,56,64,0.06,5,10),(11,57,65,0.06,5,10),(12,58,66,0.06,5,10),
    (13,59,67,0.09,6,11),(14,60,68,0.09,6,11),(15,61,69,0.09,6,11),
    (16,62,71,0.12,6,11),(17,63,72,0.12,6,11),
    (18,64,73,0.16,6,12),(19,65,74,0.16,6,12),(20,66,75,0.16,6,12),
    (21,67,77,0.20,7,12),(22,68,78,0.20,7,12),
    (23,69,79,0.25,7,13),(24,70,80,0.25,7,13),(25,71,81,0.25,7,13),
    (26,72,83,0.32,8,14),(27,73,84,0.32,8,14),(28,74,85,0.32,8,14),
    (29,75,86,0.38,9,15),
    (30,76,88,0.45,10,16)
  ) AS t(level,min_pot,max_pot,rare_chance,rare_bonus_min,rare_bonus_max)
  WHERE level = LEAST(30, GREATEST(1, lvl));
$$;
CREATE OR REPLACE FUNCTION public.cron_generate_youth_for_all()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_save RECORD;
  v_club_id UUID;
  v_country TEXT;
  v_last_gen TIMESTAMPTZ;
  v_processed INT := 0;
  v_generated INT := 0;
  v_skipped INT := 0;
  v_academy JSONB;
  v_academy_level INT;
  v_academy_active BOOLEAN;
  v_investment NUMERIC;
  v_cycle_days INT;
  v_cycle_interval INTERVAL;
  v_max_prospects INT;
  v_current_count INT;
  v_name TEXT;
  v_first_names TEXT[] := ARRAY['Gabriel','Lucas','Matheus','Vinícius','Pedro','João','Felipe','Thiago','Bruno','Rodrigo','Arthur','Diego','Rafael','Vitor','Gustavo','Carlos','Eduardo','Henrique','Ícaro','Júnior','Kauã','Leonardo','Murilo','Nathan','Otávio','Paulo','Renan','Samuel','Tiago','Wesley'];
  v_surnames TEXT[] := ARRAY['Silva','Santos','Oliveira','Souza','Rodrigues','Ferreira','Alves','Pereira','Lima','Gomes','Costa','Ribeiro','Martins','Carvalho','Lopes','Almeida','Barros','Cardoso','Dias','Mendes','Nogueira','Pinto','Rocha','Teixeira','Vieira','Moreira','Cavalcanti','Tavares','Andrade','Moura'];
  v_positions TEXT[] := ARRAY['GOL','ZAG','LAT','VOL','MEI','ATA'];
  v_personalities TEXT[] := ARRAY['lider','festeiro','dedicado','ambicioso','leal','calmo','competitivo','introvertido'];
  v_position TEXT;
  v_age INT;
  v_min_ovr INT;
  v_max_ovr INT;
  v_overall INT;
  v_potential INT;
  v_pot_min INT;
  v_pot_max INT;
  v_rare_chance NUMERIC;
  v_rare_bonus_min INT;
  v_rare_bonus_max INT;
  v_rare_roll NUMERIC;
  v_invest_rare_boost NUMERIC;
  v_is_rare BOOLEAN;
  v_rarity TEXT;
  v_dominant TEXT;
  v_height INT;
  v_weight INT;
  v_market_value BIGINT;
  v_attrs JSONB;
  v_prospect_id UUID;
BEGIN
  FOR v_save IN
    SELECT gs.user_id, gs.club_data
    FROM public.game_saves gs
    WHERE gs.user_id IS NOT NULL
      AND COALESCE((gs.club_data->'infrastructure'->'youthAcademy'->>'level')::INT, 0) >= 1
  LOOP
    v_processed := v_processed + 1;
    SELECT id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen
    FROM public.clubs WHERE user_id = v_save.user_id LIMIT 1;
    IF v_club_id IS NULL THEN
      INSERT INTO public.clubs (user_id, name, country, fans, reputation)
      VALUES (
        v_save.user_id,
        COALESCE(v_save.club_data->>'name', 'Meu Clube'),
        COALESCE(v_save.club_data->>'country', 'Brasil'),
        COALESCE((v_save.club_data->>'fans')::INT, 1000),
        COALESCE((v_save.club_data->>'reputation')::INT, 65)
      )
      ON CONFLICT (user_id) DO UPDATE SET name = EXCLUDED.name
      RETURNING id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen;
    END IF;
    v_academy := COALESCE(v_save.club_data->'infrastructure'->'youthAcademy', '{}'::jsonb);
    v_academy_level := COALESCE((v_academy->>'level')::INT, 0);
    v_academy_active := v_academy_level >= 1 AND COALESCE((v_academy->>'active')::BOOLEAN, true);
    v_investment := COALESCE((v_save.club_data->>'youthInvestment')::NUMERIC, 0);
    IF NOT v_academy_active THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_cycle_days := GREATEST(7, 15 - v_academy_level);
    v_cycle_interval := (v_cycle_days || ' days')::INTERVAL;
    IF v_last_gen IS NOT NULL AND (now() - v_last_gen) < v_cycle_interval THEN
      v_skipped := v_skipped + 1; CONTINUE;
    END IF;
    v_max_prospects := LEAST(40, 10 + v_academy_level * 2);
    SELECT COUNT(*) INTO v_current_count FROM public.youth_prospects WHERE club_id = v_club_id;
    IF v_current_count >= v_max_prospects THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_position := v_positions[1 + floor(random() * array_length(v_positions, 1))::INT];
    v_age := 15 + floor(random() * 3)::INT;
    v_min_ovr := CASE v_age WHEN 15 THEN 45 WHEN 16 THEN 48 ELSE 52 END + (v_academy_level / 3);
    v_max_ovr := CASE v_age WHEN 15 THEN 58 WHEN 16 THEN 62 ELSE 66 END + (v_academy_level / 3);
    v_overall := v_min_ovr + floor(random() * (v_max_ovr - v_min_ovr + 1))::INT;
    IF v_investment >= 2400000 THEN v_overall := v_overall + 5;
    ELSIF v_investment >= 1200000 THEN v_overall := v_overall + 3;
    ELSIF v_investment >= 600000 THEN v_overall := v_overall + 1;
    END IF;
    -- Potencial pela tabela oficial nível 1-30
    SELECT min_pot, max_pot, rare_chance, rare_bonus_min, rare_bonus_max
      INTO v_pot_min, v_pot_max, v_rare_chance, v_rare_bonus_min, v_rare_bonus_max
    FROM public.youth_potential_bounds(v_academy_level);
    v_rare_roll := random();
    v_invest_rare_boost := CASE
      WHEN v_investment >= 2400000 THEN 0.04
      WHEN v_investment >= 1200000 THEN 0.02
      WHEN v_investment >= 600000 THEN 0.01
      ELSE 0
    END;
    v_is_rare := v_rare_roll < (v_rare_chance + v_invest_rare_boost);
    IF v_is_rare THEN
      v_potential := LEAST(99, v_pot_max + v_rare_bonus_min
        + floor(random() * (v_rare_bonus_max - v_rare_bonus_min + 1))::INT);
    ELSE
      v_potential := v_pot_min + floor(random() * (v_pot_max - v_pot_min + 1))::INT;
    END IF;
    -- Potencial nunca abaixo do OVR atual + 3
    v_potential := LEAST(99, GREATEST(v_potential, v_overall + 3));
    v_rarity := CASE
      WHEN v_potential >= 90 THEN 'Craque geracional'
      WHEN v_potential >= 82 THEN 'Promessa'
      WHEN v_potential >= 75 THEN 'Bom talento'
      ELSE 'Comum'
    END;
    v_dominant := CASE WHEN random() < 0.7 THEN 'Destro' WHEN random() < 0.9 THEN 'Canhoto' ELSE 'Ambidestro' END;
    v_height := 165 + (v_age - 15) * 3 + CASE WHEN v_position IN ('GOL','ZAG') THEN 8 WHEN v_position = 'ATA' THEN 3 ELSE 0 END + floor(random() * 15)::INT;
    v_weight := v_height - 105 + floor(random() * 15)::INT;
    v_market_value := (v_overall::BIGINT * v_overall * 1200) + (v_potential::BIGINT * v_potential * 2500);
    v_name := v_first_names[1 + floor(random() * array_length(v_first_names, 1))::INT] || ' '
           || v_surnames[1 + floor(random() * array_length(v_surnames, 1))::INT];
    v_attrs := jsonb_build_object(
      'speed', v_overall, 'shooting', v_overall, 'passing', v_overall, 'defending', v_overall,
      'physical', v_overall, 'dribbling', v_overall, 'positioning', v_overall, 'heading', v_overall,
      'marking', v_overall, 'vision', v_overall, 'crossing', v_overall, 'longShots', v_overall,
      'workRate', v_overall, 'composure', v_overall, 'aggression', v_overall, 'setPieces', v_overall,
      'goalkeeping', CASE WHEN v_position = 'GOL' THEN v_overall + 5 ELSE GREATEST(1, v_overall - 30) END
    );
    INSERT INTO public.youth_prospects (
      club_id, name, age, position, overall, potential, attributes, market_value,
      personality, dominant_foot, rarity, nationality, morale, months_in_academy,
      height, weight, tactical_iq, interception, stamina_stat, energy, fatigue,
      contract_status, evolution_history
    ) VALUES (
      v_club_id, v_name, v_age, v_position, v_overall, v_potential, v_attrs, v_market_value,
      v_personalities[1 + floor(random() * array_length(v_personalities, 1))::INT],
      v_dominant, v_rarity,
      CASE WHEN random() < 0.9 THEN COALESCE(v_country, 'Brasil') ELSE 'Brasil' END,
      100, 0, v_height, v_weight,
      30 + floor(random() * 20)::INT + (v_overall / 5),
      CASE WHEN v_position IN ('ZAG','VOL') THEN LEAST(99, v_overall + 10) ELSE GREATEST(10, v_overall - 15) END,
      v_overall + floor(random() * 11)::INT - 5,
      100, 0, 'base',
      jsonb_build_array(jsonb_build_object('date', now(), 'overall', v_overall, 'attributes', v_attrs))
    ) RETURNING id INTO v_prospect_id;
    UPDATE public.clubs SET last_youth_generation_at = now() WHERE id = v_club_id;
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES (
      v_save.user_id,
      CASE WHEN v_rarity = 'Comum' THEN 'info' ELSE 'success' END,
      'Base',
      CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 'high' ELSE 'medium' END,
      CASE WHEN v_rarity = 'Comum' THEN '🌟 Novo talento na base!' ELSE format('⭐ Nova %s na base!', v_rarity) END,
      format('%s (%s, OVR %s, POT %s) acaba de surgir na categoria de base.', v_name, v_position, v_overall, v_potential),
      '🎓',
      jsonb_build_object('prospect_id', v_prospect_id, 'rarity', v_rarity, 'source', 'cron_auto')
    );
    v_generated := v_generated + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'processed', v_processed, 'generated', v_generated, 'skipped', v_skipped, 'ran_at', now());
END;
$function$;
ALTER FUNCTION public.youth_potential_bounds(INT) SET search_path = public;
CREATE OR REPLACE FUNCTION public.youth_market_value(p_overall INT, p_potential INT, p_age INT)
RETURNS BIGINT
LANGUAGE plpgsql IMMUTABLE
SET search_path = public
AS $$
DECLARE
  v_base BIGINT;
  v_age_factor NUMERIC;
  v_pot_mult NUMERIC := 1.0;
BEGIN
  v_base := CASE
    WHEN p_overall >= 90 THEN p_overall * 250000
    WHEN p_overall >= 85 THEN p_overall * 150000
    WHEN p_overall >= 80 THEN p_overall * 80000
    WHEN p_overall >= 75 THEN p_overall * 50000
    WHEN p_overall >= 70 THEN p_overall * 30000
    WHEN p_overall >= 65 THEN p_overall * 20000
    WHEN p_overall >= 55 THEN p_overall * 10000
    ELSE p_overall * 5000
  END;
  v_age_factor := CASE
    WHEN p_age <= 17 THEN 1.5
    WHEN p_age <= 20 THEN 1.4
    ELSE 1.2
  END;
  IF p_potential >= 90 THEN v_pot_mult := 1.4;
  ELSIF p_potential >= 82 THEN v_pot_mult := 1.25;
  ELSIF p_potential >= 75 THEN v_pot_mult := 1.1;
  END IF;
  RETURN GREATEST(50000, FLOOR(v_base::NUMERIC * v_age_factor * v_pot_mult))::BIGINT;
END;
$$;
CREATE OR REPLACE FUNCTION public.cron_generate_youth_for_all()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_save RECORD;
  v_club_id UUID; v_country TEXT; v_last_gen TIMESTAMPTZ;
  v_processed INT := 0; v_generated INT := 0; v_skipped INT := 0;
  v_academy JSONB; v_academy_level INT; v_academy_active BOOLEAN;
  v_investment NUMERIC; v_cycle_days INT; v_cycle_interval INTERVAL;
  v_max_prospects INT; v_current_count INT;
  v_name TEXT;
  v_first_names TEXT[] := ARRAY['Gabriel','Lucas','Matheus','Vinícius','Pedro','João','Felipe','Thiago','Bruno','Rodrigo','Arthur','Diego','Rafael','Vitor','Gustavo','Carlos','Eduardo','Henrique','Ícaro','Júnior','Kauã','Leonardo','Murilo','Nathan','Otávio','Paulo','Renan','Samuel','Tiago','Wesley'];
  v_surnames TEXT[] := ARRAY['Silva','Santos','Oliveira','Souza','Rodrigues','Ferreira','Alves','Pereira','Lima','Gomes','Costa','Ribeiro','Martins','Carvalho','Lopes','Almeida','Barros','Cardoso','Dias','Mendes','Nogueira','Pinto','Rocha','Teixeira','Vieira','Moreira','Cavalcanti','Tavares','Andrade','Moura'];
  v_positions TEXT[] := ARRAY['GOL','ZAG','LAT','VOL','MEI','ATA'];
  v_personalities TEXT[] := ARRAY['lider','festeiro','dedicado','ambicioso','leal','calmo','competitivo','introvertido'];
  v_position TEXT; v_age INT;
  v_min_ovr INT; v_max_ovr INT; v_overall INT; v_potential INT;
  v_pot_min INT; v_pot_max INT; v_rare_chance NUMERIC;
  v_rare_bonus_min INT; v_rare_bonus_max INT;
  v_rare_roll NUMERIC; v_invest_rare_boost NUMERIC; v_is_rare BOOLEAN;
  v_rarity TEXT; v_dominant TEXT; v_height INT; v_weight INT;
  v_market_value BIGINT; v_attrs JSONB; v_prospect_id UUID;
BEGIN
  FOR v_save IN
    SELECT gs.user_id, gs.club_data FROM public.game_saves gs
    WHERE gs.user_id IS NOT NULL
      AND COALESCE((gs.club_data->'infrastructure'->'youthAcademy'->>'level')::INT, 0) >= 1
  LOOP
    v_processed := v_processed + 1;
    SELECT id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen
    FROM public.clubs WHERE user_id = v_save.user_id LIMIT 1;
    IF v_club_id IS NULL THEN
      INSERT INTO public.clubs (user_id, name, country, fans, reputation)
      VALUES (
        v_save.user_id,
        COALESCE(v_save.club_data->'club'->>'name', v_save.club_data->>'name', 'Meu Clube'),
        COALESCE(v_save.club_data->'club'->>'country', v_save.club_data->>'country', 'Brasil'),
        COALESCE((v_save.club_data->'club'->>'fans')::INT, 1000),
        COALESCE((v_save.club_data->'club'->>'reputation')::INT, 65)
      )
      ON CONFLICT (user_id) DO UPDATE SET name = EXCLUDED.name
      RETURNING id, country, last_youth_generation_at INTO v_club_id, v_country, v_last_gen;
    END IF;
    v_academy := COALESCE(v_save.club_data->'infrastructure'->'youthAcademy', '{}'::jsonb);
    v_academy_level := COALESCE((v_academy->>'level')::INT, 0);
    v_academy_active := v_academy_level >= 1 AND COALESCE((v_academy->>'active')::BOOLEAN, true);
    v_investment := COALESCE((v_save.club_data->>'youthInvestment')::NUMERIC, 0);
    IF NOT v_academy_active THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_cycle_days := GREATEST(7, 15 - v_academy_level);
    v_cycle_interval := (v_cycle_days || ' days')::INTERVAL;
    IF v_last_gen IS NOT NULL AND (now() - v_last_gen) < v_cycle_interval THEN
      v_skipped := v_skipped + 1; CONTINUE;
    END IF;
    v_max_prospects := LEAST(40, 10 + v_academy_level * 2);
    SELECT COUNT(*) INTO v_current_count FROM public.youth_prospects WHERE club_id = v_club_id;
    IF v_current_count >= v_max_prospects THEN v_skipped := v_skipped + 1; CONTINUE; END IF;
    v_position := v_positions[1 + floor(random() * array_length(v_positions, 1))::INT];
    v_age := 15 + floor(random() * 3)::INT;
    v_min_ovr := CASE v_age WHEN 15 THEN 45 WHEN 16 THEN 48 ELSE 52 END + (v_academy_level / 3);
    v_max_ovr := CASE v_age WHEN 15 THEN 58 WHEN 16 THEN 62 ELSE 66 END + (v_academy_level / 3);
    v_overall := v_min_ovr + floor(random() * (v_max_ovr - v_min_ovr + 1))::INT;
    IF v_investment >= 2400000 THEN v_overall := v_overall + 5;
    ELSIF v_investment >= 1200000 THEN v_overall := v_overall + 3;
    ELSIF v_investment >= 600000 THEN v_overall := v_overall + 1;
    END IF;
    SELECT min_pot, max_pot, rare_chance, rare_bonus_min, rare_bonus_max
      INTO v_pot_min, v_pot_max, v_rare_chance, v_rare_bonus_min, v_rare_bonus_max
    FROM public.youth_potential_bounds(v_academy_level);
    v_rare_roll := random();
    v_invest_rare_boost := CASE
      WHEN v_investment >= 2400000 THEN 0.04
      WHEN v_investment >= 1200000 THEN 0.02
      WHEN v_investment >= 600000 THEN 0.01 ELSE 0
    END;
    v_is_rare := v_rare_roll < (v_rare_chance + v_invest_rare_boost);
    IF v_is_rare THEN
      v_potential := LEAST(99, v_pot_max + v_rare_bonus_min
        + floor(random() * (v_rare_bonus_max - v_rare_bonus_min + 1))::INT);
    ELSE
      v_potential := v_pot_min + floor(random() * (v_pot_max - v_pot_min + 1))::INT;
    END IF;
    v_potential := LEAST(99, GREATEST(v_potential, v_overall + 3));
    v_rarity := CASE
      WHEN v_potential >= 90 THEN 'Craque geracional'
      WHEN v_potential >= 82 THEN 'Promessa'
      WHEN v_potential >= 75 THEN 'Bom talento'
      ELSE 'Comum'
    END;
    v_dominant := CASE WHEN random() < 0.7 THEN 'Destro' WHEN random() < 0.9 THEN 'Canhoto' ELSE 'Ambidestro' END;
    v_height := 165 + (v_age - 15) * 3 + CASE WHEN v_position IN ('GOL','ZAG') THEN 8 WHEN v_position = 'ATA' THEN 3 ELSE 0 END + floor(random() * 15)::INT;
    v_weight := v_height - 105 + floor(random() * 15)::INT;
    -- 💰 Valor de mercado realista alinhado à economia FLM
    v_market_value := public.youth_market_value(v_overall, v_potential, v_age);
    v_name := v_first_names[1 + floor(random() * array_length(v_first_names, 1))::INT] || ' '
           || v_surnames[1 + floor(random() * array_length(v_surnames, 1))::INT];
    v_attrs := jsonb_build_object(
      'speed', v_overall, 'shooting', v_overall, 'passing', v_overall, 'defending', v_overall,
      'physical', v_overall, 'dribbling', v_overall, 'positioning', v_overall, 'heading', v_overall,
      'marking', v_overall, 'vision', v_overall, 'crossing', v_overall, 'longShots', v_overall,
      'workRate', v_overall, 'composure', v_overall, 'aggression', v_overall, 'setPieces', v_overall,
      'goalkeeping', CASE WHEN v_position = 'GOL' THEN v_overall + 5 ELSE GREATEST(1, v_overall - 30) END
    );
    INSERT INTO public.youth_prospects (
      club_id, name, age, position, overall, potential, attributes, market_value,
      personality, dominant_foot, rarity, nationality, morale, months_in_academy,
      height, weight, tactical_iq, interception, stamina_stat, energy, fatigue,
      contract_status, evolution_history
    ) VALUES (
      v_club_id, v_name, v_age, v_position, v_overall, v_potential, v_attrs, v_market_value,
      v_personalities[1 + floor(random() * array_length(v_personalities, 1))::INT],
      v_dominant, v_rarity,
      CASE WHEN random() < 0.9 THEN COALESCE(v_country, 'Brasil') ELSE 'Brasil' END,
      100, 0, v_height, v_weight,
      30 + floor(random() * 20)::INT + (v_overall / 5),
      CASE WHEN v_position IN ('ZAG','VOL') THEN LEAST(99, v_overall + 10) ELSE GREATEST(10, v_overall - 15) END,
      v_overall + floor(random() * 11)::INT - 5,
      100, 0, 'base',
      jsonb_build_array(jsonb_build_object('date', now(), 'overall', v_overall, 'attributes', v_attrs))
    ) RETURNING id INTO v_prospect_id;
    UPDATE public.clubs SET last_youth_generation_at = now() WHERE id = v_club_id;
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES (
      v_save.user_id,
      CASE WHEN v_rarity = 'Comum' THEN 'info' ELSE 'success' END,
      'Base',
      CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 'high' ELSE 'medium' END,
      CASE WHEN v_rarity = 'Comum' THEN '🌟 Novo jogador adicionado aos juniores' ELSE format('⭐ Nova %s na base!', v_rarity) END,
      format('%s (%s, OVR %s, POT %s) chegou à categoria de base. Valor: R$ %s.', v_name, v_position, v_overall, v_potential, to_char(v_market_value, 'FM999G999G999G999')),
      '🎓',
      jsonb_build_object('prospect_id', v_prospect_id, 'rarity', v_rarity, 'source', 'cron_auto')
    );
    v_generated := v_generated + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'processed', v_processed, 'generated', v_generated, 'skipped', v_skipped, 'ran_at', now());
END;
$function$;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'youth_prospects'
      AND policyname = 'Club owners can update own youth prospects'
  ) THEN
    CREATE POLICY "Club owners can update own youth prospects"
    ON public.youth_prospects
    FOR UPDATE
    USING (auth.uid() IN (SELECT user_id FROM public.clubs WHERE id = club_id))
    WITH CHECK (auth.uid() IN (SELECT user_id FROM public.clubs WHERE id = club_id));
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = 'youth_prospects'
      AND policyname = 'Club owners can delete own youth prospects'
  ) THEN
    CREATE POLICY "Club owners can delete own youth prospects"
    ON public.youth_prospects
    FOR DELETE
    USING (auth.uid() IN (SELECT user_id FROM public.clubs WHERE id = club_id));
  END IF;
END $$;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime'
      AND schemaname = 'public'
      AND tablename = 'youth_prospects'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.youth_prospects;
  END IF;
END $$;
DROP FUNCTION IF EXISTS public.youth_market_value(INT, INT, INT);
CREATE OR REPLACE FUNCTION public.youth_market_value(
  p_overall INT,
  p_potential INT,
  p_age INT,
  p_position TEXT DEFAULT 'MEI',
  p_rarity TEXT DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql IMMUTABLE
SET search_path = public
AS $$
DECLARE
  v_base BIGINT;
  v_age_factor NUMERIC;
  v_potential_bonus NUMERIC;
  v_position_factor NUMERIC;
  v_rarity_factor NUMERIC;
  v_raw NUMERIC;
BEGIN
  v_base := CASE
    WHEN p_overall >= 90 THEN p_overall * 220000
    WHEN p_overall >= 85 THEN p_overall * 135000
    WHEN p_overall >= 80 THEN p_overall * 76000
    WHEN p_overall >= 75 THEN p_overall * 46000
    WHEN p_overall >= 70 THEN p_overall * 28000
    WHEN p_overall >= 65 THEN p_overall * 18000
    WHEN p_overall >= 60 THEN p_overall * 11500
    WHEN p_overall >= 55 THEN p_overall * 7500
    ELSE p_overall * 4200
  END;
  v_age_factor := CASE
    WHEN p_age <= 16 THEN 1.22
    WHEN p_age = 17 THEN 1.16
    WHEN p_age <= 19 THEN 1.08
    ELSE 1.0
  END;
  v_potential_bonus := CASE
    WHEN p_potential >= 94 THEN 1.62
    WHEN p_potential >= 90 THEN 1.42
    WHEN p_potential >= 86 THEN 1.28
    WHEN p_potential >= 82 THEN 1.18
    WHEN p_potential >= 75 THEN 1.08
    WHEN p_potential >= 68 THEN 1.0
    ELSE 0.88
  END;
  v_position_factor := CASE p_position
    WHEN 'ATA' THEN 1.08
    WHEN 'MEI' THEN 1.05
    WHEN 'GOL' THEN 1.03
    WHEN 'VOL' THEN 1.0
    WHEN 'ZAG' THEN 0.96
    WHEN 'LAT' THEN 0.94
    ELSE 1.0
  END;
  v_rarity_factor := CASE COALESCE(p_rarity, '')
    WHEN 'Craque geracional' THEN 1.35
    WHEN 'Promessa' THEN 1.18
    WHEN 'Bom talento' THEN 1.08
    ELSE 0.92
  END;
  v_raw := v_base::NUMERIC * v_age_factor * v_potential_bonus * v_position_factor * v_rarity_factor;
  RETURN GREATEST(35000, LEAST(25000000, FLOOR(v_raw / 5000) * 5000))::BIGINT;
END;
$$;
