           || v_surnames[1 + floor(random() * array_length(v_surnames, 1))::INT];
    v_attrs := jsonb_build_object(
      'speed', v_overall, 'shooting', v_overall, 'passing', v_overall, 'defending', v_overall,
      'physical', v_overall, 'dribbling', v_overall, 'positioning', v_overall, 'heading', v_overall,
      'marking', v_overall, 'vision', v_overall, 'crossing', v_overall, 'longShots', v_overall,
      'workRate', v_overall, 'composure', v_overall, 'aggression', v_overall, 'setPieces', v_overall,
      'goalkeeping', CASE WHEN v_position = 'GOL' THEN v_overall + 5 ELSE GREATEST(1, v_overall - 30) END
    );
    INSERT INTO public.youth_prospects (
      club_id, name, age, position, overall, potential, attributes, market_value,
      personality, dominant_foot, rarity, nationality, morale, months_in_academy,
      height, weight, tactical_iq, interception, stamina_stat, energy, fatigue,
      contract_status, evolution_history
    ) VALUES (
      v_club_id, v_name, v_age, v_position, v_overall, v_potential, v_attrs, v_market_value,
      v_personalities[1 + floor(random() * array_length(v_personalities, 1))::INT],
      v_dominant, v_rarity,
      CASE WHEN random() < 0.9 THEN COALESCE(v_country, 'Brasil') ELSE 'Brasil' END,
      100, 0, v_height, v_weight,
      30 + floor(random() * 20)::INT + (v_overall / 5),
      CASE WHEN v_position IN ('ZAG','VOL') THEN LEAST(99, v_overall + 10) ELSE GREATEST(10, v_overall - 15) END,
      v_overall + floor(random() * 11)::INT - 5,
      100, 0, 'base',
      jsonb_build_array(jsonb_build_object('date', now(), 'overall', v_overall, 'attributes', v_attrs))
    ) RETURNING id INTO v_prospect_id;
    UPDATE public.clubs SET last_youth_generation_at = now() WHERE id = v_club_id;
    INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
    VALUES
      (v_save.user_id, CASE WHEN v_rarity = 'Comum' THEN 'info' ELSE 'success' END, 'Base', CASE WHEN v_rarity IN ('Promessa','Craque geracional') THEN 'high' ELSE 'medium' END, '🌟 Novo jogador adicionado aos juniores.', format('%s (%s, OVR %s, POT %s) chegou à categoria de base. Valor: R$ %s.', v_name, v_position, v_overall, v_potential, to_char(v_market_value, 'FM999G999G999G999')), '🎓', jsonb_build_object('prospect_id', v_prospect_id, 'rarity', v_rarity, 'source', 'cron_auto')),
      (v_save.user_id, 'info', 'Elenco', 'medium', '📋 Banco de reservas atualizado.', 'O elenco foi reconstruído automaticamente com os juniores disponíveis.', '📋', jsonb_build_object('prospect_id', v_prospect_id, 'source', 'cron_auto')),
      (v_save.user_id, 'info', 'Financeiro', 'low', '💰 Valor de mercado recalculado.', format('%s agora vale R$ %s conforme overall, potencial, idade, posição e raridade.', v_name, to_char(v_market_value, 'FM999G999G999G999')), '💰', jsonb_build_object('prospect_id', v_prospect_id, 'market_value', v_market_value, 'source', 'cron_auto'));
    v_generated := v_generated + 1;
  END LOOP;
  RETURN jsonb_build_object('success', true, 'processed', v_processed, 'generated', v_generated, 'skipped', v_skipped, 'ran_at', now());
END;
$function$;
UPDATE public.live_matches
SET status = 'finished',
    current_minute = GREATEST(current_minute, 90)
WHERE status = 'live'
  AND started_at < now() - ((duration_seconds + 60) * interval '1 second');
CREATE OR REPLACE FUNCTION public.finalize_stale_live_matches()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  affected integer;
BEGIN
  UPDATE public.live_matches
  SET status = 'finished',
      current_minute = GREATEST(current_minute, 90)
  WHERE status = 'live'
    AND started_at < now() - ((duration_seconds + 60) * interval '1 second');
  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$$;
ALTER TABLE public.live_matches ADD COLUMN IF NOT EXISTS is_processed BOOLEAN DEFAULT FALSE;
ALTER TABLE public.live_matches ADD COLUMN IF NOT EXISTS competition_type TEXT; -- 'league', 'cup', 'friendly'
CREATE UNIQUE INDEX IF NOT EXISTS idx_live_matches_shared_unique ON public.live_matches (shared_match_id) WHERE status != 'finished';
CREATE OR REPLACE FUNCTION public.sync_match_persistence(_match_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_match_row RECORD;
    v_league_match RECORD;
    v_cup_match RECORD;
    v_tournament_match RECORD;
    v_winner_id UUID;
BEGIN
    -- 1. Get and lock the match row to prevent race conditions
    SELECT * INTO v_match_row FROM public.live_matches WHERE id = _match_id FOR UPDATE;
    
    IF v_match_row IS NULL OR v_match_row.status != 'finished' OR v_match_row.is_processed THEN
        RETURN;
    END IF;
    -- 2. LEAGUE MATCH SYNC (World Matches or Regional League)
    -- Check world_matches (New World System)
    SELECT * INTO v_league_match FROM public.world_matches WHERE id = v_match_row.shared_match_id;
    IF v_league_match IS NOT NULL THEN
        UPDATE public.world_matches 
        SET home_goals = v_match_row.home_goals, 
            away_goals = v_match_row.away_goals, 
            status = 'finished', 
            played_at = NOW()
        WHERE id = v_league_match.id;
        
        -- The world-match-simulator logic usually handles news/stats, 
        -- but we mark it here so the system knows it's done.
    END IF;
    -- Check league_matches (Regional/Multiplayer System)
    SELECT * INTO v_tournament_match FROM public.league_matches WHERE id = v_match_row.shared_match_id;
    IF v_tournament_match IS NOT NULL THEN
        UPDATE public.league_matches 
        SET home_goals = v_match_row.home_goals, 
            away_goals = v_match_row.away_goals, 
            status = 'played', 
            played_at = NOW(),
            match_data = v_match_row.match_data -- JSONB events/stats
        WHERE id = v_tournament_match.id;
        
        PERFORM public.update_league_standings(v_tournament_match.league_id);
    END IF;
    -- 3. NATIONAL CUP SYNC
    SELECT * INTO v_cup_match FROM public.national_cup_matches WHERE id = v_match_row.shared_match_id;
    IF v_cup_match IS NOT NULL THEN
        v_winner_id := CASE 
            WHEN v_match_row.home_goals > v_match_row.away_goals THEN v_cup_match.home_team_id 
            WHEN v_match_row.away_goals > v_match_row.home_goals THEN v_cup_match.away_team_id 
            -- Tie-breaker: penalties (saved in match_data or columns)
            ELSE COALESCE(
                (v_match_row.match_data->>'winner_team_id')::UUID, 
                v_cup_match.home_team_id -- Fallback
            )
        END;
        UPDATE public.national_cup_matches 
        SET home_score = v_match_row.home_goals, 
            away_score = v_match_row.away_goals, 
            status = 'finished', 
            winner_team_id = v_winner_id,
            updated_at = NOW()
        WHERE id = v_cup_match.id;
        
        -- Eliminate the loser
        UPDATE public.national_cup_teams 
        SET eliminated = TRUE 
        WHERE id = (CASE WHEN v_winner_id = v_cup_match.home_team_id THEN v_cup_match.away_team_id ELSE v_cup_match.home_team_id END);
    END IF;
    -- 4. Mark as processed
    UPDATE public.live_matches SET is_processed = TRUE WHERE id = _match_id;
    -- 5. Finalize UI Status (Optional but helpful for realtime)
    -- The status is already 'finished' to get here.
END;
$$;
