CREATE POLICY "Public disciplinary records read" ON public.disciplinary_records FOR SELECT USING (true);
CREATE POLICY "Public suspensions read" ON public.suspensions FOR SELECT USING (true);
CREATE OR REPLACE FUNCTION public.handle_card_discipline()
RETURNS TRIGGER AS $$
DECLARE
    yellow_count INTEGER;
BEGIN
    IF NEW.card_type = 'yellow' THEN
        -- Count yellows in this competition for this player
        SELECT count(*) INTO yellow_count
        FROM public.disciplinary_records
        WHERE player_id = NEW.player_id
          AND competition_type = NEW.competition_type
          AND card_type = 'yellow';
        -- Every 2 yellows = 1 match suspension
        IF yellow_count % 2 = 0 THEN
            INSERT INTO public.suspensions (player_id, competition_type, remaining_games, reason)
            VALUES (NEW.player_id, NEW.competition_type, 1, 'Acúmulo de Amarelos')
            ON CONFLICT (player_id, competition_type)
            DO UPDATE SET remaining_games = public.suspensions.remaining_games + 1;
        END IF;
    ELSIF NEW.card_type = 'red' THEN
        -- Red card = 1 match suspension
        INSERT INTO public.suspensions (player_id, competition_type, remaining_games, reason)
        VALUES (NEW.player_id, NEW.competition_type, 1, 'Cartão Vermelho')
        ON CONFLICT (player_id, competition_type)
        DO UPDATE SET remaining_games = public.suspensions.remaining_games + 1;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE TRIGGER on_card_issued
AFTER INSERT ON public.disciplinary_records
FOR EACH ROW EXECUTE FUNCTION public.handle_card_discipline();
CREATE OR REPLACE FUNCTION public.process_match_suspensions(_player_ids UUID[], _competition_type TEXT)
RETURNS VOID AS $$
BEGIN
    UPDATE public.suspensions
    SET remaining_games = remaining_games - 1
    WHERE player_id = ANY(_player_ids)
      AND competition_type = _competition_type;
    DELETE FROM public.suspensions WHERE remaining_games <= 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
ALTER TABLE public.world_matches ADD COLUMN IF NOT EXISTS synced BOOLEAN DEFAULT false;
ALTER TABLE public.league_matches ADD COLUMN IF NOT EXISTS synced BOOLEAN DEFAULT false;
ALTER TABLE public.national_cup_matches ADD COLUMN IF NOT EXISTS synced BOOLEAN DEFAULT false;
ALTER TABLE public.world_player_stats ADD COLUMN IF NOT EXISTS total_rating NUMERIC(15,2) DEFAULT 0;
ALTER TABLE public.world_player_stats ADD COLUMN IF NOT EXISTS matches_played INTEGER DEFAULT 0;
ALTER TABLE public.cup_player_stats ADD COLUMN IF NOT EXISTS total_rating NUMERIC(15,2) DEFAULT 0;
ALTER TABLE public.cup_player_stats ADD COLUMN IF NOT EXISTS matches_played INTEGER DEFAULT 0;
CREATE OR REPLACE FUNCTION public.sync_match_stats(
    p_match_id UUID,
    p_competition_type TEXT -- 'world', 'league', 'cup'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_match_record RECORD;
    v_match_data JSONB;
    v_player_ratings JSONB;
    v_goal_scorers JSONB;
    v_player_id UUID;
    v_player_name TEXT;
    v_team_id UUID;
    v_team_name TEXT;
    v_goals INTEGER;
    v_assists INTEGER;
    v_rating NUMERIC;
    v_player_record RECORD;
    v_results JSONB := '{"success": true, "synced_players": 0}';
    v_comp_id UUID;
BEGIN
    -- 1. Get match record and check if already synced
    IF p_competition_type = 'world' THEN
        SELECT * INTO v_match_record FROM public.world_matches WHERE id = p_match_id;
        IF v_match_record.synced THEN RETURN '{"success": false, "error": "Already synced"}'::JSONB; END IF;
        v_comp_id := v_match_record.league_id;
    ELSIF p_competition_type = 'league' THEN
        SELECT * INTO v_match_record FROM public.league_matches WHERE id = p_match_id;
        IF v_match_record.synced THEN RETURN '{"success": false, "error": "Already synced"}'::JSONB; END IF;
        v_comp_id := v_match_record.league_id;
    ELSIF p_competition_type = 'cup' THEN
        SELECT * INTO v_match_record FROM public.national_cup_matches WHERE id = p_match_id;
        IF v_match_record.synced THEN RETURN '{"success": false, "error": "Already synced"}'::JSONB; END IF;
        v_comp_id := v_match_record.cup_id;
    ELSE
        RETURN '{"success": false, "error": "Invalid competition type"}'::JSONB;
    END IF;
    IF v_match_record IS NULL THEN
        RETURN '{"success": false, "error": "Match not found"}'::JSONB;
    END IF;
    v_match_data := v_match_record.match_data;
    IF v_match_data IS NULL THEN
        RETURN '{"success": false, "error": "No match data found"}'::JSONB;
    END IF;
    v_player_ratings := v_match_data->'playerRatings';
    v_goal_scorers := v_match_data->'goalScorers';
    -- 2. Process all players from match_data
    -- Note: match_data.playerRatings is Record<string_id, number>
    FOR v_player_id, v_rating IN SELECT * FROM jsonb_each_text(v_player_ratings) LOOP
        -- Initialize player stats for this match
        v_goals := 0;
        v_assists := 0;
        -- Count goals and assists from goalScorers array
        -- goalScorers: { name: string, team: 'home'|'away', assist: string }[]
        -- We need to find the player by ID to get their name for matching in goalScorers
        SELECT name, (CASE WHEN v_player_id::TEXT = ANY(ARRAY[v_match_record.home_team_id::TEXT]) THEN v_match_record.home_team_id ELSE v_match_record.away_team_id END) as team_id 
        INTO v_player_record 
        FROM public.world_players 
        WHERE id = v_player_id::UUID;
        IF v_player_record IS NULL THEN CONTINUE; END IF;
        -- Count goals
        SELECT count(*) INTO v_goals 
        FROM jsonb_array_elements(v_goal_scorers) AS gs 
        WHERE gs->>'name' = v_player_record.name;
        -- Count assists
        SELECT count(*) INTO v_assists 
        FROM jsonb_array_elements(v_goal_scorers) AS gs 
        WHERE gs->>'assist' = v_player_record.name;
        -- 3. Update the specific table
        IF p_competition_type = 'world' THEN
            INSERT INTO public.world_player_stats (
                player_id, team_id, league_id, season_month, season_year, 
                matches_played, goals, assists, total_rating, avg_rating
            ) VALUES (
                v_player_id::UUID, v_player_record.team_id, v_comp_id, v_match_record.season_month, v_match_record.season_year,
                1, v_goals, v_assists, v_rating::NUMERIC, v_rating::NUMERIC
            )
            ON CONFLICT (player_id, league_id, season_month, season_year) DO UPDATE SET
                matches_played = world_player_stats.matches_played + 1,
                goals = world_player_stats.goals + EXCLUDED.goals,
                assists = world_player_stats.assists + EXCLUDED.assists,
                total_rating = world_player_stats.total_rating + EXCLUDED.total_rating,
                avg_rating = (world_player_stats.total_rating + EXCLUDED.total_rating) / (world_player_stats.matches_played + 1),
                updated_at = NOW();
        ELSIF p_competition_type = 'league' THEN
            -- In league_player_stats, team_id is member_id
            -- We already have home_team_id/away_team_id which are member IDs in league_matches
            INSERT INTO public.league_player_stats (
                league_id, member_id, player_name, team_name,
                matches_played, goals, assists, total_rating
            ) VALUES (
                v_comp_id, v_player_record.team_id, v_player_record.name, 'Club',
                1, v_goals, v_assists, v_rating::NUMERIC
            )
            ON CONFLICT (league_id, member_id, player_name) DO UPDATE SET
                matches_played = league_player_stats.matches_played + 1,
                goals = league_player_stats.goals + EXCLUDED.goals,
                assists = league_player_stats.assists + EXCLUDED.assists,
                total_rating = league_player_stats.total_rating + EXCLUDED.total_rating,
                updated_at = NOW();
        ELSIF p_competition_type = 'cup' THEN
            INSERT INTO public.cup_player_stats (
                cup_id, player_id, team_id, player_name,
                matches_played, goals, assists, total_rating, avg_rating
            ) VALUES (
                v_comp_id, v_player_id::UUID, v_player_record.team_id, v_player_record.name,
                1, v_goals, v_assists, v_rating::NUMERIC, v_rating::NUMERIC
            )
            ON CONFLICT (cup_id, player_id) DO UPDATE SET
                matches_played = cup_player_stats.matches_played + 1,
                goals = cup_player_stats.goals + EXCLUDED.goals,
                assists = cup_player_stats.assists + EXCLUDED.assists,
                total_rating = cup_player_stats.total_rating + EXCLUDED.total_rating,
                avg_rating = (cup_player_stats.total_rating + EXCLUDED.total_rating) / (cup_player_stats.matches_played + 1);
        END IF;
        v_results := jsonb_set(v_results, '{synced_players}', ((v_results->>'synced_players')::INT + 1)::TEXT::JSONB);
    END LOOP;
    -- 4. Mark as synced
    IF p_competition_type = 'world' THEN
        UPDATE public.world_matches SET synced = true WHERE id = p_match_id;
    ELSIF p_competition_type = 'league' THEN
        UPDATE public.league_matches SET synced = true WHERE id = p_match_id;
    ELSIF p_competition_type = 'cup' THEN
        UPDATE public.national_cup_matches SET synced = true WHERE id = p_match_id;
    END IF;
    RETURN v_results;
END;
$$;
ALTER TABLE public.world_matches ADD COLUMN IF NOT EXISTS simulated BOOLEAN DEFAULT false;
CREATE OR REPLACE FUNCTION public.simulate_realistic_bot_match(p_match_id UUID)
RETURNS VOID AS $$
DECLARE
    v_home_team_id UUID;
    v_away_team_id UUID;
    v_home_strength INT;
    v_away_strength INT;
    v_home_goals INT := 0;
    v_away_goals INT := 0;
    v_home_name TEXT;
    v_away_name TEXT;
    v_league_id UUID;
    v_round INT;
    v_events JSONB := '[]';
    v_player_ratings JSONB := '{}';
    v_goal_scorers JSONB := '[]';
    v_home_player_ids UUID[];
    v_away_player_ids UUID[];
    v_i INT;
    v_scorer_id UUID;
    v_assist_id UUID;
    v_scorer_name TEXT;
    v_assist_name TEXT;
    v_minute INT;
BEGIN
    -- Get match info
    SELECT home_team_id, away_team_id, league_id, round
    INTO v_home_team_id, v_away_team_id, v_league_id, v_round
    FROM public.world_matches WHERE id = p_match_id;
    -- Get team info
    SELECT name, strength INTO v_home_name, v_home_strength FROM public.world_teams WHERE id = v_home_team_id;
    SELECT name, strength INTO v_away_name, v_away_strength FROM public.world_teams WHERE id = v_away_team_id;
    -- Simple strength-based poisson simulation
    v_home_goals := floor(random() * (v_home_strength / 20.0) + (random() * 2));
    v_away_goals := floor(random() * (v_away_strength / 20.0) + (random() * 1.5));
    
    -- Caps
    IF v_home_goals > 7 THEN v_home_goals := 7; END IF;
    IF v_away_goals > 7 THEN v_away_goals := 7; END IF;
    -- Get some players for events
    SELECT array_agg(id) INTO v_home_player_ids FROM (SELECT id FROM public.world_players WHERE team_id = v_home_team_id AND position != 'GOL' ORDER BY overall DESC LIMIT 5) s;
    SELECT array_agg(id) INTO v_away_player_ids FROM (SELECT id FROM public.world_players WHERE team_id = v_away_team_id AND position != 'GOL' ORDER BY overall DESC LIMIT 5) s;
    -- Generate Home Goals
    FOR v_i IN 1..v_home_goals LOOP
        v_scorer_id := v_home_player_ids[1 + floor(random() * array_length(v_home_player_ids, 1))];
        SELECT name INTO v_scorer_name FROM public.world_players WHERE id = v_scorer_id;
        v_minute := floor(random() * 90) + 1;
        
        v_events := v_events || jsonb_build_object(
            'minute', v_minute,
            'type', 'goal',
            'team', 'home',
            'playerName', v_scorer_name,
            'description', '⚽ GOOOL de ' || v_scorer_name || '!'
        );
        
        v_goal_scorers := v_goal_scorers || jsonb_build_object(
            'name', v_scorer_name,
            'team', 'home',
            'minute', v_minute
        );
    END LOOP;
    -- Generate Away Goals
    FOR v_i IN 1..v_away_goals LOOP
        v_scorer_id := v_away_player_ids[1 + floor(random() * array_length(v_away_player_ids, 1))];
        SELECT name INTO v_scorer_name FROM public.world_players WHERE id = v_scorer_id;
        v_minute := floor(random() * 90) + 1;
        
        v_events := v_events || jsonb_build_object(
            'minute', v_minute,
            'type', 'goal',
            'team', 'away',
            'playerName', v_scorer_name,
            'description', '⚽ GOOOL de ' || v_scorer_name || '!'
        );
        
        v_goal_scorers := v_goal_scorers || jsonb_build_object(
            'name', v_scorer_name,
            'team', 'away',
            'minute', v_minute
        );
    END LOOP;
    -- Update match
    UPDATE public.world_matches
    SET status = 'finished',
        home_goals = v_home_goals,
        away_goals = v_away_goals,
        played_at = now(),
        simulated = true,
        match_data = jsonb_build_object(
            'events', v_events,
            'goalScorers', v_goal_scorers,
            'simulated', true,
            'auto_simulated', true
        )
    WHERE id = p_match_id;
    -- Sync stats
    PERFORM public.sync_match_stats(p_match_id, 'world');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_bot_matches_for_round(p_league_id UUID, p_round INT)
RETURNS VOID AS $$
DECLARE
    v_match RECORD;
BEGIN
    FOR v_match IN 
        SELECT m.id 
        FROM public.world_matches m
        JOIN public.world_teams ht ON ht.id = m.home_team_id
        JOIN public.world_teams at ON at.id = m.away_team_id
        WHERE m.league_id = p_league_id 
          AND m.round = p_round 
          AND m.status = 'scheduled'
          AND ht.is_bot = true 
          AND at.is_bot = true
    LOOP
        PERFORM public.simulate_realistic_bot_match(v_match.id);
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_realistic_bot_cup_match(p_match_id UUID)
RETURNS VOID AS $$
DECLARE
    v_home_team_id UUID;
    v_away_team_id UUID;
    v_home_strength INT;
    v_away_strength INT;
    v_home_score INT := 0;
    v_away_score INT := 0;
    v_cup_id UUID;
    v_winner_id UUID;
BEGIN
    SELECT home_team_id, away_team_id, cup_id
    INTO v_home_team_id, v_away_team_id, v_cup_id
    FROM public.national_cup_matches WHERE id = p_match_id;
    SELECT strength INTO v_home_strength FROM public.national_cup_teams WHERE id = v_home_team_id;
    SELECT strength INTO v_away_strength FROM public.national_cup_teams WHERE id = v_away_team_id;
    v_home_score := floor(random() * (v_home_strength / 25.0) + (random() * 2));
    v_away_score := floor(random() * (v_away_strength / 25.0) + (random() * 1.5));
    
    IF v_home_score > v_away_score THEN 
        v_winner_id := v_home_team_id; 
    ELSIF v_away_score > v_home_score THEN 
        v_winner_id := v_away_team_id; 
    ELSE
        -- Random winner for draw in cup
        IF random() > 0.5 THEN v_winner_id := v_home_team_id; ELSE v_winner_id := v_away_team_id; END IF;
    END IF;
    UPDATE public.national_cup_matches
    SET status = 'finished',
        home_score = v_home_score,
        away_score = v_away_score,
        winner_team_id = v_winner_id,
        updated_at = now(),
        match_data = jsonb_build_object('simulated', true, 'auto_simulated', true)
    WHERE id = p_match_id;
    -- Sync stats
    PERFORM public.sync_match_stats(p_match_id, 'cup');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_bot_matches_for_round(p_league_id UUID, p_round INT)
RETURNS VOID AS $$
DECLARE
    v_match RECORD;
BEGIN
    -- 1. World Matches
    FOR v_match IN 
        SELECT m.id 
        FROM public.world_matches m
        JOIN public.world_teams ht ON ht.id = m.home_team_id
        JOIN public.world_teams at ON at.id = m.away_team_id
        WHERE m.league_id = p_league_id 
          AND m.round = p_round 
          AND m.status = 'scheduled'
          AND ht.is_bot = true 
          AND at.is_bot = true
    LOOP
        PERFORM public.simulate_realistic_bot_match(v_match.id);
    END LOOP;
    -- 2. National Cup Matches (if round matches)
    -- This is slightly different as round in cup is phase
    FOR v_match IN
        SELECT m.id
        FROM public.national_cup_matches m
        JOIN public.national_cup_teams ht ON ht.id = m.home_team_id
        JOIN public.national_cup_teams at ON at.id = m.away_team_id
        WHERE m.round = p_round
          AND m.status = 'scheduled'
          AND ht.user_id IS NULL
          AND at.user_id IS NULL
    LOOP
        PERFORM public.simulate_realistic_bot_cup_match(v_match.id);
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_realistic_bot_tournament_match(p_match_id UUID)
RETURNS VOID AS $$
DECLARE
    v_home_team_id UUID;
    v_away_team_id UUID;
    v_home_strength INT;
    v_away_strength INT;
    v_home_goals INT := 0;
    v_away_goals INT := 0;
    v_tournament_id UUID;
BEGIN
    SELECT home_team_id, away_team_id, tournament_id
    INTO v_home_team_id, v_away_team_id, v_tournament_id
    FROM public.custom_tournament_matches WHERE id = p_match_id;
    -- Custom tournament teams might have bot_strength or derive from user strength
    SELECT COALESCE(bot_strength, 70) INTO v_home_strength FROM public.custom_tournament_teams WHERE id = v_home_team_id;
    SELECT COALESCE(bot_strength, 70) INTO v_away_strength FROM public.custom_tournament_teams WHERE id = v_away_team_id;
    v_home_goals := floor(random() * (v_home_strength / 25.0) + (random() * 2));
    v_away_goals := floor(random() * (v_away_strength / 25.0) + (random() * 1.5));
    
    UPDATE public.custom_tournament_matches
    SET status = 'finished',
        home_goals = v_home_goals,
        away_goals = v_away_goals,
        played_at = now(),
        match_data = jsonb_build_object('simulated', true, 'auto_simulated', true)
    WHERE id = p_match_id;
    -- Standings are usually updated by triggers or need manual update
    -- Assuming a trigger exists for custom_tournament_matches results
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_bot_matches_for_round(p_competition_id UUID, p_round INT, p_type TEXT)
RETURNS VOID AS $$
DECLARE
    v_match RECORD;
BEGIN
    IF p_type = 'world' THEN
        FOR v_match IN 
            SELECT m.id 
            FROM public.world_matches m
            JOIN public.world_teams ht ON ht.id = m.home_team_id
            JOIN public.world_teams at ON at.id = m.away_team_id
            WHERE m.league_id = p_competition_id 
              AND m.round = p_round 
              AND m.status = 'scheduled'
              AND ht.is_bot = true 
              AND at.is_bot = true
        LOOP
            PERFORM public.simulate_realistic_bot_match(v_match.id);
        END LOOP;
    ELSIF p_type = 'cup' THEN
        FOR v_match IN
            SELECT m.id
            FROM public.national_cup_matches m
            JOIN public.national_cup_teams ht ON ht.id = m.home_team_id
            JOIN public.national_cup_teams at ON at.id = m.away_team_id
            WHERE m.cup_id = p_competition_id
              AND m.round = p_round
              AND m.status = 'scheduled'
              AND ht.user_id IS NULL
              AND at.user_id IS NULL
        LOOP
            PERFORM public.simulate_realistic_bot_cup_match(v_match.id);
        END LOOP;
    ELSIF p_type = 'tournament' THEN
        FOR v_match IN
            SELECT m.id
            FROM public.custom_tournament_matches m
            JOIN public.custom_tournament_teams ht ON ht.id = m.home_team_id
            JOIN public.custom_tournament_teams at ON at.id = m.away_team_id
            WHERE m.tournament_id = p_competition_id
              AND m.round = p_round
              AND m.status = 'scheduled'
              AND ht.user_id IS NULL
              AND at.user_id IS NULL
        LOOP
            PERFORM public.simulate_realistic_bot_tournament_match(v_match.id);
        END LOOP;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.check_and_advance_league_round(p_league_id UUID)
RETURNS VOID AS $$
DECLARE
    v_current_round INT;
    v_unfinished_matches INT;
BEGIN
    -- Get current round
    SELECT current_round INTO v_current_round FROM public.world_leagues WHERE id = p_league_id;
    -- Count unfinished matches in the current round
    SELECT COUNT(*) INTO v_unfinished_matches 
    FROM public.world_matches 
    WHERE league_id = p_league_id 
      AND round = v_current_round 
      AND status != 'finished';
    -- If all finished, advance round
    IF v_unfinished_matches = 0 THEN
        UPDATE public.world_leagues 
        SET current_round = current_round + 1 
        WHERE id = p_league_id;
        
        -- You could also trigger newspaper generation or other end-of-round events here
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.simulate_bot_matches_for_round(p_competition_id UUID, p_round INT, p_type TEXT)
RETURNS VOID AS $$
DECLARE
    v_match RECORD;
BEGIN
    IF p_type = 'world' THEN
        FOR v_match IN 
            SELECT m.id 
            FROM public.world_matches m
            JOIN public.world_teams ht ON ht.id = m.home_team_id
            JOIN public.world_teams at ON at.id = m.away_team_id
            WHERE m.league_id = p_competition_id 
              AND m.round = p_round 
              AND m.status = 'scheduled'
              AND ht.is_bot = true 
              AND at.is_bot = true
        LOOP
            PERFORM public.simulate_realistic_bot_match(v_match.id);
        END LOOP;
        
        -- Check if all matches in round are now finished and advance
        PERFORM public.check_and_advance_league_round(p_competition_id);
        
    ELSIF p_type = 'cup' THEN
        FOR v_match IN
            SELECT m.id
            FROM public.national_cup_matches m
            JOIN public.national_cup_teams ht ON ht.id = m.home_team_id
            JOIN public.national_cup_teams at ON at.id = m.away_team_id
            WHERE m.cup_id = p_competition_id
              AND m.round = p_round
              AND m.status = 'scheduled'
              AND ht.user_id IS NULL
              AND at.user_id IS NULL
        LOOP
            PERFORM public.simulate_realistic_bot_cup_match(v_match.id);
        END LOOP;
    ELSIF p_type = 'tournament' THEN
        FOR v_match IN
            SELECT m.id
            FROM public.custom_tournament_matches m
            JOIN public.custom_tournament_teams ht ON ht.id = m.home_team_id
            JOIN public.custom_tournament_teams at ON at.id = m.away_team_id
            WHERE m.tournament_id = p_competition_id
              AND m.round = p_round
              AND m.status = 'scheduled'
              AND ht.user_id IS NULL
              AND at.user_id IS NULL
        LOOP
            PERFORM public.simulate_realistic_bot_tournament_match(v_match.id);
        END LOOP;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.recalculate_league_table_from_matches(p_league_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    team_rec RECORD;
    v_wins INT;
    v_draws INT;
    v_losses INT;
    v_played INT;
    v_goals_for INT;
    v_goals_against INT;
    v_points INT;
    v_last5 TEXT;
    v_year INT;
    v_month INT;
BEGIN
    -- Get current season from league
    SELECT season_year, season_month INTO v_year, v_month FROM public.world_leagues WHERE id = p_league_id;
    FOR team_rec IN SELECT id FROM public.world_teams WHERE league_id = p_league_id LOOP
        -- Calcula vitórias, empates, derrotas e gols em casa
        SELECT 
            COALESCE(COUNT(*) FILTER (WHERE home_goals > away_goals), 0),
            COALESCE(COUNT(*) FILTER (WHERE home_goals = away_goals), 0),
            COALESCE(COUNT(*) FILTER (WHERE home_goals < away_goals), 0),
            COALESCE(SUM(home_goals), 0),
            COALESCE(SUM(away_goals), 0)
        INTO v_wins, v_draws, v_losses, v_goals_for, v_goals_against
        FROM public.world_matches 
        WHERE league_id = p_league_id 
          AND home_team_id = team_rec.id 
          AND status = 'finished'
          AND season_year = v_year
          AND season_month = v_month;
        -- Adiciona resultados como visitante
        DECLARE
            v_away_wins INT;
            v_away_draws INT;
            v_away_losses INT;
            v_away_gf INT;
            v_away_ga INT;
        BEGIN
            SELECT 
                COALESCE(COUNT(*) FILTER (WHERE away_goals > home_goals), 0),
                COALESCE(COUNT(*) FILTER (WHERE away_goals = home_goals), 0),
                COALESCE(COUNT(*) FILTER (WHERE away_goals < home_goals), 0),
                COALESCE(SUM(away_goals), 0),
                COALESCE(SUM(home_goals), 0)
            INTO v_away_wins, v_away_draws, v_away_losses, v_away_gf, v_away_ga
            FROM public.world_matches 
            WHERE league_id = p_league_id 
              AND away_team_id = team_rec.id 
              AND status = 'finished'
              AND season_year = v_year
              AND season_month = v_month;
            v_wins := v_wins + v_away_wins;
            v_draws := v_draws + v_away_draws;
            v_losses := v_losses + v_away_losses;
            v_goals_for := v_goals_for + v_away_gf;
            v_goals_against := v_goals_against + v_away_ga;
        END;
        v_played := v_wins + v_draws + v_losses;
        v_points := (v_wins * 3) + v_draws;
        -- Calcula a sequência dos últimos 5 jogos reais
        SELECT string_agg(res, '') FROM (
            SELECT 
                CASE 
                    WHEN (home_team_id = team_rec.id AND home_goals > away_goals) OR (away_team_id = team_rec.id AND away_goals > home_goals) THEN 'V'
                    WHEN home_goals = away_goals THEN 'E'
                    ELSE 'D'
                END as res
            FROM public.world_matches
            WHERE (home_team_id = team_rec.id OR away_team_id = team_rec.id) 
              AND status = 'finished'
              AND season_year = v_year
              AND season_month = v_month
            ORDER BY played_at DESC
            LIMIT 5
        ) sub INTO v_last5;
        -- Atualiza a tabela
        INSERT INTO public.world_league_table (
            league_id, team_id, points, played, wins, draws, losses, goals_for, goals_against, last_5_games,
            season_year, season_month
        ) VALUES (
            p_league_id, team_rec.id, 
            v_points, v_played, v_wins, v_draws, v_losses, v_goals_for, v_goals_against, COALESCE(v_last5, '-----'),
            v_year, v_month
        )
        ON CONFLICT (league_id, team_id) DO UPDATE SET
            points = EXCLUDED.points,
            played = EXCLUDED.played,
            wins = EXCLUDED.wins,
            draws = EXCLUDED.draws,
            losses = EXCLUDED.losses,
            goals_for = EXCLUDED.goals_for,
            goals_against = EXCLUDED.goals_against,
            last_5_games = EXCLUDED.last_5_games;
    END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.notify_player_status_change()
RETURNS TRIGGER AS $$
DECLARE
    owner_id UUID;
BEGIN
    -- Correctly link to user via world_teams
    SELECT user_id INTO owner_id FROM public.world_teams WHERE id = NEW.team_id;
    IF owner_id IS NOT NULL THEN
        -- Injury
        IF NEW.injury_weeks_remaining > 0 AND (OLD.injury_weeks_remaining IS NULL OR NEW.injury_weeks_remaining != OLD.injury_weeks_remaining) THEN
            INSERT INTO public.user_notifications (user_id, title, message, type, category, priority, icon)
            VALUES (
                owner_id,
                'Departamento Médico 🏥',
                NEW.name || ' sofreu uma lesão e ficará fora por ' || NEW.injury_weeks_remaining || ' rodadas.',
                'danger',
                'Clube',
                'high',
                '🏥'
            );
        END IF;
        -- Suspension (Check via suspensions table if possible, or we'll handle it in the next step)
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DO $$ BEGIN
    CREATE TYPE squad_status_type AS ENUM ('starter', 'bench', 'reserve', 'injured', 'suspended');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;
ALTER TABLE public.world_players 
ADD COLUMN IF NOT EXISTS squad_status squad_status_type DEFAULT 'reserve';
WITH team_rosters AS (
  SELECT 
    id, 
    team_id,
    row_number() OVER (PARTITION BY team_id ORDER BY overall DESC) as roster_rank
  FROM public.world_players
)
UPDATE public.world_players wp
SET squad_status = 
  CASE 
    WHEN tr.roster_rank <= 11 THEN 'starter'::squad_status_type
    WHEN tr.roster_rank <= 18 THEN 'bench'::squad_status_type
    ELSE 'reserve'::squad_status_type
  END
FROM team_rosters tr
WHERE wp.id = tr.id;
CREATE OR REPLACE FUNCTION public.sync_player_squad_status()
RETURNS TRIGGER AS $$
DECLARE
    is_suspended BOOLEAN;
BEGIN
    -- Check if suspended
    SELECT EXISTS (
        SELECT 1 FROM public.suspensions s 
        WHERE s.player_id = NEW.id AND s.remaining_games > 0
    ) INTO is_suspended;
    IF NEW.injury_weeks_remaining > 0 THEN
        NEW.squad_status := 'injured'::squad_status_type;
    ELSIF is_suspended THEN
        NEW.squad_status := 'suspended'::squad_status_type;
    ELSE
        -- If returning from injury/suspension, default to reserve if it was one of those
        IF OLD.squad_status IN ('injured', 'suspended') THEN
            NEW.squad_status := 'reserve'::squad_status_type;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS tr_sync_player_squad_status ON public.world_players;
CREATE TRIGGER tr_sync_player_squad_status
BEFORE UPDATE OF injury_weeks_remaining, squad_status ON public.world_players
FOR EACH ROW
EXECUTE FUNCTION public.sync_player_squad_status();
CREATE OR REPLACE FUNCTION public.ensure_full_rosters()
RETURNS void AS $$
DECLARE
    t RECORD;
    p_count INTEGER;
    players_to_add INTEGER;
    first_names TEXT[] := ARRAY['Carlos', 'Henrique', 'Vinícius', 'Jonathan', 'Renan', 'Caio', 'Yuri', 'Danilo', 'Leandro', 'Igor', 'Gustavo', 'Eduardo', 'Ricardo', 'Fabrício', 'Willian', 'Jean', 'Samuel', 'Otávio', 'Rogério', 'Adriano'];
    last_names TEXT[] := ARRAY['Pereira', 'Araújo', 'Barbosa', 'Ribeiro', 'Martins', 'Cardoso', 'Pinto', 'Nascimento', 'Moreira', 'Teixeira', 'Santos', 'Silva', 'Oliveira', 'Souza', 'Lima'];
    positions TEXT[] := ARRAY['GOL', 'ZAG', 'LAT', 'VOL', 'MEI', 'ATA'];
BEGIN
    FOR t IN SELECT id, name FROM public.world_teams LOOP
        SELECT count(*) INTO p_count FROM public.world_players WHERE team_id = t.id;
        
        IF p_count < 20 THEN
            players_to_add := 20 - p_count;
            FOR i IN 1..players_to_add LOOP
                INSERT INTO public.world_players (
                    team_id,
                    name,
                    position,
                    overall,
                    age,
                    squad_status
                ) VALUES (
                    t.id,
                    first_names[floor(random() * array_length(first_names, 1) + 1)] || ' ' || last_names[floor(random() * array_length(last_names, 1) + 1)],
                    positions[floor(random() * array_length(positions, 1) + 1)],
                    floor(random() * 20 + 50)::int,
                    floor(random() * 15 + 18)::int,
                    'reserve'
                );
            END LOOP;
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
SELECT public.ensure_full_rosters();
DO $$ BEGIN
    CREATE TYPE squad_status_type AS ENUM ('starter', 'bench', 'reserve', 'injured', 'suspended');
EXCEPTION
    WHEN duplicate_object THEN null;
END $$;
ALTER TABLE public.world_players 
ADD COLUMN IF NOT EXISTS squad_status squad_status_type DEFAULT 'reserve';
CREATE OR REPLACE FUNCTION public.sync_player_squad_status()
RETURNS TRIGGER AS $$
BEGIN
    -- If player is suspended, they MUST be 'suspended'
    IF EXISTS (SELECT 1 FROM public.suspensions WHERE player_id = NEW.id) THEN
        NEW.squad_status = 'suspended';
    -- Else if player is injured, they MUST be 'injured'
    ELSIF NEW.injury_weeks_remaining > 0 THEN
        NEW.squad_status = 'injured';
    -- If it was suspended or injured but is no longer, move back to reserve if it was one of those
    ELSIF OLD.squad_status IN ('injured', 'suspended') THEN
        NEW.squad_status = 'reserve';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS tr_sync_player_squad_status ON public.world_players;
CREATE TRIGGER tr_sync_player_squad_status
BEFORE UPDATE ON public.world_players
FOR EACH ROW
EXECUTE FUNCTION public.sync_player_squad_status();
CREATE OR REPLACE FUNCTION public.auto_fill_team_rosters()
RETURNS void AS $$
DECLARE
    team_record RECORD;
    player_count INTEGER;
    needed INTEGER;
    i INTEGER;
    new_ovr INTEGER;
    new_age INTEGER;
    new_pos TEXT;
    positions TEXT[] := ARRAY['GOL', 'ZAG', 'LAT', 'VOL', 'MEI', 'ATA'];
BEGIN
    FOR team_record IN SELECT id, name FROM public.world_teams LOOP
        SELECT count(*) INTO player_count FROM public.world_players WHERE team_id = team_record.id;
        
        IF player_count < 20 THEN
            needed := 20 - player_count;
            FOR i IN 1..needed LOOP
                new_ovr := floor(random() * (75 - 55 + 1) + 55);
                new_age := floor(random() * (35 - 18 + 1) + 18);
                new_pos := positions[floor(random() * array_length(positions, 1)) + 1];
                
                INSERT INTO public.world_players (team_id, name, position, overall, age, squad_status)
                VALUES (team_record.id, 'Jogador Base ' || team_record.name || ' ' || i, new_pos, new_ovr, new_age, 'reserve');
            END LOOP;
        END IF;
        -- Ensure they have 11 starters if not already set
        IF NOT EXISTS (SELECT 1 FROM public.world_players WHERE team_id = team_record.id AND squad_status = 'starter') THEN
            UPDATE public.world_players 
            SET squad_status = 'starter'
            WHERE id IN (
                SELECT id FROM public.world_players 
                WHERE team_id = team_record.id 
                ORDER BY overall DESC 
                LIMIT 11
            );
        END IF;
        -- Ensure they have bench players
        IF NOT EXISTS (SELECT 1 FROM public.world_players WHERE team_id = team_record.id AND squad_status = 'bench') THEN
            UPDATE public.world_players 
            SET squad_status = 'bench'
            WHERE id IN (
                SELECT id FROM public.world_players 
                WHERE team_id = team_record.id 
                AND squad_status != 'starter'
                ORDER BY overall DESC 
                LIMIT 7
            );
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
SELECT public.auto_fill_team_rosters();
CREATE TABLE IF NOT EXISTS public.world_player_availability (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    player_id UUID REFERENCES public.world_players(id) ON DELETE CASCADE,
    team_id UUID REFERENCES public.world_teams(id) ON DELETE CASCADE,
    type TEXT NOT NULL CHECK (type IN ('injury', 'suspension')),
    reason TEXT,
    rounds_remaining INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    UNIQUE(player_id, type)
);
CREATE TABLE IF NOT EXISTS public.world_league_standings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    league_id UUID NOT NULL,
    team_id UUID NOT NULL,
    points INTEGER DEFAULT 0,
    played INTEGER DEFAULT 0,
    wins INTEGER DEFAULT 0,
    draws INTEGER DEFAULT 0,
    losses INTEGER DEFAULT 0,
    goals_for INTEGER DEFAULT 0,
    goals_against INTEGER DEFAULT 0,
    goal_diff INTEGER DEFAULT 0,
    season_year INTEGER NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(),
    UNIQUE(league_id, team_id, season_year)
);
ALTER TABLE public.world_matches 
ADD COLUMN IF NOT EXISTS synced BOOLEAN DEFAULT false,
ADD COLUMN IF NOT EXISTS match_data JSONB DEFAULT '{}'::jsonb;
CREATE OR REPLACE FUNCTION public.update_world_league_standings()
RETURNS TRIGGER AS $$
DECLARE
    h_win INT := 0;
    h_draw INT := 0;
    h_loss INT := 0;
    a_win INT := 0;
    a_draw INT := 0;
    a_loss INT := 0;
BEGIN
    IF (NEW.status = 'finished' AND (OLD.status IS NULL OR OLD.status != 'finished') AND NEW.synced = false) THEN
        -- Determinar resultado
        IF NEW.home_goals > NEW.away_goals THEN h_win := 1; a_loss := 1;
        ELSIF NEW.home_goals < NEW.away_goals THEN h_loss := 1; a_win := 1;
        ELSE h_draw := 1; a_draw := 1;
        END IF;
        -- Update Mandante
        INSERT INTO public.world_league_standings (league_id, team_id, season_year, points, played, wins, draws, losses, goals_for, goals_against, goal_diff)
        VALUES (NEW.league_id, NEW.home_team_id, NEW.season_year, (h_win*3 + h_draw), 1, h_win, h_draw, h_loss, NEW.home_goals, NEW.away_goals, (NEW.home_goals - NEW.away_goals))
        ON CONFLICT (league_id, team_id, season_year) DO UPDATE SET
            points = world_league_standings.points + excluded.points,
            played = world_league_standings.played + 1,
            wins = world_league_standings.wins + h_win,
            draws = world_league_standings.draws + h_draw,
            losses = world_league_standings.losses + h_loss,
            goals_for = world_league_standings.goals_for + excluded.goals_for,
            goals_against = world_league_standings.goals_against + excluded.goals_against,
            goal_diff = world_league_standings.goal_diff + (excluded.goals_for - excluded.goals_against),
            updated_at = now();
        -- Update Visitante
        INSERT INTO public.world_league_standings (league_id, team_id, season_year, points, played, wins, draws, losses, goals_for, goals_against, goal_diff)
        VALUES (NEW.league_id, NEW.away_team_id, NEW.season_year, (a_win*3 + a_draw), 1, a_win, a_draw, a_loss, NEW.away_goals, NEW.home_goals, (NEW.away_goals - NEW.home_goals))
        ON CONFLICT (league_id, team_id, season_year) DO UPDATE SET
            points = world_league_standings.points + excluded.points,
            played = world_league_standings.played + 1,
            wins = world_league_standings.wins + a_win,
            draws = world_league_standings.draws + a_draw,
            losses = world_league_standings.losses + a_loss,
            goals_for = world_league_standings.goals_for + excluded.goals_for,
            goals_against = world_league_standings.goals_against + excluded.goals_against,
            goal_diff = world_league_standings.goal_diff + (excluded.goals_for - excluded.goals_against),
            updated_at = now();
        NEW.synced := true;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
