CREATE OR REPLACE FUNCTION public.sync_world_league_standings(_league_id UUID)
RETURNS VOID AS $$
BEGIN
    -- This function recalculates the whole league table for simplicity and consistency
    -- It updates world_league_standings based on world_matches results
    
    INSERT INTO public.world_league_standings (league_id, team_id, played, wins, draws, losses, goals_for, goals_against, points)
    SELECT 
        m.league_id,
        t.id as team_id,
        COUNT(m.id) as played,
        COUNT(CASE WHEN (m.home_team_id = t.id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.id AND m.away_goals > m.home_goals) THEN 1 END) as wins,
        COUNT(CASE WHEN m.home_goals = m.away_goals THEN 1 END) as draws,
        COUNT(CASE WHEN (m.home_team_id = t.id AND m.home_goals < m.away_goals) OR (m.away_team_id = t.id AND m.away_goals < m.home_goals) THEN 1 END) as losses,
        SUM(CASE WHEN m.home_team_id = t.id THEN m.home_goals ELSE m.away_goals END) as goals_for,
        SUM(CASE WHEN m.home_team_id = t.id THEN m.away_goals ELSE m.home_goals END) as goals_against,
        SUM(CASE 
            WHEN (m.home_team_id = t.id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.id AND m.away_goals > m.home_goals) THEN 3
            WHEN m.home_goals = m.away_goals THEN 1
            ELSE 0
        END) as points
    FROM public.world_matches m
    JOIN public.world_teams t ON t.id IN (m.home_team_id, m.away_team_id)
    WHERE m.league_id = _league_id AND m.status = 'finished'
    GROUP BY m.league_id, t.id
    ON CONFLICT (league_id, team_id) DO UPDATE SET
        played = EXCLUDED.played,
        wins = EXCLUDED.wins,
        draws = EXCLUDED.draws,
        losses = EXCLUDED.losses,
        goals_for = EXCLUDED.goals_for,
        goals_against = EXCLUDED.goals_against,
        points = EXCLUDED.points;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.after_world_match_finished()
RETURNS TRIGGER AS $$
DECLARE
    v_pending INT;
    v_current_round INT;
BEGIN
    -- Only run if status changed to 'finished'
    IF (OLD.status IS NULL OR OLD.status != 'finished') AND NEW.status = 'finished' THEN
        
        -- 1. Update Standings
        PERFORM public.recalculate_league_table_from_matches(NEW.league_id);
        
        -- 2. Check if all matches in current round are finished
        SELECT current_round INTO v_current_round FROM public.world_leagues WHERE id = NEW.league_id;
        
        -- Use the correct column name from the table (round)
        SELECT count(*) INTO v_pending 
        FROM public.world_matches 
        WHERE league_id = NEW.league_id AND round = v_current_round AND status != 'finished';
        
        -- 3. If no pending matches, advance round
        IF v_pending = 0 THEN
            UPDATE public.world_leagues 
            SET current_round = current_round + 1 
            WHERE id = NEW.league_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.after_league_match_finished()
RETURNS TRIGGER AS $$
DECLARE
    v_pending INT;
    v_current_round INT;
BEGIN
    -- Only run if status changed to 'finished' or 'played' (different tables use different terminologies)
    IF (OLD.status IS NULL OR (OLD.status != 'finished' AND OLD.status != 'played')) AND (NEW.status = 'finished' OR NEW.status = 'played') THEN
        
        -- 1. Update Standings
        PERFORM public.update_league_standings(NEW.league_id);
        
        -- 2. Check if all matches in current round are finished
        SELECT current_round INTO v_current_round FROM public.multiplayer_leagues WHERE id = NEW.league_id;
        
        SELECT count(*) INTO v_pending 
        FROM public.league_matches 
        WHERE league_id = NEW.league_id AND round = v_current_round AND (status != 'finished' AND status != 'played');
        
        -- 3. If no pending matches, advance round
        IF v_pending = 0 THEN
            UPDATE public.multiplayer_leagues 
            SET current_round = current_round + 1 
            WHERE id = NEW.league_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
