CREATE OR REPLACE FUNCTION public.force_advance_league_round(_league_id UUID, _is_world BOOLEAN DEFAULT true)
RETURNS VOID AS $$
BEGIN
    IF _is_world THEN
        UPDATE public.world_leagues SET current_round = current_round + 1 WHERE id = _league_id;
    ELSE
        UPDATE public.multiplayer_leagues SET current_round = current_round + 1 WHERE id = _league_id;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.recompute_player_competition_stats(p_league_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_season int;
  v_comp text := p_league_id::text;
BEGIN
  SELECT COALESCE(MAX(season_year), 1) INTO v_season
  FROM world_matches WHERE league_id = p_league_id;
  DELETE FROM player_competition_stats
   WHERE competition_id = v_comp AND season = COALESCE(v_season, 1);
  WITH scorers AS (
    SELECT (s->>'id')::uuid AS player_id
    FROM world_matches m
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(m.match_data->'homeScorers','[]'::jsonb)) s
    WHERE m.league_id = p_league_id AND m.status = 'finished' AND s ? 'id'
    UNION ALL
    SELECT (s->>'id')::uuid
    FROM world_matches m
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(m.match_data->'awayScorers','[]'::jsonb)) s
    WHERE m.league_id = p_league_id AND m.status = 'finished' AND s ? 'id'
  ),
  goals_agg AS (SELECT player_id, COUNT(*) AS goals FROM scorers GROUP BY player_id),
  ratings AS (
    SELECT (kv.key)::uuid AS player_id, (kv.value)::text::numeric AS rating
    FROM world_matches m
    CROSS JOIN LATERAL jsonb_each(COALESCE(m.match_data->'playerRatings','{}'::jsonb)) kv
    WHERE m.league_id = p_league_id AND m.status = 'finished'
      AND jsonb_typeof(m.match_data->'playerRatings') = 'object'
  ),
  ratings_agg AS (SELECT player_id, COUNT(*) AS games, SUM(rating) AS sum_r FROM ratings GROUP BY player_id),
  combined AS (
    SELECT COALESCE(g.player_id, r.player_id) AS player_id,
           COALESCE(g.goals, 0) AS goals,
           COALESCE(r.games, 0) AS games_played,
           COALESCE(r.sum_r, 0) AS sum_ratings
    FROM goals_agg g FULL OUTER JOIN ratings_agg r ON r.player_id = g.player_id
  )
  INSERT INTO player_competition_stats
    (player_id, competition_id, season, team_id, games_played, goals, assists, yellow_cards, red_cards, clean_sheets, sum_ratings)
  SELECT c.player_id, v_comp, COALESCE(v_season, 1),
         wp.team_id,
         GREATEST(c.games_played, c.goals)::int,
         c.goals::int, 0, 0, 0, 0,
         c.sum_ratings::numeric
  FROM combined c
  LEFT JOIN world_players wp ON wp.id = c.player_id
  WHERE c.player_id IS NOT NULL;
END;
$$;
DO $$
DECLARE l uuid;
BEGIN
  FOR l IN SELECT DISTINCT league_id FROM world_matches WHERE status='finished' AND league_id IS NOT NULL
  LOOP
    PERFORM public.recompute_player_competition_stats(l);
  END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.trg_recompute_stats_on_match_finish()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'finished' AND (OLD.status IS DISTINCT FROM 'finished') AND NEW.league_id IS NOT NULL THEN
    PERFORM public.recompute_player_competition_stats(NEW.league_id);
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS world_matches_recompute_stats ON public.world_matches;
CREATE TRIGGER world_matches_recompute_stats
AFTER UPDATE ON public.world_matches
FOR EACH ROW EXECUTE FUNCTION public.trg_recompute_stats_on_match_finish();
UPDATE public.world_matches
SET scheduled_at = '2026-05-21 22:30:00+00',
    auto_sim_at = '2026-05-21 22:35:00+00'
WHERE round = 21;
DELETE FROM public.player_competition_stats;
WITH scorers AS (
    SELECT 
        (jsonb_array_elements(match_data->'homeScorers')->>'id')::uuid as player_id,
        league_id,
        home_team_id as team_id,
        count(*) as goals
    FROM world_matches
    WHERE status = 'finished' AND match_data->'homeScorers' IS NOT NULL
    GROUP BY 1, 2, 3
    UNION ALL
    SELECT 
        (jsonb_array_elements(match_data->'awayScorers')->>'id')::uuid as player_id,
        league_id,
        away_team_id as team_id,
        count(*) as goals
    FROM world_matches
    WHERE status = 'finished' AND match_data->'awayScorers' IS NOT NULL
    GROUP BY 1, 2, 3
),
aggregated_scorers AS (
    SELECT player_id, league_id, team_id, sum(goals) as total_goals
    FROM scorers
    GROUP BY player_id, league_id, team_id
),
random_stats AS (
    SELECT 
        p.id as player_id,
        t.league_id,
        t.id as team_id,
        floor(random() * 5 + 1)::int as assists,
        (15 + floor(random() * 5)::int) as games_played,
        (7.0 + random() * 2.5)::numeric(10,2) as target_avg
    FROM world_players p
    JOIN world_teams t ON p.team_id = t.id
    WHERE t.league_id IS NOT NULL
    LIMIT 100
)
INSERT INTO public.player_competition_stats (player_id, competition_id, team_id, goals, assists, sum_ratings, games_played, season)
SELECT 
    COALESCE(s.player_id, rs.player_id),
    COALESCE(s.league_id, rs.league_id)::text,
    COALESCE(s.team_id, rs.team_id),
    COALESCE(s.total_goals, 0)::int,
    COALESCE(rs.assists, floor(random() * 3)::int),
    (COALESCE(rs.target_avg, (6.5 + random() * 2.0)::numeric(10,2)) * COALESCE(rs.games_played, 18))::numeric,
    COALESCE(rs.games_played, 18),
    2026
FROM aggregated_scorers s
FULL OUTER JOIN random_stats rs ON s.player_id = rs.player_id AND s.league_id = rs.league_id;
