CREATE OR REPLACE FUNCTION public.calculate_daily_uniform_sales(
    p_club_id UUID,
    p_launch_id UUID
)
RETURNS void AS $$
DECLARE
    v_fans INTEGER;
    v_reputation INTEGER;
    v_hype DOUBLE PRECISION;
    v_days_since_launch INTEGER;
    v_daily_sales INTEGER;
    v_revenue_cents BIGINT;
    v_user_id UUID;
    v_club_name TEXT;
    v_uniform_name TEXT;
    v_last_notified TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Get club and launch data
    SELECT c.user_id, c.name, c.fans, c.reputation, l.name, l.hype_score, 
           EXTRACT(DAY FROM (now() - l.launched_at))::INTEGER
    INTO v_user_id, v_club_name, v_fans, v_reputation, v_uniform_name, v_hype, v_days_since_launch
    FROM public.clubs c
    JOIN public.club_uniform_launches l ON l.club_id = c.id
    WHERE l.id = p_launch_id AND c.id = p_club_id;
    IF NOT FOUND THEN RETURN; END IF;
    -- Calculate decay (hype drops over time)
    -- Starts at 1.0, drops towards 0.05 over 60 days
    v_hype := GREATEST(0.05, 1.0 * EXP(-v_days_since_launch / 20.0));
    
    -- Update hype in the record
    UPDATE public.club_uniform_launches 
    SET hype_score = v_hype,
        last_sales_update_at = now()
    WHERE id = p_launch_id;
    -- Daily sales calculation: (Fans * 0.5% base) * (Reputation factor) * Hype
    -- Rep factor: 0.5 to 1.5 based on 0-100 reputation
    v_daily_sales := FLOOR(
        (v_fans * 0.005) * 
        (0.5 + (v_reputation / 100.0)) * 
        v_hype
    );
    -- Random variance (+/- 15%)
    v_daily_sales := FLOOR(v_daily_sales * (0.85 + (random() * 0.3)));
    
    -- Minimum sales if club is active
    IF v_daily_sales < 5 AND v_fans > 1000 THEN v_daily_sales := 5; END IF;
    -- Revenue: R$ 120 base + reputation bonus
    v_revenue_cents := v_daily_sales * (12000 + (v_reputation * 80));
    -- Update statistics
    UPDATE public.club_uniform_launches
    SET total_sales_count = total_sales_count + v_daily_sales,
        total_revenue_cents = total_revenue_cents + v_revenue_cents,
        peak_daily_sales = GREATEST(peak_daily_sales, v_daily_sales)
    WHERE id = p_launch_id;
    -- Add money to club budget
    UPDATE public.clubs
    SET budget = budget + (v_revenue_cents / 100)
    WHERE id = p_club_id;
    -- Record in shop stats
    INSERT INTO public.club_shop_stats (club_id, total_revenue, daily_revenue, total_sales, updated_at)
    VALUES (p_club_id, v_revenue_cents, v_revenue_cents, v_daily_sales, now())
    ON CONFLICT (club_id) DO UPDATE SET
        total_revenue = club_shop_stats.total_revenue + EXCLUDED.total_revenue,
        daily_revenue = EXCLUDED.daily_revenue,
        total_sales = club_shop_stats.total_sales + EXCLUDED.total_sales,
        updated_at = now();
    -- Check for "Flop" status (low hype after some time) and notify user
    IF v_hype < 0.15 AND v_days_since_launch > 15 THEN
        -- Check if we already notified recently (last 7 days)
        SELECT created_at INTO v_last_notified 
        FROM public.user_notifications 
        WHERE user_id = v_user_id AND title = 'Interesse em queda'
        ORDER BY created_at DESC LIMIT 1;
        IF v_last_notified IS NULL OR v_last_notified < now() - INTERVAL '7 days' THEN
            INSERT INTO public.user_notifications (user_id, type, category, title, message, icon)
            VALUES (
                v_user_id, 
                'warning', 
                'Marketing', 
                'Interesse em queda', 
                'Sua torcida perdeu o interesse no uniforme atual. As vendas despencaram! Crie uma nova coleção para voltar a lucrar.', 
                '👕'
            );
            
            INSERT INTO public.newspaper_entries (user_id, text, category, importance)
            VALUES (
                v_user_id,
                format('📉 FLOP! As vendas de camisas do %s caíram drasticamente. Especialistas dizem que o design saturou e a torcida pede novidades.', v_club_name),
                'marketing',
                1
            );
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
CREATE OR REPLACE FUNCTION public.process_all_uniform_sales()
RETURNS void AS $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT club_id, id 
        FROM public.club_uniform_launches 
        WHERE is_active = true 
        AND (last_sales_update_at IS NULL OR last_sales_update_at < now() - INTERVAL '1 hour')
    ) LOOP
        PERFORM public.calculate_daily_uniform_sales(r.club_id, r.id);
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;
DO $$ 
BEGIN 
    IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'clubs' AND COLUMN_NAME = 'total_members') THEN
        ALTER TABLE public.clubs ADD COLUMN total_members INTEGER DEFAULT 0;
    END IF;
END $$;
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
    v_immediate_fans INTEGER := 0;
    v_immediate_members INTEGER := 0;
    v_immediate_cash BIGINT := 0;
    v_result JSONB;
BEGIN
    -- 1. Obter dados do pedido
    SELECT * INTO v_order FROM payment_orders WHERE id = p_order_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pedido não encontrado');
    END IF;
    IF v_order.delivered THEN
        RETURN jsonb_build_object('success', true, 'message', 'Pedido já entregue');
    END IF;
    -- 2. Obter dados do item
    SELECT * INTO v_item FROM shop_items WHERE id = v_order.item_id;
    -- Se não for um item fixo, tenta pegar do metadata (itens dinâmicos)
    
    -- 3. Identificar o clube do usuário
    SELECT id INTO v_club_id FROM clubs WHERE user_id = v_order.user_id ORDER BY updated_at DESC LIMIT 1;
    IF v_club_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Clube não encontrado para o usuário');
    END IF;
    -- 4. Processar bônus baseado na categoria e metadata
    v_immediate_fans := (v_order.metadata->'bonus_data'->>'immediate_fans')::INTEGER;
    v_immediate_members := (v_order.metadata->'bonus_data'->>'immediate_members')::INTEGER;
    v_immediate_cash := (v_order.metadata->'bonus_data'->>'immediate_cash')::BIGINT;
    -- Se vier do shop_items fixo
    IF v_item IS NOT NULL THEN
        v_immediate_fans := COALESCE(v_immediate_fans, (v_item.bonus_data->>'immediate_fans')::INTEGER, 0);
        v_immediate_members := COALESCE(v_immediate_members, (v_item.bonus_data->>'immediate_members')::INTEGER, 0);
        v_immediate_cash := COALESCE(v_immediate_cash, (v_item.bonus_data->>'immediate_cash')::BIGINT, 0);
    END IF;
    -- 5. Aplicar mudanças no clube
    UPDATE clubs 
    SET 
        fans = COALESCE(fans, 0) + COALESCE(v_immediate_fans, 0),
        total_members = COALESCE(total_members, 0) + COALESCE(v_immediate_members, 0),
        budget = COALESCE(budget, 0) + COALESCE(v_immediate_cash, 0),
        updated_at = NOW()
    WHERE id = v_club_id;
    -- 6. Atualizar club_memberships para receita recorrente se for item de sócios
    IF v_item.category = 'members' OR (v_order.metadata->>'category') = 'members' THEN
        INSERT INTO club_memberships (club_id, total_members, last_update)
        VALUES (v_club_id, v_immediate_members, NOW())
        ON CONFLICT (club_id) DO UPDATE 
        SET 
            total_members = club_memberships.total_members + EXCLUDED.total_members,
            last_update = NOW();
    END IF;
    -- 7. Marcar como entregue
    UPDATE payment_orders SET delivered = true, updated_at = NOW() WHERE id = p_order_id;
    -- 8. Log administrativo
    INSERT INTO admin_shop_activity (
        user_id, item_id, item_name, amount_cents, status, transaction_id
    ) VALUES (
        v_order.user_id, v_order.item_id, COALESCE(v_order.metadata->>'item_name', v_item.name), 
        v_order.amount_cents, 'delivered', v_order.payment_id
    );
    RETURN jsonb_build_object(
        'success', true, 
        'fans_added', v_immediate_fans, 
        'members_added', v_immediate_members,
        'cash_added', v_immediate_cash
    );
END;
$$;
