CREATE OR REPLACE FUNCTION public.start_world_cup(_season INTEGER)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_cup_id UUID;
    v_team_count INTEGER;
    v_online_teams RECORD;
    v_new_cup_name TEXT;
    v_team_ids UUID[];
    v_match_id UUID;
BEGIN
    v_new_cup_name := 'Mundial de Clubes ' || _season::text;
    
    -- Create the competition
    INSERT INTO public.world_cup_competitions (name, season_year, status)
    VALUES (v_new_cup_name, _season, 'active')
    RETURNING id INTO v_cup_id;
    -- Select up to 8 real teams (online players)
    -- We'll use clubs that have been updated recently or just all non-bot clubs available
    WITH participants AS (
        SELECT id, user_id FROM public.clubs 
        WHERE user_id IS NOT NULL 
        ORDER BY reputation DESC 
        LIMIT 8
    )
    INSERT INTO public.world_cup_teams (cup_id, club_id, user_id, is_bot, entry_round)
    SELECT v_cup_id, id, user_id, false, 'quarter-finals'
    FROM participants;
    GET DIAGNOSTICS v_team_count = ROW_COUNT;
    -- If less than 8, fill with elite bots if necessary (or just run with fewer)
    -- But request said "start with online teams", so we'll focus on them.
    -- If we have 4 or 8, we can build the bracket.
    
    IF v_team_count >= 2 THEN
        -- Basic bracket generation for Quarter Finals or Semi Finals
        -- For simplicity, let's pair them up.
        DECLARE
            v_t1 UUID;
            v_t2 UUID;
            v_teams_list UUID[];
            v_i INTEGER;
            v_stage TEXT;
        BEGIN
            SELECT ARRAY_AGG(id) INTO v_teams_list FROM public.world_cup_teams WHERE cup_id = v_cup_id;
            v_stage := CASE WHEN v_team_count > 4 THEN 'quarter-finals' ELSE 'semi-finals' END;
            
            FOR v_i IN 1..(v_team_count/2) LOOP
                v_t1 := v_teams_list[(v_i-1)*2 + 1];
                v_t2 := v_teams_list[(v_i-1)*2 + 2];
                
                IF v_t1 IS NOT NULL AND v_t2 IS NOT NULL THEN
                    INSERT INTO public.world_cup_matches (cup_id, home_team_id, away_team_id, stage, scheduled_at)
                    VALUES (v_cup_id, v_t1, v_t2, v_stage, NOW() + (v_i * interval '1 day'));
                END IF;
            END LOOP;
        END;
    END IF;
    RETURN jsonb_build_object(
        'success', true,
        'cup_id', v_cup_id,
        'team_count', v_team_count,
        'message', 'Mundial iniciado com ' || v_team_count::text || ' times online.'
    );
END;
$$;
ALTER FUNCTION public.start_world_cup(_season INTEGER) SET search_path TO public;
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
    v_user_id UUID;
    v_immediate_fans INTEGER := 0;
    v_immediate_members INTEGER := 0;
    v_immediate_cash BIGINT := 0;
    v_monthly_revenue BIGINT := 0;
    v_duration_days INTEGER := 30;
    v_result JSONB;
BEGIN
    -- 1. Obter dados do pedido
    SELECT * INTO v_order FROM payment_orders WHERE id = p_order_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pedido não encontrado');
    END IF;
    IF v_order.delivered THEN
        RETURN jsonb_build_object('success', true, 'message', 'Pedido já entregue');
    END IF;
    v_user_id := v_order.user_id;
    -- 2. Obter dados do item
    SELECT * INTO v_item FROM shop_items WHERE id = v_order.item_id;
    
    -- 3. Identificar o clube do usuário
    SELECT id INTO v_club_id FROM clubs WHERE user_id = v_user_id ORDER BY updated_at DESC LIMIT 1;
    IF v_club_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Clube não encontrado para o usuário');
    END IF;
    -- 4. Extrair bônus (Prioridade para metadata do pedido, depois item fixo)
    -- Metadata (itens dinâmicos)
    v_immediate_fans := COALESCE((v_order.metadata->'bonus_data'->>'immediate_fans')::INTEGER, (v_order.metadata->'bonus_data'->>'initialFans')::INTEGER, 0);
    v_immediate_members := COALESCE((v_order.metadata->'bonus_data'->>'immediate_members')::INTEGER, (v_order.metadata->'bonus_data'->>'initialMembers')::INTEGER, 0);
    v_immediate_cash := COALESCE((v_order.metadata->'bonus_data'->>'immediate_cash')::BIGINT, 0);
    v_monthly_revenue := COALESCE((v_order.metadata->'bonus_data'->>'monthlyRevenue')::BIGINT, (v_order.metadata->'bonus_data'->>'monthly_revenue')::BIGINT, 0);
    -- Item fixo (se metadata for vazio)
    IF v_item IS NOT NULL THEN
        v_immediate_fans := COALESCE(NULLIF(v_immediate_fans, 0), (v_item.bonus_data->>'immediate_fans')::INTEGER, (v_item.bonus_data->>'initialFans')::INTEGER, 0);
        v_immediate_members := COALESCE(NULLIF(v_immediate_members, 0), (v_item.bonus_data->>'immediate_members')::INTEGER, (v_item.bonus_data->>'initialMembers')::INTEGER, 0);
        v_immediate_cash := COALESCE(NULLIF(v_immediate_cash, 0), (v_item.bonus_data->>'immediate_cash')::BIGINT, 0);
        v_monthly_revenue := COALESCE(NULLIF(v_monthly_revenue, 0), (v_item.bonus_data->>'monthlyRevenue')::BIGINT, (v_item.bonus_data->>'monthly_revenue')::BIGINT, 0);
        v_duration_days := COALESCE(v_item.duration_days, 30);
    END IF;
    -- 5. Aplicar mudanças imediatas no clube
    UPDATE clubs 
    SET 
        fans = COALESCE(fans, 0) + v_immediate_fans,
        total_members = COALESCE(total_members, 0) + v_immediate_members,
        budget = COALESCE(budget, 0) + v_immediate_cash,
        updated_at = NOW()
    WHERE id = v_club_id;
    -- 6. Processar Categorias Específicas
    
    -- SÓCIOS: Atualizar club_memberships para receita recorrente
    IF v_item.category = 'members' OR (v_order.metadata->>'category') = 'members' THEN
        INSERT INTO club_memberships (club_id, total_members, monthly_revenue_cents, updated_at)
        VALUES (v_club_id, v_immediate_members, v_monthly_revenue * 100, NOW())
        ON CONFLICT (club_id) DO UPDATE 
        SET 
            total_members = COALESCE(club_memberships.total_members, 0) + EXCLUDED.total_members,
            monthly_revenue_cents = COALESCE(club_memberships.monthly_revenue_cents, 0) + EXCLUDED.monthly_revenue_cents,
            updated_at = NOW();
    END IF;
    -- PATROCÍNIO: Criar contrato ativo
    IF v_item.category = 'sponsorship' OR (v_order.metadata->>'category') = 'sponsorship' THEN
        INSERT INTO club_sponsorships (
            club_id, sponsor_name, contract_value_cents, started_at, expires_at, is_active, bonus_data
        ) VALUES (
            v_club_id, v_item.name, (v_item.bonus_data->>'dinheiroSemanal')::BIGINT * 100, 
            NOW(), NOW() + (v_duration_days * interval '1 day'), true, v_item.bonus_data
        );
    END IF;
    -- MARKETING / OLHEIROS / TORCIDA: Criar efeitos ativos
    IF v_item.category IN ('marketing', 'scouting', 'fans') OR (v_order.metadata->>'category') IN ('marketing', 'scouting', 'fans') THEN
        INSERT INTO club_active_effects (
            club_id, item_id, category, bonus_data, started_at, expires_at, created_at
        ) VALUES (
            v_club_id, v_item.id, COALESCE(v_item.category, (v_order.metadata->>'category')), 
            v_item.bonus_data, NOW(), NOW() + (v_duration_days * interval '1 day'), NOW()
        );
    END IF;
    -- 7. Marcar como entregue
    UPDATE payment_orders SET delivered = true, updated_at = NOW() WHERE id = p_order_id;
    -- 8. Log administrativo
    INSERT INTO admin_shop_activity (
        user_id, item_id, item_name, amount_cents, status, transaction_id
    ) VALUES (
        v_user_id, v_order.item_id, COALESCE(v_order.metadata->>'item_name', v_item.name), 
        v_order.amount_cents, 'delivered', v_order.payment_id
    );
    -- 9. Notificação para o usuário
    INSERT INTO user_notifications (user_id, type, title, message, importance)
    VALUES (
        v_user_id, 'purchase_delivery', '✅ Produto Entregue!', 
        format('Seu item "%s" foi ativado. %s %s', 
            COALESCE(v_item.name, (v_order.metadata->>'item_name')),
            CASE WHEN v_immediate_fans > 0 THEN format('+%s torcedores. ', v_immediate_fans) ELSE '' END,
            CASE WHEN v_immediate_members > 0 THEN format('+%s sócios. ', v_immediate_members) ELSE '' END
        ),
        2
    );
    RETURN jsonb_build_object(
        'success', true, 
        'fans_added', v_immediate_fans, 
        'members_added', v_immediate_members,
        'cash_added', v_immediate_cash,
        'category', v_item.category
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_daily_shop_bonuses(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_club_id UUID;
    v_club_name TEXT;
    v_last_process TIMESTAMP WITH TIME ZONE;
    v_now TIMESTAMP WITH TIME ZONE := now();
    v_days_to_process INTEGER;
    v_current_day_iter DATE;
    
    v_total_fans INTEGER := 0;
    v_total_cash BIGINT := 0;
    v_total_uniform_sales BIGINT := 0;
    
    v_day_fans INTEGER;
    v_day_cash BIGINT;
    v_day_uniform_sales BIGINT;
    
    v_effect RECORD;
    v_sponsor RECORD;
    v_uniform RECORD;
    v_members RECORD;
BEGIN
    -- Get user club
    SELECT id, name INTO v_club_id, v_club_name
    FROM public.clubs WHERE user_id = p_user_id;
    
    IF v_club_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Club not found');
    END IF;
    -- Get last process time
    SELECT last_daily_shop_bonus_at INTO v_last_process FROM public.profiles WHERE user_id = p_user_id;
    -- If never processed, start from yesterday to give 1 day of bonus or just mark as now
    IF v_last_process IS NULL THEN
        UPDATE public.profiles SET last_daily_shop_bonus_at = v_now WHERE user_id = p_user_id;
        RETURN jsonb_build_object('success', true, 'message', 'First time initialization complete');
    END IF;
    -- Calculate days passed (date difference)
    v_days_to_process := v_now::date - v_last_process::date;
    IF v_days_to_process < 1 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Already processed today');
    END IF;
    -- Limit catch up to 30 days to prevent overflow or abuse
    IF v_days_to_process > 30 THEN
        v_days_to_process := 30;
    END IF;
    -- Loop through each day since last process
    FOR i IN 1..v_days_to_process LOOP
        v_current_day_iter := (v_last_process + (i * interval '1 day'))::date;
        v_day_fans := 0;
        v_day_cash := 0;
        v_day_uniform_sales := 0;
        -- 1. Active Effects (Marketing)
        FOR v_effect IN 
            SELECT * FROM public.club_active_effects 
            WHERE club_id = v_club_id AND (expires_at IS NULL OR expires_at::date >= v_current_day_iter)
        LOOP
            IF v_effect.category = 'marketing' THEN
                v_day_fans := v_day_fans + COALESCE((v_effect.bonus_data->>'torcidaPorDia')::int, 0);
                v_day_cash := v_day_cash + COALESCE((v_effect.bonus_data->>'daily_cash')::bigint, (v_effect.bonus_data->>'dinheiroDia')::bigint, 0);
            END IF;
        END LOOP;
        -- 2. Sponsorships
        FOR v_sponsor IN 
            SELECT * FROM public.club_sponsorships 
            WHERE club_id = v_club_id AND is_active = true AND (expires_at IS NULL OR expires_at::date >= v_current_day_iter)
        LOOP
            v_day_cash := v_day_cash + (v_sponsor.contract_value_cents / 700.0)::bigint;
            -- Bonus diário direto se existir no json
            v_day_cash := v_day_cash + COALESCE((v_sponsor.bonus_data->>'daily_cash')::bigint, 0);
        END LOOP;
        -- 3. Membership
        SELECT * INTO v_members FROM public.club_memberships WHERE club_id = v_club_id;
        IF v_members IS NOT NULL THEN
            v_day_cash := v_day_cash + (v_members.monthly_revenue_cents / 3000.0)::bigint; -- cents to R$
        END IF;
        -- 4. Uniform Sales (Simplified cumulative for catch up)
        FOR v_uniform IN 
            SELECT * FROM public.club_uniform_launches 
            WHERE club_id = v_club_id AND is_active = true AND launched_at::date <= v_current_day_iter
        LOOP
            DECLARE
                v_days_since_launch INTEGER;
                v_decay_factor DOUBLE PRECISION;
                v_sales_today BIGINT;
                v_fans_now INTEGER;
                v_rep_now INTEGER;
            BEGIN
                v_days_since_launch := v_current_day_iter - v_uniform.launched_at::date;
                
                IF v_days_since_launch <= 15 THEN
                    v_decay_factor := 1.0;
                ELSE
                    v_decay_factor := exp(-0.05 * (v_days_since_launch - 15));
                END IF;
                -- Get club state for that iter (using current as approximation)
                SELECT fans, reputation INTO v_fans_now, v_rep_now FROM public.clubs WHERE id = v_club_id;
                v_sales_today := (v_fans_now * (v_rep_now / 100.0) * (v_uniform.hype_score / 100.0) * v_decay_factor * 10)::bigint;
                v_day_uniform_sales := v_day_uniform_sales + v_sales_today;
                
                UPDATE public.club_uniform_launches 
                SET total_sales_cents = total_sales_cents + v_sales_today 
                WHERE id = v_uniform.id;
            END;
        END LOOP;
        -- Accumulate totals
        v_total_fans := v_total_fans + v_day_fans;
        v_total_cash := v_total_cash + v_day_cash + (v_day_uniform_sales / 100);
        
        -- Update club for current day iter so next iteration has updated fans/rep
        UPDATE public.clubs 
        SET fans = fans + v_day_fans, budget = budget + v_day_cash + (v_day_uniform_sales / 100), updated_at = v_now
        WHERE id = v_club_id;
    END LOOP;
    -- Update last process time
    UPDATE public.profiles 
    SET last_daily_shop_bonus_at = v_now 
    WHERE user_id = p_user_id;
    -- News generation for high total sales
    IF v_total_cash > 100000 THEN
        INSERT INTO public.newspaper_entries (user_id, text, category, importance)
        VALUES (p_user_id, format('📈 O %s registrou receitas recordes de merchandising e marketing nos últimos dias!', v_club_name), 'finance', 1);
    END IF;
    -- Final Notification
    IF v_days_to_process > 1 THEN
        INSERT INTO user_notifications (user_id, type, title, message, importance)
        VALUES (
            p_user_id, 'daily_catchup', '📅 Resumo de sua Ausência', 
            format('Enquanto você estava fora (%s dias), seu clube arrecadou R$ %s e conquistou %s novos torcedores.', 
                v_days_to_process, v_total_cash, v_total_fans),
            1
        );
    END IF;
    RETURN jsonb_build_object(
        'success', true, 
        'days_processed', v_days_to_process,
        'total_fans_added', v_total_fans, 
        'total_cash_added', v_total_cash
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_daily_shop_bonuses(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_club_id UUID;
    v_club_name TEXT;
    v_last_process TIMESTAMP WITH TIME ZONE;
    v_now TIMESTAMP WITH TIME ZONE := now();
    v_days_to_process INTEGER;
    v_current_day_iter DATE;
    
    v_total_fans INTEGER := 0;
    v_total_cash BIGINT := 0;
    v_total_uniform_sales BIGINT := 0;
    v_total_shop_profit BIGINT := 0;
    
    v_day_fans INTEGER;
    v_day_cash BIGINT;
    v_day_uniform_sales BIGINT;
    v_day_shop_profit BIGINT := 0;
    
    v_effect RECORD;
    v_sponsor RECORD;
    v_uniform RECORD;
    v_members RECORD;
    v_shop_stats RECORD;
BEGIN
    -- Get user club
    SELECT id, name INTO v_club_id, v_club_name
    FROM public.clubs WHERE user_id = p_user_id ORDER BY updated_at DESC LIMIT 1;
    
    IF v_club_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Club not found');
    END IF;
    -- Get last process time
    SELECT last_daily_shop_bonus_at INTO v_last_process FROM public.profiles WHERE user_id = p_user_id;
    -- If never processed, start from yesterday
    IF v_last_process IS NULL THEN
        UPDATE public.profiles SET last_daily_shop_bonus_at = v_now WHERE user_id = p_user_id;
        RETURN jsonb_build_object('success', true, 'message', 'First time initialization complete');
    END IF;
    -- Calculate days passed (date difference)
    v_days_to_process := v_now::date - v_last_process::date;
    IF v_days_to_process < 1 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Already processed today');
    END IF;
    -- Limit catch up to 30 days
    IF v_days_to_process > 30 THEN
        v_days_to_process := 30;
    END IF;
    -- Loop through each day since last process
    FOR i IN 1..v_days_to_process LOOP
        v_current_day_iter := (v_last_process + (i * interval '1 day'))::date;
        v_day_fans := 0;
        v_day_cash := 0;
        v_day_uniform_sales := 0;
        v_day_shop_profit := 0;
        -- 1. Active Effects (Marketing)
        FOR v_effect IN 
            SELECT * FROM public.club_active_effects 
            WHERE club_id = v_club_id AND (expires_at IS NULL OR expires_at::date >= v_current_day_iter)
        LOOP
            IF v_effect.category = 'marketing' THEN
                v_day_fans := v_day_fans + COALESCE((v_effect.bonus_data->>'torcidaPorDia')::int, 0);
                v_day_cash := v_day_cash + COALESCE((v_effect.bonus_data->>'daily_cash')::bigint, (v_effect.bonus_data->>'dinheiroDia')::bigint, 0);
            END IF;
        END LOOP;
        -- 2. Sponsorships
        FOR v_sponsor IN 
            SELECT * FROM public.club_sponsorships 
            WHERE club_id = v_club_id AND is_active = true AND (expires_at IS NULL OR expires_at::date >= v_current_day_iter)
        LOOP
            v_day_cash := v_day_cash + (v_sponsor.contract_value_cents / 700.0)::bigint;
            v_day_cash := v_day_cash + COALESCE((v_sponsor.bonus_data->>'daily_cash')::bigint, 0);
        END LOOP;
        -- 3. Membership
        SELECT * INTO v_members FROM public.club_memberships WHERE club_id = v_club_id;
        IF v_members IS NOT NULL THEN
            v_day_cash := v_day_cash + (v_members.monthly_revenue_cents / 3000.0)::bigint;
        END IF;
        -- 4. Club Shop Daily Processing (Logic from process_club_shop_daily integrated)
        SELECT * INTO v_shop_stats FROM public.club_shop_stats WHERE club_id = v_club_id;
        IF v_shop_stats IS NOT NULL THEN
            DECLARE
                v_fans_now INTEGER;
                v_rep_now INTEGER;
                v_buyers INTEGER;
                v_daily_rev BIGINT;
                v_profit BIGINT;
            BEGIN
                SELECT fans, reputation INTO v_fans_now, v_rep_now FROM public.clubs WHERE id = v_club_id;
                -- 2% base conversion + level and reputation bonuses
                v_buyers := floor(v_fans_now * (0.02 + (v_shop_stats.level * 0.005) + (v_rep_now * 0.0001)) * v_shop_stats.popularity);
                IF v_fans_now > 0 AND v_buyers < 1 THEN v_buyers := 1; END IF;
                
                v_daily_rev := v_buyers * 4500; -- R$ 45,00 avg
                v_profit := floor(v_daily_rev * 0.4); -- 40% margin
                
                v_day_shop_profit := v_profit;
                
                -- Update shop stats table
                UPDATE public.club_shop_stats SET
                    daily_revenue = v_daily_rev,
                    total_revenue = total_revenue + v_daily_rev,
                    total_profit = total_profit + v_profit,
                    total_sales = total_sales + v_buyers,
                    buying_fans = v_buyers,
                    weekly_revenue = weekly_revenue + v_daily_rev,
                    monthly_revenue = monthly_revenue + v_daily_rev,
                    last_update = v_now,
                    updated_at = v_now
                WHERE id = v_shop_stats.id;
            END;
        END IF;
        -- 5. Uniform Sales
        FOR v_uniform IN 
            SELECT * FROM public.club_uniform_launches 
            WHERE club_id = v_club_id AND is_active = true AND launched_at::date <= v_current_day_iter
        LOOP
            DECLARE
                v_days_since_launch INTEGER;
                v_decay_factor DOUBLE PRECISION;
                v_sales_today BIGINT;
                v_fans_now INTEGER;
                v_rep_now INTEGER;
            BEGIN
                v_days_since_launch := v_current_day_iter - v_uniform.launched_at::date;
                IF v_days_since_launch <= 15 THEN v_decay_factor := 1.0;
                ELSE v_decay_factor := exp(-0.05 * (v_days_since_launch - 15)); END IF;
                SELECT fans, reputation INTO v_fans_now, v_rep_now FROM public.clubs WHERE id = v_club_id;
                v_sales_today := (v_fans_now * (v_rep_now / 100.0) * (v_uniform.hype_score / 100.0) * v_decay_factor * 10)::bigint;
                v_day_uniform_sales := v_day_uniform_sales + v_sales_today;
                
                UPDATE public.club_uniform_launches SET total_sales_cents = total_sales_cents + v_sales_today WHERE id = v_uniform.id;
            END;
        END LOOP;
        -- Accumulate totals
        v_total_fans := v_total_fans + v_day_fans;
        v_total_cash := v_total_cash + v_day_cash + (v_day_uniform_sales / 100) + v_day_shop_profit;
        v_total_shop_profit := v_total_shop_profit + v_day_shop_profit;
        
        -- Update club
        UPDATE public.clubs 
        SET fans = fans + v_day_fans, budget = budget + v_day_cash + (v_day_uniform_sales / 100) + v_day_shop_profit, updated_at = v_now
        WHERE id = v_club_id;
    END LOOP;
    -- Update last process time
    UPDATE public.profiles SET last_daily_shop_bonus_at = v_now WHERE user_id = p_user_id;
    -- News and Notifications
    IF v_total_cash > 100000 THEN
        INSERT INTO public.newspaper_entries (user_id, text, category, importance)
        VALUES (p_user_id, format('📈 O %s registrou receitas recordes de merchandising e marketing nos últimos dias!', v_club_name), 'finance', 1);
    END IF;
    IF v_days_to_process > 1 THEN
        INSERT INTO user_notifications (user_id, type, title, message, importance)
        VALUES (
            p_user_id, 'daily_catchup', '📅 Resumo de sua Ausência', 
            format('Enquanto você estava fora (%s dias), seu clube arrecadou R$ %s (incluindo R$ %s da loja oficial) e conquistou %s novos torcedores.', 
                v_days_to_process, v_total_cash, v_total_shop_profit, v_total_fans),
            1
        );
    END IF;
    RETURN jsonb_build_object(
        'success', true, 
        'days_processed', v_days_to_process,
        'total_fans_added', v_total_fans, 
        'total_cash_added', v_total_cash,
        'shop_profit', v_total_shop_profit
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_match_persistence(_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_match RECORD;
    v_home_team_id UUID;
    v_away_team_id UUID;
    v_home_goals INT;
    v_away_goals INT;
    v_league_id UUID;
    v_competition TEXT;
    v_home_win INT;
    v_away_win INT;
    v_draw INT;
BEGIN
    -- 1. Fetch match data with LOCK to prevent concurrent processing
    SELECT * INTO v_match FROM public.live_matches WHERE id = _match_id FOR UPDATE;
    
    IF v_match IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Match not found');
    END IF;
    IF v_match.status != 'finished' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Match not finished yet');
    END IF;
    -- CHECK FOR DUPLICATE SYNC
    IF EXISTS (SELECT 1 FROM public.match_reports WHERE match_id = _match_id) THEN
        RETURN jsonb_build_object('success', true, 'info', 'Already synced');
    END IF;
    v_home_team_id := v_match.home_team_id;
    v_away_team_id := v_match.away_team_id;
    v_home_goals := v_match.home_goals;
    v_away_goals := v_match.away_goals;
    v_league_id := v_match.league_id;
    v_competition := v_match.competition;
    v_home_win := CASE WHEN v_home_goals > v_away_goals THEN 1 ELSE 0 END;
    v_away_win := CASE WHEN v_away_goals > v_home_goals THEN 1 ELSE 0 END;
    v_draw := CASE WHEN v_home_goals = v_away_goals THEN 1 ELSE 0 END;
    -- 2. Update League Table
    IF v_league_id IS NOT NULL THEN
        -- Home Team
        UPDATE public.world_league_table 
        SET 
            played = played + 1,
            wins = wins + v_home_win,
            draws = draws + v_draw,
            losses = losses + (CASE WHEN v_home_goals < v_away_goals THEN 1 ELSE 0 END),
            goals_for = goals_for + v_home_goals,
            goals_against = goals_against + v_away_goals,
            points = points + (CASE WHEN v_home_win = 1 THEN 3 WHEN v_draw = 1 THEN 1 ELSE 0 END),
            updated_at = NOW()
        WHERE league_id = v_league_id AND team_id = v_home_team_id;
        -- Away Team
        UPDATE public.world_league_table 
        SET 
            played = played + 1,
            wins = wins + v_away_win,
            draws = draws + v_draw,
            losses = losses + (CASE WHEN v_away_goals < v_home_goals THEN 1 ELSE 0 END),
            goals_for = goals_for + v_away_goals,
            goals_against = goals_against + v_home_goals,
            points = points + (CASE WHEN v_away_win = 1 THEN 3 WHEN v_draw = 1 THEN 1 ELSE 0 END),
            updated_at = NOW()
        WHERE league_id = v_league_id AND team_id = v_away_team_id;
    END IF;
    -- 3. Update Global Club stats (using columns directly as 'stats' jsonb doesn't exist)
    -- We assume the 'clubs' table holds the aggregate historical performance.
    -- If these columns don't exist, this might fail, but based on common patterns in FLM:
    
    -- Note: Since the user specifically asked for "Pontos na Liga sicronize", 
    -- the primary goal is the world_league_table and visibility in the UI.
    -- 4. Save to Match History
    INSERT INTO public.match_reports (
        id, match_id, home_team_id, away_team_id, 
        home_goals, away_goals, 
        stats, events, attendance, stadium_name
    ) VALUES (
        gen_random_uuid(), _match_id, v_home_team_id, v_away_team_id,
        v_home_goals, v_away_goals,
        v_match.stats, v_match.events, v_match.attendance, v_match.stadium_name
    );
    RETURN jsonb_build_object(
        'success', true, 
        'match_id', _match_id,
        'home_team_id', v_home_team_id,
        'away_team_id', v_away_team_id,
        'home_goals', v_home_goals,
        'away_goals', v_away_goals,
        'competition', v_competition,
        'league_id', v_league_id
    );
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_daily_stamina_recovery()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path = public
AS $function$
DECLARE
    v_updated_count INTEGER;
BEGIN
    -- Update all players with less than 100 stamina
    UPDATE public.world_players
    SET 
        stamina = LEAST(100, COALESCE(stamina, 0) + 30),
        last_stamina_recovery = now()
    WHERE stamina < 100 OR stamina IS NULL;
    
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    -- Log the action for verification
    -- Check if admin_logs exists first, if not create a simple one or skip
    IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'admin_logs') THEN
        INSERT INTO public.admin_logs (action, details)
        VALUES ('daily_stamina_recovery', 'Recuperação de +30% aplicada a ' || v_updated_count || ' jogadores.');
    END IF;
    
    -- Also log to a system status table if it exists
    IF EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'system_status') THEN
        INSERT INTO public.system_status (key, value, last_updated)
        VALUES ('last_stamina_recovery_run', now()::text, now())
        ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, last_updated = EXCLUDED.last_updated;
    END IF;
END;
$function$;
SELECT cron.unschedule('daily-stamina-recovery') WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'daily-stamina-recovery');
SELECT cron.schedule('daily-stamina-recovery', '0 0 * * *', 'SELECT public.process_daily_stamina_recovery()');
GRANT EXECUTE ON FUNCTION public.process_daily_stamina_recovery() TO service_role;
GRANT EXECUTE ON FUNCTION public.process_daily_stamina_recovery() TO postgres;
CREATE TABLE IF NOT EXISTS public.scout_market_config (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    last_refresh TIMESTAMP WITH TIME ZONE DEFAULT now(),
    refresh_interval_days INTEGER DEFAULT 15
);
INSERT INTO public.scout_market_config (last_refresh)
SELECT now() WHERE NOT EXISTS (SELECT 1 FROM public.scout_market_config);
CREATE OR REPLACE FUNCTION public.refresh_scout_market()
RETURNS void AS $$
DECLARE
    v_last_refresh TIMESTAMP WITH TIME ZONE;
    v_interval INTEGER;
BEGIN
    SELECT last_refresh, refresh_interval_days INTO v_last_refresh, v_interval FROM public.scout_market_config LIMIT 1;
    
    -- If 15 days passed OR market is empty, refresh
    IF (v_last_refresh + (v_interval || ' days')::interval <= now()) OR (NOT EXISTS (SELECT 1 FROM public.scout_market_pool)) THEN
        -- Clear old market
        DELETE FROM public.scout_market_pool;
        
        -- Insert 2 random scouts
        -- Level is weighted or random. Let's pick random levels for "habilidade aleatória"
        INSERT INTO public.scout_market_pool (
            id, name, country, level, specialization, 
            potential_evaluation, technical_evaluation, analysis_speed, 
            youth_discovery, reputation, salary, preferred_region, 
            efficiency, expires_at
        )
        SELECT 
            gen_random_uuid(),
            'Olheiro ' || chr(65 + (random() * 25)::int) || chr(97 + (random() * 25)::int),
            CASE (random() * 5)::int 
                WHEN 0 THEN 'Brasil' 
                WHEN 1 THEN 'Argentina' 
                WHEN 2 THEN 'Espanha' 
                WHEN 3 THEN 'Inglaterra' 
                WHEN 4 THEN 'Itália' 
                ELSE 'Alemanha' 
            END,
            (ARRAY['Amador', 'Regional', 'Nacional', 'Internacional', 'Elite Mundial'])[floor(random() * 5 + 1)],
            (ARRAY['ataque', 'defesa', 'meio', 'jovens', 'geral'])[floor(random() * 5 + 1)],
            (random() * 100)::int,
            (random() * 100)::int,
            (random() * 100)::int,
            (random() * 100)::int,
            (random() * 100)::int,
            (random() * 10000 + 1000)::int,
            (ARRAY['Brasil', 'América do Sul', 'Europa', 'África', 'Ásia', 'América do Norte'])[floor(random() * 6 + 1)],
            random(),
            now() + interval '15 days'
        FROM generate_series(1, 2);
        
        -- Update last refresh timestamp
        UPDATE public.scout_market_config SET last_refresh = now();
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.get_scout_market()
RETURNS SETOF public.scout_market_pool AS $$
BEGIN
    PERFORM public.refresh_scout_market();
    RETURN QUERY SELECT * FROM public.scout_market_pool;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
