CREATE OR REPLACE FUNCTION public.process_monthly_membership_revenue()
RETURNS void AS $$
DECLARE
    club_record RECORD;
    plan_record RECORD;
    total_revenue DECIMAL(15,2);
    total_members INTEGER;
    current_month_start DATE := date_trunc('month', now())::DATE;
BEGIN
    FOR club_record IN SELECT id, budget FROM public.clubs LOOP
        total_revenue := 0;
        total_members := 0;
        
        -- Verificar se já foi processado este mês
        IF EXISTS (SELECT 1 FROM public.membership_revenue_history WHERE club_id = club_record.id AND month_year = current_month_start) THEN
            CONTINUE;
        END IF;
        -- Calcular receita baseada nos sócios atuais (ajustado para a estrutura detectada)
        -- Assumimos agora que club_memberships tem club_id, plan_id e member_count
        FOR plan_record IN 
            SELECT cm.member_count, mp.monthly_price, mp.bonus_multiplier 
            FROM public.club_memberships cm
            JOIN public.membership_plans mp ON cm.plan_id = mp.id
            WHERE cm.club_id = club_record.id
        LOOP
            total_revenue := total_revenue + (plan_record.member_count * plan_record.monthly_price * plan_record.bonus_multiplier);
            total_members := total_members + COALESCE(plan_record.member_count, 0);
        END LOOP;
        IF total_revenue > 0 THEN
            -- Atualizar orçamento do clube
            UPDATE public.clubs SET budget = budget + total_revenue WHERE id = club_record.id;
            
            -- Registrar histórico
            INSERT INTO public.membership_revenue_history (club_id, amount, member_total, month_year)
            VALUES (club_record.id, total_revenue, total_members, current_month_start);
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
CREATE OR REPLACE FUNCTION public.sync_match_to_history()
RETURNS TRIGGER AS $$
DECLARE
    v_user_id UUID;
    v_club_name TEXT;
    v_competition TEXT;
    v_is_home BOOLEAN;
    v_stadium TEXT;
    v_home_club_name TEXT;
    v_away_club_name TEXT;
BEGIN
    -- Só processa se o status mudou para 'finished'
    IF NEW.status = 'finished' AND OLD.status != 'finished' THEN
        
        -- Busca informações do time da casa
        SELECT user_id, name INTO v_user_id, v_home_club_name 
        FROM public.world_teams WHERE id = NEW.home_team_id;
        
        -- Busca informações do time de fora
        SELECT name INTO v_away_club_name 
        FROM public.world_teams WHERE id = NEW.away_team_id;
        -- Identifica se o usuário é o dono de algum dos times
        -- (No caso de multiplayer, pode haver dois usuários, mas o histórico é individual)
        
        -- Caso o mandante seja o usuário
        IF v_user_id IS NOT NULL THEN
            INSERT INTO public.match_history (
                user_id, match_type, competition, home_team, away_team, 
                home_goals, away_goals, is_home, stadium_name, played_at
            ) VALUES (
                v_user_id, 'league', 'Liga', v_home_club_name, v_away_club_name,
                NEW.home_goals, NEW.away_goals, TRUE, NEW.stadium, NOW()
            );
        END IF;
        -- Busca informações do time de fora para ver se é outro usuário
        SELECT user_id INTO v_user_id FROM public.world_teams WHERE id = NEW.away_team_id;
        
        IF v_user_id IS NOT NULL THEN
            INSERT INTO public.match_history (
                user_id, match_type, competition, home_team, away_team, 
                home_goals, away_goals, is_home, stadium_name, played_at
            ) VALUES (
                v_user_id, 'league', 'Liga', v_home_club_name, v_away_club_name,
                NEW.home_goals, NEW.away_goals, FALSE, NEW.stadium, NOW()
            );
        END IF;
        -- Atualiza a tabela da liga automaticamente para ambos os times
        -- Mandante
        UPDATE public.world_league_table 
        SET played = played + 1,
            wins = wins + CASE WHEN NEW.home_goals > NEW.away_goals THEN 1 ELSE 0 END,
            draws = draws + CASE WHEN NEW.home_goals = NEW.away_goals THEN 1 ELSE 0 END,
            losses = losses + CASE WHEN NEW.home_goals < NEW.away_goals THEN 1 ELSE 0 END,
            goals_for = goals_for + NEW.home_goals,
            goals_against = goals_against + NEW.away_goals,
            points = points + CASE WHEN NEW.home_goals > NEW.away_goals THEN 3 
                                   WHEN NEW.home_goals = NEW.away_goals THEN 1 ELSE 0 END
        WHERE team_id = NEW.home_team_id;
        -- Visitante
        UPDATE public.world_league_table 
        SET played = played + 1,
            wins = wins + CASE WHEN NEW.away_goals > NEW.home_goals THEN 1 ELSE 0 END,
            draws = draws + CASE WHEN NEW.away_goals = NEW.home_goals THEN 1 ELSE 0 END,
            losses = losses + CASE WHEN NEW.away_goals < NEW.home_goals THEN 1 ELSE 0 END,
            goals_for = goals_for + NEW.away_goals,
            goals_against = goals_against + NEW.home_goals,
            points = points + CASE WHEN NEW.away_goals > NEW.home_goals THEN 3 
                                   WHEN NEW.away_goals = NEW.home_goals THEN 1 ELSE 0 END
        WHERE team_id = NEW.away_team_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
DROP TRIGGER IF EXISTS tr_sync_match_history ON public.world_matches;
CREATE TRIGGER tr_sync_match_history
AFTER UPDATE ON public.world_matches
FOR EACH ROW EXECUTE FUNCTION public.sync_match_to_history();
ALTER TABLE public.league_matches ADD COLUMN IF NOT EXISTS synced BOOLEAN DEFAULT false;
DROP FUNCTION IF EXISTS public.sync_league_integrity(uuid);
CREATE OR REPLACE FUNCTION public.finalize_league_match(
    _match_id UUID,
    _home_goals INT,
    _away_goals INT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_match RECORD;
    v_home_id UUID;
    v_away_id UUID;
    v_league_id UUID;
BEGIN
    -- Select match with lock
    SELECT * INTO v_match FROM public.league_matches WHERE id = _match_id FOR UPDATE;
    
    IF v_match IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Match not found');
    END IF;
    IF v_match.status = 'finished' AND v_match.synced = true THEN
        RETURN jsonb_build_object('success', true, 'info', 'Already finalized');
    END IF;
    v_home_id := v_match.home_user_id;
    v_away_id := v_match.away_user_id;
    v_league_id := v_match.league_id;
    -- Update match status
    UPDATE public.league_matches 
    SET 
        status = 'finished',
        home_goals = _home_goals,
        away_goals = _away_goals,
        played_at = NOW(),
        synced = true
    WHERE id = _match_id;
    -- Atomic Table Update for Home Team
    UPDATE public.league_standings 
    SET 
        played = played + 1,
        wins = wins + (CASE WHEN _home_goals > _away_goals THEN 1 ELSE 0 END),
        draws = draws + (CASE WHEN _home_goals = _away_goals THEN 1 ELSE 0 END),
        losses = losses + (CASE WHEN _home_goals < _away_goals THEN 1 ELSE 0 END),
        goals_for = goals_for + _home_goals,
        goals_against = goals_against + _away_goals,
        goals_diff = (goals_for + _home_goals) - (goals_against + _away_goals),
        points = points + (CASE WHEN _home_goals > _away_goals THEN 3 WHEN _home_goals = _away_goals THEN 1 ELSE 0 END)
    WHERE league_id = v_league_id AND user_id = v_home_id;
    -- Atomic Table Update for Away Team
    UPDATE public.league_standings 
    SET 
        played = played + 1,
        wins = wins + (CASE WHEN _away_goals > _home_goals THEN 1 ELSE 0 END),
        draws = draws + (CASE WHEN _home_goals = _away_goals THEN 1 ELSE 0 END),
        losses = losses + (CASE WHEN _away_goals < _home_goals THEN 1 ELSE 0 END),
        goals_for = goals_for + _away_goals,
        goals_against = goals_against + _home_goals,
        goals_diff = (goals_for + _away_goals) - (goals_against + _home_goals),
        points = points + (CASE WHEN _away_goals > _home_goals THEN 3 WHEN _home_goals = _away_goals THEN 1 ELSE 0 END)
    WHERE league_id = v_league_id AND user_id = v_away_id;
    -- Log synchronization if table exists
    BEGIN
        INSERT INTO public.match_sync_log (match_id, status, details)
        VALUES (_match_id, 'success', jsonb_build_object('home', _home_goals, 'away', _away_goals));
    EXCEPTION WHEN OTHERS THEN
        -- Table might not exist, ignore
    END;
    RETURN jsonb_build_object('success', true);
END;
$$;
CREATE OR REPLACE FUNCTION public.sync_league_integrity(_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_league_id UUID;
BEGIN
    -- Find which league the user is in
    SELECT league_id INTO v_league_id FROM public.league_members WHERE user_id = _user_id LIMIT 1;
    
    IF v_league_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'No league found for user');
    END IF;
    -- Reset all stats for this league to 0
    UPDATE public.league_standings 
    SET 
        played = 0, wins = 0, draws = 0, losses = 0,
        goals_for = 0, goals_against = 0, goals_diff = 0, points = 0
    WHERE league_id = v_league_id;
    -- Recalculate based on finished matches
    WITH match_stats AS (
        SELECT 
            league_id, 
            home_user_id as user_id,
            COUNT(*) as p,
            SUM(CASE WHEN home_goals > away_goals THEN 1 ELSE 0 END) as w,
            SUM(CASE WHEN home_goals = away_goals THEN 1 ELSE 0 END) as d,
            SUM(CASE WHEN home_goals < away_goals THEN 1 ELSE 0 END) as l,
            SUM(home_goals) as gf,
            SUM(away_goals) as ga
        FROM public.league_matches 
        WHERE league_id = v_league_id AND status = 'finished'
        GROUP BY league_id, home_user_id
        
        UNION ALL
        
        SELECT 
            league_id, 
            away_user_id as user_id,
            COUNT(*) as p,
            SUM(CASE WHEN away_goals > home_goals THEN 1 ELSE 0 END) as w,
            SUM(CASE WHEN home_goals = away_goals THEN 1 ELSE 0 END) as d,
            SUM(CASE WHEN away_goals < home_goals THEN 1 ELSE 0 END) as l,
            SUM(away_goals) as gf,
            SUM(home_goals) as ga
        FROM public.league_matches 
        WHERE league_id = v_league_id AND status = 'finished'
        GROUP BY league_id, away_user_id
    ),
    aggregated AS (
        SELECT 
            user_id,
            SUM(p) as played,
            SUM(w) as wins,
            SUM(d) as draws,
            SUM(l) as losses,
            SUM(gf) as goals_for,
            SUM(ga) as goals_against
        FROM match_stats
        GROUP BY user_id
    )
    UPDATE public.league_standings ls
    SET 
        played = a.played,
        wins = a.wins,
        draws = a.draws,
        losses = a.losses,
        goals_for = a.goals_for,
        goals_against = a.goals_against,
        goals_diff = a.goals_for - a.goals_against,
        points = (a.wins * 3) + a.draws
    FROM aggregated a
    WHERE ls.league_id = v_league_id AND ls.user_id = a.user_id;
    RETURN jsonb_build_object('success', true, 'league_id', v_league_id);
END;
$$;
CREATE OR REPLACE FUNCTION public.auto_simulate_expired_matches()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_match RECORD;
    v_count INT := 0;
    v_home_strength INT;
    v_away_strength INT;
    v_home_goals INT;
    v_away_goals INT;
BEGIN
    FOR v_match IN 
        SELECT lm.* 
        FROM public.league_matches lm
        WHERE lm.status != 'finished'
        AND lm.scheduled_at < (NOW() - INTERVAL '5 minutes')
        AND (lm.home_joined = false OR lm.away_joined = false)
        LIMIT 50
    LOOP
        v_home_strength := 60 + floor(random() * 20);
        v_away_strength := 60 + floor(random() * 20);
        v_home_goals := floor(random() * 2.5);
        v_away_goals := floor(random() * 2.5);
        PERFORM public.finalize_league_match(v_match.id, v_home_goals, v_away_goals);
        v_count := v_count + 1;
    END LOOP;
    RETURN jsonb_build_object('simulated_count', v_count);
END;
$$;
CREATE OR REPLACE FUNCTION public.update_player_after_match(
    _player_id UUID,
    _rating NUMERIC,
    _goals INTEGER,
    _assists INTEGER,
    _clean_sheet BOOLEAN,
    _competition TEXT
) RETURNS JSONB AS $$
DECLARE
    p_morale INTEGER;
    p_reputation NUMERIC;
    p_market_value BIGINT;
    p_season_ratings NUMERIC[];
    morale_delta INTEGER;
    rep_delta NUMERIC;
    value_mult NUMERIC;
BEGIN
    -- 1. Fetch current player data
    SELECT morale, reputation, market_value, season_ratings 
    INTO p_morale, p_reputation, p_market_value, p_season_ratings
    FROM public.players 
    WHERE id = _player_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Player not found');
    END IF;
    -- 2. Calculate deltas based on rating
    -- Morale
    IF _rating >= 7.5 THEN morale_delta := 5;
    ELSIF _rating <= 5.0 THEN morale_delta := -5;
    ELSE morale_delta := 0;
    END IF;
    -- Reputation
    IF _rating >= 8.5 THEN rep_delta := 0.5;
    ELSIF _rating <= 4.0 THEN rep_delta := -0.3;
    ELSE rep_delta := 0;
    END IF;
    -- Market Value
    IF _rating >= 9.0 THEN value_mult := 1.02;
    ELSIF _rating >= 8.0 THEN value_mult := 1.01;
    ELSIF _rating <= 4.0 THEN value_mult := 0.98;
    ELSE value_mult := 1.0;
    END IF;
    -- 3. Apply updates
    UPDATE public.players 
    SET 
        morale = GREATEST(0, LEAST(100, COALESCE(morale, 70) + morale_delta)),
        reputation = GREATEST(0, LEAST(100, COALESCE(reputation, 50) + rep_delta)),
        market_value = ROUND(COALESCE(market_value, 100000) * value_mult),
        season_ratings = array_append(COALESCE(season_ratings, '{}'), _rating),
        goals = COALESCE(goals, 0) + _goals,
        assists = COALESCE(assists, 0) + _assists,
        games_played = COALESCE(games_played, 0) + 1
    WHERE id = _player_id;
    RETURN jsonb_build_object('success', true);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;
