CREATE OR REPLACE FUNCTION public.activate_uniform_on_payment()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NEW.status = 'approved'
       AND COALESCE(NEW.metadata->>'item_type', '') = 'uniform_launch'
       AND COALESCE(NEW.metadata->>'uniform_id', '') <> '' THEN
        UPDATE public.club_uniform_launches
        SET
            status = 'approved',
            launched_at = COALESCE(launched_at, now()),
            payment_order_id = NEW.id,
            hype_score = GREATEST(COALESCE(hype_score, 0), 100),
            last_sales_update_at = COALESCE(last_sales_update_at, now())
        WHERE id = (NEW.metadata->>'uniform_id')::uuid;
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS on_payment_approved_activate_kit ON public.payment_orders;
CREATE TRIGGER on_payment_approved_activate_kit
AFTER UPDATE ON public.payment_orders
FOR EACH ROW
WHEN (OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'approved')
EXECUTE FUNCTION public.activate_uniform_on_payment();
CREATE OR REPLACE FUNCTION public.deliver_shop_item(p_order_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_order RECORD;
    v_item RECORD;
    v_club_id UUID;
    v_user_id UUID;
    v_uniform_id UUID;
    v_immediate_fans INTEGER := 0;
    v_immediate_members INTEGER := 0;
    v_immediate_cash BIGINT := 0;
    v_monthly_revenue BIGINT := 0;
    v_duration_days INTEGER := 30;
BEGIN
    SELECT * INTO v_order FROM public.payment_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pedido não encontrado');
    END IF;
    IF COALESCE(v_order.delivered, false) THEN
        RETURN jsonb_build_object('success', true, 'message', 'Pedido já entregue', 'already_delivered', true);
    END IF;
    v_user_id := v_order.user_id;
    SELECT * INTO v_item FROM public.shop_items WHERE id = v_order.item_id;
    SELECT id INTO v_club_id
    FROM public.clubs
    WHERE user_id = v_user_id
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
    IF v_club_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Clube não encontrado para o usuário');
    END IF;
    IF COALESCE(v_order.metadata->>'item_type', '') = 'uniform_launch' THEN
        v_uniform_id := NULLIF(v_order.metadata->>'uniform_id', '')::uuid;
        IF v_uniform_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'Lançamento de uniforme não identificado');
        END IF;
        UPDATE public.club_uniform_launches
        SET
            status = 'approved',
            launched_at = COALESCE(launched_at, now()),
            payment_order_id = v_order.id,
            hype_score = GREATEST(COALESCE(hype_score, 0), 100),
            last_sales_update_at = COALESCE(last_sales_update_at, now())
        WHERE id = v_uniform_id
          AND club_id = v_club_id;
        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'Lançamento de uniforme não encontrado para este clube');
        END IF;
        UPDATE public.clubs
        SET current_uniform_launch_id = v_uniform_id,
            updated_at = now()
        WHERE id = v_club_id;
        UPDATE public.payment_orders
        SET delivered = true,
            status = 'approved',
            updated_at = now()
        WHERE id = p_order_id;
        INSERT INTO public.admin_shop_activity (
            user_id, item_id, item_name, amount_cents, status, payment_method, transaction_id, metadata
        ) VALUES (
            v_user_id,
            v_order.item_id,
            COALESCE(v_order.metadata->>'item_name', 'Lançamento de Uniforme'),
            v_order.amount_cents,
            'delivered',
            COALESCE(v_order.payment_method, v_order.metadata->>'checkout_type', 'pix'),
            v_order.payment_id,
            v_order.metadata
        );
        INSERT INTO public.user_notifications (user_id, type, category, priority, title, message, icon, data)
        VALUES (
            v_user_id,
            'success',
            'Marketing',
            'high',
            'Uniforme Lançado!',
            'Seu novo uniforme foi lançado oficialmente e já está conectado à Loja FLM.',
            '👕',
            jsonb_build_object('order_id', p_order_id, 'uniform_id', v_uniform_id, 'delivered', true)
        );
        RETURN jsonb_build_object(
            'success', true,
            'category', 'uniform',
            'uniform_id', v_uniform_id,
            'message', 'Uniforme lançado com sucesso'
        );
    END IF;
    v_immediate_fans := COALESCE((v_order.metadata->'bonus_data'->>'immediate_fans')::INTEGER, (v_order.metadata->'bonus_data'->>'initialFans')::INTEGER, 0);
    v_immediate_members := COALESCE((v_order.metadata->'bonus_data'->>'immediate_members')::INTEGER, (v_order.metadata->'bonus_data'->>'initialMembers')::INTEGER, 0);
    v_immediate_cash := COALESCE((v_order.metadata->'bonus_data'->>'immediate_cash')::BIGINT, 0);
    v_monthly_revenue := COALESCE((v_order.metadata->'bonus_data'->>'monthlyRevenue')::BIGINT, (v_order.metadata->'bonus_data'->>'monthly_revenue')::BIGINT, 0);
    IF v_item IS NOT NULL THEN
        v_immediate_fans := COALESCE(NULLIF(v_immediate_fans, 0), (v_item.bonus_data->>'immediate_fans')::INTEGER, (v_item.bonus_data->>'initialFans')::INTEGER, 0);
        v_immediate_members := COALESCE(NULLIF(v_immediate_members, 0), (v_item.bonus_data->>'immediate_members')::INTEGER, (v_item.bonus_data->>'initialMembers')::INTEGER, 0);
        v_immediate_cash := COALESCE(NULLIF(v_immediate_cash, 0), (v_item.bonus_data->>'immediate_cash')::BIGINT, 0);
        v_monthly_revenue := COALESCE(NULLIF(v_monthly_revenue, 0), (v_item.bonus_data->>'monthlyRevenue')::BIGINT, (v_item.bonus_data->>'monthly_revenue')::BIGINT, 0);
        v_duration_days := COALESCE(v_item.duration_days, 30);
    END IF;
    UPDATE public.clubs
    SET fans = COALESCE(fans, 0) + v_immediate_fans,
        total_members = COALESCE(total_members, 0) + v_immediate_members,
        budget = COALESCE(budget, 0) + v_immediate_cash,
        updated_at = now()
    WHERE id = v_club_id;
    IF (v_item.category = 'members') OR ((v_order.metadata->>'category') = 'members') THEN
        INSERT INTO public.club_memberships (club_id, total_members, monthly_revenue_cents, updated_at)
        VALUES (v_club_id, v_immediate_members, v_monthly_revenue * 100, now())
        ON CONFLICT (club_id) DO UPDATE
        SET total_members = COALESCE(public.club_memberships.total_members, 0) + EXCLUDED.total_members,
            monthly_revenue_cents = COALESCE(public.club_memberships.monthly_revenue_cents, 0) + EXCLUDED.monthly_revenue_cents,
            updated_at = now();
    END IF;
    IF (v_item.category = 'sponsorship') OR ((v_order.metadata->>'category') = 'sponsorship') THEN
        INSERT INTO public.club_sponsorships (
            club_id, sponsor_name, contract_value_cents, started_at, expires_at, is_active, bonus_data
        ) VALUES (
            v_club_id,
            COALESCE(v_item.name, v_order.metadata->>'item_name'),
            COALESCE((v_item.bonus_data->>'dinheiroSemanal')::BIGINT, 0) * 100,
            now(),
            now() + (v_duration_days * interval '1 day'),
            true,
            COALESCE(v_item.bonus_data, v_order.metadata->'bonus_data')
        );
    END IF;
    IF COALESCE(v_item.category, v_order.metadata->>'category') IN ('marketing', 'scouting', 'fans') THEN
        INSERT INTO public.club_active_effects (
            club_id, item_id, category, bonus_data, started_at, expires_at, created_at
        ) VALUES (
            v_club_id,
            v_order.item_id,
            COALESCE(v_item.category, v_order.metadata->>'category'),
            COALESCE(v_item.bonus_data, v_order.metadata->'bonus_data'),
            now(),
            now() + (v_duration_days * interval '1 day'),
            now()
        );
    END IF;
    UPDATE public.payment_orders
    SET delivered = true,
        updated_at = now()
    WHERE id = p_order_id;
    INSERT INTO public.admin_shop_activity (
        user_id, item_id, item_name, amount_cents, status, payment_method, transaction_id, metadata
    ) VALUES (
        v_user_id,
        v_order.item_id,
        COALESCE(v_order.metadata->>'item_name', v_item.name),
        v_order.amount_cents,
        'delivered',
        COALESCE(v_order.payment_method, v_order.metadata->>'checkout_type', 'unknown'),
        v_order.payment_id,
        v_order.metadata
    );
    INSERT INTO public.user_notifications (user_id, type, title, message, importance)
    VALUES (
        v_user_id,
        'purchase_delivery',
        '✅ Produto Entregue!',
        format('Seu item "%s" foi ativado. %s %s',
            COALESCE(v_item.name, v_order.metadata->>'item_name'),
            CASE WHEN v_immediate_fans > 0 THEN format('+%s torcedores. ', v_immediate_fans) ELSE '' END,
            CASE WHEN v_immediate_members > 0 THEN format('+%s sócios. ', v_immediate_members) ELSE '' END
        ),
        2
    );
    RETURN jsonb_build_object(
        'success', true,
        'fans_added', v_immediate_fans,
        'members_added', v_immediate_members,
        'cash_added', v_immediate_cash,
        'category', COALESCE(v_item.category, v_order.metadata->>'category')
    );
END;
$$;
CREATE POLICY "Users can insert their own club shop stats"
ON public.club_shop_stats
FOR INSERT
TO authenticated
WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.clubs
    WHERE clubs.id = club_shop_stats.club_id
      AND clubs.user_id = auth.uid()
  )
);
CREATE POLICY "Users can delete their own club shop stats"
ON public.club_shop_stats
FOR DELETE
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.clubs
    WHERE clubs.id = club_shop_stats.club_id
      AND clubs.user_id = auth.uid()
  )
);
CREATE OR REPLACE FUNCTION public.publish_uniform_launch_news()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id uuid;
  v_club_name text;
  v_manager text;
  v_headline text;
  v_variant int;
  v_already_exists boolean;
BEGIN
  -- Só agir em transições para approved/active/official
  IF NEW.status NOT IN ('approved', 'active', 'official') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;
  -- Resolver clube e dono
  SELECT c.user_id, c.name INTO v_user_id, v_club_name
  FROM public.clubs c
  WHERE c.id = NEW.club_id
  LIMIT 1;
  IF v_user_id IS NULL THEN
    RAISE LOG '[publish_uniform_launch_news] club % sem user_id', NEW.club_id;
    RETURN NEW;
  END IF;
  -- Proteção contra duplicidade
  SELECT EXISTS (
    SELECT 1 FROM public.newspaper_entries
    WHERE template_key = 'kit_launch'
      AND (metadata->>'launchId') = NEW.id::text
  ) INTO v_already_exists;
  IF v_already_exists THEN
    RAISE LOG '[publish_uniform_launch_news] notícia já existe para launch %', NEW.id;
    RETURN NEW;
  END IF;
  -- Nome do manager (opcional)
  SELECT display_name INTO v_manager
  FROM public.profiles
  WHERE user_id = v_user_id
  LIMIT 1;
  v_manager := COALESCE(v_manager, 'do clube');
  -- Manchete aleatória (6 variações)
  v_variant := 1 + floor(random() * 6)::int;
  v_headline := CASE v_variant
    WHEN 1 THEN '👕 O ' || v_club_name || ' apresenta seu novo uniforme para a temporada!'
    WHEN 2 THEN '✨ Nova camisa do ' || v_club_name || ' é revelada oficialmente.'
    WHEN 3 THEN '🔥 Torcida reage ao novo manto lançado pelo ' || v_club_name || '.'
    WHEN 4 THEN '📣 ' || v_club_name || ' lança coleção inédita e movimenta o mercado.'
    WHEN 5 THEN '🏆 O Manager ' || v_manager || ' apresenta o novo uniforme do ' || v_club_name || '.'
    ELSE '👀 Confira o novo uniforme oficial do ' || v_club_name || ' — já disponível na loja!'
  END;
  INSERT INTO public.newspaper_entries (
    user_id, text, category, importance, template_key, metadata
  ) VALUES (
    v_user_id,
    v_headline,
    'ELENCO',
    3,
    'kit_launch',
    jsonb_build_object(
      'launchId', NEW.id,
      'clubName', v_club_name,
      'managerName', v_manager,
      'kit', NEW.config,
      'launchName', NEW.name
    )
  );
  RAISE LOG '[publish_uniform_launch_news] notícia publicada para launch % (clube %)', NEW.id, v_club_name;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE LOG '[publish_uniform_launch_news] erro: %', SQLERRM;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_publish_uniform_launch_news ON public.club_uniform_launches;
CREATE TRIGGER trg_publish_uniform_launch_news
AFTER INSERT OR UPDATE OF status ON public.club_uniform_launches
FOR EACH ROW
EXECUTE FUNCTION public.publish_uniform_launch_news();
CREATE OR REPLACE FUNCTION public.sync_post_match_data()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
    -- Atualiza ranking global do usuário (best-effort, nunca bloqueia)
    BEGIN
        IF NEW.user_id IS NOT NULL THEN
            IF NEW.is_home THEN
                IF NEW.home_goals > NEW.away_goals THEN
                    UPDATE public.global_ranking
                       SET ranking_points = ranking_points + 10,
                           wins = COALESCE(wins,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                ELSIF NEW.home_goals < NEW.away_goals THEN
                    UPDATE public.global_ranking
                       SET losses = COALESCE(losses,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                ELSE
                    UPDATE public.global_ranking
                       SET ranking_points = ranking_points + 4,
                           draws = COALESCE(draws,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                END IF;
            ELSE
                IF NEW.away_goals > NEW.home_goals THEN
                    UPDATE public.global_ranking
                       SET ranking_points = ranking_points + 10,
                           wins = COALESCE(wins,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                ELSIF NEW.away_goals < NEW.home_goals THEN
                    UPDATE public.global_ranking
                       SET losses = COALESCE(losses,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                ELSE
                    UPDATE public.global_ranking
                       SET ranking_points = ranking_points + 4,
                           draws = COALESCE(draws,0) + 1,
                           games_played = COALESCE(games_played,0) + 1,
                           updated_at = now()
                     WHERE user_id = NEW.user_id;
                END IF;
            END IF;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        -- log silencioso, nunca bloqueia
        NULL;
    END;
    -- Bump sync version para forçar refresh no front
    BEGIN
        IF NEW.user_id IS NOT NULL THEN
            UPDATE public.world_sync_state
               SET sync_version = sync_version + 1,
                   updated_at = now()
             WHERE user_id = NEW.user_id;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;
    RETURN NEW;
END;
$function$;
CREATE UNIQUE INDEX IF NOT EXISTS uniform_sales_history_launch_date_uidx
  ON public.uniform_sales_history(launch_id, sale_date);
CREATE OR REPLACE FUNCTION public.calculate_daily_uniform_sales(p_launch_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_club_id       uuid;
  v_user_id       uuid;
  v_club_name     text;
  v_fans          integer;
  v_reputation    integer;
  v_launched_at   timestamptz;
  v_last_update   timestamptz;
  v_hype          double precision;
  v_status        text;
  v_days          double precision;
  v_hours_elapsed double precision;
  v_decay_per_hr  double precision;
  v_hype_floor    double precision;
  v_recent_wins   integer := 0;
  v_form_bonus    double precision := 1.0;
  v_daily_target  double precision;
  v_sales         integer;
  v_revenue_cents bigint;
  v_price_cents   integer;
  v_today         date := (now() at time zone 'America/Sao_Paulo')::date;
BEGIN
  SELECT l.club_id, l.launched_at, COALESCE(l.last_sales_update_at, l.launched_at),
         COALESCE(l.hype_score, 100), COALESCE(l.status,'')
    INTO v_club_id, v_launched_at, v_last_update, v_hype, v_status
    FROM public.club_uniform_launches l
   WHERE l.id = p_launch_id;
  IF NOT FOUND OR v_status NOT IN ('approved','active') THEN
    RETURN;
  END IF;
  SELECT c.user_id, c.name, COALESCE(c.fans,0), COALESCE(c.reputation,50)
    INTO v_user_id, v_club_name, v_fans, v_reputation
    FROM public.clubs c WHERE c.id = v_club_id;
  IF v_user_id IS NULL THEN RETURN; END IF;
  -- Tempo decorrido (em horas) desde o último tick, com teto de 24h
  v_hours_elapsed := LEAST(24.0, GREATEST(0.0, EXTRACT(EPOCH FROM (now() - v_last_update)) / 3600.0));
  IF v_hours_elapsed < 0.25 THEN
    -- Menos de 15 min desde o último tick: ignora pra evitar duplicação
    RETURN;
  END IF;
  v_days := EXTRACT(EPOCH FROM (now() - v_launched_at)) / 86400.0;
  -- Decaimento e piso baseados em tamanho do clube
  IF v_fans >= 30000 OR v_reputation >= 75 THEN
    v_decay_per_hr := 0.12;          -- ~2.9 pts/dia
    v_hype_floor   := 18.0;          -- clubes grandes nunca caem demais
  ELSIF v_fans >= 8000 OR v_reputation >= 55 THEN
    v_decay_per_hr := 0.20;          -- ~4.8 pts/dia
    v_hype_floor   := 12.0;
  ELSE
    v_decay_per_hr := 0.30;          -- ~7.2 pts/dia
    v_hype_floor   := 8.0;
  END IF;
  v_hype := GREATEST(v_hype_floor, v_hype - (v_decay_per_hr * v_hours_elapsed));
  -- Chance de viralizar (3% por tick): salto de +15 pts no hype
  IF random() < 0.03 THEN
    v_hype := LEAST(100.0, v_hype + 15.0);
  END IF;
  -- Bônus por vitórias recentes (últimos 5 jogos do usuário)
  BEGIN
    SELECT COUNT(*) INTO v_recent_wins
      FROM (
        SELECT is_home, home_goals, away_goals
          FROM public.match_history
         WHERE user_id = v_user_id
         ORDER BY played_at DESC NULLS LAST, created_at DESC NULLS LAST
         LIMIT 5
      ) m
     WHERE (m.is_home AND m.home_goals > m.away_goals)
        OR (NOT m.is_home AND m.away_goals > m.home_goals);
    v_form_bonus := 1.0 + (v_recent_wins * 0.06); -- até +30%
  EXCEPTION WHEN OTHERS THEN
    v_form_bonus := 1.0;
  END;
  -- Alvo de vendas diárias (multifator)
  -- base: ~0.35% da torcida * fator reputação * hype * forma
  v_daily_target := GREATEST(0,
      (v_fans * 0.0035)
      * (0.55 + (v_reputation / 100.0))   -- 0.55 .. 1.55
      * (v_hype / 100.0)                  -- 0.08 .. 1.0
      * v_form_bonus                      -- 1.0 .. 1.3
  );
  -- Fração proporcional às horas decorridas + variação aleatória ±15%
  v_sales := GREATEST(0, FLOOR(v_daily_target * (v_hours_elapsed / 24.0) * (0.85 + (random() * 0.30)))::int);
  -- Piso: clubes ativos vendem pelo menos 1 unidade por hora se houver demanda mínima
  IF v_sales = 0 AND v_fans > 500 AND v_hype > v_hype_floor THEN
    v_sales := GREATEST(1, FLOOR(v_hours_elapsed)::int);
  END IF;
  -- Receita: R$ 120 + 0.80/reputação por camisa (em centavos)
  v_price_cents   := 12000 + (v_reputation * 80);
  v_revenue_cents := (v_sales::bigint) * v_price_cents;
  -- Persistir hype + acumular totais
  UPDATE public.club_uniform_launches
     SET hype_score           = v_hype,
         last_sales_update_at = now(),
         total_sales_count    = COALESCE(total_sales_count,0) + v_sales,
         total_revenue_cents  = COALESCE(total_revenue_cents,0) + v_revenue_cents,
         peak_daily_sales     = GREATEST(COALESCE(peak_daily_sales,0), v_sales),
         total_sold           = COALESCE(total_sold,0) + v_sales,
         total_revenue        = COALESCE(total_revenue,0) + (v_revenue_cents / 100.0)
   WHERE id = p_launch_id;
  -- Histórico diário (upsert no dia de hoje em BRT)
  INSERT INTO public.uniform_sales_history (launch_id, club_id, quantity, revenue, sale_date, metadata)
  VALUES (p_launch_id, v_club_id, v_sales, (v_revenue_cents / 100.0), v_today,
          jsonb_build_object('hype', v_hype, 'hours', v_hours_elapsed, 'wins5', v_recent_wins))
  ON CONFLICT (launch_id, sale_date) DO UPDATE
     SET quantity = uniform_sales_history.quantity + EXCLUDED.quantity,
         revenue  = uniform_sales_history.revenue  + EXCLUDED.revenue,
         metadata = jsonb_build_object('hype', v_hype, 'wins5', v_recent_wins);
  -- Credita orçamento do clube
  IF v_revenue_cents > 0 THEN
    UPDATE public.clubs
       SET budget = COALESCE(budget,0) + (v_revenue_cents / 100)
     WHERE id = v_club_id;
  END IF;
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_all_uniform_sales()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  r RECORD;
BEGIN
  FOR r IN (
    SELECT id
      FROM public.club_uniform_launches
     WHERE status IN ('approved','active')
       AND (last_sales_update_at IS NULL
            OR last_sales_update_at < now() - INTERVAL '30 minutes')
  ) LOOP
    PERFORM public.calculate_daily_uniform_sales(r.id);
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.boost_uniform_hype_on_news()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_launch_id uuid;
BEGIN
  IF NEW.template_key IS NOT NULL AND NEW.template_key ILIKE 'kit_launch%' THEN
    BEGIN
      v_launch_id := NULLIF(NEW.metadata->>'launchId','')::uuid;
    EXCEPTION WHEN OTHERS THEN v_launch_id := NULL;
    END;
    IF v_launch_id IS NOT NULL THEN
      UPDATE public.club_uniform_launches
         SET hype_score = LEAST(100.0, COALESCE(hype_score,50) + 10.0)
       WHERE id = v_launch_id
         AND status IN ('approved','active');
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$;
DROP TRIGGER IF EXISTS tr_boost_uniform_hype_on_news ON public.newspaper_entries;
CREATE TRIGGER tr_boost_uniform_hype_on_news
AFTER INSERT ON public.newspaper_entries
FOR EACH ROW EXECUTE FUNCTION public.boost_uniform_hype_on_news();
DO $$ BEGIN
  PERFORM 1 FROM pg_publication_tables
   WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='uniform_sales_history';
  IF NOT FOUND THEN
    EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE public.uniform_sales_history';
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
DO $$ BEGIN
  PERFORM 1 FROM pg_publication_tables
   WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='club_uniform_launches';
  IF NOT FOUND THEN
    EXECUTE 'ALTER PUBLICATION supabase_realtime ADD TABLE public.club_uniform_launches';
  END IF;
EXCEPTION WHEN OTHERS THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.player_training_history (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID NOT NULL,
  player_id TEXT NOT NULL,
  player_name TEXT NOT NULL,
  attribute TEXT NOT NULL,
  old_value NUMERIC NOT NULL,
  new_value NUMERIC NOT NULL,
  delta NUMERIC GENERATED ALWAYS AS (new_value - old_value) STORED,
  week INTEGER,
  season INTEGER,
  focus TEXT,
  intensity TEXT,
  ct_level INTEGER,
  premium_boost BOOLEAN NOT NULL DEFAULT false,
  age INTEGER,
  stamina INTEGER,
  source TEXT NOT NULL DEFAULT 'training',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_pth_user_created ON public.player_training_history (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pth_user_player ON public.player_training_history (user_id, player_id, created_at DESC);
ALTER TABLE public.player_training_history ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "users read own training history" ON public.player_training_history;
CREATE POLICY "users read own training history"
ON public.player_training_history
FOR SELECT
USING (auth.uid() = user_id);
DROP POLICY IF EXISTS "users insert own training history" ON public.player_training_history;
CREATE POLICY "users insert own training history"
ON public.player_training_history
FOR INSERT
WITH CHECK (auth.uid() = user_id);
CREATE TABLE IF NOT EXISTS public.match_event_catalog (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  category text NOT NULL CHECK (category IN ('attack','defense','midfield','goalkeeper','special')),
  subcategory text NOT NULL,
  outcome text NOT NULL CHECK (outcome IN ('goal','shot_on','shot_off','chance','foul','card','injury','flavor','save','woodwork')),
  base_weight numeric NOT NULL DEFAULT 1.0,
  min_minute int NOT NULL DEFAULT 0,
  max_minute int NOT NULL DEFAULT 120,
  requires_context jsonb NOT NULL DEFAULT '{}'::jsonb,
  narration_templates text[] NOT NULL DEFAULT '{}',
  headline_templates text[] NOT NULL DEFAULT '{}',
  stats_impact jsonb NOT NULL DEFAULT '{}'::jsonb,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_match_event_catalog_cat ON public.match_event_catalog(category, enabled);
CREATE INDEX IF NOT EXISTS idx_match_event_catalog_outcome ON public.match_event_catalog(outcome);
ALTER TABLE public.match_event_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY "event catalog public read"
ON public.match_event_catalog FOR SELECT TO authenticated, anon USING (true);
CREATE POLICY "event catalog admin write"
ON public.match_event_catalog FOR ALL TO authenticated
USING (public.has_role(auth.uid(),'admin'))
WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.match_context_modifiers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  description text,
  condition jsonb NOT NULL DEFAULT '{}'::jsonb,
  event_filter jsonb NOT NULL DEFAULT '{}'::jsonb,
  weight_multiplier numeric NOT NULL DEFAULT 1.0,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.match_context_modifiers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "modifiers public read"
ON public.match_context_modifiers FOR SELECT TO authenticated, anon USING (true);
CREATE POLICY "modifiers admin write"
ON public.match_context_modifiers FOR ALL TO authenticated
USING (public.has_role(auth.uid(),'admin'))
WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE IF NOT EXISTS public.match_narratives (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  match_id text NOT NULL,
  shared_match_id uuid,
  headline text NOT NULL,
  summary text,
  tactical_read text,
  man_of_the_match jsonb,
  key_moments jsonb NOT NULL DEFAULT '[]'::jsonb,
  event_diversity_score numeric,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_match_narratives_match ON public.match_narratives(match_id);
CREATE INDEX IF NOT EXISTS idx_match_narratives_shared ON public.match_narratives(shared_match_id);
ALTER TABLE public.match_narratives ENABLE ROW LEVEL SECURITY;
CREATE POLICY "narratives public read"
ON public.match_narratives FOR SELECT TO authenticated, anon USING (true);
CREATE POLICY "narratives service insert"
ON public.match_narratives FOR INSERT TO authenticated
WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.match_history
  ADD COLUMN IF NOT EXISTS narrative_id uuid REFERENCES public.match_narratives(id),
  ADD COLUMN IF NOT EXISTS event_diversity_score numeric,
  ADD COLUMN IF NOT EXISTS man_of_the_match jsonb;
