ALTER TABLE public.world_player_stats
  ADD COLUMN IF NOT EXISTS penalties_saved INT NOT NULL DEFAULT 0 CHECK (penalties_saved >= 0);
ALTER TABLE public.global_player_ranking
  ADD COLUMN IF NOT EXISTS penalties_saved INT NOT NULL DEFAULT 0;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'gpr_non_negative_stats') THEN
    ALTER TABLE public.global_player_ranking
      ADD CONSTRAINT gpr_non_negative_stats
      CHECK (
        total_goals >= 0 AND total_assists >= 0 AND
        total_clean_sheets >= 0 AND penalties_saved >= 0 AND
        ranking_points >= 0
      );
  END IF;
END$$;
CREATE OR REPLACE FUNCTION public.calculate_player_ranking_points()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
    p_record RECORD;
    v_score NUMERIC;
    v_reputation INTEGER;
    v_level TEXT;
BEGIN
    FOR p_record IN
        SELECT
            wp.id, wp.overall, wp.potential, wp.age, wp.position,
            COALESCE(SUM(wps.goals), 0)              AS goals,
            COALESCE(SUM(wps.assists), 0)            AS assists,
            COALESCE(SUM(wps.clean_sheets), 0)       AS clean_sheets,
            COALESCE(SUM(wps.penalties_saved), 0)    AS pen_saved,
            COALESCE(AVG(NULLIF(wps.avg_rating,0)),0) AS avg_rating
        FROM public.world_players wp
        LEFT JOIN public.world_player_stats wps ON wp.id = wps.player_id
        GROUP BY wp.id
    LOOP
        IF p_record.position = 'Goleiro' THEN
            v_score := (p_record.clean_sheets * 15)
                     + (p_record.pen_saved   * 20)
                     + (GREATEST(p_record.avg_rating - 5, 0) * 30);
        ELSE
            v_score := (p_record.goals   * 12)
                     + (p_record.assists *  8)
                     + (GREATEST(p_record.avg_rating - 5, 0) * 30);
            IF p_record.position IN ('Zagueiro','Lateral Esquerdo','Lateral Direito') THEN
                v_score := v_score + (p_record.clean_sheets * 5);
            END IF;
        END IF;
        v_score := GREATEST(v_score, 0);
        v_reputation := LEAST(GREATEST(ROUND(v_score / 15), 0), 100);
        IF v_reputation >= 90 THEN v_level := 'Mundial';
        ELSIF v_reputation >= 70 THEN v_level := 'Continental';
        ELSIF v_reputation >= 40 THEN v_level := 'Nacional';
        ELSE v_level := 'Local';
        END IF;
        INSERT INTO public.global_player_ranking AS gpr (
            player_id, ranking_points, total_goals, total_assists,
            total_clean_sheets, penalties_saved, avg_rating, mvp_count,
            reputation_score, reputation_level, last_update
        ) VALUES (
            p_record.id, v_score, p_record.goals, p_record.assists,
            p_record.clean_sheets, p_record.pen_saved, p_record.avg_rating, 0,
            v_reputation, v_level, now()
        )
        ON CONFLICT (player_id) DO UPDATE SET
            ranking_points     = EXCLUDED.ranking_points,
            total_goals        = EXCLUDED.total_goals,
            total_assists      = EXCLUDED.total_assists,
            total_clean_sheets = EXCLUDED.total_clean_sheets,
            penalties_saved    = EXCLUDED.penalties_saved,
            avg_rating         = EXCLUDED.avg_rating,
            reputation_score   = EXCLUDED.reputation_score,
            reputation_level   = EXCLUDED.reputation_level,
            last_update        = now();
        UPDATE public.world_players SET reputation = v_reputation WHERE id = p_record.id;
    END LOOP;
    WITH RankedPlayers AS (
        SELECT id, ROW_NUMBER() OVER (
            ORDER BY ranking_points DESC, total_goals DESC, avg_rating DESC
        ) AS pos
        FROM public.global_player_ranking
    )
    UPDATE public.global_player_ranking gpr
    SET prev_position = COALESCE(gpr.current_position, rp.pos),
        current_position = rp.pos
    FROM RankedPlayers rp
    WHERE gpr.id = rp.id;
    WITH PosRanked AS (
        SELECT gpr.id, ROW_NUMBER() OVER (
            PARTITION BY wp.position
            ORDER BY gpr.ranking_points DESC, gpr.total_goals DESC
        ) AS p_pos
        FROM public.global_player_ranking gpr
        JOIN public.world_players wp ON gpr.player_id = wp.id
    )
    UPDATE public.global_player_ranking gpr
    SET position_rank = pr.p_pos
    FROM PosRanked pr
    WHERE gpr.id = pr.id;
END;
$function$;
ALTER TABLE public.global_player_ranking REPLICA IDENTITY FULL;
ALTER TABLE public.global_ranking        REPLICA IDENTITY FULL;
SELECT public.calculate_player_ranking_points();
CREATE OR REPLACE FUNCTION public.sync_global_ranking_from_match()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_goals INTEGER;
  v_opp_goals  INTEGER;
  v_outcome    TEXT;
  v_club_name  TEXT;
  v_comp_lower TEXT;
  v_comp_kind  TEXT;
  v_delta      INTEGER := 0;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.is_home THEN
    v_user_goals := NEW.home_goals;
    v_opp_goals  := NEW.away_goals;
    v_club_name  := NEW.home_team;
  ELSE
    v_user_goals := NEW.away_goals;
    v_opp_goals  := NEW.home_goals;
    v_club_name  := NEW.away_team;
  END IF;
  IF v_user_goals > v_opp_goals THEN v_outcome := 'win';
  ELSIF v_user_goals < v_opp_goals THEN v_outcome := 'loss';
  ELSE v_outcome := 'draw';
  END IF;
  v_comp_lower := lower(coalesce(NEW.competition, '') || ' ' || coalesce(NEW.match_type, ''));
  v_comp_kind := CASE
    WHEN v_comp_lower LIKE '%mundial%' OR v_comp_lower LIKE '%world%' THEN 'world'
    WHEN v_comp_lower LIKE '%continental%' OR v_comp_lower LIKE '%libertador%' OR v_comp_lower LIKE '%champions%' OR v_comp_lower LIKE '%europa%' OR v_comp_lower LIKE '%afc%' OR v_comp_lower LIKE '%caf%' OR v_comp_lower LIKE '%concacaf%' OR v_comp_lower LIKE '%ofc%' THEN 'continental'
    WHEN v_comp_lower LIKE '%copa%' OR v_comp_lower LIKE '%cup%' THEN 'cup'
    WHEN v_comp_lower LIKE '%amist%' OR v_comp_lower LIKE '%friendly%' THEN 'friendly'
    ELSE 'league'
  END;
  v_delta := CASE v_comp_kind
    WHEN 'world'       THEN CASE v_outcome WHEN 'win' THEN 10 WHEN 'draw' THEN 5 ELSE 0 END
    WHEN 'continental' THEN CASE v_outcome WHEN 'win' THEN  6 WHEN 'draw' THEN 3 ELSE 0 END
    WHEN 'cup'         THEN CASE v_outcome WHEN 'win' THEN  4 WHEN 'draw' THEN 2 ELSE 0 END
    WHEN 'league'      THEN CASE v_outcome WHEN 'win' THEN  3 WHEN 'draw' THEN 1 ELSE 0 END
    ELSE 0
  END;
  INSERT INTO public.global_ranking (
    user_id, club_name, ranking_points, games_played,
    wins, draws, losses, last_change, current_competition
  ) VALUES (
    NEW.user_id, v_club_name, GREATEST(0, v_delta), 1,
    CASE WHEN v_outcome = 'win'  THEN 1 ELSE 0 END,
    CASE WHEN v_outcome = 'draw' THEN 1 ELSE 0 END,
    CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
    v_delta, coalesce(NEW.competition, 'Amistoso')
  )
  ON CONFLICT (user_id) DO UPDATE SET
    club_name           = EXCLUDED.club_name,
    ranking_points      = GREATEST(0, coalesce(public.global_ranking.ranking_points, 0) + v_delta),
    games_played        = coalesce(public.global_ranking.games_played, 0) + 1,
    wins                = coalesce(public.global_ranking.wins,   0) + CASE WHEN v_outcome = 'win'  THEN 1 ELSE 0 END,
    draws               = coalesce(public.global_ranking.draws,  0) + CASE WHEN v_outcome = 'draw' THEN 1 ELSE 0 END,
    losses              = coalesce(public.global_ranking.losses, 0) + CASE WHEN v_outcome = 'loss' THEN 1 ELSE 0 END,
    last_change         = v_delta,
    current_competition = EXCLUDED.current_competition,
    updated_at          = now();
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sync_global_ranking_from_match falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;
CREATE OR REPLACE FUNCTION public.apply_title_bonus(_user_id uuid, _kind text)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_bonus integer;
BEGIN
  IF _user_id IS NULL THEN RETURN; END IF;
  v_bonus := CASE lower(_kind)
    WHEN 'league'      THEN 30
    WHEN 'cup'         THEN 40
    WHEN 'continental' THEN 80
    WHEN 'world'       THEN 150
    ELSE 0
  END;
  IF v_bonus = 0 THEN RETURN; END IF;
  INSERT INTO public.global_ranking (user_id, ranking_points, last_change, current_competition)
  VALUES (_user_id, v_bonus, v_bonus, 'Título ' || _kind)
  ON CONFLICT (user_id) DO UPDATE SET
    ranking_points = coalesce(public.global_ranking.ranking_points, 0) + v_bonus,
    last_change    = v_bonus,
    titles_count   = coalesce(public.global_ranking.titles_count, 0) + 1,
    updated_at     = now();
END;
$$;
CREATE OR REPLACE FUNCTION public.trg_cup_champion_bonus()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid;
BEGIN
  IF NEW.status = 'finished'
     AND (OLD.status IS DISTINCT FROM 'finished')
     AND NEW.winner_team_id IS NOT NULL THEN
    SELECT user_id INTO v_user FROM public.national_cup_teams WHERE id = NEW.winner_team_id;
    PERFORM public.apply_title_bonus(v_user, 'cup');
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_cup_champion_bonus falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_cup_champion_bonus ON public.national_cups;
CREATE TRIGGER trg_cup_champion_bonus
  AFTER UPDATE ON public.national_cups
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_cup_champion_bonus();
CREATE OR REPLACE FUNCTION public.trg_league_champion_bonus()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_kind text;
BEGIN
  IF NEW.award_type = 'best_team' AND NEW.user_id IS NOT NULL THEN
    v_kind := CASE lower(coalesce(NEW.scope, ''))
      WHEN 'league'      THEN 'league'
      WHEN 'cup'         THEN 'cup'
      WHEN 'continental' THEN 'continental'
      WHEN 'world'       THEN 'world'
      WHEN 'global'      THEN 'world'
      ELSE NULL
    END;
    IF v_kind IS NOT NULL THEN
      PERFORM public.apply_title_bonus(NEW.user_id, v_kind);
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'trg_league_champion_bonus falhou: %', SQLERRM;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS trg_league_champion_bonus ON public.season_awards;
CREATE TRIGGER trg_league_champion_bonus
  AFTER INSERT ON public.season_awards
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_league_champion_bonus();
CREATE OR REPLACE FUNCTION public.recalc_player_ranking(p_player_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_position text;
  v_goals int;
  v_assists int;
  v_clean int;
  v_pen int;
  v_avg numeric;
  v_matches int;
  v_score numeric;
  v_reputation int;
  v_level text;
BEGIN
  SELECT position INTO v_position FROM public.world_players WHERE id = p_player_id;
  IF v_position IS NULL THEN
    RETURN;
  END IF;
  SELECT
    COALESCE(SUM(goals),0),
    COALESCE(SUM(assists),0),
    COALESCE(SUM(clean_sheets),0),
    COALESCE(SUM(penalties_saved),0),
    COALESCE(AVG(NULLIF(avg_rating,0)),0),
    COALESCE(SUM(matches_played),0)
  INTO v_goals, v_assists, v_clean, v_pen, v_avg, v_matches
  FROM public.world_player_stats
  WHERE player_id = p_player_id;
  IF v_position = 'Goleiro' THEN
    -- Goleiro: pênalti defendido +6, clean sheet +2, nota média influencia
    v_score := (v_pen * 6) + (v_clean * 2) + (GREATEST(v_avg - 5, 0) * 10);
  ELSE
    -- Linha: gol +5, assistência +3, nota média influencia
    v_score := (v_goals * 5) + (v_assists * 3) + (GREATEST(v_avg - 5, 0) * 10);
  END IF;
  v_score := GREATEST(v_score, 0);
  v_reputation := LEAST(GREATEST(ROUND(v_score / 10), 0), 100);
  IF v_reputation >= 90 THEN v_level := 'Mundial';
  ELSIF v_reputation >= 70 THEN v_level := 'Continental';
  ELSIF v_reputation >= 40 THEN v_level := 'Nacional';
  ELSE v_level := 'Local';
  END IF;
  INSERT INTO public.global_player_ranking AS gpr (
    player_id, ranking_points, total_goals, total_assists,
    total_clean_sheets, penalties_saved, avg_rating,
    reputation_score, reputation_level, last_update
  ) VALUES (
    p_player_id, v_score, v_goals, v_assists,
    v_clean, v_pen, v_avg,
    v_reputation, v_level, now()
  )
  ON CONFLICT (player_id) DO UPDATE SET
    ranking_points     = EXCLUDED.ranking_points,
    total_goals        = EXCLUDED.total_goals,
    total_assists      = EXCLUDED.total_assists,
    total_clean_sheets = EXCLUDED.total_clean_sheets,
    penalties_saved    = EXCLUDED.penalties_saved,
    avg_rating         = EXCLUDED.avg_rating,
    reputation_score   = EXCLUDED.reputation_score,
    reputation_level   = EXCLUDED.reputation_level,
    last_update        = now();
END;
$$;
CREATE OR REPLACE FUNCTION public.calculate_player_ranking_points()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  rec RECORD;
BEGIN
  FOR rec IN SELECT id FROM public.world_players LOOP
    PERFORM public.recalc_player_ranking(rec.id);
  END LOOP;
END;
$$;
CREATE OR REPLACE FUNCTION public.trg_recalc_player_ranking()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM public.recalc_player_ranking(OLD.player_id);
    RETURN OLD;
  ELSE
    PERFORM public.recalc_player_ranking(NEW.player_id);
    RETURN NEW;
  END IF;
END;
$$;
DROP TRIGGER IF EXISTS world_player_stats_recalc_ranking ON public.world_player_stats;
CREATE TRIGGER world_player_stats_recalc_ranking
AFTER INSERT OR UPDATE OR DELETE ON public.world_player_stats
FOR EACH ROW EXECUTE FUNCTION public.trg_recalc_player_ranking();
INSERT INTO public.global_player_ranking (player_id, ranking_points, reputation_score, reputation_level, last_update)
SELECT wp.id, 0, 0, 'Local', now()
FROM public.world_players wp
WHERE NOT EXISTS (
  SELECT 1 FROM public.global_player_ranking gpr WHERE gpr.player_id = wp.id
);
SELECT public.calculate_player_ranking_points();
CREATE OR REPLACE FUNCTION public.recalc_player_ranking(p_player_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_position text;
  v_is_gk boolean;
  v_goals int;
  v_assists int;
  v_clean int;
  v_pen int;
  v_avg numeric;
  v_score numeric;
  v_reputation int;
  v_level text;
BEGIN
  SELECT position INTO v_position FROM public.world_players WHERE id = p_player_id;
  IF v_position IS NULL THEN
    RETURN;
  END IF;
  v_is_gk := v_position IN ('Goleiro','GOL','GK');
  SELECT
    COALESCE(SUM(goals),0),
    COALESCE(SUM(assists),0),
    COALESCE(SUM(clean_sheets),0),
    COALESCE(SUM(penalties_saved),0),
    COALESCE(AVG(NULLIF(avg_rating,0)),0)
  INTO v_goals, v_assists, v_clean, v_pen, v_avg
  FROM public.world_player_stats
  WHERE player_id = p_player_id;
  IF v_is_gk THEN
    v_score := (v_pen * 6) + (v_clean * 2) + (GREATEST(v_avg - 5, 0) * 10);
  ELSE
    v_score := (v_goals * 5) + (v_assists * 3) + (GREATEST(v_avg - 5, 0) * 10);
  END IF;
  v_score := GREATEST(v_score, 0);
  v_reputation := LEAST(GREATEST(ROUND(v_score / 10), 0), 100);
  IF v_reputation >= 90 THEN v_level := 'Mundial';
  ELSIF v_reputation >= 70 THEN v_level := 'Continental';
  ELSIF v_reputation >= 40 THEN v_level := 'Nacional';
  ELSE v_level := 'Local';
  END IF;
  INSERT INTO public.global_player_ranking AS gpr (
    player_id, ranking_points, total_goals, total_assists,
    total_clean_sheets, penalties_saved, avg_rating,
    reputation_score, reputation_level, last_update
  ) VALUES (
    p_player_id, v_score, v_goals, v_assists,
    v_clean, v_pen, v_avg,
    v_reputation, v_level, now()
  )
  ON CONFLICT (player_id) DO UPDATE SET
    ranking_points     = EXCLUDED.ranking_points,
    total_goals        = EXCLUDED.total_goals,
    total_assists      = EXCLUDED.total_assists,
    total_clean_sheets = EXCLUDED.total_clean_sheets,
    penalties_saved    = EXCLUDED.penalties_saved,
    avg_rating         = EXCLUDED.avg_rating,
    reputation_score   = EXCLUDED.reputation_score,
    reputation_level   = EXCLUDED.reputation_level,
    last_update        = now();
END;
$$;
CREATE OR REPLACE FUNCTION public.admin_reset_real_clubs(
  p_admin_id uuid,
  p_confirmation_token text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_backup jsonb := '{}'::jsonb;
  v_log_id uuid;
  v_real_user_ids uuid[];
  v_real_team_ids uuid[];
  v_real_player_ids uuid[];
BEGIN
  -- Authorization
  IF NOT public.has_role(p_admin_id, 'admin'::app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;
  IF p_confirmation_token IS DISTINCT FROM 'CONFIRM_RESET_REAL_CLUBS' THEN
    RAISE EXCEPTION 'invalid confirmation token';
  END IF;
  -- Build sets of "real" entities
  SELECT COALESCE(array_agg(DISTINCT user_id), ARRAY[]::uuid[])
    INTO v_real_user_ids
  FROM (
    SELECT user_id FROM public.world_teams WHERE user_id IS NOT NULL
    UNION
    SELECT user_id FROM public.league_members WHERE user_id IS NOT NULL AND COALESCE(is_bot,false)=false
    UNION
    SELECT user_id FROM public.world_league_teams WHERE user_id IS NOT NULL AND COALESCE(is_bot,false)=false
  ) s;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_real_team_ids
  FROM public.world_teams
  WHERE user_id IS NOT NULL;
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[])
    INTO v_real_player_ids
  FROM public.world_players
  WHERE team_id = ANY(v_real_team_ids);
  -- Snapshot counters (backup)
  v_backup := jsonb_build_object(
    'real_users', COALESCE(array_length(v_real_user_ids,1),0),
    'real_teams', COALESCE(array_length(v_real_team_ids,1),0),
    'real_players', COALESCE(array_length(v_real_player_ids,1),0),
    'match_history', (SELECT count(*) FROM public.match_history WHERE user_id = ANY(v_real_user_ids)),
    'match_reports', (SELECT count(*) FROM public.match_reports WHERE user_id = ANY(v_real_user_ids)),
    'league_matches', (SELECT count(*) FROM public.league_matches WHERE home_user_id = ANY(v_real_user_ids) OR away_user_id = ANY(v_real_user_ids)),
    'world_matches', (SELECT count(*) FROM public.world_matches WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids)),
    'global_ranking', (SELECT count(*) FROM public.global_ranking WHERE user_id = ANY(v_real_user_ids)),
    'global_player_ranking', (SELECT count(*) FROM public.global_player_ranking WHERE player_id = ANY(v_real_player_ids))
  );
  -- 1) Histórico de partidas (apenas usuários reais)
  DELETE FROM public.match_reports WHERE user_id = ANY(v_real_user_ids);
  DELETE FROM public.match_history WHERE user_id = ANY(v_real_user_ids);
  -- 2) Remover live_matches travadas envolvendo reais
  DELETE FROM public.live_matches
  WHERE home_user_id = ANY(v_real_user_ids) OR away_user_id = ANY(v_real_user_ids);
  -- 3) Liga multiplayer entre reais — resetar partidas
  UPDATE public.league_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      played_at=NULL, match_data=NULL,
      synced=false, game_state=NULL
  WHERE home_user_id = ANY(v_real_user_ids) OR away_user_id = ANY(v_real_user_ids);
  -- 4) league_standings (mp) zerar reais
  UPDATE public.league_standings
  SET played=0, wins=0, draws=0, losses=0,
      goals_for=0, goals_against=0, points=0, goals_diff=0
  WHERE user_id = ANY(v_real_user_ids);
  -- 5) league_members zerar stats (não-bots)
  UPDATE public.league_members
  SET points=0, wins=0, draws=0, losses=0,
      goals_for=0, goals_against=0, played=0
  WHERE COALESCE(is_bot,false)=false;
  -- 6) world_matches envolvendo times reais — voltar a "scheduled"
  UPDATE public.world_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      played_at=NULL, match_data=NULL,
      game_state=NULL, synced=false, simulated=false
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  -- 7) world_league_table / world_league_standings — zerar reais
  UPDATE public.world_league_table
  SET played=0, wins=0, draws=0, losses=0,
      goals_for=0, goals_against=0, goal_diff=0, points=0
  WHERE team_id = ANY(v_real_team_ids);
  UPDATE public.world_league_standings
  SET played=0, wins=0, draws=0, losses=0,
      goals_for=0, goals_against=0, points=0
  WHERE team_id = ANY(v_real_team_ids);
  -- 8) world_league_teams — zerar stats (não-bots)
  UPDATE public.world_league_teams
  SET points=0, wins=0, draws=0, losses=0,
      goals_for=0, goals_against=0, played=0
  WHERE COALESCE(is_bot,false)=false;
  -- 9) Copas nacionais — resetar partidas envolvendo times reais
  UPDATE public.national_cup_matches
  SET status='scheduled', home_score=NULL, away_score=NULL,
      home_penalties=NULL, away_penalties=NULL,
      winner_team_id=NULL, match_data=NULL,
      aggregate_home_score=NULL, aggregate_away_score=NULL,
      synced=false
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  -- 10) Copa do mundo / Internacional — resetar partidas com times reais
  UPDATE public.world_cup_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      home_penalty_goals=NULL, away_penalty_goals=NULL,
      winner_team_id=NULL, match_data=NULL,
      has_extra_time=false, home_extra_goals=NULL, away_extra_goals=NULL
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  UPDATE public.international_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      home_penalty_goals=NULL, away_penalty_goals=NULL,
      winner_id=NULL, is_penalty_shootout=false
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  -- 11) Torneios custom / oficiais
  UPDATE public.tournament_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      played_at=NULL, match_data=NULL
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  UPDATE public.custom_tournament_matches
  SET status='scheduled', home_goals=NULL, away_goals=NULL,
      played_at=NULL, match_data=NULL
  WHERE home_team_id = ANY(v_real_team_ids) OR away_team_id = ANY(v_real_team_ids);
  -- 12) Ranking global de clubes — zerar reais
  UPDATE public.global_ranking
  SET ranking_points=0, games_played=0, wins=0, draws=0, losses=0,
      last_change=0, recent_form='[]'::jsonb, winning_streak=0,
      goals_for=0, goals_against=0,
      season_points=0, total_wins=0, total_draws=0, total_losses=0,
      titles_count=0, titles_data='[]'::jsonb, points_history='[]'::jsonb,
      updated_at=now()
  WHERE user_id = ANY(v_real_user_ids);
  -- 13) Ranking de jogadores — zerar jogadores de clubes reais
  UPDATE public.global_player_ranking
  SET ranking_points=0, seasonal_points=0, reputation_score=0,
      total_goals=0, total_assists=0, total_clean_sheets=0,
      avg_rating=0, mvp_count=0, penalties_saved=0,
      last_update=now()
  WHERE player_id = ANY(v_real_player_ids);
  -- 14) Estatísticas por competição — zerar dos jogadores reais
  UPDATE public.world_player_stats
  SET matches_played=0, goals=0, assists=0, avg_rating=0, best_rating=0,
      mvp_count=0, yellow_cards=0, red_cards=0, clean_sheets=0,
      goals_conceded=0, decisive_passes=0, minutes_played=0,
      total_rating=0, penalties_saved=0
  WHERE player_id = ANY(v_real_player_ids);
  DELETE FROM public.league_player_stats
  WHERE member_id IN (
    SELECT id FROM public.league_members
    WHERE user_id = ANY(v_real_user_ids)
  );
  DELETE FROM public.cup_player_stats
  WHERE player_id = ANY(v_real_player_ids);
  DELETE FROM public.tournament_stats
  WHERE player_id = ANY(v_real_player_ids);
  DELETE FROM public.player_competition_stats
  WHERE player_id = ANY(v_real_player_ids);
  -- 15) Títulos / awards da temporada atual envolvendo reais
  DELETE FROM public.season_awards
  WHERE user_id = ANY(v_real_user_ids);
  DELETE FROM public.league_awards
  WHERE user_id = ANY(v_real_user_ids);
  -- 16) Histórico de ranking (apenas reais)
  DELETE FROM public.club_ranking_history
  WHERE user_id = ANY(v_real_user_ids);
  -- 17) Remover duplicatas de match_history (defensivo)
  DELETE FROM public.match_history a
  USING public.match_history b
  WHERE a.id < b.id
    AND a.user_id = b.user_id
    AND a.played_at = b.played_at
    AND a.home_team = b.home_team
    AND a.away_team = b.away_team
    AND COALESCE(a.competition,'') = COALESCE(b.competition,'');
  -- 18) Log
  INSERT INTO public.admin_logs (user_id, action, details)
  VALUES (
    p_admin_id,
    'reset_real_clubs',
    jsonb_build_object('backup', v_backup, 'executed_at', now())
  )
  RETURNING id INTO v_log_id;
  RETURN jsonb_build_object(
    'success', true,
    'log_id', v_log_id,
    'backup', v_backup,
    'executed_at', now()
  );
END;
$$;
REVOKE ALL ON FUNCTION public.admin_reset_real_clubs(uuid, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.admin_reset_real_clubs(uuid, text) TO authenticated;
DROP TRIGGER IF EXISTS on_transfer_offer_inserted ON public.transfer_offers;
DROP FUNCTION IF EXISTS public.notify_transfer_offer();
CREATE OR REPLACE FUNCTION public.close_expired_auctions()
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE
  _auction RECORD;
  _closed int := 0;
  _to_free int := 0;
  _sold int := 0;
  _money text;
  _importance int;
  _headline text;
  _ovr int;
  _meta jsonb;
BEGIN
  FOR _auction IN
    SELECT * FROM public.player_auctions
    WHERE status = 'active' AND expires_at <= now()
    FOR UPDATE
  LOOP
    IF _auction.current_bidder_id IS NOT NULL AND _auction.current_bid >= _auction.min_price THEN
      UPDATE public.player_auctions SET status = 'sold' WHERE id = _auction.id;
      INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
      VALUES (
        _auction.current_bidder_id, 'auction_won',
        '🏆 Leilão vencido!',
        'Você arrematou ' || _auction.player_name || ' por R$ ' || _auction.current_bid::text,
        '🏆',
        jsonb_build_object('auction_id', _auction.id, 'player_data', _auction.player_data, 'amount', _auction.current_bid)
      );
      IF _auction.seller_id IS NOT NULL AND NOT _auction.is_system THEN
        INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
        VALUES (
          _auction.seller_id, 'auction_sold',
          '💰 Jogador vendido no leilão',
          _auction.player_name || ' vendido por R$ ' || _auction.current_bid::text,
          '💰',
          jsonb_build_object('auction_id', _auction.id, 'amount', _auction.current_bid, 'buyer', _auction.current_bidder_name)
        );
      END IF;
      -- ============================================================
      -- 📰 NOTÍCIA AUTOMÁTICA: Leilão arrematado
      -- ============================================================
      _ovr := COALESCE(_auction.player_overall, 0);
      IF _auction.current_bid >= 1000000 THEN
        _money := 'R$ ' || ROUND(_auction.current_bid::numeric / 1000000.0, 1)::text || 'M';
      ELSE
        _money := 'R$ ' || ROUND(_auction.current_bid::numeric / 1000.0, 0)::text || 'k';
      END IF;
      _importance := 1;
      IF _ovr >= 78 OR _auction.current_bid >= 5000000 THEN _importance := 2; END IF;
      IF _ovr >= 85 OR _auction.current_bid >= 20000000 THEN _importance := 3; END IF;
      _headline := CASE (floor(random() * 3))::int
        WHEN 0 THEN '🏆 LEILÃO! ' || COALESCE(_auction.current_bidder_name, 'Clube comprador') ||
                    ' arremata ' || _auction.player_name || ' (OVR ' || _ovr::text || ') por ' || _money
        WHEN 1 THEN '🔨 Martelo batido: ' || _auction.player_name ||
                    ' é do ' || COALESCE(_auction.current_bidder_name, 'novo clube') ||
                    ' após disputa acirrada no leilão (' || _money || ')'
        ELSE        '💸 ' || COALESCE(_auction.current_bidder_name, 'Clube vencedor') ||
                    ' dá o lance vencedor por ' || _auction.player_name ||
                    ' (OVR ' || _ovr::text || ') no leilão — ' || _money
      END;
      _meta := jsonb_build_object(
        'kind', 'auction_won',
        'player_name', _auction.player_name,
        'player_overall', _ovr,
        'from_club', _auction.seller_club_name,
        'to_club', _auction.current_bidder_name,
        'value', _auction.current_bid,
        'auction_id', _auction.id
      );
      -- Notícia para o vencedor
      INSERT INTO public.newspaper_entries (user_id, category, text, is_event, importance, metadata)
      VALUES (_auction.current_bidder_id, 'TRANSFERÊNCIA', _headline, true, _importance, _meta);
      -- Notícia para o vendedor (se humano)
      IF _auction.seller_id IS NOT NULL AND NOT _auction.is_system THEN
        INSERT INTO public.newspaper_entries (user_id, category, text, is_event, importance, metadata)
        VALUES (_auction.seller_id, 'TRANSFERÊNCIA', _headline, true, _importance, _meta);
      END IF;
      _sold := _sold + 1;
    ELSE
      UPDATE public.player_auctions SET status = 'expired' WHERE id = _auction.id;
      INSERT INTO public.free_agents_market (
        player_data, player_name, player_position, player_age, player_overall,
        visible_stats, origin, origin_club_name, available_from, available_until
      ) VALUES (
        _auction.player_data,
        _auction.player_name,
        COALESCE(_auction.player_data->>'position', 'CM'),
        _auction.player_age,
        _auction.player_overall,
        '{}'::jsonb,
        'auction_unsold',
        _auction.seller_club_name,
        now(),
        now() + interval '7 days'
      );
      IF _auction.seller_id IS NOT NULL AND NOT _auction.is_system THEN
        INSERT INTO public.user_notifications (user_id, type, title, message, icon, data)
        VALUES (
          _auction.seller_id, 'auction_unsold',
          'Leilão sem lances',
          _auction.player_name || ' foi para os Jogadores Livres.',
          '🆓',
          jsonb_build_object('auction_id', _auction.id)
        );
      END IF;
      _to_free := _to_free + 1;
    END IF;
    _closed := _closed + 1;
  END LOOP;
  RETURN jsonb_build_object('closed', _closed, 'sold', _sold, 'to_free', _to_free);
END;
$function$;
CREATE POLICY "Users can takeover bots" ON public.world_teams
FOR UPDATE
TO authenticated
USING (is_bot = true OR auth.uid() = user_id)
WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Users can insert their own world team" ON public.world_teams
FOR INSERT
TO authenticated
WITH CHECK (auth.uid() = user_id);
CREATE POLICY "Owners can manage their players" ON public.world_players
FOR ALL
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.world_teams
    WHERE world_teams.id = world_players.team_id
    AND world_teams.user_id = auth.uid()
  )
)
WITH CHECK (
  EXISTS (
    SELECT 1 FROM public.world_teams
    WHERE world_teams.id = world_players.team_id
    AND world_teams.user_id = auth.uid()
  )
);
GRANT ALL ON public.world_teams TO authenticated;
GRANT ALL ON public.world_players TO authenticated;
