CREATE TABLE IF NOT EXISTS public.league_registration_logs (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL,
    league_id UUID,
    country TEXT,
    club_name TEXT,
    action TEXT NOT NULL, -- 'joined', 'replaced_bot', 'queued', 'error'
    bot_replaced_id UUID,
    details JSONB,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);
GRANT SELECT, INSERT ON public.league_registration_logs TO authenticated;
GRANT ALL ON public.league_registration_logs TO service_role;
ALTER TABLE public.league_registration_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users can view their own logs" ON public.league_registration_logs
FOR SELECT USING (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.auto_assign_league(_user_id uuid, _club_name text, _country text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _league_id uuid;
  _bot_user_id uuid;
  _has_active_main boolean;
  _log_id uuid;
BEGIN
  -- 1. Check if user is already in any league of this country
  SELECT lm.league_id INTO _league_id
  FROM league_members lm
  JOIN multiplayer_leagues ml ON ml.id = lm.league_id
  WHERE lm.user_id = _user_id AND ml.country = _country
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    RETURN _league_id;
  END IF;
  -- 2. Try to find a league with empty space (count < max_members)
  -- Priority to 'main' league first, then 'beginner'
  SELECT ml.id INTO _league_id
  FROM multiplayer_leagues ml
  WHERE ml.country = _country
    AND ml.auto_created = true
    AND ml.season_status IN ('registration', 'waiting', 'in_progress') -- Allow joining in progress too
    AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id) < ml.max_members
  ORDER BY 
    CASE WHEN ml.league_type = 'main' THEN 1 ELSE 2 END ASC,
    ml.division ASC, 
    ml.created_at ASC
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    INSERT INTO league_members (league_id, user_id, club_name, club_logo, is_bot)
    VALUES (_league_id, _user_id, _club_name, '⚽', false)
    ON CONFLICT (league_id, user_id) DO NOTHING;
    
    INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action)
    VALUES (_user_id, _league_id, _country, _club_name, 'joined');
    
    RETURN _league_id;
  END IF;
  -- 3. No empty space? Try to replace a BOT in an existing league
  SELECT ml.id INTO _league_id
  FROM multiplayer_leagues ml
  WHERE ml.country = _country
    AND ml.auto_created = true
    AND EXISTS (SELECT 1 FROM league_members lm3 WHERE lm3.league_id = ml.id AND lm3.is_bot = true)
  ORDER BY 
    CASE WHEN ml.league_type = 'main' THEN 1 ELSE 2 END ASC,
    ml.division ASC, 
    ml.created_at ASC
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    -- Find the BOT to replace
    SELECT user_id INTO _bot_user_id
    FROM league_members
    WHERE league_id = _league_id AND is_bot = true
    LIMIT 1;
    IF _bot_user_id IS NOT NULL THEN
      -- Replace BOT in league_members
      UPDATE league_members 
      SET user_id = _user_id, 
          club_name = _club_name, 
          is_bot = false, 
          bot_strength = NULL,
          joined_at = NOW()
      WHERE league_id = _league_id AND user_id = _bot_user_id;
      -- Update match fixtures
      UPDATE league_matches SET home_user_id = _user_id WHERE league_id = _league_id AND home_user_id = _bot_user_id;
      UPDATE league_matches SET away_user_id = _user_id WHERE league_id = _league_id AND away_user_id = _bot_user_id;
      
      -- Update squads if any (usually bots don't have league_squads entries, but for safety)
      UPDATE league_squads SET user_id = _user_id WHERE league_id = _league_id AND user_id = _bot_user_id;
      INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action, bot_replaced_id)
      VALUES (_user_id, _league_id, _country, _club_name, 'replaced_bot', _bot_user_id);
      
      RETURN _league_id;
    END IF;
  END IF;
  -- 4. Still no space and no bots? Add to waiting list
  INSERT INTO public.league_waiting_list (user_id, country, league_type, status)
  VALUES (_user_id, _country, 'main', 'waiting')
  ON CONFLICT (user_id, country, league_type) DO UPDATE SET status = 'waiting', enrolled_at = NOW();
  INSERT INTO league_registration_logs (user_id, country, club_name, action)
  VALUES (_user_id, _country, _club_name, 'queued');
  RETURN NULL; -- Return NULL to indicate queued
END;
$function$;
CREATE OR REPLACE FUNCTION public.process_league_waiting_list(_league_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_country TEXT;
  v_league_type TEXT;
  v_max_members INT;
  v_current_members INT;
  v_bot_user_id UUID;
  v_next_user RECORD;
BEGIN
  -- Get league details
  SELECT country, league_type, max_members INTO v_country, v_league_type, v_max_members
  FROM multiplayer_leagues
  WHERE id = _league_id;
  LOOP
    -- 1. Try to find space or a bot
    SELECT count(*) INTO v_current_members FROM league_members WHERE league_id = _league_id;
    
    -- Check if we have a bot to replace if full
    IF v_current_members >= v_max_members THEN
      SELECT user_id INTO v_bot_user_id FROM league_members WHERE league_id = _league_id AND is_bot = true LIMIT 1;
      EXIT WHEN v_bot_user_id IS NULL; -- Truly full with humans
    ELSE
      v_bot_user_id := NULL;
    END IF;
    -- Get next user in line for this country and type
    SELECT * INTO v_next_user
    FROM league_waiting_list
    WHERE country = v_country 
      AND league_type = v_league_type 
      AND status = 'waiting'
    ORDER BY enrolled_at ASC
    LIMIT 1;
    EXIT WHEN v_next_user IS NULL;
    DECLARE
      v_club_name TEXT;
    BEGIN
      SELECT name INTO v_club_name FROM clubs WHERE user_id = v_next_user.user_id LIMIT 1;
      IF v_club_name IS NULL THEN v_club_name := 'Novo Clube'; END IF;
      IF v_bot_user_id IS NOT NULL THEN
        -- Replace BOT
        UPDATE league_members 
        SET user_id = v_next_user.user_id, club_name = v_club_name, is_bot = false, bot_strength = NULL, joined_at = NOW()
        WHERE league_id = _league_id AND user_id = v_bot_user_id;
        
        UPDATE league_matches SET home_user_id = v_next_user.user_id WHERE league_id = _league_id AND home_user_id = v_bot_user_id;
        UPDATE league_matches SET away_user_id = v_next_user.user_id WHERE league_id = _league_id AND away_user_id = v_bot_user_id;
        
        INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action, bot_replaced_id)
        VALUES (v_next_user.user_id, _league_id, v_country, v_club_name, 'replaced_bot', v_bot_user_id);
      ELSE
        -- Add to league directly
        INSERT INTO league_members (league_id, user_id, club_name, club_logo, is_bot)
        VALUES (_league_id, v_next_user.user_id, v_club_name, '⚽', false)
        ON CONFLICT (league_id, user_id) DO NOTHING;
        
        INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action)
        VALUES (v_next_user.user_id, _league_id, v_country, v_club_name, 'joined');
      END IF;
      -- Mark as processed
      UPDATE league_waiting_list SET status = 'processed' WHERE id = v_next_user.id;
      
      -- Send notification
      INSERT INTO user_notifications (user_id, title, message, type)
      VALUES (v_next_user.user_id, '⚽ Bem-vindo à Liga!', 'Sua vaga na liga ' || v_country || ' foi liberada. A temporada começou!', 'league_entry');
    END;
  END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.auto_assign_league(_user_id uuid, _club_name text, _country text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _league_id uuid;
  _bot_user_id uuid;
  _log_id uuid;
BEGIN
  -- 1. Check if user is already in any league of this country
  SELECT lm.league_id INTO _league_id
  FROM league_members lm
  JOIN multiplayer_leagues ml ON ml.id = lm.league_id
  WHERE lm.user_id = _user_id AND ml.country = _country
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    -- If already in league, ensure waiting list is cleaned up
    UPDATE public.league_waiting_list 
    SET status = 'processed' 
    WHERE user_id = _user_id AND country = _country AND status = 'waiting';
    
    RETURN _league_id;
  END IF;
  -- 2. Try to find a league with empty space (count < max_members)
  SELECT ml.id INTO _league_id
  FROM multiplayer_leagues ml
  WHERE ml.country = _country
    AND ml.auto_created = true
    AND ml.season_status IN ('registration', 'waiting', 'in_progress')
    AND (SELECT count(*) FROM league_members lm2 WHERE lm2.league_id = ml.id) < ml.max_members
  ORDER BY 
    CASE WHEN ml.league_type = 'main' THEN 1 ELSE 2 END ASC,
    ml.division ASC, 
    ml.created_at ASC
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    INSERT INTO league_members (league_id, user_id, club_name, club_logo, is_bot)
    VALUES (_league_id, _user_id, _club_name, '⚽', false)
    ON CONFLICT (league_id, user_id) DO NOTHING;
    
    UPDATE public.league_waiting_list 
    SET status = 'processed' 
    WHERE user_id = _user_id AND country = _country AND status = 'waiting';
    INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action)
    VALUES (_user_id, _league_id, _country, _club_name, 'joined');
    
    RETURN _league_id;
  END IF;
  -- 3. No empty space? Try to replace a BOT in an existing league
  SELECT ml.id INTO _league_id
  FROM multiplayer_leagues ml
  WHERE ml.country = _country
    AND ml.auto_created = true
    AND EXISTS (SELECT 1 FROM league_members lm3 WHERE lm3.league_id = ml.id AND lm3.is_bot = true)
  ORDER BY 
    CASE WHEN ml.league_type = 'main' THEN 1 ELSE 2 END ASC,
    ml.division ASC, 
    ml.created_at ASC
  LIMIT 1;
  IF _league_id IS NOT NULL THEN
    -- Find the BOT to replace
    SELECT user_id INTO _bot_user_id
    FROM league_members
    WHERE league_id = _league_id AND is_bot = true
    LIMIT 1;
    IF _bot_user_id IS NOT NULL THEN
      -- Replace BOT in league_members
      UPDATE league_members 
      SET user_id = _user_id, 
          club_name = _club_name, 
          is_bot = false, 
          bot_strength = NULL,
          joined_at = NOW()
      WHERE league_id = _league_id AND user_id = _bot_user_id;
      -- Update match fixtures
      UPDATE league_matches SET home_user_id = _user_id WHERE league_id = _league_id AND home_user_id = _bot_user_id;
      UPDATE league_matches SET away_user_id = _user_id WHERE league_id = _league_id AND away_user_id = _bot_user_id;
      
      UPDATE league_squads SET user_id = _user_id WHERE league_id = _league_id AND user_id = _bot_user_id;
      UPDATE public.league_waiting_list 
      SET status = 'processed' 
      WHERE user_id = _user_id AND country = _country AND status = 'waiting';
      INSERT INTO league_registration_logs (user_id, league_id, country, club_name, action, bot_replaced_id)
      VALUES (_user_id, _league_id, _country, _club_name, 'replaced_bot', _bot_user_id);
      
      RETURN _league_id;
    END IF;
  END IF;
  -- 4. Still no space and no bots? Add to waiting list
  INSERT INTO public.league_waiting_list (user_id, country, league_type, status)
  VALUES (_user_id, _country, 'main', 'waiting')
  ON CONFLICT (user_id, country, league_type) DO UPDATE SET status = 'waiting', enrolled_at = NOW();
  INSERT INTO league_registration_logs (user_id, country, club_name, action)
  VALUES (_user_id, _country, _club_name, 'queued');
  RETURN NULL;
END;
$function$;
CREATE OR REPLACE FUNCTION public.finalize_player_transfer(
  p_listing_id UUID,
  p_offer_id UUID,
  p_buyer_id UUID
) RETURNS JSONB AS $$
DECLARE
  v_listing RECORD;
  v_offer RECORD;
  v_player_data JSONB;
  v_seller_id UUID;
  v_price BIGINT;
  v_salary INT;
  v_contract INT;
  v_new_player JSONB;
  v_success BOOLEAN := FALSE;
  v_error_msg TEXT;
BEGIN
  -- 1. Get listing and offer
  SELECT * INTO v_listing FROM public.transfer_listings WHERE id = p_listing_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não encontrado');
  END IF;
  SELECT * INTO v_offer FROM public.transfer_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Proposta não encontrada');
  END IF;
  IF v_listing.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não está mais ativo');
  END IF;
  IF v_offer.status != 'accepted' AND v_offer.status != 'pending' THEN
    -- In some flows it might be pending if coming from a buy-now simulation
    -- but usually it should be accepted. Let's be flexible but safe.
  END IF;
  v_seller_id := v_listing.seller_id;
  v_player_data := v_listing.player_data;
  v_price := v_offer.offered_price;
  v_salary := v_offer.offered_salary;
  v_contract := v_offer.offered_contract_years;
  -- 2. Create the player object for the buyer
  v_new_player := v_player_data || jsonb_build_object(
    'salary', v_salary,
    'contract', v_contract,
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'onTransferList', false,
    'isLoaned', false,
    'signedAt', extract(epoch from now()) * 1000
  );
  -- 3. Update Buyer Save (Add player, subtract budget)
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      (club_data->'club'->'players') || v_new_player
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric - v_price)
  )
  WHERE user_id = p_buyer_id;
  -- 4. Update Seller Save (Remove player, add budget)
  -- We filter by id. Since we don't know the index, we use a subquery/expression.
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      COALESCE((
        SELECT jsonb_agg(p)
        FROM jsonb_array_elements(club_data->'club'->'players') p
        WHERE (p->>'id') != (v_player_data->>'id')
      ), '[]'::jsonb)
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric + v_price)
  )
  WHERE user_id = v_seller_id;
  -- 5. Update metadata tables
  UPDATE public.transfer_listings SET status = 'sold', sold_at = now() WHERE id = p_listing_id;
  UPDATE public.transfer_offers SET status = 'completed' WHERE id = p_offer_id;
  
  -- 6. Log transfer
  INSERT INTO public.transfer_log (
    player_name, player_overall, from_user_id, to_user_id, 
    from_club_name, to_club_name, price, salary, transfer_type
  ) VALUES (
    v_listing.player_name, v_listing.player_overall, v_seller_id, p_buyer_id,
    v_listing.seller_club_name, v_offer.buyer_club_name, v_price, v_salary, 'sale'
  );
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.finalize_free_agent_signing(
  p_offer_id UUID,
  p_buyer_id UUID
) RETURNS JSONB AS $$
DECLARE
  v_offer RECORD;
  v_agent RECORD;
  v_player_data JSONB;
  v_new_player JSONB;
  v_price BIGINT; -- signing bonus
BEGIN
  SELECT * INTO v_offer FROM public.free_agent_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Proposta não encontrada');
  END IF;
  SELECT * INTO v_agent FROM public.free_agents_market WHERE id = v_offer.agent_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Jogador não encontrado no mercado');
  END IF;
  v_player_data := v_agent.player_data;
  v_price := COALESCE(v_offer.signing_bonus, 0);
  v_new_player := v_player_data || jsonb_build_object(
    'salary', v_offer.offered_salary,
    'contract', v_offer.offered_contract_years,
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'signedAt', extract(epoch from now()) * 1000,
    'signingType', 'free_agent'
  );
  -- Update Buyer Save
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      (club_data->'club'->'players') || v_new_player
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric - v_price)
  )
  WHERE user_id = p_buyer_id;
  -- Delete from market and mark offer completed
  DELETE FROM public.free_agents_market WHERE id = v_offer.agent_id;
  UPDATE public.free_agent_offers SET status = 'completed', resolved_at = now() WHERE id = p_offer_id;
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION public.promote_youth_to_pro(
  p_user_id UUID,
  p_youth_id UUID,
  p_player_data JSONB
) RETURNS JSONB AS $$
DECLARE
  v_new_player JSONB;
BEGIN
  v_new_player := p_player_data || jsonb_build_object(
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'signedAt', extract(epoch from now()) * 1000,
    'signingType', 'youth_promotion'
  );
  -- Update Save
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    club_data,
    '{club, players}',
    (club_data->'club'->'players') || v_new_player
  )
  WHERE user_id = p_user_id;
  -- Delete from youth prospects
  DELETE FROM public.youth_prospects WHERE id = p_youth_id AND user_id = p_user_id;
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql;
GRANT EXECUTE ON FUNCTION public.finalize_player_transfer(UUID, UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.finalize_free_agent_signing(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.promote_youth_to_pro(UUID, UUID, JSONB) TO authenticated, service_role;
