CREATE OR REPLACE FUNCTION public.finalize_loan_transfer(
  p_listing_id UUID,
  p_offer_id UUID,
  p_buyer_id UUID
) RETURNS JSONB AS $$
DECLARE
  v_listing RECORD;
  v_offer RECORD;
  v_player_data JSONB;
  v_seller_id UUID;
  v_salary INT;
  v_new_player JSONB;
  v_loaned_out_player JSONB;
BEGIN
  -- 1. Get listing and offer
  SELECT * INTO v_listing FROM public.transfer_listings WHERE id = p_listing_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não encontrado');
  END IF;
  SELECT * INTO v_offer FROM public.transfer_offers WHERE id = p_offer_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Proposta não encontrada');
  END IF;
  v_seller_id := v_listing.seller_id;
  v_player_data := v_listing.player_data;
  v_salary := v_offer.offered_salary;
  -- 2. Create the player object for the buyer (loaned in)
  v_new_player := v_player_data || jsonb_build_object(
    'salary', v_salary,
    'contract', v_offer.offered_contract_years,
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'isLoaned', true,
    'isReceivedLoan', true,
    'signedAt', extract(epoch from now()) * 1000,
    'signingType', 'loan_in'
  );
  -- 3. Create the player object for the seller (loaned out)
  v_loaned_out_player := v_player_data || jsonb_build_object(
    'isLoaned', true,
    'onLoanList', false,
    'squad_status', 'reserve',
    'squadRole', 'reserva'
  );
  -- 4. Update Buyer Save (Add player)
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    club_data,
    '{club, players}',
    (club_data->'club'->'players') || v_new_player
  )
  WHERE user_id = p_buyer_id;
  -- 5. Update Seller Save (Mark as loaned out)
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    club_data,
    '{club, players}',
    COALESCE((
      SELECT jsonb_agg(CASE WHEN (p->>'id') = (v_player_data->>'id') THEN v_loaned_out_player ELSE p END)
      FROM jsonb_array_elements(club_data->'club'->'players') p
    ), '[]'::jsonb)
  )
  WHERE user_id = v_seller_id;
  -- 6. Update metadata tables
  UPDATE public.transfer_listings SET status = 'loaned', sold_at = now() WHERE id = p_listing_id;
  UPDATE public.transfer_offers SET status = 'completed' WHERE id = p_offer_id;
  
  -- 7. Log transfer
  INSERT INTO public.transfer_log (
    player_name, player_overall, from_user_id, to_user_id, 
    from_club_name, to_club_name, price, salary, transfer_type
  ) VALUES (
    v_listing.player_name, v_listing.player_overall, v_seller_id, p_buyer_id,
    v_listing.seller_club_name, v_offer.buyer_club_name, 0, v_salary, 'loan'
  );
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SET search_path = public;
GRANT EXECUTE ON FUNCTION public.finalize_loan_transfer(UUID, UUID, UUID) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.finalize_player_transfer(
  p_listing_id UUID,
  p_offer_id UUID,
  p_buyer_id UUID,
  p_buyer_club_name TEXT DEFAULT NULL
) RETURNS JSONB AS $$
DECLARE
  v_listing RECORD;
  v_offer RECORD;
  v_player_data JSONB;
  v_seller_id UUID;
  v_price BIGINT;
  v_salary INT;
  v_contract INT;
  v_new_player JSONB;
  v_buyer_club TEXT;
BEGIN
  -- 1. Get listing
  SELECT * INTO v_listing FROM public.transfer_listings WHERE id = p_listing_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não encontrado');
  END IF;
  IF v_listing.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não está mais ativo');
  END IF;
  -- 2. Get offer or use listing data for Buy Now
  IF p_offer_id IS NOT NULL THEN
    SELECT * INTO v_offer FROM public.transfer_offers WHERE id = p_offer_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'Proposta não encontrada');
    END IF;
    v_price := v_offer.offered_price;
    v_salary := v_offer.offered_salary;
    v_contract := v_offer.offered_contract_years;
    v_buyer_club := v_offer.buyer_club_name;
  ELSE
    -- Buy Now
    v_price := v_listing.asking_price;
    v_salary := (v_listing.player_data->>'salary')::INT;
    v_contract := 2; -- Default for buy now
    v_buyer_club := COALESCE(p_buyer_club_name, 'Clube Comprador');
  END IF;
  v_seller_id := v_listing.seller_id;
  v_player_data := v_listing.player_data;
  -- 3. Create the player object for the buyer
  v_new_player := v_player_data || jsonb_build_object(
    'salary', v_salary,
    'contract', v_contract,
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'onTransferList', false,
    'isLoaned', false,
    'signedAt', extract(epoch from now()) * 1000
  );
  -- 4. Update Buyer Save
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      (club_data->'club'->'players') || v_new_player
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric - v_price)
  )
  WHERE user_id = p_buyer_id;
  -- 5. Update Seller Save
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      COALESCE((
        SELECT jsonb_agg(p)
        FROM jsonb_array_elements(club_data->'club'->'players') p
        WHERE (p->>'id') != (v_player_data->>'id')
      ), '[]'::jsonb)
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric + v_price)
  )
  WHERE user_id = v_seller_id;
  -- 6. Update metadata tables
  UPDATE public.transfer_listings SET status = 'sold', sold_at = now() WHERE id = p_listing_id;
  IF p_offer_id IS NOT NULL THEN
    UPDATE public.transfer_offers SET status = 'completed' WHERE id = p_offer_id;
  END IF;
  
  -- 7. Log transfer
  INSERT INTO public.transfer_log (
    player_name, player_overall, from_user_id, to_user_id, 
    from_club_name, to_club_name, price, salary, transfer_type
  ) VALUES (
    v_listing.player_name, v_listing.player_overall, v_seller_id, p_buyer_id,
    v_listing.seller_club_name, v_buyer_club, v_price, v_salary, 'sale'
  );
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SET search_path = public;
CREATE OR REPLACE FUNCTION public.finalize_loan_listing_transfer(
  p_listing_id UUID,
  p_buyer_id UUID,
  p_buyer_club_name TEXT
) RETURNS JSONB AS $$
DECLARE
  v_listing RECORD;
  v_player_data JSONB;
  v_seller_id UUID;
  v_new_player JSONB;
  v_loaned_out_player JSONB;
BEGIN
  -- 1. Get listing
  SELECT * INTO v_listing FROM public.loan_listings WHERE id = p_listing_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio de empréstimo não encontrado');
  END IF;
  IF v_listing.status != 'active' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Anúncio não está mais ativo');
  END IF;
  v_seller_id := v_listing.seller_id;
  v_player_data := v_listing.player_data;
  -- 2. Create the player object for the buyer (loaned in)
  v_new_player := v_player_data || jsonb_build_object(
    'salary', v_listing.salary,
    'contract', 1, -- Default 1 season for loans
    'squad_status', 'reserve',
    'squadRole', 'reserva',
    'isLoaned', true,
    'isReceivedLoan', true,
    'signedAt', extract(epoch from now()) * 1000,
    'signingType', 'loan_in',
    'loanedFrom', v_listing.seller_club_name
  );
  -- 3. Create the player object for the seller (loaned out)
  v_loaned_out_player := v_player_data || jsonb_build_object(
    'isLoaned', true,
    'onLoanList', false,
    'squad_status', 'reserve',
    'squadRole', 'reserva'
  );
  -- 4. Update Buyer Save (Add player)
  -- Subtract loan fee if any
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      (club_data->'club'->'players') || v_new_player
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric - COALESCE(v_listing.loan_fee, 0))
  )
  WHERE user_id = p_buyer_id;
  -- 5. Update Seller Save (Mark as loaned out)
  UPDATE public.game_saves
  SET club_data = jsonb_set(
    jsonb_set(
      club_data,
      '{club, players}',
      COALESCE((
        SELECT jsonb_agg(CASE WHEN (p->>'id') = (v_player_data->>'id') THEN v_loaned_out_player ELSE p END)
        FROM jsonb_array_elements(club_data->'club'->'players') p
      ), '[]'::jsonb)
    ),
    '{club, budget}',
    to_jsonb((club_data->'club'->'budget')::numeric + COALESCE(v_listing.loan_fee, 0))
  )
  WHERE user_id = v_seller_id;
  -- 6. Update listing
  UPDATE public.loan_listings SET 
    status = 'accepted', 
    buyer_id = p_buyer_id, 
    buyer_club_name = p_buyer_club_name,
    accepted_at = now() 
  WHERE id = p_listing_id;
  
  -- 7. Log transfer (using existing transfer_log)
  INSERT INTO public.transfer_log (
    player_name, player_overall, from_user_id, to_user_id, 
    from_club_name, to_club_name, price, salary, transfer_type
  ) VALUES (
    v_listing.player_name, v_listing.player_overall, v_seller_id, p_buyer_id,
    v_listing.seller_club_name, p_buyer_club_name, COALESCE(v_listing.loan_fee, 0), v_listing.salary, 'loan'
  );
  RETURN jsonb_build_object('success', true, 'player', v_new_player);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$ LANGUAGE plpgsql SET search_path = public;
GRANT EXECUTE ON FUNCTION public.finalize_loan_listing_transfer(UUID, UUID, TEXT) TO authenticated, service_role;
ALTER TABLE public.user_notifications ADD COLUMN actions JSONB;
COMMENT ON COLUMN public.user_notifications.actions IS 'Array of objects: { label: string, type: string, payload: any, variant?: string }';
DO $$
DECLARE
  d1 uuid := 'b01ef2e0-298f-4313-a093-680715e25fec';
  d2 uuid := 'baaeea96-d1e0-4914-9255-8008a3059fb4';
  d3 uuid := '08284dd1-9064-4950-8f33-6c91cb68d532';
  user_team uuid := '52b34eb7-6757-49c1-94c4-219a75ad3e7e';
  v_team_id uuid;
  v_target uuid;
  v_counter int := 0;
BEGIN
  FOR v_team_id IN
    SELECT id FROM world_teams 
    WHERE league_id = d1 AND is_bot = true AND id <> user_team
    ORDER BY strength ASC NULLS LAST, created_at ASC
    OFFSET 15
  LOOP
    v_counter := v_counter + 1;
    IF v_counter <= 16 THEN v_target := d2;
    ELSIF v_counter <= 32 THEN v_target := d3;
    ELSE v_target := NULL;
    END IF;
    UPDATE world_teams SET league_id = v_target WHERE id = v_team_id;
    DELETE FROM world_league_table WHERE team_id = v_team_id AND league_id = d1;
    
    IF v_target IS NOT NULL THEN
      INSERT INTO world_league_table (league_id, team_id, points, wins, draws, losses, goals_for, goals_against, season_year, season_month, country)
      SELECT v_target, v_team_id, 0, 0, 0, 0, 0, 0, season_year, season_month, country
      FROM world_leagues WHERE id = v_target
      ON CONFLICT DO NOTHING;
    END IF;
  END LOOP;
END $$;
