CREATE OR REPLACE FUNCTION public.watchdog_simulate_world_matches(p_batch_size INT DEFAULT 50)
RETURNS TABLE (
    matches_simulated INT,
    leagues_advanced INT
) AS $$
DECLARE
    v_match_record RECORD;
    v_simulated_count INT := 0;
    v_leagues_advanced INT := 0;
    v_h_strength INT;
    v_a_strength INT;
    v_hg INT;
    v_ag INT;
    v_league_id UUID;
    v_round INT;
BEGIN
    -- 1. Identificar partidas pendentes de ligas de bots que já deveriam ter ocorrido
    -- (scheduled_at <= now())
    FOR v_match_record IN 
        SELECT m.id, m.league_id, m.round, m.home_team_id, m.away_team_id,
               th.strength as h_strength, ta.strength as a_strength
        FROM world_matches m
        JOIN world_teams th ON m.home_team_id = th.id
        JOIN world_teams ta ON m.away_team_id = ta.id
        WHERE m.status = 'scheduled' 
          AND m.scheduled_at <= (NOW() + INTERVAL '5 minutes') -- Margem de segurança
        LIMIT p_batch_size
    LOOP
        -- Cálculo rápido de resultado (Poison distribuition simplificado em SQL)
        -- Usando força base 50
        v_h_strength := COALESCE(v_match_record.h_strength, 60);
        v_a_strength := COALESCE(v_match_record.a_strength, 60);
        
        -- Gols Casa: floor(random() * (força/20 + 2))
        v_hg := FLOOR(RANDOM() * (v_h_strength / 25.0 + 2.5));
        -- Gols Fora: floor(random() * (força/25 + 1.8))
        v_ag := FLOOR(RANDOM() * (v_a_strength / 30.0 + 2.0));
        -- Atualizar a partida
        UPDATE world_matches 
        SET home_goals = v_hg,
            away_goals = v_ag,
            status = 'finished',
            played_at = NOW(),
            simulated = true,
            match_data = jsonb_build_object(
                'auto_simulated', true,
                'watchdog', true,
                'stats', jsonb_build_object(
                    'possession', ARRAY[50, 50],
                    'shots', ARRAY[v_hg + 5, v_ag + 4]
                )
            )
        WHERE id = v_match_record.id;
        v_simulated_count := v_simulated_count + 1;
    END LOOP;
    -- 2. Identificar ligas onde a rodada atual não tem mais jogos pendentes e avançar
    FOR v_league_id, v_round IN
        SELECT wl.id, wl.current_round
        FROM world_leagues wl
        WHERE wl.active = true
          AND NOT EXISTS (
              SELECT 1 FROM world_matches m 
              WHERE m.league_id = wl.id 
                AND m.round <= wl.current_round 
                AND m.status = 'scheduled'
          )
          -- Apenas se houver partidas da próxima rodada já agendadas ou se for o fim
          AND EXISTS (
              SELECT 1 FROM world_matches m 
              WHERE m.league_id = wl.id 
                AND m.round = wl.current_round + 1
          )
    LOOP
        UPDATE world_leagues 
        SET current_round = current_round + 1 
        WHERE id = v_league_id;
        
        v_leagues_advanced := v_leagues_advanced + 1;
        
        -- Log de avanço
        INSERT INTO match_worker_logs (match_type, result_text, status, details)
        VALUES ('watchdog', 'League advanced: ' || v_league_id, 'finished', jsonb_build_object('league_id', v_league_id, 'new_round', v_round + 1));
    END LOOP;
    RETURN QUERY SELECT v_simulated_count, v_leagues_advanced;
END;
$$ LANGUAGE plpgsql;
GRANT EXECUTE ON FUNCTION public.watchdog_simulate_world_matches(INT) TO service_role;
GRANT EXECUTE ON FUNCTION public.watchdog_simulate_world_matches(INT) TO authenticated;
CREATE OR REPLACE FUNCTION public.regenerate_missing_league_calendars()
RETURNS INT AS $$
DECLARE
    v_league_record RECORD;
    v_team_ids UUID[];
    v_round_robin_rounds INT;
    v_num_teams INT;
    v_matches_created INT := 0;
    v_current_round_start TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    FOR v_league_record IN 
        SELECT id, name, season_month, season_year 
        FROM world_leagues 
        WHERE id NOT IN (SELECT DISTINCT league_id FROM world_matches)
          AND id IN (SELECT DISTINCT league_id FROM world_teams)
    LOOP
        -- Buscar IDs dos times da liga
        SELECT array_agg(id) INTO v_team_ids FROM world_teams WHERE league_id = v_league_record.id;
        v_num_teams := array_length(v_team_ids, 1);
        
        -- Apenas ligas com pelo menos 2 times
        IF v_num_teams >= 2 THEN
            -- Simples geração de partidas (todos contra todos ida e volta)
            -- Para resolver o travamento imediato, geramos as rodadas faltantes
            -- Rodada 1 a 30
            FOR r IN 1..30 LOOP
                -- Gerar pares de partidas simples (fallback rápido)
                FOR i IN 1..(v_num_teams/2) LOOP
                    INSERT INTO world_matches (
                        league_id, home_team_id, away_team_id, round, 
                        status, scheduled_at, season_month, season_year
                    ) VALUES (
                        v_league_record.id, 
                        v_team_ids[((i + r) % v_num_teams) + 1], 
                        v_team_ids[((v_num_teams - i + r) % v_num_teams) + 1], 
                        r, 
                        'scheduled', 
                        v_current_round_start + (r || ' days')::interval + (i || ' hours')::interval,
                        v_league_record.season_month,
                        v_league_record.season_year
                    );
                    v_matches_created := v_matches_created + 1;
                END LOOP;
            END LOOP;
            
            -- Resetar a rodada para 1 para começar a simular
            UPDATE world_leagues SET current_round = 1 WHERE id = v_league_record.id;
        END IF;
    END LOOP;
    
    RETURN v_matches_created;
END;
$$ LANGUAGE plpgsql;
SELECT public.regenerate_missing_league_calendars();
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['abuse_alerts','suspicious_activity','auth_verification_codes','beta_whitelist','game_saves','payment_webhooks_logs','support_messages']
  LOOP
    BEGIN
      EXECUTE format('ALTER PUBLICATION supabase_realtime DROP TABLE public.%I', t);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END $$;
