CREATE OR REPLACE FUNCTION public.generate_world_league_calendar(p_league_id uuid, p_start_date timestamp with time zone, p_match_time time without time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    team_ids UUID[];
    num_teams INTEGER;
    num_rounds INTEGER;
    matches_per_round INTEGER;
    r INTEGER;
    m INTEGER;
    home_idx INTEGER;
    away_idx INTEGER;
    temp_team UUID;
    scheduled_time TIMESTAMP WITH TIME ZONE;
BEGIN
    -- Use world_teams instead of world_league_teams
    SELECT ARRAY_AGG(id) INTO team_ids FROM public.world_teams WHERE league_id = p_league_id;
    num_teams := array_length(team_ids, 1);
    
    IF num_teams < 2 THEN RETURN; END IF;
    
    -- Ensure even number of teams for rotation algorithm
    IF num_teams % 2 != 0 THEN
        -- This shouldn't happen with 20 teams but good for safety
        num_teams := num_teams - 1;
        team_ids := team_ids[1:num_teams];
    END IF;
    num_rounds := (num_teams - 1) * 2;
    matches_per_round := num_teams / 2;
    
    -- Clear existing matches for this league
    DELETE FROM public.world_matches WHERE league_id = p_league_id AND status = 'scheduled';
    
    -- Round robin scheduling algorithm (Circle method)
    FOR r IN 1..num_rounds LOOP
        -- For season 1 catch-up, we don't worry too much about exact dates here as simulation will fix it
        scheduled_time := p_start_date + (r - 1) * INTERVAL '1 day';
        scheduled_time := (scheduled_time::date + p_match_time)::timestamp with time zone;
        
        FOR m IN 1..matches_per_round LOOP
            home_idx := m;
            away_idx := num_teams - m + 1;
            
            IF r > (num_teams - 1) THEN
                -- Second half of the season: Swap home/away
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, status)
                VALUES (p_league_id, team_ids[away_idx], team_ids[home_idx], r, scheduled_time, 'scheduled');
            ELSE
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, status)
                VALUES (p_league_id, team_ids[home_idx], team_ids[away_idx], r, scheduled_time, 'scheduled');
            END IF;
        END LOOP;
        
        -- Rotate teams (keep first team fixed)
        temp_team := team_ids[num_teams];
        FOR i IN REVERSE num_teams..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_team;
    END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.init_world_sync_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.user_id IS NOT NULL THEN
        INSERT INTO public.world_sync_state (user_id) VALUES (NEW.user_id)
        ON CONFLICT (user_id) DO NOTHING;
    END IF;
    RETURN NEW;
END;
$function$;
CREATE OR REPLACE FUNCTION public.generate_world_league_calendar(p_league_id uuid, p_start_date timestamp with time zone, p_match_time time without time zone)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    team_ids UUID[];
    num_teams INTEGER;
    num_rounds INTEGER;
    matches_per_round INTEGER;
    r INTEGER;
    m INTEGER;
    home_idx INTEGER;
    away_idx INTEGER;
    temp_team UUID;
    scheduled_time TIMESTAMP WITH TIME ZONE;
    v_season_year INTEGER;
    v_season_month INTEGER;
BEGIN
    -- Get season info from league
    SELECT season_year, season_month INTO v_season_year, v_season_month 
    FROM public.world_leagues WHERE id = p_league_id;
    
    v_season_year := COALESCE(v_season_year, 1);
    v_season_month := COALESCE(v_season_month, 1);
    -- Get teams in the league
    SELECT ARRAY_AGG(id) INTO team_ids FROM public.world_teams WHERE league_id = p_league_id;
    num_teams := array_length(team_ids, 1);
    
    IF num_teams < 2 THEN RETURN; END IF;
    
    IF num_teams % 2 != 0 THEN
        num_teams := num_teams - 1;
        team_ids := team_ids[1:num_teams];
    END IF;
    num_rounds := (num_teams - 1) * 2;
    matches_per_round := num_teams / 2;
    
    DELETE FROM public.world_matches WHERE league_id = p_league_id AND status = 'scheduled';
    
    FOR r IN 1..num_rounds LOOP
        scheduled_time := p_start_date + (r - 1) * INTERVAL '1 day';
        scheduled_time := (scheduled_time::date + p_match_time)::timestamp with time zone;
        
        FOR m IN 1..matches_per_round LOOP
            home_idx := m;
            away_idx := num_teams - m + 1;
            
            IF r > (num_teams - 1) THEN
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, status, season_year, season_month)
                VALUES (p_league_id, team_ids[away_idx], team_ids[home_idx], r, scheduled_time, 'scheduled', v_season_year, v_season_month);
            ELSE
                INSERT INTO public.world_matches (league_id, home_team_id, away_team_id, round, scheduled_at, status, season_year, season_month)
                VALUES (p_league_id, team_ids[home_idx], team_ids[away_idx], r, scheduled_time, 'scheduled', v_season_year, v_season_month);
            END IF;
        END LOOP;
        
        temp_team := team_ids[num_teams];
        FOR i IN REVERSE num_teams..3 LOOP
            team_ids[i] := team_ids[i-1];
        END LOOP;
        team_ids[2] := temp_team;
    END LOOP;
END;
$function$;
CREATE OR REPLACE FUNCTION public.sync_world_league_standings(_league_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_season_year int;
BEGIN
    SELECT season_year INTO v_season_year FROM public.world_leagues WHERE id = _league_id;
    v_season_year := COALESCE(v_season_year, 1);
    INSERT INTO public.world_league_standings (league_id, team_id, season_year, played, wins, draws, losses, goals_for, goals_against, points, goal_diff)
    SELECT 
        m.league_id,
        t.id as team_id,
        v_season_year,
        COUNT(m.id) as played,
        COUNT(CASE WHEN (m.home_team_id = t.id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.id AND m.away_goals > m.home_goals) THEN 1 END) as wins,
        COUNT(CASE WHEN m.home_goals = m.away_goals THEN 1 END) as draws,
        COUNT(CASE WHEN (m.home_team_id = t.id AND m.home_goals < m.away_goals) OR (m.away_team_id = t.id AND m.away_goals < m.home_goals) THEN 1 END) as losses,
        SUM(CASE WHEN m.home_team_id = t.id THEN m.home_goals ELSE m.away_goals END) as goals_for,
        SUM(CASE WHEN m.home_team_id = t.id THEN m.away_goals ELSE m.home_goals END) as goals_against,
        SUM(CASE 
            WHEN (m.home_team_id = t.id AND m.home_goals > m.away_goals) OR (m.away_team_id = t.id AND m.away_goals > m.home_goals) THEN 3
            WHEN m.home_goals = m.away_goals THEN 1
            ELSE 0
        END) as points,
        SUM(CASE WHEN m.home_team_id = t.id THEN m.home_goals - m.away_goals ELSE m.away_goals - m.home_goals END) as goal_diff
    FROM public.world_matches m
    JOIN public.world_teams t ON t.id IN (m.home_team_id, m.away_team_id)
    WHERE m.league_id = _league_id AND m.status = 'finished'
    GROUP BY m.league_id, t.id
    ON CONFLICT (league_id, team_id, season_year) DO UPDATE SET
        played = EXCLUDED.played,
        wins = EXCLUDED.wins,
        draws = EXCLUDED.draws,
        losses = EXCLUDED.losses,
        goals_for = EXCLUDED.goals_for,
        goals_against = EXCLUDED.goals_against,
        points = EXCLUDED.points,
        goal_diff = EXCLUDED.goal_diff,
        updated_at = now();
END;
$function$;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'world_league_standings_team_id_fkey'
  ) THEN
    -- Clean orphan rows first so the FK can be added
    DELETE FROM public.world_league_standings s
     WHERE NOT EXISTS (SELECT 1 FROM public.world_teams t WHERE t.id = s.team_id);
    ALTER TABLE public.world_league_standings
      ADD CONSTRAINT world_league_standings_team_id_fkey
      FOREIGN KEY (team_id) REFERENCES public.world_teams(id) ON DELETE CASCADE;
  END IF;
END$$;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conname = 'world_player_stats_player_id_fkey'
  ) THEN
    DELETE FROM public.world_player_stats ps
     WHERE NOT EXISTS (SELECT 1 FROM public.world_players p WHERE p.id = ps.player_id);
    ALTER TABLE public.world_player_stats
      ADD CONSTRAINT world_player_stats_player_id_fkey
      FOREIGN KEY (player_id) REFERENCES public.world_players(id) ON DELETE CASCADE;
  END IF;
END$$;
CREATE INDEX IF NOT EXISTS idx_world_league_standings_league_points
  ON public.world_league_standings (league_id, points DESC, goal_diff DESC);
CREATE INDEX IF NOT EXISTS idx_world_player_stats_league_goals
  ON public.world_player_stats (league_id, goals DESC);
DO $$
DECLARE
  lg RECORD;
  team_ids UUID[];
  pos UUID[];
  fixed_team UUID;
  r INT;
  i INT;
  k INT;
  home_t UUID;
  away_t UUID;
  tmp UUID;
  hg INT;
  ag INT;
  match_round INT;
  base_date TIMESTAMPTZ;
  match_date TIMESTAMPTZ;
  match_status TEXT;
  team_count INT;
BEGIN
  FOR lg IN SELECT id, season_year FROM public.world_leagues WHERE active = true LOOP
    -- 1) Trim to 16 teams (prefer humans, fill remaining bots randomly)
    DELETE FROM public.world_matches WHERE league_id = lg.id;
    DELETE FROM public.world_league_standings WHERE league_id = lg.id;
    DELETE FROM public.world_league_table WHERE league_id = lg.id;
    DELETE FROM public.world_player_stats WHERE league_id = lg.id;
    DELETE FROM public.world_teams
     WHERE id IN (
       SELECT id FROM (
         SELECT id, row_number() OVER (ORDER BY (user_id IS NOT NULL) DESC, random()) AS rn
           FROM public.world_teams WHERE league_id = lg.id
       ) x WHERE rn > 16
     );
    SELECT COUNT(*) INTO team_count FROM public.world_teams WHERE league_id = lg.id;
    IF team_count <> 16 THEN
      RAISE NOTICE 'Liga % tem % times (esperado 16), pulando', lg.id, team_count;
      CONTINUE;
    END IF;
    SELECT array_agg(id ORDER BY random()) INTO team_ids
      FROM public.world_teams WHERE league_id = lg.id;
    fixed_team := team_ids[1];
    base_date := now() - interval '30 days';
    -- 2) Generate first leg (rounds 1..15) using circle method
    FOR r IN 0..14 LOOP
      -- Build positions array: fixed at slot 1, others rotated by r
      pos := ARRAY[fixed_team];
      FOR k IN 1..15 LOOP
        pos := array_append(pos, team_ids[((k - 1 + r) % 15) + 2]);
      END LOOP;
      match_round := r + 1;
      match_status := CASE WHEN match_round <= 26 THEN 'finished' ELSE 'scheduled' END;
      match_date := base_date + ((r) * interval '1 day');
      FOR i IN 1..8 LOOP
        home_t := pos[i];
        away_t := pos[17 - i];
        IF r % 2 = 1 THEN
          tmp := home_t; home_t := away_t; away_t := tmp;
        END IF;
        IF match_status = 'finished' THEN
          hg := floor(random() * 4)::int;
          ag := floor(random() * 4)::int;
        ELSE
          hg := 0; ag := 0;
        END IF;
        INSERT INTO public.world_matches(
          league_id, home_team_id, away_team_id, round,
          season_month, season_year, scheduled_at, status,
          home_goals, away_goals, simulated, synced, played_at
        ) VALUES (
          lg.id, home_t, away_t, match_round,
          1, lg.season_year, match_date, match_status,
          hg, ag, match_status = 'finished', match_status = 'finished',
          CASE WHEN match_status = 'finished' THEN match_date ELSE NULL END
        );
      END LOOP;
    END LOOP;
    -- 3) Generate second leg (rounds 16..30) with reversed home/away
    FOR r IN 0..14 LOOP
      pos := ARRAY[fixed_team];
      FOR k IN 1..15 LOOP
        pos := array_append(pos, team_ids[((k - 1 + r) % 15) + 2]);
      END LOOP;
      match_round := r + 16;
      match_status := CASE WHEN match_round <= 26 THEN 'finished' ELSE 'scheduled' END;
      match_date := base_date + ((r + 15) * interval '1 day');
      FOR i IN 1..8 LOOP
        home_t := pos[i];
        away_t := pos[17 - i];
        -- Reverse leg: flip versus first leg
        IF r % 2 = 0 THEN
          tmp := home_t; home_t := away_t; away_t := tmp;
        END IF;
        IF match_status = 'finished' THEN
          hg := floor(random() * 4)::int;
          ag := floor(random() * 4)::int;
        ELSE
          hg := 0; ag := 0;
        END IF;
        INSERT INTO public.world_matches(
          league_id, home_team_id, away_team_id, round,
          season_month, season_year, scheduled_at, status,
          home_goals, away_goals, simulated, synced, played_at
        ) VALUES (
          lg.id, home_t, away_t, match_round,
          1, lg.season_year, match_date, match_status,
          hg, ag, match_status = 'finished', match_status = 'finished',
          CASE WHEN match_status = 'finished' THEN match_date ELSE NULL END
        );
      END LOOP;
    END LOOP;
    -- 4) Compute standings from finished matches
    INSERT INTO public.world_league_standings(
      league_id, team_id, season_year, played, wins, draws, losses,
      goals_for, goals_against, goal_diff, points
    )
    SELECT
      lg.id, t.id, lg.season_year,
      COUNT(*) FILTER (WHERE m.id IS NOT NULL AND m.status = 'finished'),
      COUNT(*) FILTER (WHERE m.status = 'finished' AND (
        (m.home_team_id = t.id AND m.home_goals > m.away_goals) OR
        (m.away_team_id = t.id AND m.away_goals > m.home_goals)
      )),
      COUNT(*) FILTER (WHERE m.status = 'finished' AND m.home_goals = m.away_goals),
      COUNT(*) FILTER (WHERE m.status = 'finished' AND (
        (m.home_team_id = t.id AND m.home_goals < m.away_goals) OR
        (m.away_team_id = t.id AND m.away_goals < m.home_goals)
      )),
      COALESCE(SUM(CASE
        WHEN m.status = 'finished' AND m.home_team_id = t.id THEN m.home_goals
        WHEN m.status = 'finished' AND m.away_team_id = t.id THEN m.away_goals
        ELSE 0 END), 0),
      COALESCE(SUM(CASE
        WHEN m.status = 'finished' AND m.home_team_id = t.id THEN m.away_goals
        WHEN m.status = 'finished' AND m.away_team_id = t.id THEN m.home_goals
        ELSE 0 END), 0),
      0, 0
    FROM public.world_teams t
    LEFT JOIN public.world_matches m
      ON (m.home_team_id = t.id OR m.away_team_id = t.id) AND m.league_id = lg.id
    WHERE t.league_id = lg.id
    GROUP BY t.id;
    UPDATE public.world_league_standings
       SET goal_diff = goals_for - goals_against,
           points    = wins * 3 + draws,
           updated_at = now()
     WHERE league_id = lg.id;
    -- 5) Update league meta
    UPDATE public.world_leagues
       SET current_round = 27,
           max_teams     = 16,
           total_slots   = 16,
           total_matchdays = 30
     WHERE id = lg.id;
  END LOOP;
END $$;
